window.ExtraBibleBooks=window.ExtraBibleBooks||{};window.ExtraBibleBooks["JER"]={"book":"JER","editions":{"epo-londona":[[1,1,"Paroloj de Jeremia, filo de Ĥilkija, el la pastroj, kiuj estis en Anatot, en la lando de Benjamen;","Paroloj de Jeremia, filo de Ĥilkija, el la pastroj, kiuj estis en Anatot, en la lando de Benjamen;"],[1,2,"al kiu aperis la vorto de la Eternulo en la tempo de Joŝija, filo de Amon, reĝo de Judujo, en la dek-tria jaro de lia reĝado,","al kiu aperis la vorto de la Eternulo en la tempo de Joŝija, filo de Amon, reĝo de Judujo, en la dek-tria jaro de lia reĝado,"],[1,3,"kaj poste en la tempo de Jehojakim, filo de Joŝija, reĝo de Judujo, ĝis la fino de la dek-unua jaro de Cidkija, filo de Joŝija, reĝo de Judujo, ĝis la forkonduko de la Jerusalemanoj en la kvina monato.","kaj poste en la tempo de Jehojakim, filo de Joŝija, reĝo de Judujo, ĝis la fino de la dek-unua jaro de Cidkija, filo de Joŝija, reĝo de Judujo, ĝis la forkonduko de la Jerusalemanoj en la kvina monato."],[1,4,"Aperis al mi la vorto de la Eternulo, dirante:","Aperis al mi la vorto de la Eternulo, dirante:"],[1,5,"Antaŭ ol Mi formis vin en la utero, Mi vin konis, kaj antaŭ ol vi eliris el la ventro, Mi vin sanktigis, Mi faris vin profeto por la popoloj.","Antaŭ ol Mi formis vin en la utero, Mi vin konis, kaj antaŭ ol vi eliris el la ventro, Mi vin sanktigis, Mi faris vin profeto por la popoloj."],[1,6,"Mi diris: Ho ve, Sinjoro, ho Eternulo! mi ne povoscias paroli, ĉar mi estas juna.","Mi diris: Ho ve, Sinjoro, ho Eternulo! mi ne povoscias paroli, ĉar mi estas juna."],[1,7,"Sed la Eternulo diris al mi: Ne diru, ke vi estas juna; sed ĉien, kien Mi sendos vin, iru, kaj ĉion, kion Mi ordonos al vi, parolu.","Sed la Eternulo diris al mi: Ne diru, ke vi estas juna; sed ĉien, kien Mi sendos vin, iru, kaj ĉion, kion Mi ordonos al vi, parolu."],[1,8,"Ne timu ilin; ĉar Mi estas kun vi, por savi vin, diras la Eternulo.","Ne timu ilin; ĉar Mi estas kun vi, por savi vin, diras la Eternulo."],[1,9,"Kaj la Eternulo etendis Sian manon kaj ektuŝis mian buŝon, kaj la Eternulo diris al mi: Jen Mi enmetis Miajn vortojn en vian buŝon.","Kaj la Eternulo etendis Sian manon kaj ektuŝis mian buŝon, kaj la Eternulo diris al mi: Jen Mi enmetis Miajn vortojn en vian buŝon."],[1,10,"Vidu, Mi starigas vin hodiaŭ super la popoloj kaj super la regnoj, por elŝiri, rompi, pereigi, kaj detrui, por konstrui kaj planti.","Vidu, Mi starigas vin hodiaŭ super la popoloj kaj super la regnoj, por elŝiri, rompi, pereigi, kaj detrui, por konstrui kaj planti."],[1,11,"Kaj aperis al mi la vorto de la Eternulo, dirante: Kion vi vidas, Jeremia? Kaj mi diris: Mi vidas bastonon maldormantan.","Kaj aperis al mi la vorto de la Eternulo, dirante: Kion vi vidas, Jeremia? Kaj mi diris: Mi vidas bastonon maldormantan."],[1,12,"Kaj la Eternulo diris al mi: Vi vidis bone; ĉar Mi maldormos pri Mia vorto, por plenumi ĝin.","Kaj la Eternulo diris al mi: Vi vidis bone; ĉar Mi maldormos pri Mia vorto, por plenumi ĝin."],[1,13,"Kaj duafoje aperis al mi la vorto de la Eternulo, dirante: Kion vi vidas? Kaj mi diris: Mi vidas flame bolantan poton, kaj ĝi rigardas de norde.","Kaj duafoje aperis al mi la vorto de la Eternulo, dirante: Kion vi vidas? Kaj mi diris: Mi vidas flame bolantan poton, kaj ĝi rigardas de norde."],[1,14,"Kaj la Eternulo diris al mi: De norde venos la malfeliĉo sur ĉiujn loĝantojn de la lando.","Kaj la Eternulo diris al mi: De norde venos la malfeliĉo sur ĉiujn loĝantojn de la lando."],[1,15,"Ĉar jen Mi alvokos ĉiujn gentojn de la nordaj regnoj, diras la Eternulo, kaj ili venos kaj starigos ĉiu sian tronon antaŭ la pordegoj de Jerusalem kaj ĉirkaŭ ĝiaj muregoj kaj antaŭ ĉiuj urboj de Judujo.","Ĉar jen Mi alvokos ĉiujn gentojn de la nordaj regnoj, diras la Eternulo, kaj ili venos kaj starigos ĉiu sian tronon antaŭ la pordegoj de Jerusalem kaj ĉirkaŭ ĝiaj muregoj kaj antaŭ ĉiuj urboj de Judujo."],[1,16,"Kaj Mi eldiros Mian verdikton pri ili pro ĉiuj iliaj malbonagoj, pro tio, ke ili forlasis Min kaj incensis al aliaj dioj kaj adorkliniĝis antaŭ la faritaĵo de siaj manoj.","Kaj Mi eldiros Mian verdikton pri ili pro ĉiuj iliaj malbonagoj, pro tio, ke ili forlasis Min kaj incensis al aliaj dioj kaj adorkliniĝis antaŭ la faritaĵo de siaj manoj."],[1,17,"Kaj vi zonu viajn lumbojn, leviĝu, kaj diru al ili ĉion, kion Mi ordonas al vi; ne tremu antaŭ ili, por ke Mi ne tremigu vin antaŭ ili.","Kaj vi zonu viajn lumbojn, leviĝu, kaj diru al ili ĉion, kion Mi ordonas al vi; ne tremu antaŭ ili, por ke Mi ne tremigu vin antaŭ ili."],[1,18,"Jen Mi faras vin hodiaŭ fortikigita urbo, fera kolono, kaj kupraj muroj en la tuta lando, kontraŭ la reĝoj de Judujo, kontraŭ ĝiaj princoj, kontraŭ ĝiaj pastroj, kaj kontraŭ la popolo de la lando.","Jen Mi faras vin hodiaŭ fortikigita urbo, fera kolono, kaj kupraj muroj en la tuta lando, kontraŭ la reĝoj de Judujo, kontraŭ ĝiaj princoj, kontraŭ ĝiaj pastroj, kaj kontraŭ la popolo de la lando."],[1,19,"Ili batalos kontraŭ vi, sed ne venkos vin; ĉar Mi estas kun vi, diras la Eternulo, por savi vin.","Ili batalos kontraŭ vi, sed ne venkos vin; ĉar Mi estas kun vi, diras la Eternulo, por savi vin."],[2,1,"Kaj aperis al mi la vorto de la Eternulo, dirante:","Kaj aperis al mi la vorto de la Eternulo, dirante:"],[2,2,"Iru kaj prediku al la oreloj de Jerusalem, dirante: Tiele diras la Eternulo: Mi memoras la piecon de via juneco, la amon de via fianĉineco, kiam vi sekvis Min en la dezerto, en lando ne prisemita.","Iru kaj prediku al la oreloj de Jerusalem, dirante: Tiele diras la Eternulo: Mi memoras la piecon de via juneco, la amon de via fianĉineco, kiam vi sekvis Min en la dezerto, en lando ne prisemita."],[2,3,"Izrael tiam estis sanktaĵo de la Eternulo, Lia unua frukto; ĉiuj, kiuj manĝis ĝin, estis kondamnitaj, malbono venis sur ilin, diras la Eternulo.","Izrael tiam estis sanktaĵo de la Eternulo, Lia unua frukto; ĉiuj, kiuj manĝis ĝin, estis kondamnitaj, malbono venis sur ilin, diras la Eternulo."],[2,4,"Aŭskultu la vorton de la Eternulo, ho domo de Jakob kaj ĉiuj familioj de la domo de Izrael.","Aŭskultu la vorton de la Eternulo, ho domo de Jakob kaj ĉiuj familioj de la domo de Izrael."],[2,5,"Tiele diras la Eternulo: Kian maljustaĵon viaj patroj trovis en Mi, ke ili malproksimiĝis de Mi kaj sekvis vantaĵon kaj mem vantiĝis?","Tiele diras la Eternulo: Kian maljustaĵon viaj patroj trovis en Mi, ke ili malproksimiĝis de Mi kaj sekvis vantaĵon kaj mem vantiĝis?"],[2,6,"Kaj ili ne diris: Kie estas la Eternulo, kiu elkondukis nin el la Egipta lando, kiu kondukis nin tra dezerto, tra lando de stepoj kaj kavoj, tra lando seka kaj malluma, tra lando, kiun neniu trapasis kaj kie neniu loĝis?","Kaj ili ne diris: Kie estas la Eternulo, kiu elkondukis nin el la Egipta lando, kiu kondukis nin tra dezerto, tra lando de stepoj kaj kavoj, tra lando seka kaj malluma, tra lando, kiun neniu trapasis kaj kie neniu loĝis?"],[2,7,"Kaj Mi venigis vin en landon fruktodonan, por ke vi manĝu ĝiajn fruktojn kaj bonaĵojn; sed vi venis kaj malpurigis Mian landon, kaj Mian heredaĵon vi faris abomenindaĵo.","Kaj Mi venigis vin en landon fruktodonan, por ke vi manĝu ĝiajn fruktojn kaj bonaĵojn; sed vi venis kaj malpurigis Mian landon, kaj Mian heredaĵon vi faris abomenindaĵo."],[2,8,"La pastroj ne diris: Kie estas la Eternulo? la leĝokompetentuloj ne atentis Min, la paŝtistoj perfidis Min, la profetoj profetis per Baal kaj sekvis idolojn.","La pastroj ne diris: Kie estas la Eternulo? la leĝokompetentuloj ne atentis Min, la paŝtistoj perfidis Min, la profetoj profetis per Baal kaj sekvis idolojn."],[2,9,"Pro tio Mi ankoraŭ procesos kun vi, diras la Eternulo, kaj kun la filoj de viaj filoj Mi procesos.","Pro tio Mi ankoraŭ procesos kun vi, diras la Eternulo, kaj kun la filoj de viaj filoj Mi procesos."],[2,10,"Ĉar iru sur la insulojn de la Kitidoj kaj rigardu, sendu al la Kedaridoj kaj esploru bone kaj rigardu, ĉu tie estas farita io simila.","Ĉar iru sur la insulojn de la Kitidoj kaj rigardu, sendu al la Kedaridoj kaj esploru bone kaj rigardu, ĉu tie estas farita io simila."],[2,11,"Ĉu ia popolo ŝanĝis siajn diojn, kvankam ili ne estas dioj? sed Mia popolo ŝanĝis sian gloron je idoloj.","Ĉu ia popolo ŝanĝis siajn diojn, kvankam ili ne estas dioj? sed Mia popolo ŝanĝis sian gloron je idoloj."],[2,12,"Miregu pri tio, ho ĉielo, sentu teruron kaj forte konsterniĝu, diras la Eternulo.","Miregu pri tio, ho ĉielo, sentu teruron kaj forte konsterniĝu, diras la Eternulo."],[2,13,"Ĉar du malbonagojn faris Mia popolo: Min ili forlasis, la fonton de viva akvo, por elhaki al si putojn, truhavajn putojn, kiuj ne povas teni akvon.","Ĉar du malbonagojn faris Mia popolo: Min ili forlasis, la fonton de viva akvo, por elhaki al si putojn, truhavajn putojn, kiuj ne povas teni akvon."],[2,14,"Ĉu Izrael estas sklavo, aŭ ĉu li estas infano de la domo? kial li fariĝis rabitaĵo?","Ĉu Izrael estas sklavo, aŭ ĉu li estas infano de la domo? kial li fariĝis rabitaĵo?"],[2,15,"Kontraŭ li blekegis leonidoj, forte kriis, kaj ili faris lian landon dezerto; liaj urboj estas bruligitaj, kaj neniu loĝas en ili.","Kontraŭ li blekegis leonidoj, forte kriis, kaj ili faris lian landon dezerto; liaj urboj estas bruligitaj, kaj neniu loĝas en ili."],[2,16,"Eĉ la filoj de Nof kaj de Taĥpanĥes frakasis vian verton.","Eĉ la filoj de Nof kaj de Taĥpanĥes frakasis vian verton."],[2,17,"Vi jam mem tion faris al vi, ĉar vi forlasis la Eternulon, vian Dion, en la tempo, kiam Li gvidis vin sur la vojo.","Vi jam mem tion faris al vi, ĉar vi forlasis la Eternulon, vian Dion, en la tempo, kiam Li gvidis vin sur la vojo."],[2,18,"Kaj nun por kio vi bezonas la vojon al Egiptujo? ĉu por trinki la akvon de Nilo? Kaj por kio vi bezonas la vojon al Asirio? ĉu por trinki la akvon de Eŭfrato?","Kaj nun por kio vi bezonas la vojon al Egiptujo? ĉu por trinki la akvon de Nilo? Kaj por kio vi bezonas la vojon al Asirio? ĉu por trinki la akvon de Eŭfrato?"],[2,19,"Via malboneco vin punos, kaj viaj malbonagoj faros al vi riproĉojn, por ke vi sciu kaj vidu, kiel malbone kaj maldolĉe estas, ke vi forlasis la Eternulon, vian Dion, kaj ne timas Min, diras la Sinjoro, la Eternulo Cebaot.","Via malboneco vin punos, kaj viaj malbonagoj faros al vi riproĉojn, por ke vi sciu kaj vidu, kiel malbone kaj maldolĉe estas, ke vi forlasis la Eternulon, vian Dion, kaj ne timas Min, diras la Sinjoro, la Eternulo Cebaot."],[2,20,"Ĉar antaŭ longe vi rompis vian jugon kaj disŝiris viajn ŝnurojn, kaj vi diris: Mi ne plu malbonagos; tamen sur ĉiu alta loko kaj sub ĉiu verda arbo vi kuŝigis vin kiel malĉastistino.","Ĉar antaŭ longe vi rompis vian jugon kaj disŝiris viajn ŝnurojn, kaj vi diris: Mi ne plu malbonagos; tamen sur ĉiu alta loko kaj sub ĉiu verda arbo vi kuŝigis vin kiel malĉastistino."],[2,21,"Mi plantis vin kiel bonegan vinberbranĉon, portontan plej ĝustajn fruktojn; kiel do vi ŝanĝiĝis ĉe Mi je vinberbranĉo sovaĝa?","Mi plantis vin kiel bonegan vinberbranĉon, portontan plej ĝustajn fruktojn; kiel do vi ŝanĝiĝis ĉe Mi je vinberbranĉo sovaĝa?"],[2,22,"Se vi eĉ lavus vin per natro kaj uzus por vi multe da sapo, via malvirto tamen restos makula antaŭ Mi, diras la Sinjoro, la Eternulo.","Se vi eĉ lavus vin per natro kaj uzus por vi multe da sapo, via malvirto tamen restos makula antaŭ Mi, diras la Sinjoro, la Eternulo."],[2,23,"Kiel vi povas diri: Mi ne malpurigis min, mi ne sekvis Baalojn? rigardu vian agadon en la valo, pripensu, kion vi faris, juna kamelino rapidpieda, petolanta sur sia vojo.","Kiel vi povas diri: Mi ne malpurigis min, mi ne sekvis Baalojn? rigardu vian agadon en la valo, pripensu, kion vi faris, juna kamelino rapidpieda, petolanta sur sia vojo."],[2,24,"Kiu povas reteni sovaĝan azeninon, alkutimiĝintan al la dezerto, kiam ĝi sopiregas de sia volupta celado? ĉiuj, kiuj ĝin serĉas, ne bezonas laciĝi, en la sama stato ili ĝin trovos.","Kiu povas reteni sovaĝan azeninon, alkutimiĝintan al la dezerto, kiam ĝi sopiregas de sia volupta celado? ĉiuj, kiuj ĝin serĉas, ne bezonas laciĝi, en la sama stato ili ĝin trovos."],[2,25,"Detenu viajn piedojn de nudeco kaj vian gorĝon de soifo. Sed vi diras: Ne, mi ne volas, ĉar mi amas fremdulojn kaj mi sekvos ilin.","Detenu viajn piedojn de nudeco kaj vian gorĝon de soifo. Sed vi diras: Ne, mi ne volas, ĉar mi amas fremdulojn kaj mi sekvos ilin."],[2,26,"Kiel ŝtelinto hontas, kiam oni lin trovas, tiel estas hontigita la domo de Izrael, ili, iliaj reĝoj, iliaj princoj, iliaj pastroj, kaj iliaj profetoj,","Kiel ŝtelinto hontas, kiam oni lin trovas, tiel estas hontigita la domo de Izrael, ili, iliaj reĝoj, iliaj princoj, iliaj pastroj, kaj iliaj profetoj,"],[2,27,"kiuj diras al ligno: Vi estas mia patro; kaj al ŝtono: Vi min naskis. Ili turnis al Mi la nukon, ne la vizaĝon; sed en la tempo de sia malfeliĉo ili diras: Leviĝu, kaj savu nin.","kiuj diras al ligno: Vi estas mia patro; kaj al ŝtono: Vi min naskis. Ili turnis al Mi la nukon, ne la vizaĝon; sed en la tempo de sia malfeliĉo ili diras: Leviĝu, kaj savu nin."],[2,28,"Kie do estas viaj dioj, kiujn vi faris al vi? ili leviĝu, se ili povas vin savi en la tempo de via malfeliĉo; ĉar kiom da urboj, tiom da dioj vi havas, ho Jehuda.","Kie do estas viaj dioj, kiujn vi faris al vi? ili leviĝu, se ili povas vin savi en la tempo de via malfeliĉo; ĉar kiom da urboj, tiom da dioj vi havas, ho Jehuda."],[2,29,"Kial vi volas disputi kun Mi? vi ĉiuj defalis de Mi, diras la Eternulo.","Kial vi volas disputi kun Mi? vi ĉiuj defalis de Mi, diras la Eternulo."],[2,30,"Vane Mi frapis viajn infanojn, ili ne akceptis la moralinstruon; via glavo ekstermis viajn profetojn, kiel furioza leono.","Vane Mi frapis viajn infanojn, ili ne akceptis la moralinstruon; via glavo ekstermis viajn profetojn, kiel furioza leono."],[2,31,"Ho generacio, atentu la vorton de la Eternulo! Ĉu Mi estis por Izrael dezerto aŭ lando malluma? Kial do Mia popolo diras: Ni mem estas sinjoroj, ni ne plu iros al Vi?","Ho generacio, atentu la vorton de la Eternulo! Ĉu Mi estis por Izrael dezerto aŭ lando malluma? Kial do Mia popolo diras: Ni mem estas sinjoroj, ni ne plu iros al Vi?"],[2,32,"Ĉu virgulino forgesas sian ornamon, aŭ fianĉino sian ĉirkaŭligon? sed Mia popolo Min forgesis jam de tempo nekalkulebla.","Ĉu virgulino forgesas sian ornamon, aŭ fianĉino sian ĉirkaŭligon? sed Mia popolo Min forgesis jam de tempo nekalkulebla."],[2,33,"Kiel vi beligas vian vojon, por serĉi amon! al agoj malbonaj vi ja alkutimiĝis.","Kiel vi beligas vian vojon, por serĉi amon! al agoj malbonaj vi ja alkutimiĝis."],[2,34,"Eĉ sur viaj baskoj oni trovas sangon de malriĉuloj, senkulpuloj; ne en foskavoj Mi tion trovis, sed sur ĉiuj tiuj lokoj.","Eĉ sur viaj baskoj oni trovas sangon de malriĉuloj, senkulpuloj; ne en foskavoj Mi tion trovis, sed sur ĉiuj tiuj lokoj."],[2,35,"Vi diras: Mi estas senkulpa, Lia kolero deturnu sin de mi. Sed Mi postulos juĝon inter ni pro tio, ke vi diras: Mi ne pekis.","Vi diras: Mi estas senkulpa, Lia kolero deturnu sin de mi. Sed Mi postulos juĝon inter ni pro tio, ke vi diras: Mi ne pekis."],[2,36,"Kiel malestiminda vi fariĝis, ŝanĝante vian vojon! De Egiptujo vi estos tiel same hontigita, kiel vi estas hontigita de Asirio.","Kiel malestiminda vi fariĝis, ŝanĝante vian vojon! De Egiptujo vi estos tiel same hontigita, kiel vi estas hontigita de Asirio."],[2,37,"Ankaŭ el tie vi eliros kun la manoj sur la kapo, ĉar la Eternulo forpuŝis viajn esperojn kaj vi ne sukcesos kun ili.","Ankaŭ el tie vi eliros kun la manoj sur la kapo, ĉar la Eternulo forpuŝis viajn esperojn kaj vi ne sukcesos kun ili."],[3,1,"Oni diras: Se viro forigas sian edzinon, kaj ŝi foriras de li kaj edziniĝas kun alia viro, ĉu li tiam povas reveni al ŝi denove? ĉu ne malpuriĝus per tio tiu lando? Kaj vi malĉastis kun multaj amantoj; tamen revenu al Mi, diras la Eternulo.","Oni diras: Se viro forigas sian edzinon, kaj ŝi foriras de li kaj edziniĝas kun alia viro, ĉu li tiam povas reveni al ŝi denove? ĉu ne malpuriĝus per tio tiu lando? Kaj vi malĉastis kun multaj amantoj; tamen revenu al Mi, diras la Eternulo."],[3,2,"Levu viajn okulojn al la altaĵoj, kaj rigardu; kie vi ne adultis? Ĉe la vojoj vi sidis por ili, kiel Arabo en la dezerto, kaj vi malpurigis la landon per via malĉastado kaj malbonagoj.","Levu viajn okulojn al la altaĵoj, kaj rigardu; kie vi ne adultis? Ĉe la vojoj vi sidis por ili, kiel Arabo en la dezerto, kaj vi malpurigis la landon per via malĉastado kaj malbonagoj."],[3,3,"Pro tio estas retenitaj la pluvoj, kaj la printempa pluvo ne aperis; sed vi havas frunton de malĉastistino, vi ne plu volas honti.","Pro tio estas retenitaj la pluvoj, kaj la printempa pluvo ne aperis; sed vi havas frunton de malĉastistino, vi ne plu volas honti."],[3,4,"Tamen vi kriis al Mi: Mia patro, Vi, gvidinto de mia juneco!","Tamen vi kriis al Mi: Mia patro, Vi, gvidinto de mia juneco!"],[3,5,"ĉu Vi koleros eterne kaj konservos la koleron por ĉiam? Tiel vi parolas, kaj tamen vi faras malbonon kaj kontraŭstaras.","ĉu Vi koleros eterne kaj konservos la koleron por ĉiam? Tiel vi parolas, kaj tamen vi faras malbonon kaj kontraŭstaras."],[3,6,"La Eternulo diris al mi en la tempo de la reĝo Joŝija: Ĉu vi vidis, kion faris la defalinta Izrael? ŝi iris sur ĉiun altan monton kaj sub ĉiun verdan arbon kaj tie malĉastis.","La Eternulo diris al mi en la tempo de la reĝo Joŝija: Ĉu vi vidis, kion faris la defalinta Izrael? ŝi iris sur ĉiun altan monton kaj sub ĉiun verdan arbon kaj tie malĉastis."],[3,7,"Kaj post kiam ŝi faris ĉion ĉi tion, Mi diris: Revenu al Mi; sed ŝi ne revenis. Kaj tion vidis ŝia perfidema fratino Judujo.","Kaj post kiam ŝi faris ĉion ĉi tion, Mi diris: Revenu al Mi; sed ŝi ne revenis. Kaj tion vidis ŝia perfidema fratino Judujo."],[3,8,"Mi vidis ĉiujn adultaĵojn de la defalinta Izrael, kaj Mi forpelis ŝin kaj donis al ŝi eksedzigan leteron; tamen ne ektimis ŝia perfidema fratino Judujo, sed ŝi iris kaj ankaŭ malĉastis.","Mi vidis ĉiujn adultaĵojn de la defalinta Izrael, kaj Mi forpelis ŝin kaj donis al ŝi eksedzigan leteron; tamen ne ektimis ŝia perfidema fratino Judujo, sed ŝi iris kaj ankaŭ malĉastis."],[3,9,"Kaj de la bruo de ŝia malĉastado malpuriĝis la lando, kaj ŝi adultis kun ŝtono kaj kun ligno.","Kaj de la bruo de ŝia malĉastado malpuriĝis la lando, kaj ŝi adultis kun ŝtono kaj kun ligno."],[3,10,"Kaj malgraŭ ĉio ŝia perfidema fratino Judujo revenis al Mi ne per sia tuta koro, sed nur hipokrite, diras la Eternulo.","Kaj malgraŭ ĉio ŝia perfidema fratino Judujo revenis al Mi ne per sia tuta koro, sed nur hipokrite, diras la Eternulo."],[3,11,"Kaj la Eternulo diris al mi: La defalinta Izrael estas piulino en komparo kun la perfidema Judujo.","Kaj la Eternulo diris al mi: La defalinta Izrael estas piulino en komparo kun la perfidema Judujo."],[3,12,"Iru, kaj proklamu ĉi tiujn vortojn norden, kaj diru: Revenu, defalinta Izrael, diras la Eternulo; Mi ne forturnos de vi Mian vizaĝon, ĉar Mi estas kompatema, diras la Eternulo, Mi ne koleros eterne.","Iru, kaj proklamu ĉi tiujn vortojn norden, kaj diru: Revenu, defalinta Izrael, diras la Eternulo; Mi ne forturnos de vi Mian vizaĝon, ĉar Mi estas kompatema, diras la Eternulo, Mi ne koleros eterne."],[3,13,"Nur konfesu vian kulpon, ke vi pekis kontraŭ la Eternulo, via Dio, kaj kuradis al aliaj sub ĉiun verdan arbon, kaj Mian voĉon vi ne aŭskultis, diras la Eternulo.","Nur konfesu vian kulpon, ke vi pekis kontraŭ la Eternulo, via Dio, kaj kuradis al aliaj sub ĉiun verdan arbon, kaj Mian voĉon vi ne aŭskultis, diras la Eternulo."],[3,14,"Revenu, defalintaj infanoj, diras la Eternulo, ĉar Mi estas via sinjoro, kaj Mi prenos vin po unu el urbo kaj po du el tribo kaj venigos vin en Cionon.","Revenu, defalintaj infanoj, diras la Eternulo, ĉar Mi estas via sinjoro, kaj Mi prenos vin po unu el urbo kaj po du el tribo kaj venigos vin en Cionon."],[3,15,"Kaj Mi donos al vi paŝtistojn laŭ Mia koro, kiuj paŝtos vin kun sciado kaj saĝeco.","Kaj Mi donos al vi paŝtistojn laŭ Mia koro, kiuj paŝtos vin kun sciado kaj saĝeco."],[3,16,"Kaj kiam vi kreskos kaj multiĝos en la lando en tiu tempo, diras la Eternulo, oni ne plu parolos pri la kesto de interligo de la Eternulo; ĝi ne venos en la koron, oni ne rememoros ĝin, oni ne serĉos ĝin, oni ne faros ĝin denove.","Kaj kiam vi kreskos kaj multiĝos en la lando en tiu tempo, diras la Eternulo, oni ne plu parolos pri la kesto de interligo de la Eternulo; ĝi ne venos en la koron, oni ne rememoros ĝin, oni ne serĉos ĝin, oni ne faros ĝin denove."],[3,17,"En tiu tempo oni nomos Jerusalemon trono de la Eternulo, kaj tie kolektiĝos ĉiuj popoloj en la nomo de la Eternulo, en Jerusalem, kaj ili ne plu sekvos la logojn de sia malbona koro.","En tiu tempo oni nomos Jerusalemon trono de la Eternulo, kaj tie kolektiĝos ĉiuj popoloj en la nomo de la Eternulo, en Jerusalem, kaj ili ne plu sekvos la logojn de sia malbona koro."],[3,18,"En tiu tempo la domo de Jehuda iros al la domo de Izrael, kaj ili kune iros el la norda lando en la landon, kiun Mi donis kiel heredaĵon al viaj patroj.","En tiu tempo la domo de Jehuda iros al la domo de Izrael, kaj ili kune iros el la norda lando en la landon, kiun Mi donis kiel heredaĵon al viaj patroj."],[3,19,"Mi diris: Kiamaniere Mi alkalkulos vin al la filoj, kaj donos al vi la ĉarman landon, la plej belan heredaĵon inter multe da popoloj? Kaj Mi diris: Vi nomos Min patro, kaj vi ne fordeturnos vin de Mi.","Mi diris: Kiamaniere Mi alkalkulos vin al la filoj, kaj donos al vi la ĉarman landon, la plej belan heredaĵon inter multe da popoloj? Kaj Mi diris: Vi nomos Min patro, kaj vi ne fordeturnos vin de Mi."],[3,20,"Sed kiel virino, kiu perfidis sian amanton, tiel vi perfidis Min, ho domo de Izrael, diras la Eternulo.","Sed kiel virino, kiu perfidis sian amanton, tiel vi perfidis Min, ho domo de Izrael, diras la Eternulo."],[3,21,"Voĉo estas aŭdata sur la altaĵoj, plenda plorado de la filoj de Izrael, ĉar ili malvirtigis sian vojon, forgesis la Eternulon, sian Dion.","Voĉo estas aŭdata sur la altaĵoj, plenda plorado de la filoj de Izrael, ĉar ili malvirtigis sian vojon, forgesis la Eternulon, sian Dion."],[3,22,"Revenu, defalintaj infanoj; Mi resanigos vian defalon. Jen ni venis al Vi, ĉar Vi estas la Eternulo, nia Dio.","Revenu, defalintaj infanoj; Mi resanigos vian defalon. Jen ni venis al Vi, ĉar Vi estas la Eternulo, nia Dio."],[3,23,"Vere, mensogo estis en la altaĵoj, en la multo da montoj; nur en la Eternulo, nia Dio, estas la savo de Izrael.","Vere, mensogo estis en la altaĵoj, en la multo da montoj; nur en la Eternulo, nia Dio, estas la savo de Izrael."],[3,24,"La hontindaĵo formanĝis la penadon de niaj patroj de post nia juneco: iliajn ŝafojn, iliajn bovojn, iliajn filojn, kaj iliajn filinojn.","La hontindaĵo formanĝis la penadon de niaj patroj de post nia juneco: iliajn ŝafojn, iliajn bovojn, iliajn filojn, kaj iliajn filinojn."],[3,25,"Ni kuŝu en nia abomenindaĵo, kaj nia hontindaĵo nin kovru; ĉar kontraŭ la Eternulo, nia Dio, ni pekis, ni kaj niaj patroj, de nia juneco ĝis la nuna tago, kaj ni ne aŭskultis la voĉon de la Eternulo, nia Dio.","Ni kuŝu en nia abomenindaĵo, kaj nia hontindaĵo nin kovru; ĉar kontraŭ la Eternulo, nia Dio, ni pekis, ni kaj niaj patroj, de nia juneco ĝis la nuna tago, kaj ni ne aŭskultis la voĉon de la Eternulo, nia Dio."],[4,1,"Se vi volas rekonverti vin, ho Izrael, diras la Eternulo, rekonvertu vin al Mi; kaj se vi forigos viajn abomenindaĵojn de antaŭ Mia vizaĝo, kaj ne plu vagados,","Se vi volas rekonverti vin, ho Izrael, diras la Eternulo, rekonvertu vin al Mi; kaj se vi forigos viajn abomenindaĵojn de antaŭ Mia vizaĝo, kaj ne plu vagados,"],[4,2,"kaj se vi en vero, bonordo, kaj pieco ĵuros: Kiel la Eternulo vivas, tiam ankaŭ la popoloj benos sin per Li kaj gloros sin per Li.","kaj se vi en vero, bonordo, kaj pieco ĵuros: Kiel la Eternulo vivas, tiam ankaŭ la popoloj benos sin per Li kaj gloros sin per Li."],[4,3,"Ĉar tiele diras la Eternulo al la viroj de Judujo kaj al Jerusalem: Plugu al vi novan plugokampon, kaj ne semu inter dornaĵo.","Ĉar tiele diras la Eternulo al la viroj de Judujo kaj al Jerusalem: Plugu al vi novan plugokampon, kaj ne semu inter dornaĵo."],[4,4,"Cirkumcidu vin al la Eternulo kaj forigu la prepucion de via koro, ho viroj de Judujo kaj loĝantoj de Jerusalem, por ke Mia kolero ne eliru kiel fajro kaj ne brulu pro viaj malbonagoj tiel, ke neniu ĝin estingos.","Cirkumcidu vin al la Eternulo kaj forigu la prepucion de via koro, ho viroj de Judujo kaj loĝantoj de Jerusalem, por ke Mia kolero ne eliru kiel fajro kaj ne brulu pro viaj malbonagoj tiel, ke neniu ĝin estingos."],[4,5,"Proklamu en Judujo, aŭdigu en Jerusalem, prediku kaj trumpetu en la lando; voku per plena voĉo, kaj diru: Kolektiĝu, kaj ni iru en la fortikigitajn urbojn.","Proklamu en Judujo, aŭdigu en Jerusalem, prediku kaj trumpetu en la lando; voku per plena voĉo, kaj diru: Kolektiĝu, kaj ni iru en la fortikigitajn urbojn."],[4,6,"Levu standardon en Cion, kuru, ne haltu; ĉar malfeliĉon Mi venigas de nordo kaj grandan pereon.","Levu standardon en Cion, kuru, ne haltu; ĉar malfeliĉon Mi venigas de nordo kaj grandan pereon."],[4,7,"Leono leviĝas el sia densejo, kaj pereiganto de popoloj elmoviĝas kaj eliras el sia loko, por fari vian landon dezerto; viaj urboj estos detruitaj, kaj neniu loĝos en ili.","Leono leviĝas el sia densejo, kaj pereiganto de popoloj elmoviĝas kaj eliras el sia loko, por fari vian landon dezerto; viaj urboj estos detruitaj, kaj neniu loĝos en ili."],[4,8,"Pro tio zonu vin per sakaĵo, ploru kaj ĝemu, ĉar la flama kolero de la Eternulo ne foriĝas de ni.","Pro tio zonu vin per sakaĵo, ploru kaj ĝemu, ĉar la flama kolero de la Eternulo ne foriĝas de ni."],[4,9,"En tiu tago, diras la Eternulo, senviviĝos la koro de la reĝo kaj la koro de la princoj, konsterniĝos la pastroj, kaj la profetoj konfuziĝos.","En tiu tago, diras la Eternulo, senviviĝos la koro de la reĝo kaj la koro de la princoj, konsterniĝos la pastroj, kaj la profetoj konfuziĝos."],[4,10,"Kaj mi diris: Ho Sinjoro, ho Eternulo! ĉu Vi erarigis ĉi tiun popolon kaj Jerusalemon, dirinte: Vi havos pacon — kaj dume la glavo atingis jam la animon?","Kaj mi diris: Ho Sinjoro, ho Eternulo! ĉu Vi erarigis ĉi tiun popolon kaj Jerusalemon, dirinte: Vi havos pacon — kaj dume la glavo atingis jam la animon?"],[4,11,"En tiu tempo oni diros al tiu popolo kaj al Jerusalem: Seka vento de la altaĵoj en la dezerto venas sur la vojon de la filino de Mia popolo, ne por ventumi kaj ne por purigi;","En tiu tempo oni diros al tiu popolo kaj al Jerusalem: Seka vento de la altaĵoj en la dezerto venas sur la vojon de la filino de Mia popolo, ne por ventumi kaj ne por purigi;"],[4,12,"vento pli forta ol ili venos al Mi; tiam Mi diros Mian verdikton kontraŭ ili.","vento pli forta ol ili venos al Mi; tiam Mi diros Mian verdikton kontraŭ ili."],[4,13,"Jen ĝi leviĝas kiel nuboj, kaj ĝiaj ĉaroj estas kiel ventegoj, ĝiaj ĉevaloj estas pli rapidaj ol agloj; ve al ni! ni estos ruinigitaj.","Jen ĝi leviĝas kiel nuboj, kaj ĝiaj ĉaroj estas kiel ventegoj, ĝiaj ĉevaloj estas pli rapidaj ol agloj; ve al ni! ni estos ruinigitaj."],[4,14,"Lavu de la malbono vian koron, ho Jerusalem, por ke vi saviĝu; ĝis kiam loĝos en vi viaj malbonaj pensoj?","Lavu de la malbono vian koron, ho Jerusalem, por ke vi saviĝu; ĝis kiam loĝos en vi viaj malbonaj pensoj?"],[4,15,"Venas voko el la regiono de Dan, kaj malbona sciigo de la monto de Efraim:","Venas voko el la regiono de Dan, kaj malbona sciigo de la monto de Efraim:"],[4,16,"Sciigu al la popoloj, aŭdigu pri Jerusalem, ke sieĝontoj venas el lando malproksima kaj sonigas sian voĉon kontraŭ la urboj de Judujo.","Sciigu al la popoloj, aŭdigu pri Jerusalem, ke sieĝontoj venas el lando malproksima kaj sonigas sian voĉon kontraŭ la urboj de Judujo."],[4,17,"Kiel kampogardistoj ili ĉirkaŭas ĝin, ĉar ĝi ribelis kontraŭ Mi, diras la Eternulo.","Kiel kampogardistoj ili ĉirkaŭas ĝin, ĉar ĝi ribelis kontraŭ Mi, diras la Eternulo."],[4,18,"Via konduto kaj viaj faroj kaŭzis tion al vi, tiu via malboneco, ĉar ĝi estas maldolĉa, ĉar ĝi penetris ĝis via koro.","Via konduto kaj viaj faroj kaŭzis tion al vi, tiu via malboneco, ĉar ĝi estas maldolĉa, ĉar ĝi penetris ĝis via koro."],[4,19,"Mia internaĵo, mia internaĵo min doloras, batas mia koro, mi ne povas silenti; ĉar vi, mia animo, aŭdis sonon de korno, trumpetadon de batalo.","Mia internaĵo, mia internaĵo min doloras, batas mia koro, mi ne povas silenti; ĉar vi, mia animo, aŭdis sonon de korno, trumpetadon de batalo."],[4,20,"Estas proklamata malfeliĉo post malfeliĉo, ĉar la tuta lando estas ruinigata, subite estas detruataj miaj domoj, momente miaj tendoj.","Estas proklamata malfeliĉo post malfeliĉo, ĉar la tuta lando estas ruinigata, subite estas detruataj miaj domoj, momente miaj tendoj."],[4,21,"Kiel longe ankoraŭ mi vidos standardon, aŭdos sonadon de korno?","Kiel longe ankoraŭ mi vidos standardon, aŭdos sonadon de korno?"],[4,22,"Ĉar Mia popolo estas freneza, Min ili ne rekonas; ili estas malsaĝaj infanoj, ili ne komprenas; saĝaj ili estas por fari malbonon, sed fari bonon ili ne povoscias.","Ĉar Mia popolo estas freneza, Min ili ne rekonas; ili estas malsaĝaj infanoj, ili ne komprenas; saĝaj ili estas por fari malbonon, sed fari bonon ili ne povoscias."],[4,23,"Mi rigardas la teron, kaj jen ĝi estas malplena kaj dezerta; la ĉielon, kaj jen ĝi estas senluma.","Mi rigardas la teron, kaj jen ĝi estas malplena kaj dezerta; la ĉielon, kaj jen ĝi estas senluma."],[4,24,"Mi rigardas la montojn — ili tremas, kaj ĉiuj montetoj ŝanceliĝas.","Mi rigardas la montojn — ili tremas, kaj ĉiuj montetoj ŝanceliĝas."],[4,25,"Mi rigardas — troviĝas neniu homo, kaj ĉiuj birdoj de la ĉielo disflugis.","Mi rigardas — troviĝas neniu homo, kaj ĉiuj birdoj de la ĉielo disflugis."],[4,26,"Mi rigardas — la fruktoriĉa lando fariĝis dezerto, kaj ĉiuj ĝiaj urboj estas detruitaj de la Eternulo, de la flamo de Lia kolero.","Mi rigardas — la fruktoriĉa lando fariĝis dezerto, kaj ĉiuj ĝiaj urboj estas detruitaj de la Eternulo, de la flamo de Lia kolero."],[4,27,"Ĉar tiele diras la Eternulo: Dezertigita estos la tuta lando, sed plenan ekstermon Mi ne faros.","Ĉar tiele diras la Eternulo: Dezertigita estos la tuta lando, sed plenan ekstermon Mi ne faros."],[4,28,"Pro tio la tero ploros kaj la ĉielo supre malĝojos; ĉar Mi eldiris Mian decidon, kaj Mi ne bedaŭras, kaj Mi ne reprenos ĝin.","Pro tio la tero ploros kaj la ĉielo supre malĝojos; ĉar Mi eldiris Mian decidon, kaj Mi ne bedaŭras, kaj Mi ne reprenos ĝin."],[4,29,"Pro la bruo de la rajdantoj kaj pafantoj forkuras la tuta urbo; oni kuras en densajn arbarojn, grimpas sur rokojn; ĉiuj urboj malpleniĝis, kaj neniu en ili loĝas.","Pro la bruo de la rajdantoj kaj pafantoj forkuras la tuta urbo; oni kuras en densajn arbarojn, grimpas sur rokojn; ĉiuj urboj malpleniĝis, kaj neniu en ili loĝas."],[4,30,"Kaj vi, dezertigita, kion vi faros? Eĉ se vi metos sur vin purpuron, se vi ornamos vin per oraj ornamoj, se vi ruĝe kolorigos vian vizaĝon, vi ornamos vin vane: viaj amantoj vin malestimos, ili volos vin mortigi.","Kaj vi, dezertigita, kion vi faros? Eĉ se vi metos sur vin purpuron, se vi ornamos vin per oraj ornamoj, se vi ruĝe kolorigos vian vizaĝon, vi ornamos vin vane: viaj amantoj vin malestimos, ili volos vin mortigi."],[4,31,"Ĉar Mi aŭdas krion kiel de naskantino, ĝemegadon kiel de virino naskanta la unuan infanon, krion de la filino de Cion; ŝi ĝemas, kaj etendas siajn manojn: Ho ve al mi! ĉar mia animo pereas de la mortigantoj.","Ĉar Mi aŭdas krion kiel de naskantino, ĝemegadon kiel de virino naskanta la unuan infanon, krion de la filino de Cion; ŝi ĝemas, kaj etendas siajn manojn: Ho ve al mi! ĉar mia animo pereas de la mortigantoj."],[5,1,"Trairu la stratojn de Jerusalem kaj rigardu, esploru kaj serĉu sur ĝiaj palacoj, ĉu vi trovos homon, kiu agas juste, kiu serĉas la veron — tiam Mi pardonos al ĝi.","Trairu la stratojn de Jerusalem kaj rigardu, esploru kaj serĉu sur ĝiaj palacoj, ĉu vi trovos homon, kiu agas juste, kiu serĉas la veron — tiam Mi pardonos al ĝi."],[5,2,"Eĉ se ili diras: Mi ĵuras per la Eternulo — ili tamen ĵuras mensoge.","Eĉ se ili diras: Mi ĵuras per la Eternulo — ili tamen ĵuras mensoge."],[5,3,"Ho Eternulo, Viaj okuloj rigardas ja la fidelecon; Vi batas ilin, sed ili ne sentas doloron; Vi preskaŭ pereigas ilin, sed ili ne volas preni moralinstruon; sian vizaĝon ili faris pli malmola ol roko, ili ne volas konvertiĝi.","Ho Eternulo, Viaj okuloj rigardas ja la fidelecon; Vi batas ilin, sed ili ne sentas doloron; Vi preskaŭ pereigas ilin, sed ili ne volas preni moralinstruon; sian vizaĝon ili faris pli malmola ol roko, ili ne volas konvertiĝi."],[5,4,"Mi diris al mi: Eble ili estas malriĉuloj, malkleruloj, ili ne konas la vojon de la Eternulo, la leĝojn de sia Dio;","Mi diris al mi: Eble ili estas malriĉuloj, malkleruloj, ili ne konas la vojon de la Eternulo, la leĝojn de sia Dio;"],[5,5,"mi iros al la eminentuloj, kaj mi parolos kun ili: ili ja konas la vojon de la Eternulo, la leĝojn de sia Dio; sed ankaŭ ili ĉiuj kune rompis la jugon, disŝiris la ŝnurojn.","mi iros al la eminentuloj, kaj mi parolos kun ili: ili ja konas la vojon de la Eternulo, la leĝojn de sia Dio; sed ankaŭ ili ĉiuj kune rompis la jugon, disŝiris la ŝnurojn."],[5,6,"Pro tio mortigos ilin leono el la arbaro, lupo el la stepo ilin prirabos, leopardo atendos ilin apud iliaj urboj; ĉiu, kiu eliros el tie, estos disŝirata. Ĉar multaj fariĝis iliaj krimoj, fortaj fariĝis iliaj perfidoj.","Pro tio mortigos ilin leono el la arbaro, lupo el la stepo ilin prirabos, leopardo atendos ilin apud iliaj urboj; ĉiu, kiu eliros el tie, estos disŝirata. Ĉar multaj fariĝis iliaj krimoj, fortaj fariĝis iliaj perfidoj."],[5,7,"Kiel Mi tion pardonus al vi? viaj filoj Min forlasis kaj ĵuris per ne-dioj. Mi ĵurigis ilin, sed ili adultas kaj iras amase en malĉastejojn.","Kiel Mi tion pardonus al vi? viaj filoj Min forlasis kaj ĵuris per ne-dioj. Mi ĵurigis ilin, sed ili adultas kaj iras amase en malĉastejojn."],[5,8,"Ili fariĝis kiel voluptemaj pasiaj ĉevaloj; ĉiu blekas al la edzino de sia proksimulo.","Ili fariĝis kiel voluptemaj pasiaj ĉevaloj; ĉiu blekas al la edzino de sia proksimulo."],[5,9,"Ĉu Mi povas ne puni pro tio? diras la Eternulo; kaj ĉu al tia popolo Mia animo povas ne venĝi?","Ĉu Mi povas ne puni pro tio? diras la Eternulo; kaj ĉu al tia popolo Mia animo povas ne venĝi?"],[5,10,"Iru sur ĝiajn muregojn kaj detruu ilin, tamen ne tute ekstermu; forigu ĝiajn branĉojn, ĉar ne por la Eternulo ili estas.","Iru sur ĝiajn muregojn kaj detruu ilin, tamen ne tute ekstermu; forigu ĝiajn branĉojn, ĉar ne por la Eternulo ili estas."],[5,11,"Ĉar forte perfidis Min la domo de Izrael kaj la domo de Jehuda, diras la Eternulo.","Ĉar forte perfidis Min la domo de Izrael kaj la domo de Jehuda, diras la Eternulo."],[5,12,"Ili neis la ekzistadon de la Eternulo, kaj diris: Li ne ekzistas, kaj ne venos sur nin malbono, kaj glavon kaj malsaton ni ne vidos.","Ili neis la ekzistadon de la Eternulo, kaj diris: Li ne ekzistas, kaj ne venos sur nin malbono, kaj glavon kaj malsaton ni ne vidos."],[5,13,"Kaj la profetoj estas kiel vento, ne troviĝas en ili la vorto de Dio; tiel fariĝu al ili.","Kaj la profetoj estas kiel vento, ne troviĝas en ili la vorto de Dio; tiel fariĝu al ili."],[5,14,"Pro tio tiele diras la Eternulo, Dio Cebaot: Pro tio, ke vi parolas tiajn vortojn, jen Mi metos Miajn vortojn en vian buŝon kiel fajron, kaj ĉi tiu popolo estos kiel ligno, kiun ĝi konsumos.","Pro tio tiele diras la Eternulo, Dio Cebaot: Pro tio, ke vi parolas tiajn vortojn, jen Mi metos Miajn vortojn en vian buŝon kiel fajron, kaj ĉi tiu popolo estos kiel ligno, kiun ĝi konsumos."],[5,15,"Jen Mi venigos sur vin, sur la domon de Izrael, popolon de malproksime, diras la Eternulo, popolon fortan, popolon antikvan, popolon, kies lingvon vi ne scias; kaj vi ne komprenos, kion ĝi parolas.","Jen Mi venigos sur vin, sur la domon de Izrael, popolon de malproksime, diras la Eternulo, popolon fortan, popolon antikvan, popolon, kies lingvon vi ne scias; kaj vi ne komprenos, kion ĝi parolas."],[5,16,"Ĝia sagujo estas kiel malfermita tombo; ĉiuj ili estas herooj.","Ĝia sagujo estas kiel malfermita tombo; ĉiuj ili estas herooj."],[5,17,"Ĝi formanĝos vian rikolton kaj vian panon, ekstermos viajn filojn kaj viajn filinojn, formanĝos viajn ŝafojn kaj viajn bovojn, formanĝos viajn vinberojn kaj viajn figojn, detruos per glavo viajn fortikigitajn urbojn, kiujn vi fidas.","Ĝi formanĝos vian rikolton kaj vian panon, ekstermos viajn filojn kaj viajn filinojn, formanĝos viajn ŝafojn kaj viajn bovojn, formanĝos viajn vinberojn kaj viajn figojn, detruos per glavo viajn fortikigitajn urbojn, kiujn vi fidas."],[5,18,"Sed eĉ en tiu tempo, diras la Eternulo, Mi ne pereigos vin tute.","Sed eĉ en tiu tempo, diras la Eternulo, Mi ne pereigos vin tute."],[5,19,"Kaj kiam oni demandos: Pro kio la Eternulo, nia Dio, faras al ni ĉion ĉi tion? tiam diru al ili: Kiel vi forlasis Min kaj servas al fremdaj dioj en via lando, tiel vi servos al fremduloj en lando, kiu ne apartenas al vi.","Kaj kiam oni demandos: Pro kio la Eternulo, nia Dio, faras al ni ĉion ĉi tion? tiam diru al ili: Kiel vi forlasis Min kaj servas al fremdaj dioj en via lando, tiel vi servos al fremduloj en lando, kiu ne apartenas al vi."],[5,20,"Anoncu tion en la domo de Jakob kaj aŭdigu en Judujo, dirante:","Anoncu tion en la domo de Jakob kaj aŭdigu en Judujo, dirante:"],[5,21,"Aŭskultu ĉi tion, ho popolo malsaĝa kaj senkora, kiu havas okulojn, sed ne vidas, havas orelojn, sed ne aŭdas.","Aŭskultu ĉi tion, ho popolo malsaĝa kaj senkora, kiu havas okulojn, sed ne vidas, havas orelojn, sed ne aŭdas."],[5,22,"Ĉu vi ne timas Min? diras la Eternulo; ĉu vi ne tremas antaŭ Mi, kiu faris sablon limo por la maro, aranĝo eterna, kiun ĝi ne transpaŝas? kiom ajn ĝi skuiĝas, ĝi nenion povas fari; kiom ajn bruas ĝiaj ondoj, ili ne povas ĝin transpaŝi.","Ĉu vi ne timas Min? diras la Eternulo; ĉu vi ne tremas antaŭ Mi, kiu faris sablon limo por la maro, aranĝo eterna, kiun ĝi ne transpaŝas? kiom ajn ĝi skuiĝas, ĝi nenion povas fari; kiom ajn bruas ĝiaj ondoj, ili ne povas ĝin transpaŝi."],[5,23,"Sed ĉi tiu popolo havas koron defaleman kaj neobeeman, ili defalis kaj foriris.","Sed ĉi tiu popolo havas koron defaleman kaj neobeeman, ili defalis kaj foriris."],[5,24,"Kaj ili ne diris en sia koro: Ni timu la Eternulon, nian Dion, kiu donas al ni pluvon frusezonan kaj malfrusezonan en ĝia tempo, kiu gardas por ni la semajnojn, destinitajn por la rikolto.","Kaj ili ne diris en sia koro: Ni timu la Eternulon, nian Dion, kiu donas al ni pluvon frusezonan kaj malfrusezonan en ĝia tempo, kiu gardas por ni la semajnojn, destinitajn por la rikolto."],[5,25,"Viaj malbonagoj tion forklinis, kaj viaj pekoj forigis de vi la bonon.","Viaj malbonagoj tion forklinis, kaj viaj pekoj forigis de vi la bonon."],[5,26,"Ĉar inter Mia popolo troviĝas malvirtuloj, kiuj faras insidojn, starigas pereigajn kaptilojn, kaptas la homojn.","Ĉar inter Mia popolo troviĝas malvirtuloj, kiuj faras insidojn, starigas pereigajn kaptilojn, kaptas la homojn."],[5,27,"Kiel birdejo estas plena de birdoj, tiel iliaj domoj estas plenaj de trompakiraĵoj; tial ili fariĝis grandaj kaj riĉaj.","Kiel birdejo estas plena de birdoj, tiel iliaj domoj estas plenaj de trompakiraĵoj; tial ili fariĝis grandaj kaj riĉaj."],[5,28,"Ili fariĝis grasaj, ili fariĝis dikaj; ili faris malbonajn agojn; juĝon ili ne faras, juĝon pri orfo, sed ili ĝuas la vivon; justecon al malriĉuloj ili ne faras.","Ili fariĝis grasaj, ili fariĝis dikaj; ili faris malbonajn agojn; juĝon ili ne faras, juĝon pri orfo, sed ili ĝuas la vivon; justecon al malriĉuloj ili ne faras."],[5,29,"Ĉu Mi povas lasi tion sen puno? diras la Eternulo; ĉu al tia popolo Mia animo ne venĝos?","Ĉu Mi povas lasi tion sen puno? diras la Eternulo; ĉu al tia popolo Mia animo ne venĝos?"],[5,30,"Io konsterna kaj terura fariĝis en la lando:","Io konsterna kaj terura fariĝis en la lando:"],[5,31,"la profetoj profetas malveraĵon, kaj la pastroj regas per ili; kaj al mia popolo tio plaĉas. Kaj kion vi faros en la estonteco?","la profetoj profetas malveraĵon, kaj la pastroj regas per ili; kaj al mia popolo tio plaĉas. Kaj kion vi faros en la estonteco?"],[6,1,"Kuru rapide, ho filoj de Benjamen, el Jerusalem, kaj en Tekoa sonigu la trumpeton kaj super Bet-Kerem faru signalon; ĉar de nordo aperas malbono kaj granda pereo.","Kuru rapide, ho filoj de Benjamen, el Jerusalem, kaj en Tekoa sonigu la trumpeton kaj super Bet-Kerem faru signalon; ĉar de nordo aperas malbono kaj granda pereo."],[6,2,"Al bela kaj delikata virino Mi similigis la filinon de Cion.","Al bela kaj delikata virino Mi similigis la filinon de Cion."],[6,3,"Al ŝi venos paŝtistoj kun siaj brutaroj, ĉirkaŭ ŝi ili starigos tendojn, kaj ĉiu paŝtos sur sia loko.","Al ŝi venos paŝtistoj kun siaj brutaroj, ĉirkaŭ ŝi ili starigos tendojn, kaj ĉiu paŝtos sur sia loko."],[6,4,"Aranĝu militon kontraŭ ŝi; leviĝu, ni iru en tagmezo. Ho ve al ni! ĉar baldaŭ vesperiĝos, etendiĝas la ombroj de vespero.","Aranĝu militon kontraŭ ŝi; leviĝu, ni iru en tagmezo. Ho ve al ni! ĉar baldaŭ vesperiĝos, etendiĝas la ombroj de vespero."],[6,5,"Leviĝu, ni iru nokte, kaj ni detruu ŝiajn palacojn.","Leviĝu, ni iru nokte, kaj ni detruu ŝiajn palacojn."],[6,6,"Ĉar tiele diras la Eternulo Cebaot: Haku ŝiajn arbojn kaj aranĝu remparon ĉirkaŭ Jerusalem; ĉi tiun urbon oni devas puni, ĝi estas tute plena de malbonagoj.","Ĉar tiele diras la Eternulo Cebaot: Haku ŝiajn arbojn kaj aranĝu remparon ĉirkaŭ Jerusalem; ĉi tiun urbon oni devas puni, ĝi estas tute plena de malbonagoj."],[6,7,"Kiel fonto elfluigas sian akvon, tiel ĝi elfluigas el si malbonon; nur perforteco kaj rabado estas aŭdataj en ĝi, antaŭ Mi estas ĉiam turmentado kaj batado.","Kiel fonto elfluigas sian akvon, tiel ĝi elfluigas el si malbonon; nur perforteco kaj rabado estas aŭdataj en ĝi, antaŭ Mi estas ĉiam turmentado kaj batado."],[6,8,"Prudentiĝu, ho Jerusalem, por ke ne foriĝu de vi Mia animo, por ke Mi ne faru vin dezerto, lando ne loĝata.","Prudentiĝu, ho Jerusalem, por ke ne foriĝu de vi Mia animo, por ke Mi ne faru vin dezerto, lando ne loĝata."],[6,9,"Tiele diras la Eternulo Cebaot: Oni kolektu la restaĵon de Izrael kiel restaĵon de vinberoj; eltiru kaj retiru vian manon, kiel ŝirkolektanto de vinberoj super la korboj.","Tiele diras la Eternulo Cebaot: Oni kolektu la restaĵon de Izrael kiel restaĵon de vinberoj; eltiru kaj retiru vian manon, kiel ŝirkolektanto de vinberoj super la korboj."],[6,10,"Kun kiu Mi parolu, kiun Mi admonu, ke oni Min aŭskultu? ilia orelo ne estas cirkumcidita, kaj ili ne povas aŭdi. Jen la vorton de la Eternulo ili malŝatas; ili ne deziras ĝin.","Kun kiu Mi parolu, kiun Mi admonu, ke oni Min aŭskultu? ilia orelo ne estas cirkumcidita, kaj ili ne povas aŭdi. Jen la vorton de la Eternulo ili malŝatas; ili ne deziras ĝin."],[6,11,"Tial Mi pleniĝis de kolero de la Eternulo, Mi ne plu povas toleri; elverŝu ĝin sur la infanojn sur la strato kaj sur la interkonsiliĝon de la junuloj; kiel viro, tiel ankaŭ virino estos kaptita, maljunulo kaj profundaĝulo.","Tial Mi pleniĝis de kolero de la Eternulo, Mi ne plu povas toleri; elverŝu ĝin sur la infanojn sur la strato kaj sur la interkonsiliĝon de la junuloj; kiel viro, tiel ankaŭ virino estos kaptita, maljunulo kaj profundaĝulo."],[6,12,"Iliaj domoj transiros al aliuloj, ankaŭ la kampoj kaj la edzinoj; ĉar Mi etendos Mian manon sur la loĝantojn de la lando, diras la Eternulo.","Iliaj domoj transiros al aliuloj, ankaŭ la kampoj kaj la edzinoj; ĉar Mi etendos Mian manon sur la loĝantojn de la lando, diras la Eternulo."],[6,13,"Ĉar ĉiuj, de la malgrandaj ĝis la grandaj, estas profitavidaj; kaj de la profetoj ĝis la pastroj ĉiuj faras malhonestaĵon.","Ĉar ĉiuj, de la malgrandaj ĝis la grandaj, estas profitavidaj; kaj de la profetoj ĝis la pastroj ĉiuj faras malhonestaĵon."],[6,14,"Kaj la vundojn de Mia popolo ili kuracas per facilanimigo, dirante, ke ĉio estas en bona stato, kvankam ne estas bona stato.","Kaj la vundojn de Mia popolo ili kuracas per facilanimigo, dirante, ke ĉio estas en bona stato, kvankam ne estas bona stato."],[6,15,"Ĉu ili hontas, ke ili faras abomenindaĵon? ili tute ne hontas, ili eĉ ne povoscias ruĝiĝi; tial ili falos inter la falantoj, ili renversiĝos, kiam Mi vizitos ilin, diras la Eternulo.","Ĉu ili hontas, ke ili faras abomenindaĵon? ili tute ne hontas, ili eĉ ne povoscias ruĝiĝi; tial ili falos inter la falantoj, ili renversiĝos, kiam Mi vizitos ilin, diras la Eternulo."],[6,16,"Tiele diras la Eternulo: Stariĝu sur la vojoj kaj rigardu, kaj demandu pri la vojoj antikvaj, kia estas la bona vojo, kaj iru laŭ ĝi kaj trovu ripozon por via animo. Sed ili diris: Ni ne iros.","Tiele diras la Eternulo: Stariĝu sur la vojoj kaj rigardu, kaj demandu pri la vojoj antikvaj, kia estas la bona vojo, kaj iru laŭ ĝi kaj trovu ripozon por via animo. Sed ili diris: Ni ne iros."],[6,17,"Kaj Mi starigis gardistojn super vi, dirante: Atentu la sonadon de la trumpeto. Sed ili diris: Ni ne atentos.","Kaj Mi starigis gardistojn super vi, dirante: Atentu la sonadon de la trumpeto. Sed ili diris: Ni ne atentos."],[6,18,"Tial aŭdu, ho popoloj, kaj sciu, ho komunumoj, kio fariĝas ĉe ili.","Tial aŭdu, ho popoloj, kaj sciu, ho komunumoj, kio fariĝas ĉe ili."],[6,19,"Aŭskultu, ho tero! jen Mi venigas malfeliĉon sur ĉi tiun popolon, frukton de iliaj pensoj; ĉar ili ne atentis Miajn vortojn, kaj Mian instruon ili forpuŝis.","Aŭskultu, ho tero! jen Mi venigas malfeliĉon sur ĉi tiun popolon, frukton de iliaj pensoj; ĉar ili ne atentis Miajn vortojn, kaj Mian instruon ili forpuŝis."],[6,20,"Por kio Mi bezonas la olibanon venantan el Ŝeba, kaj la bonodoran kanon el malproksima lando? viaj bruloferoj ne plaĉas al Mi, kaj viaj buĉoferoj ne estas agrablaj al Mi.","Por kio Mi bezonas la olibanon venantan el Ŝeba, kaj la bonodoran kanon el malproksima lando? viaj bruloferoj ne plaĉas al Mi, kaj viaj buĉoferoj ne estas agrablaj al Mi."],[6,21,"Tial tiele diras la Eternulo: Jen Mi metos antaŭ ĉi tiu popolo falpuŝilon, kaj sur ĝi falpuŝiĝos kune patroj kaj filoj, najbaro kaj amiko pereos.","Tial tiele diras la Eternulo: Jen Mi metos antaŭ ĉi tiu popolo falpuŝilon, kaj sur ĝi falpuŝiĝos kune patroj kaj filoj, najbaro kaj amiko pereos."],[6,22,"Tiele diras la Eternulo: Jen venos popolo el norda lando, kaj granda nacio leviĝos de la randoj de la tero.","Tiele diras la Eternulo: Jen venos popolo el norda lando, kaj granda nacio leviĝos de la randoj de la tero."],[6,23,"Pafarkon kaj lancon ili tenas forte; kruelaj ili estas kaj senkompataj; ilia voĉo bruas kiel maro; sur ĉevaloj ili rajdas, armite por la batalo kiel unu homo, kontraŭ vin, ho filino de Cion.","Pafarkon kaj lancon ili tenas forte; kruelaj ili estas kaj senkompataj; ilia voĉo bruas kiel maro; sur ĉevaloj ili rajdas, armite por la batalo kiel unu homo, kontraŭ vin, ho filino de Cion."],[6,24,"Kiam ni aŭdis pri ili, malleviĝis niaj manoj, teruro kaj doloro nin atakis kiel naskantinon.","Kiam ni aŭdis pri ili, malleviĝis niaj manoj, teruro kaj doloro nin atakis kiel naskantinon."],[6,25,"Ne eliru sur la kampon, ne iru sur la vojon, ĉar la glavo de la malamiko vekas teruron ĉirkaŭe.","Ne eliru sur la kampon, ne iru sur la vojon, ĉar la glavo de la malamiko vekas teruron ĉirkaŭe."],[6,26,"Ho filino de Mia popolo! zonu vin per sakaĵo, rulu vin en cindro, funebru kiel pro sola filo, ploru maldolĉe, ĉar subite venos sur nin la pereiganto.","Ho filino de Mia popolo! zonu vin per sakaĵo, rulu vin en cindro, funebru kiel pro sola filo, ploru maldolĉe, ĉar subite venos sur nin la pereiganto."],[6,27,"Kiel esploranton Mi starigis vin inter Mia popolo, fortan, ke vi ekkonu kaj esploru ilian vojon.","Kiel esploranton Mi starigis vin inter Mia popolo, fortan, ke vi ekkonu kaj esploru ilian vojon."],[6,28,"Ĉiuj ili estas obstinaj defalintoj, kalumniantoj, kupro kaj fero; ĉiuj ili estas degenerintoj.","Ĉiuj ili estas obstinaj defalintoj, kalumniantoj, kupro kaj fero; ĉiuj ili estas degenerintoj."],[6,29,"La blovilo bruldifektiĝis, la plumbo malaperis en la fajro; vane fandis la fandisto: la malbonuloj ne apartiĝis.","La blovilo bruldifektiĝis, la plumbo malaperis en la fajro; vane fandis la fandisto: la malbonuloj ne apartiĝis."],[6,30,"Arĝento rifuzita oni nomos ilin, ĉar la Eternulo forrifuzis ilin.","Arĝento rifuzita oni nomos ilin, ĉar la Eternulo forrifuzis ilin."],[7,1,"Jen estas la vorto, kiu aperis al Jeremia de la Eternulo:","Jen estas la vorto, kiu aperis al Jeremia de la Eternulo:"],[7,2,"Stariĝu en la pordego de la domo de la Eternulo, kaj tie proklamu ĉi tiun vorton, kaj diru: Aŭskultu la vorton de la Eternulo, ĉiuj Judoj, kiuj venas en ĉi tiun pordegon, por adorkliniĝi al la Eternulo.","Stariĝu en la pordego de la domo de la Eternulo, kaj tie proklamu ĉi tiun vorton, kaj diru: Aŭskultu la vorton de la Eternulo, ĉiuj Judoj, kiuj venas en ĉi tiun pordegon, por adorkliniĝi al la Eternulo."],[7,3,"Tiele diras la Eternulo Cebaot, Dio de Izrael: Plibonigu vian vojon kaj vian konduton; tiam Mi loĝigos vin sur ĉi tiu loko.","Tiele diras la Eternulo Cebaot, Dio de Izrael: Plibonigu vian vojon kaj vian konduton; tiam Mi loĝigos vin sur ĉi tiu loko."],[7,4,"Ne fidu la mensogajn vortojn, kiam oni diras al vi: Ĉi tie estas la templo de la Eternulo, la templo de la Eternulo, la templo de la Eternulo.","Ne fidu la mensogajn vortojn, kiam oni diras al vi: Ĉi tie estas la templo de la Eternulo, la templo de la Eternulo, la templo de la Eternulo."],[7,5,"Nur se vi plibonigos vian vojon kaj vian konduton, se vi agos juste unu rilate la alian,","Nur se vi plibonigos vian vojon kaj vian konduton, se vi agos juste unu rilate la alian,"],[7,6,"se vi ne premos fremdulon, orfon, kaj vidvinon, se vi ne verŝos senkulpan sangon sur ĉi tiu loko, kaj ne sekvos aliajn diojn por via malfeliĉo:","se vi ne premos fremdulon, orfon, kaj vidvinon, se vi ne verŝos senkulpan sangon sur ĉi tiu loko, kaj ne sekvos aliajn diojn por via malfeliĉo:"],[7,7,"tiam Mi loĝigos vin sur ĉi tiu loko, en la lando, kiun Mi donis al viaj patroj, ĉiam kaj eterne.","tiam Mi loĝigos vin sur ĉi tiu loko, en la lando, kiun Mi donis al viaj patroj, ĉiam kaj eterne."],[7,8,"Jen vi fidas la mensogajn vortojn, kiuj neniom helpas.","Jen vi fidas la mensogajn vortojn, kiuj neniom helpas."],[7,9,"Ŝtelante, mortigante, adultante, ĵurante mensoge, incensante al Baal, kaj sekvante aliajn diojn, kiujn vi ne konas,","Ŝtelante, mortigante, adultante, ĵurante mensoge, incensante al Baal, kaj sekvante aliajn diojn, kiujn vi ne konas,"],[7,10,"vi poste venas kaj stariĝas antaŭ Mi en ĉi tiu domo, kiu estas nomata per Mia nomo, kaj vi diras: Ni saviĝis — kvankam vi plue faras ĉiujn tiujn abomenindaĵojn!","vi poste venas kaj stariĝas antaŭ Mi en ĉi tiu domo, kiu estas nomata per Mia nomo, kaj vi diras: Ni saviĝis — kvankam vi plue faras ĉiujn tiujn abomenindaĵojn!"],[7,11,"Ĉu ĉi tiun domon, kiu estas nomata per Mia nomo, vi rigardas kiel neston de rabistoj? Mi bone vidas tion, diras la Eternulo.","Ĉu ĉi tiun domon, kiu estas nomata per Mia nomo, vi rigardas kiel neston de rabistoj? Mi bone vidas tion, diras la Eternulo."],[7,12,"Iru do al Mia loko en Ŝilo, kie Mi antaŭe loĝigis Mian nomon, kaj rigardu, kion Mi faris al ĝi pro la malbonagoj de Mia popolo Izrael.","Iru do al Mia loko en Ŝilo, kie Mi antaŭe loĝigis Mian nomon, kaj rigardu, kion Mi faris al ĝi pro la malbonagoj de Mia popolo Izrael."],[7,13,"Kaj nun, ĉar vi faras ĉiujn tiujn farojn, diras la Eternulo, kaj Mi de frua mateno ĉiam parolas al vi, kaj vi ne aŭskultas, Mi vokas vin, kaj vi ne respondas:","Kaj nun, ĉar vi faras ĉiujn tiujn farojn, diras la Eternulo, kaj Mi de frua mateno ĉiam parolas al vi, kaj vi ne aŭskultas, Mi vokas vin, kaj vi ne respondas:"],[7,14,"tial al la domo, kiu estas nomata per Mia nomo kaj kiun vi fidas, kaj al la loko, kiun Mi donis al vi kaj al viaj patroj, Mi faros tiel, kiel Mi faris al Ŝilo.","tial al la domo, kiu estas nomata per Mia nomo kaj kiun vi fidas, kaj al la loko, kiun Mi donis al vi kaj al viaj patroj, Mi faros tiel, kiel Mi faris al Ŝilo."],[7,15,"Mi forpuŝos vin de antaŭ Mi, kiel Mi forpuŝis ĉiujn viajn fratojn, la tutan idaron de Efraim.","Mi forpuŝos vin de antaŭ Mi, kiel Mi forpuŝis ĉiujn viajn fratojn, la tutan idaron de Efraim."],[7,16,"Kaj vi ne preĝu por ĉi tiu popolo kaj ne direktu por ili supren krion kaj preĝon kaj ne klopodu antaŭ Mi, ĉar Mi ne aŭskultos vin.","Kaj vi ne preĝu por ĉi tiu popolo kaj ne direktu por ili supren krion kaj preĝon kaj ne klopodu antaŭ Mi, ĉar Mi ne aŭskultos vin."],[7,17,"Ĉu vi ne vidas, kion ili faras en la urboj de Judujo kaj sur la stratoj de Jerusalem?","Ĉu vi ne vidas, kion ili faras en la urboj de Judujo kaj sur la stratoj de Jerusalem?"],[7,18,"La filoj kolektas la lignon, kaj la patroj ekbruligas la fajron, kaj la virinoj knedas la paston, por fari kukojn por la reĝino de la ĉielo, kaj ili faras verŝoferojn al aliaj dioj, por ĉagreni Min.","La filoj kolektas la lignon, kaj la patroj ekbruligas la fajron, kaj la virinoj knedas la paston, por fari kukojn por la reĝino de la ĉielo, kaj ili faras verŝoferojn al aliaj dioj, por ĉagreni Min."],[7,19,"Sed ĉu Min ili ĉagrenas? diras la Eternulo; ĉu ne sin mem, por hontigi sian vizaĝon?","Sed ĉu Min ili ĉagrenas? diras la Eternulo; ĉu ne sin mem, por hontigi sian vizaĝon?"],[7,20,"Tial tiele diras la Sinjoro, la Eternulo: Jen Mia kolero kaj indigno elverŝiĝos sur ĉi tiun lokon, sur la homojn kaj sur la brutojn kaj sur la arbojn de la kampo kaj sur la fruktojn de la tero; ĝi ekflamos kaj ne estingiĝos.","Tial tiele diras la Sinjoro, la Eternulo: Jen Mia kolero kaj indigno elverŝiĝos sur ĉi tiun lokon, sur la homojn kaj sur la brutojn kaj sur la arbojn de la kampo kaj sur la fruktojn de la tero; ĝi ekflamos kaj ne estingiĝos."],[7,21,"Tiele diras la Eternulo Cebaot, Dio de Izrael: Aldonu viajn bruloferojn al viaj buĉoferoj, kaj manĝu la viandon;","Tiele diras la Eternulo Cebaot, Dio de Izrael: Aldonu viajn bruloferojn al viaj buĉoferoj, kaj manĝu la viandon;"],[7,22,"ĉar Mi ne parolis al viaj patroj kaj Mi ne ordonis al ili pri bruloferoj kaj buĉoferoj en la tago, kiam Mi elkondukis ilin el la lando Egipta;","ĉar Mi ne parolis al viaj patroj kaj Mi ne ordonis al ili pri bruloferoj kaj buĉoferoj en la tago, kiam Mi elkondukis ilin el la lando Egipta;"],[7,23,"nur ĉi tion Mi ordonis al ili: Aŭskultu Mian voĉon, kaj Mi estos via Dio, kaj vi estos Mia popolo, kaj iru laŭ la tuta vojo, kiun Mi montros al vi, por ke estu al vi bone.","nur ĉi tion Mi ordonis al ili: Aŭskultu Mian voĉon, kaj Mi estos via Dio, kaj vi estos Mia popolo, kaj iru laŭ la tuta vojo, kiun Mi montros al vi, por ke estu al vi bone."],[7,24,"Sed ili ne aŭskultis kaj ne alklinis sian orelon, ili agis laŭ siaj propraj pensoj, laŭ la obstineco de sia malbona koro, kaj ili iris malantaŭen, ne antaŭen.","Sed ili ne aŭskultis kaj ne alklinis sian orelon, ili agis laŭ siaj propraj pensoj, laŭ la obstineco de sia malbona koro, kaj ili iris malantaŭen, ne antaŭen."],[7,25,"De post la tago, kiam viaj patroj eliris el la lando Egipta, ĝis la nuna tago Mi sendadis al vi ĉiujn Miajn servantojn, la profetojn, ĉiutage Mi sendis;","De post la tago, kiam viaj patroj eliris el la lando Egipta, ĝis la nuna tago Mi sendadis al vi ĉiujn Miajn servantojn, la profetojn, ĉiutage Mi sendis;"],[7,26,"sed ili ne aŭskultis Min kaj ne alklinis sian orelon, ili obstinigis sian nukon, agis pli malbone ol iliaj patroj.","sed ili ne aŭskultis Min kaj ne alklinis sian orelon, ili obstinigis sian nukon, agis pli malbone ol iliaj patroj."],[7,27,"Kaj kiam vi diros al ili ĉion ĉi tion, ili ne aŭskultos vin; kiam vi vokos ilin, ili ne respondos al vi.","Kaj kiam vi diros al ili ĉion ĉi tion, ili ne aŭskultos vin; kiam vi vokos ilin, ili ne respondos al vi."],[7,28,"Diru do al ili: Jen estas popolo, kiu ne aŭskultas la voĉon de la Eternulo, sia Dio, kaj ne akceptas moralinstruon; la kredo malaperis kaj estas ekstermita el ilia buŝo.","Diru do al ili: Jen estas popolo, kiu ne aŭskultas la voĉon de la Eternulo, sia Dio, kaj ne akceptas moralinstruon; la kredo malaperis kaj estas ekstermita el ilia buŝo."],[7,29,"Detondu viajn harojn kaj forĵetu ilin, kantu funebran kanton sur la altaĵoj; ĉar la Eternulo forrifuzis kaj forpuŝis la generacion, kiun Li koleras.","Detondu viajn harojn kaj forĵetu ilin, kantu funebran kanton sur la altaĵoj; ĉar la Eternulo forrifuzis kaj forpuŝis la generacion, kiun Li koleras."],[7,30,"Ĉar la filoj de Jehuda faras malbonon antaŭ Miaj okuloj, diras la Eternulo; siajn abomenindaĵojn ili metis en la domon, kiu estas nomata per Mia nomo, por malpurigi ĝin.","Ĉar la filoj de Jehuda faras malbonon antaŭ Miaj okuloj, diras la Eternulo; siajn abomenindaĵojn ili metis en la domon, kiu estas nomata per Mia nomo, por malpurigi ĝin."],[7,31,"Ili aranĝis altaĵojn de Tofet en la valo de la filo de Hinom, por bruligi siajn filojn kaj siajn filinojn en fajro, kion Mi ne ordonis kaj kio neniam estis en Miaj pensoj.","Ili aranĝis altaĵojn de Tofet en la valo de la filo de Hinom, por bruligi siajn filojn kaj siajn filinojn en fajro, kion Mi ne ordonis kaj kio neniam estis en Miaj pensoj."],[7,32,"Pro tio jen venos tempo, diras la Eternulo, kiam oni jam nomos tion ne Tofet kaj valo de la filo de Hinom, sed valo de mortigado, kaj en Tofet oni enterigos mortintojn, ĉar mankos alia loko.","Pro tio jen venos tempo, diras la Eternulo, kiam oni jam nomos tion ne Tofet kaj valo de la filo de Hinom, sed valo de mortigado, kaj en Tofet oni enterigos mortintojn, ĉar mankos alia loko."],[7,33,"Kaj la kadavroj de ĉi tiu popolo estos manĝaĵo por la birdoj de la ĉielo kaj por la bestoj de la tero, kiujn neniu fortimigos.","Kaj la kadavroj de ĉi tiu popolo estos manĝaĵo por la birdoj de la ĉielo kaj por la bestoj de la tero, kiujn neniu fortimigos."],[7,34,"Kaj Mi ĉesigos en la urboj de Judujo kaj sur la stratoj de Jerusalem la sonojn de ĝojo kaj la sonojn de gajeco, la voĉon de fianĉo kaj la voĉon de fianĉino; ĉar la lando fariĝos dezerto.","Kaj Mi ĉesigos en la urboj de Judujo kaj sur la stratoj de Jerusalem la sonojn de ĝojo kaj la sonojn de gajeco, la voĉon de fianĉo kaj la voĉon de fianĉino; ĉar la lando fariĝos dezerto."],[8,1,"En tiu tempo, diras la Eternulo, oni elĵetos el iliaj tomboj la ostojn de la reĝoj de Judujo kaj la ostojn de ĝiaj princoj kaj la ostojn de la pastroj kaj la ostojn de la profetoj kaj la ostojn de la loĝantoj de Jerusalem;","En tiu tempo, diras la Eternulo, oni elĵetos el iliaj tomboj la ostojn de la reĝoj de Judujo kaj la ostojn de ĝiaj princoj kaj la ostojn de la pastroj kaj la ostojn de la profetoj kaj la ostojn de la loĝantoj de Jerusalem;"],[8,2,"kaj oni disĵetos ilin antaŭ la suno kaj antaŭ la luno kaj antaŭ la tuta armeo de la ĉielo, kiujn ili amis, al kiuj ili servis, kiujn ili sekvis, kiujn ili serĉis, kaj al kiuj ili adorkliniĝis; oni ne kolektos ilin kaj ne enterigos ilin, sed ili estos kiel sterko sur la supraĵo de la tero.","kaj oni disĵetos ilin antaŭ la suno kaj antaŭ la luno kaj antaŭ la tuta armeo de la ĉielo, kiujn ili amis, al kiuj ili servis, kiujn ili sekvis, kiujn ili serĉis, kaj al kiuj ili adorkliniĝis; oni ne kolektos ilin kaj ne enterigos ilin, sed ili estos kiel sterko sur la supraĵo de la tero."],[8,3,"Kaj preferos la morton ol la vivon ĉiuj restintoj, kiuj restos el tiu malbona gento, kiuj restos en ĉiuj lokoj, sur kiujn Mi dispelis ilin, diras la Eternulo Cebaot.","Kaj preferos la morton ol la vivon ĉiuj restintoj, kiuj restos el tiu malbona gento, kiuj restos en ĉiuj lokoj, sur kiujn Mi dispelis ilin, diras la Eternulo Cebaot."],[8,4,"Kaj diru al ili: Tiele diras la Eternulo: Ĉu se oni falis, oni ne leviĝas? ĉu se oni devojiĝis, oni ne volas reveni?","Kaj diru al ili: Tiele diras la Eternulo: Ĉu se oni falis, oni ne leviĝas? ĉu se oni devojiĝis, oni ne volas reveni?"],[8,5,"Kial do ĉi tiu popolo en Jerusalem defalis per defalo obstina? ili forte sin tenas je la malveraĵo kaj ne volas sin konverti.","Kial do ĉi tiu popolo en Jerusalem defalis per defalo obstina? ili forte sin tenas je la malveraĵo kaj ne volas sin konverti."],[8,6,"Mi atentis kaj aŭskultis, sed ili parolas nenion ĝustan; neniu pentas sian malbonecon, dirante: Kion mi faris? Ĉiu fordonis sin al sia kurado, kiel ĉevalo, kiu flugrapide kuras en la batalon.","Mi atentis kaj aŭskultis, sed ili parolas nenion ĝustan; neniu pentas sian malbonecon, dirante: Kion mi faris? Ĉiu fordonis sin al sia kurado, kiel ĉevalo, kiu flugrapide kuras en la batalon."],[8,7,"Eĉ cikonio sub la ĉielo scias sian tempon, turto, hirundo, kaj gruo observas la tempon, kiam ili devas veni; sed Mia popolo ne scias la leĝon de la Eternulo.","Eĉ cikonio sub la ĉielo scias sian tempon, turto, hirundo, kaj gruo observas la tempon, kiam ili devas veni; sed Mia popolo ne scias la leĝon de la Eternulo."],[8,8,"Kiel vi diras: Ni estas saĝuloj, kaj ni havas antaŭ ni la instruon de la Eternulo? Ĝi fariĝis ja mensogaĵo per la mensoga skribilo de la skribistoj.","Kiel vi diras: Ni estas saĝuloj, kaj ni havas antaŭ ni la instruon de la Eternulo? Ĝi fariĝis ja mensogaĵo per la mensoga skribilo de la skribistoj."],[8,9,"Per honto kovris sin la saĝuloj, konfuziĝis kaj implikiĝis; jen ili forrifuzis la vorton de la Eternulo, kian do saĝecon ili havas?","Per honto kovris sin la saĝuloj, konfuziĝis kaj implikiĝis; jen ili forrifuzis la vorton de la Eternulo, kian do saĝecon ili havas?"],[8,10,"Tial Mi fordonos iliajn edzinojn al aliuloj, iliajn kampojn al venkintoj; ĉar de malgrandulo ĝis grandulo ili ĉiuj estas profitavidaj, de profeto ĝis pastro ili ĉiuj faras malhonestaĵon.","Tial Mi fordonos iliajn edzinojn al aliuloj, iliajn kampojn al venkintoj; ĉar de malgrandulo ĝis grandulo ili ĉiuj estas profitavidaj, de profeto ĝis pastro ili ĉiuj faras malhonestaĵon."],[8,11,"Kaj la vundojn de la filino de Mia popolo ili kuracas per facilanimigo, dirante, ke ĉio estas en bona stato, kvankam ne estas bona stato.","Kaj la vundojn de la filino de Mia popolo ili kuracas per facilanimigo, dirante, ke ĉio estas en bona stato, kvankam ne estas bona stato."],[8,12,"Ĉu ili hontas, ke ili faras abomenindaĵon? ili tute ne hontas, ili eĉ ne povoscias ruĝiĝi; tial ili falos inter la falantoj, ili renversiĝos, kiam Mi vizitos ilin, diras la Eternulo.","Ĉu ili hontas, ke ili faras abomenindaĵon? ili tute ne hontas, ili eĉ ne povoscias ruĝiĝi; tial ili falos inter la falantoj, ili renversiĝos, kiam Mi vizitos ilin, diras la Eternulo."],[8,13,"Mi plene ŝirkolektos ilin, diras la Eternulo; ne restos beroj sur la vinberbranĉo nek figoj sur la figarbo, kaj la folioj forvelkos, kaj Mi donos al ili plenan pereon.","Mi plene ŝirkolektos ilin, diras la Eternulo; ne restos beroj sur la vinberbranĉo nek figoj sur la figarbo, kaj la folioj forvelkos, kaj Mi donos al ili plenan pereon."],[8,14,"Por kio ni sidas? kolektiĝu, kaj ni iru en la fortikigitajn urbojn, kaj ni tie pereu; ĉar la Eternulo, nia Dio, pereigas nin kaj trinkigas al ni akvon maldolĉan pro tio, ke ni pekis antaŭ la Eternulo.","Por kio ni sidas? kolektiĝu, kaj ni iru en la fortikigitajn urbojn, kaj ni tie pereu; ĉar la Eternulo, nia Dio, pereigas nin kaj trinkigas al ni akvon maldolĉan pro tio, ke ni pekis antaŭ la Eternulo."],[8,15,"Ni esperis pacon, sed venas nenio bona; ni esperis tempon de resaniĝo, sed jen estas teruro.","Ni esperis pacon, sed venas nenio bona; ni esperis tempon de resaniĝo, sed jen estas teruro."],[8,16,"El la regiono de Dan oni aŭdas spiregadon de iliaj ĉevaloj; de la blekegado de iliaj fortaj ĉevaloj tremas la tuta tero; ili iras, kaj ili formanĝos la teron, kaj tion, kio estas sur ĝi, la urbon kaj ĝiajn loĝantojn.","El la regiono de Dan oni aŭdas spiregadon de iliaj ĉevaloj; de la blekegado de iliaj fortaj ĉevaloj tremas la tuta tero; ili iras, kaj ili formanĝos la teron, kaj tion, kio estas sur ĝi, la urbon kaj ĝiajn loĝantojn."],[8,17,"Ĉar jen Mi sendos sur vin serpentojn, vipurojn, kiujn oni ne povas sorĉligi, kaj ili pikos vin, diras la Eternulo.","Ĉar jen Mi sendos sur vin serpentojn, vipurojn, kiujn oni ne povas sorĉligi, kaj ili pikos vin, diras la Eternulo."],[8,18,"Mia malĝojo estas super ĉiuj malĝojoj, mia koro en mi doloras.","Mia malĝojo estas super ĉiuj malĝojoj, mia koro en mi doloras."],[8,19,"Jen mi aŭdas kriadon de la filino de mia popolo el lando malproksima: Ĉu jam ne ekzistas la Eternulo en Cion? ĉu ĝia Reĝo ne estas en ĝi? Sed kial ili kolerigis min per siaj idoloj, per fremdaj vantaĵoj?","Jen mi aŭdas kriadon de la filino de mia popolo el lando malproksima: Ĉu jam ne ekzistas la Eternulo en Cion? ĉu ĝia Reĝo ne estas en ĝi? Sed kial ili kolerigis min per siaj idoloj, per fremdaj vantaĵoj?"],[8,20,"Pasis la rikolto, finiĝis la somero, sed ni ne ricevis helpon.","Pasis la rikolto, finiĝis la somero, sed ni ne ricevis helpon."],[8,21,"La malfeliĉo de mia popolo min afliktas, mi malĝojas, mi sentas teruron.","La malfeliĉo de mia popolo min afliktas, mi malĝojas, mi sentas teruron."],[8,22,"Ĉu ne ekzistas balzamo en Gilead? ĉu ne ekzistas tie kuracisto? kial do ne venas resaniĝo al la filino de mia popolo?","Ĉu ne ekzistas balzamo en Gilead? ĉu ne ekzistas tie kuracisto? kial do ne venas resaniĝo al la filino de mia popolo?"],[9,1,"Ho, se mia kapo havus sufiĉe da akvo kaj miaj okuloj estus fonto da larmoj! tage kaj nokte mi priplorus la mortigitojn el mia popolo.","Ho, se mia kapo havus sufiĉe da akvo kaj miaj okuloj estus fonto da larmoj! tage kaj nokte mi priplorus la mortigitojn el mia popolo."],[9,2,"Ho, se mi havus en la dezerto rifuĝejon por migrantoj! tiam mi forlasus mian popolon kaj forirus de ili, ĉar ili ĉiuj estas adultuloj, amaso da perfiduloj.","Ho, se mi havus en la dezerto rifuĝejon por migrantoj! tiam mi forlasus mian popolon kaj forirus de ili, ĉar ili ĉiuj estas adultuloj, amaso da perfiduloj."],[9,3,"Per siaj langoj ili pafas mensogon kiel per pafarko, ne por vero ili fortiĝas sur la tero; ili iras de malbonago al malbonago, kaj Min ili ne konas, diras la Eternulo.","Per siaj langoj ili pafas mensogon kiel per pafarko, ne por vero ili fortiĝas sur la tero; ili iras de malbonago al malbonago, kaj Min ili ne konas, diras la Eternulo."],[9,4,"Gardu vin unu kontraŭ alia, kaj fidu neniun fraton; ĉar ĉiu frato insidas, kaj ĉiu proksimulo disportas kalumniojn.","Gardu vin unu kontraŭ alia, kaj fidu neniun fraton; ĉar ĉiu frato insidas, kaj ĉiu proksimulo disportas kalumniojn."],[9,5,"Unu trompas alian, kaj veron ili ne parolas; ili lernigis sian langon paroli malveron, ili laciĝas de malbonagado.","Unu trompas alian, kaj veron ili ne parolas; ili lernigis sian langon paroli malveron, ili laciĝas de malbonagado."],[9,6,"Vi loĝas meze de malhonesteco; pro malhonesteco ili ne volas koni Min, diras la Eternulo.","Vi loĝas meze de malhonesteco; pro malhonesteco ili ne volas koni Min, diras la Eternulo."],[9,7,"Tial tiele diras la Eternulo Cebaot: Jen Mi fandos kaj elprovos ilin; ĉar kiel alie Mi povas agi kun la filino de Mia popolo?","Tial tiele diras la Eternulo Cebaot: Jen Mi fandos kaj elprovos ilin; ĉar kiel alie Mi povas agi kun la filino de Mia popolo?"],[9,8,"Ilia lango estas vundanta sago, ĝi parolas trompe; per sia buŝo ili afable salutas sian proksimulon, sed en sia koro ili faras insidon kontraŭ li.","Ilia lango estas vundanta sago, ĝi parolas trompe; per sia buŝo ili afable salutas sian proksimulon, sed en sia koro ili faras insidon kontraŭ li."],[9,9,"Ĉu pro tio Mi povas ne puni ilin? diras la Eternulo; ĉu al tia popolo Mia animo ne venĝos?","Ĉu pro tio Mi povas ne puni ilin? diras la Eternulo; ĉu al tia popolo Mia animo ne venĝos?"],[9,10,"Pri la montoj Mi ploros, kaj pri la kabanoj en la dezerto Mi kantos funebre; ĉar ili estas tiel bruligitaj, ke jam neniu migranto en ilin eniras, kaj oni jam ne aŭdas blekadon de brutoj; de la birdoj de la ĉielo ĝis la brutoj ĉio diskuris, foriris.","Pri la montoj Mi ploros, kaj pri la kabanoj en la dezerto Mi kantos funebre; ĉar ili estas tiel bruligitaj, ke jam neniu migranto en ilin eniras, kaj oni jam ne aŭdas blekadon de brutoj; de la birdoj de la ĉielo ĝis la brutoj ĉio diskuris, foriris."],[9,11,"Mi faros Jerusalemon amaso da ŝtonoj, loĝejo de ŝakaloj; kaj la urbojn de Judujo Mi dezertigos tiel, ke estos en ili neniu loĝanto.","Mi faros Jerusalemon amaso da ŝtonoj, loĝejo de ŝakaloj; kaj la urbojn de Judujo Mi dezertigos tiel, ke estos en ili neniu loĝanto."],[9,12,"Ĉu ekzistas homo saĝa, kiu komprenus tion kaj klarigus tion, kion diras al li la buŝo de la Eternulo, pro kio la lando pereis kaj estas bruldetruita kiel dezerto tiel, ke neniu iras tra ĝi?","Ĉu ekzistas homo saĝa, kiu komprenus tion kaj klarigus tion, kion diras al li la buŝo de la Eternulo, pro kio la lando pereis kaj estas bruldetruita kiel dezerto tiel, ke neniu iras tra ĝi?"],[9,13,"Kaj la Eternulo diris: Pro tio, ke ili forlasis Mian instruon, kiun Mi donis al ili, kaj ne aŭskultis Mian voĉon kaj ne sekvis ĝin,","Kaj la Eternulo diris: Pro tio, ke ili forlasis Mian instruon, kiun Mi donis al ili, kaj ne aŭskultis Mian voĉon kaj ne sekvis ĝin,"],[9,14,"sed sekvis la obstinecon de sia koro kaj la Baalojn, kiel lernigis al ili iliaj patroj:","sed sekvis la obstinecon de sia koro kaj la Baalojn, kiel lernigis al ili iliaj patroj:"],[9,15,"tial tiele diras la Eternulo Cebaot, Dio de Izrael: Jen Mi manĝigos al tiu popolo vermuton kaj trinkigos al ili akvon maldolĉan;","tial tiele diras la Eternulo Cebaot, Dio de Izrael: Jen Mi manĝigos al tiu popolo vermuton kaj trinkigos al ili akvon maldolĉan;"],[9,16,"kaj Mi dissemos ilin inter popoloj, kiujn ne konis ili nek iliaj patroj; kaj Mi sendos post ilin glavon, ĝis Mi tute ekstermos ilin.","kaj Mi dissemos ilin inter popoloj, kiujn ne konis ili nek iliaj patroj; kaj Mi sendos post ilin glavon, ĝis Mi tute ekstermos ilin."],[9,17,"Tiele diras la Eternulo Cebaot: Serĉu kaj voku ploristinojn, ke ili venu; sendu voki lertulinojn en tia afero, ke ili venu.","Tiele diras la Eternulo Cebaot: Serĉu kaj voku ploristinojn, ke ili venu; sendu voki lertulinojn en tia afero, ke ili venu."],[9,18,"Ili rapidu kaj komencu funebran ploradon pri ni, por ke el niaj okuloj ekfluu larmoj kaj de niaj palpebroj ekverŝiĝu akvo.","Ili rapidu kaj komencu funebran ploradon pri ni, por ke el niaj okuloj ekfluu larmoj kaj de niaj palpebroj ekverŝiĝu akvo."],[9,19,"Voĉo de funebra plorado estos aŭdata el Cion: Kiele ni estas ruinigitaj! kiele ni estas kovritaj de honto! ĉar ni forlasis nian landon kaj estas elĵetitaj el niaj loĝejoj.","Voĉo de funebra plorado estos aŭdata el Cion: Kiele ni estas ruinigitaj! kiele ni estas kovritaj de honto! ĉar ni forlasis nian landon kaj estas elĵetitaj el niaj loĝejoj."],[9,20,"Aŭskultu do, ho virinoj, la vorton de la Eternulo, kaj via orelo enprenu la vorton el Lia buŝo: Lernigu al viaj filinoj funebran ploradon kaj unu al alia funebran kantadon.","Aŭskultu do, ho virinoj, la vorton de la Eternulo, kaj via orelo enprenu la vorton el Lia buŝo: Lernigu al viaj filinoj funebran ploradon kaj unu al alia funebran kantadon."],[9,21,"Ĉar la morto eniras en niajn fenestrojn kaj venas en niajn palacojn, por ekstermi infanojn de ekstere, junulojn de la stratoj.","Ĉar la morto eniras en niajn fenestrojn kaj venas en niajn palacojn, por ekstermi infanojn de ekstere, junulojn de la stratoj."],[9,22,"Diru, ke tiele diras la Eternulo: La kadavroj de homoj falos kiel sterko sur la kampojn kaj kiel garboj malantaŭ la rikoltanto, kaj neniu ilin enkolektos.","Diru, ke tiele diras la Eternulo: La kadavroj de homoj falos kiel sterko sur la kampojn kaj kiel garboj malantaŭ la rikoltanto, kaj neniu ilin enkolektos."],[9,23,"Tiele diras la Eternulo: Ne fieru saĝulo pri sia saĝeco, ne fieru fortulo pri sia forteco, ne fieru riĉulo pri sia riĉeco;","Tiele diras la Eternulo: Ne fieru saĝulo pri sia saĝeco, ne fieru fortulo pri sia forteco, ne fieru riĉulo pri sia riĉeco;"],[9,24,"sed kiu volas fieri, tiu fieru nur pri tio, ke li komprenas kaj konas Min, ke Mi estas la Eternulo, kiu faras korfavoraĵon, juĝon, kaj justaĵon sur la tero; ĉar ĉi tio plaĉas al Mi, diras la Eternulo.","sed kiu volas fieri, tiu fieru nur pri tio, ke li komprenas kaj konas Min, ke Mi estas la Eternulo, kiu faras korfavoraĵon, juĝon, kaj justaĵon sur la tero; ĉar ĉi tio plaĉas al Mi, diras la Eternulo."],[9,25,"Jen venos tagoj, diras la Eternulo, kiam Mi punvizitos ĉiujn cirkumciditajn kaj necirkumciditajn,","Jen venos tagoj, diras la Eternulo, kiam Mi punvizitos ĉiujn cirkumciditajn kaj necirkumciditajn,"],[9,26,"Egiptujon, Judujon, Edomon, la Amonidojn, Moabon, kaj ĉiujn, kiuj tondas la harojn sur la tempioj kaj kiuj loĝas en la dezerto; ĉar ĉiuj popoloj havas necirkumciditan prepucion, sed la tuta domo de Izrael havas necirkumciditan koron.","Egiptujon, Judujon, Edomon, la Amonidojn, Moabon, kaj ĉiujn, kiuj tondas la harojn sur la tempioj kaj kiuj loĝas en la dezerto; ĉar ĉiuj popoloj havas necirkumciditan prepucion, sed la tuta domo de Izrael havas necirkumciditan koron."],[10,1,"Aŭskultu la vorton, kiun diras pri vi la Eternulo, ho domo de Izrael!","Aŭskultu la vorton, kiun diras pri vi la Eternulo, ho domo de Izrael!"],[10,2,"Tiele diras la Eternulo: Ne lernu la konduton de la nacioj, kaj ne timu la signojn de la ĉielo, kiel la nacioj ilin timas.","Tiele diras la Eternulo: Ne lernu la konduton de la nacioj, kaj ne timu la signojn de la ĉielo, kiel la nacioj ilin timas."],[10,3,"Ĉar la aranĝoj de la nacioj estas vantaĵo: ili dehakas arbon en la arbaro, kaj ĉarpentisto prilaboras ĝin per hakilo;","Ĉar la aranĝoj de la nacioj estas vantaĵo: ili dehakas arbon en la arbaro, kaj ĉarpentisto prilaboras ĝin per hakilo;"],[10,4,"ili ornamas ĝin per arĝento kaj oro, fortikigas per najloj kaj marteloj, por ke ĝi ne disfalu.","ili ornamas ĝin per arĝento kaj oro, fortikigas per najloj kaj marteloj, por ke ĝi ne disfalu."],[10,5,"Ili estas kiel kolono ĉirkaŭforĝita; ili ne parolas, oni portas ilin, ĉar ili ne povas iri. Ne timu ilin, ĉar ili ne faras malbonon, tiel same, kiel ili ne povas fari bonon.","Ili estas kiel kolono ĉirkaŭforĝita; ili ne parolas, oni portas ilin, ĉar ili ne povas iri. Ne timu ilin, ĉar ili ne faras malbonon, tiel same, kiel ili ne povas fari bonon."],[10,6,"Sed simila al Vi, ho Eternulo, ekzistas neniu; granda Vi estas, kaj granda estas Via nomo en potenco.","Sed simila al Vi, ho Eternulo, ekzistas neniu; granda Vi estas, kaj granda estas Via nomo en potenco."],[10,7,"Kiu povas ne timi Vin, ho Reĝo de la popoloj? al Vi tio decas, ĉar inter ĉiuj saĝuloj de la nacioj kaj en ĉiuj iliaj regnoj ekzistas neniu simila al Vi.","Kiu povas ne timi Vin, ho Reĝo de la popoloj? al Vi tio decas, ĉar inter ĉiuj saĝuloj de la nacioj kaj en ĉiuj iliaj regnoj ekzistas neniu simila al Vi."],[10,8,"Ĉiuj ili malsaĝiĝis kaj idiotiĝis, ĉar ligno donas ja nur vantaĵan instruon.","Ĉiuj ili malsaĝiĝis kaj idiotiĝis, ĉar ligno donas ja nur vantaĵan instruon."],[10,9,"Foliigita arĝento estas venigita el Taŝiŝ kaj oro el Ufaz, laboritaĵo de artisto kaj de la manoj de fandisto; blua kaj purpura ŝtofo estas ilia vesto, ĉio estas faritaĵo de lertuloj.","Foliigita arĝento estas venigita el Taŝiŝ kaj oro el Ufaz, laboritaĵo de artisto kaj de la manoj de fandisto; blua kaj purpura ŝtofo estas ilia vesto, ĉio estas faritaĵo de lertuloj."],[10,10,"Sed la Eternulo estas Dio vera, Li estas Dio vivanta kaj Reĝo eterna; de Lia kolero tremas la tero, kaj la nacioj ne povas elteni Lian indignon.","Sed la Eternulo estas Dio vera, Li estas Dio vivanta kaj Reĝo eterna; de Lia kolero tremas la tero, kaj la nacioj ne povas elteni Lian indignon."],[10,11,"Diru do al ili: La dioj, kiuj ne kreis la ĉielon kaj la teron, pereos de sur la tero kaj sub la ĉielo.","Diru do al ili: La dioj, kiuj ne kreis la ĉielon kaj la teron, pereos de sur la tero kaj sub la ĉielo."],[10,12,"Li kreis la teron per Sia forto, aranĝis la mondon per Sia saĝo, kaj per Sia prudento etendis la ĉielon.","Li kreis la teron per Sia forto, aranĝis la mondon per Sia saĝo, kaj per Sia prudento etendis la ĉielon."],[10,13,"Kiam Li eksonigas Sian voĉon, kolektiĝas multego da akvo en la ĉielo; Li levas la nubojn de la randoj de la tero, Li aperigas fulmojn inter la pluvo, kaj elirigas la venton el Siaj trezorejoj.","Kiam Li eksonigas Sian voĉon, kolektiĝas multego da akvo en la ĉielo; Li levas la nubojn de la randoj de la tero, Li aperigas fulmojn inter la pluvo, kaj elirigas la venton el Siaj trezorejoj."],[10,14,"Malsaĝiĝis ĉiu homo kun sia sciado, per honto kovriĝis ĉiu fandisto kun sia statuo; ĉar lia fanditaĵo estas malveraĵo, ĝi ne havas en si spiriton.","Malsaĝiĝis ĉiu homo kun sia sciado, per honto kovriĝis ĉiu fandisto kun sia statuo; ĉar lia fanditaĵo estas malveraĵo, ĝi ne havas en si spiriton."],[10,15,"Tio estas vantaĵo, faro de eraro; kiam ili estos vizititaj, ili pereos.","Tio estas vantaĵo, faro de eraro; kiam ili estos vizititaj, ili pereos."],[10,16,"Ne simila al ili estas Tiu, kiun havas Jakob; ĉar Li estas la kreinto de ĉio, kaj Izrael estas la gento de Lia heredo; Eternulo Cebaot estas Lia nomo.","Ne simila al ili estas Tiu, kiun havas Jakob; ĉar Li estas la kreinto de ĉio, kaj Izrael estas la gento de Lia heredo; Eternulo Cebaot estas Lia nomo."],[10,17,"Forprenu de la tero vian komercaĵon, vi, kiu loĝas en fortikaĵo;","Forprenu de la tero vian komercaĵon, vi, kiu loĝas en fortikaĵo;"],[10,18,"ĉar tiele diras la Eternulo: Jen Mi ĉi tiun fojon elĵetos la loĝantojn de la lando, kaj Mi premos ilin, ke ili sentos kaj diros:","ĉar tiele diras la Eternulo: Jen Mi ĉi tiun fojon elĵetos la loĝantojn de la lando, kaj Mi premos ilin, ke ili sentos kaj diros:"],[10,19,"Ho ve al mi en mia malfeliĉo! neresanigebla estas mia vundo. Kaj mi pensis, ke tio estas mia malsano, kiun mi devas elporti.","Ho ve al mi en mia malfeliĉo! neresanigebla estas mia vundo. Kaj mi pensis, ke tio estas mia malsano, kiun mi devas elporti."],[10,20,"Mia tendo estas ruinigita, kaj ĉiuj miaj ŝnuroj estas disŝiritaj; miaj infanoj foriris de mi kaj forestas; estas jam neniu, kiu povus starigi mian tendon kaj pendigi miajn kurtenojn.","Mia tendo estas ruinigita, kaj ĉiuj miaj ŝnuroj estas disŝiritaj; miaj infanoj foriris de mi kaj forestas; estas jam neniu, kiu povus starigi mian tendon kaj pendigi miajn kurtenojn."],[10,21,"Ĉar la paŝtistoj malsaĝiĝis kaj ne serĉis la Eternulon; tial ili nenion komprenas kaj ilia tuta paŝtataro estas dispelita.","Ĉar la paŝtistoj malsaĝiĝis kaj ne serĉis la Eternulon; tial ili nenion komprenas kaj ilia tuta paŝtataro estas dispelita."],[10,22,"Jen venas laŭta krio kaj granda bruo el norda lando, por fari la urbojn de Judujo ruinoj, loĝejo de ŝakaloj.","Jen venas laŭta krio kaj granda bruo el norda lando, por fari la urbojn de Judujo ruinoj, loĝejo de ŝakaloj."],[10,23,"Mi scias, ho Eternulo, ke la vojo de homo estas ne laŭ lia volo, ke homo iranta ne povas libere direkti siajn paŝojn.","Mi scias, ho Eternulo, ke la vojo de homo estas ne laŭ lia volo, ke homo iranta ne povas libere direkti siajn paŝojn."],[10,24,"Punu min, ho Eternulo, sed laŭjuĝe, ne en Via kolero, por ke Vi min ne tro dispremu.","Punu min, ho Eternulo, sed laŭjuĝe, ne en Via kolero, por ke Vi min ne tro dispremu."],[10,25,"Elverŝu Vian koleron sur tiujn naciojn, kiuj Vin ne konas, kaj sur la gentojn, kiuj ne vokas Vian nomon; ĉar ili formanĝis Jakobon, englutis lin, ekstermis lin, kaj dezertigis lian loĝejon.","Elverŝu Vian koleron sur tiujn naciojn, kiuj Vin ne konas, kaj sur la gentojn, kiuj ne vokas Vian nomon; ĉar ili formanĝis Jakobon, englutis lin, ekstermis lin, kaj dezertigis lian loĝejon."],[11,1,"Jen estas la vorto, kiu aperis al Jeremia de la Eternulo:","Jen estas la vorto, kiu aperis al Jeremia de la Eternulo:"],[11,2,"Aŭskultu la vortojn de ĉi tiu interligo, kaj raportu ilin al la Judoj kaj al la loĝantoj de Jerusalem.","Aŭskultu la vortojn de ĉi tiu interligo, kaj raportu ilin al la Judoj kaj al la loĝantoj de Jerusalem."],[11,3,"Kaj diru al ili: Tiele diras la Eternulo, Dio de Izrael: Malbenita estu la homo, kiu ne aŭskultos la vortojn de ĉi tiu interligo,","Kaj diru al ili: Tiele diras la Eternulo, Dio de Izrael: Malbenita estu la homo, kiu ne aŭskultos la vortojn de ĉi tiu interligo,"],[11,4,"kiun Mi donis al viaj patroj, kiam Mi elkondukis ilin el la lando Egipta, el la fera forno, dirante: Obeu Mian voĉon, kaj faru ĉion, kion Mi ordonas al vi; kaj vi estos Mia popolo, kaj Mi estos via Dio;","kiun Mi donis al viaj patroj, kiam Mi elkondukis ilin el la lando Egipta, el la fera forno, dirante: Obeu Mian voĉon, kaj faru ĉion, kion Mi ordonas al vi; kaj vi estos Mia popolo, kaj Mi estos via Dio;"],[11,5,"por ke plenumiĝu la ĵuro, kiun Mi ĵuris al viaj patroj, ke Mi donos al ili landon, kie fluas lakto kaj mielo, kiel tio estas nun. Kaj mi respondis kaj diris: Tiel estu, ho Eternulo.","por ke plenumiĝu la ĵuro, kiun Mi ĵuris al viaj patroj, ke Mi donos al ili landon, kie fluas lakto kaj mielo, kiel tio estas nun. Kaj mi respondis kaj diris: Tiel estu, ho Eternulo."],[11,6,"Kaj la Eternulo diris al mi: Proklamu ĉiujn ĉi tiujn vortojn en la urboj de Judujo kaj sur la stratoj de Jerusalem, dirante: Aŭskultu la vortojn de ĉi tiu interligo kaj plenumu ilin.","Kaj la Eternulo diris al mi: Proklamu ĉiujn ĉi tiujn vortojn en la urboj de Judujo kaj sur la stratoj de Jerusalem, dirante: Aŭskultu la vortojn de ĉi tiu interligo kaj plenumu ilin."],[11,7,"Ĉar Mi klare avertis viajn patrojn, kiam Mi elkondukis ilin el la lando Egipta, ĝis la nuna tago, Mi konstante avertadis ilin, dirante: Aŭskultu Mian voĉon.","Ĉar Mi klare avertis viajn patrojn, kiam Mi elkondukis ilin el la lando Egipta, ĝis la nuna tago, Mi konstante avertadis ilin, dirante: Aŭskultu Mian voĉon."],[11,8,"Sed ili ne aŭskultis kaj ne alklinis sian orelon, ĉiu sekvis la obstinecon de sia malbona koro; kaj tial Mi venigis sur ilin ĉion, kio estas dirita en ĉi tiu interligo, kiun Mi ordonis plenumi, sed kiun ili ne plenumis.","Sed ili ne aŭskultis kaj ne alklinis sian orelon, ĉiu sekvis la obstinecon de sia malbona koro; kaj tial Mi venigis sur ilin ĉion, kio estas dirita en ĉi tiu interligo, kiun Mi ordonis plenumi, sed kiun ili ne plenumis."],[11,9,"Kaj la Eternulo diris al mi: Fariĝis ribelo ĉe la Judoj kaj ĉe la loĝantoj de Jerusalem;","Kaj la Eternulo diris al mi: Fariĝis ribelo ĉe la Judoj kaj ĉe la loĝantoj de Jerusalem;"],[11,10,"ili returnis sin al la malbonagoj de siaj prapatroj, kiuj ne volis obei Miajn vortojn kaj sekvis aliajn diojn, servante al ili; la domo de Izrael kaj la domo de Jehuda rompis Mian interligon, kiun Mi faris kun iliaj patroj.","ili returnis sin al la malbonagoj de siaj prapatroj, kiuj ne volis obei Miajn vortojn kaj sekvis aliajn diojn, servante al ili; la domo de Izrael kaj la domo de Jehuda rompis Mian interligon, kiun Mi faris kun iliaj patroj."],[11,11,"Tial tiele diras la Eternulo: Jen Mi venigos sur ilin malfeliĉon, el kiu ili ne povos liberiĝi; kaj ili krios al Mi, sed Mi ne aŭskultos ilin.","Tial tiele diras la Eternulo: Jen Mi venigos sur ilin malfeliĉon, el kiu ili ne povos liberiĝi; kaj ili krios al Mi, sed Mi ne aŭskultos ilin."],[11,12,"Tiam la urboj de Judujo kaj la loĝantoj de Jerusalem iros kaj krios al tiuj dioj, al kiuj ili incensas, sed tiuj ne helpos ilin en la tempo de ilia malfeliĉo.","Tiam la urboj de Judujo kaj la loĝantoj de Jerusalem iros kaj krios al tiuj dioj, al kiuj ili incensas, sed tiuj ne helpos ilin en la tempo de ilia malfeliĉo."],[11,13,"Ĉar kiom da urboj, tiom da dioj vi havas, ho Jehuda; kaj kiom da stratoj estas en Jerusalem, tiom da hontindaj altaroj vi starigis, por incensi al Baal.","Ĉar kiom da urboj, tiom da dioj vi havas, ho Jehuda; kaj kiom da stratoj estas en Jerusalem, tiom da hontindaj altaroj vi starigis, por incensi al Baal."],[11,14,"Kaj vi ne preĝu por ĉi tiu popolo kaj ne direktu por ili supren peton kaj preĝon; ĉar Mi ne aŭskultos, kiam ili vokos al Mi en la tempo de sia malfeliĉo.","Kaj vi ne preĝu por ĉi tiu popolo kaj ne direktu por ili supren peton kaj preĝon; ĉar Mi ne aŭskultos, kiam ili vokos al Mi en la tempo de sia malfeliĉo."],[11,15,"Por kio, Mia kara, vi faras en Mia domo la multajn artifikojn kaj alportas la sanktan viandon, se vi fariĝas ĉiam pli malbona kaj ankoraŭ ĝojas pri tio?","Por kio, Mia kara, vi faras en Mia domo la multajn artifikojn kaj alportas la sanktan viandon, se vi fariĝas ĉiam pli malbona kaj ankoraŭ ĝojas pri tio?"],[11,16,"La Eternulo nomis vin verda, bela, fruktoriĉa olivarbo; sed kun granda bruo ekbruligis ĝin fajro, kaj ĝiaj branĉoj difektiĝis.","La Eternulo nomis vin verda, bela, fruktoriĉa olivarbo; sed kun granda bruo ekbruligis ĝin fajro, kaj ĝiaj branĉoj difektiĝis."],[11,17,"La Eternulo Cebaot, kiu plantis vin, dekretis por vi malbonon pro la malbono de la domo de Izrael kaj de la domo de Jehuda, kiun ili faris, kolerigante Min per la incensado al Baal.","La Eternulo Cebaot, kiu plantis vin, dekretis por vi malbonon pro la malbono de la domo de Izrael kaj de la domo de Jehuda, kiun ili faris, kolerigante Min per la incensado al Baal."],[11,18,"Vi, ho Eternulo, sciigis tion al mi, por ke mi sciu; Vi montris al mi iliajn farojn.","Vi, ho Eternulo, sciigis tion al mi, por ke mi sciu; Vi montris al mi iliajn farojn."],[11,19,"Kaj mi, kiel milda ŝafido, kondukata al la buĉo, ne sciis, ke ili havas malbonajn intencojn kontraŭ mi, dirante: Ni ekstermu la arbon kun ĝiaj fruktoj, ni elhaku ĝin el la tero de la vivo, por ke lia nomo ne plu estu rememorata.","Kaj mi, kiel milda ŝafido, kondukata al la buĉo, ne sciis, ke ili havas malbonajn intencojn kontraŭ mi, dirante: Ni ekstermu la arbon kun ĝiaj fruktoj, ni elhaku ĝin el la tero de la vivo, por ke lia nomo ne plu estu rememorata."],[11,20,"Sed Vi, ho Eternulo Cebaot, kiu juĝas juste, kiu esploras la internon kaj la koron, vidigu al mi Vian venĝon kontraŭ ili, ĉar al Vi mi transdonis mian proceson.","Sed Vi, ho Eternulo Cebaot, kiu juĝas juste, kiu esploras la internon kaj la koron, vidigu al mi Vian venĝon kontraŭ ili, ĉar al Vi mi transdonis mian proceson."],[11,21,"Tial tiele diras la Eternulo pri la loĝantoj de Anatot, kiuj serĉas vian animon, kaj diras: Ne profetu al ni en la nomo de la Eternulo, por ke vi ne mortu de niaj manoj;","Tial tiele diras la Eternulo pri la loĝantoj de Anatot, kiuj serĉas vian animon, kaj diras: Ne profetu al ni en la nomo de la Eternulo, por ke vi ne mortu de niaj manoj;"],[11,22,"tiele diras la Eternulo Cebaot: Jen Mi punvizitos ilin; la junuloj mortos de glavo, iliaj filoj kaj filinoj mortos de malsato.","tiele diras la Eternulo Cebaot: Jen Mi punvizitos ilin; la junuloj mortos de glavo, iliaj filoj kaj filinoj mortos de malsato."],[11,23,"Kaj neniu restos el ili, ĉar Mi venigos malfeliĉon sur la loĝantojn de Anatot en la jaro, kiam Mi punvizitos ilin.","Kaj neniu restos el ili, ĉar Mi venigos malfeliĉon sur la loĝantojn de Anatot en la jaro, kiam Mi punvizitos ilin."],[12,1,"Vi estos prava, ho Eternulo, kiam mi procesos kun Vi; tamen mi parolos kun Vi pri justeco: kial la vojo de malpiuloj estas sukcesa kaj ĉiuj perfiduloj vivas trankvile?","Vi estos prava, ho Eternulo, kiam mi procesos kun Vi; tamen mi parolos kun Vi pri justeco: kial la vojo de malpiuloj estas sukcesa kaj ĉiuj perfiduloj vivas trankvile?"],[12,2,"Vi plantis ilin, kaj ili ricevis fortajn radikojn, ili kreskas kaj donas fruktojn; proksima Vi estas en ilia buŝo, sed malproksima de ilia interno.","Vi plantis ilin, kaj ili ricevis fortajn radikojn, ili kreskas kaj donas fruktojn; proksima Vi estas en ilia buŝo, sed malproksima de ilia interno."],[12,3,"Sed min, ho Eternulo, Vi konas; Vi vidis kaj esploris, kia estas mia koro koncerne Vin. Pelu ilin, kiel ŝafojn al la buĉo, kaj apartigu ilin por la tago de mortigo.","Sed min, ho Eternulo, Vi konas; Vi vidis kaj esploris, kia estas mia koro koncerne Vin. Pelu ilin, kiel ŝafojn al la buĉo, kaj apartigu ilin por la tago de mortigo."],[12,4,"Kiel longe Vi tenos la landon en malĝojo kaj la herbo sur ĉiuj kampoj velkos? Brutoj kaj birdoj pereas pro la malboneco de ĝiaj loĝantoj, kiuj diras: Li ne scias, kio estos al ni.","Kiel longe Vi tenos la landon en malĝojo kaj la herbo sur ĉiuj kampoj velkos? Brutoj kaj birdoj pereas pro la malboneco de ĝiaj loĝantoj, kiuj diras: Li ne scias, kio estos al ni."],[12,5,"Se vi kuras kun piedirantoj kaj ili vin lacigas, kiel do vi povas konkuri kun ĉevaloj? se vi esperas trovi sendanĝerecon en lando paca, kion vi faros ĉe la majesta Jordan?","Se vi kuras kun piedirantoj kaj ili vin lacigas, kiel do vi povas konkuri kun ĉevaloj? se vi esperas trovi sendanĝerecon en lando paca, kion vi faros ĉe la majesta Jordan?"],[12,6,"Ĉar eĉ viaj fratoj kaj la domo de via patro agas perfide kontraŭ vi, krias post vi plenvoĉe. Ne fidu ilin, eĉ se ili parolos al vi bone.","Ĉar eĉ viaj fratoj kaj la domo de via patro agas perfide kontraŭ vi, krias post vi plenvoĉe. Ne fidu ilin, eĉ se ili parolos al vi bone."],[12,7,"Mi forlasis Mian domon, Mi foriris de Mia heredaĵo; tion, kio estis kara por Mia animo, Mi fordonis en la manojn de ĝiaj malamikoj.","Mi forlasis Mian domon, Mi foriris de Mia heredaĵo; tion, kio estis kara por Mia animo, Mi fordonis en la manojn de ĝiaj malamikoj."],[12,8,"Mia heredaĵo fariĝis por Mi kiel leono en la arbaro: ĝi ekblekegis kontraŭ Mi, tial Mi ĝin ekmalamis.","Mia heredaĵo fariĝis por Mi kiel leono en la arbaro: ĝi ekblekegis kontraŭ Mi, tial Mi ĝin ekmalamis."],[12,9,"Mia heredaĵo fariĝis kiel diverskolora rabobirdo, kiun ĉirkaŭe atakis aliaj rabobirdoj. Venu, kolektiĝu, ĉiuj bestoj de la kampo, venu, por formanĝi ĝin.","Mia heredaĵo fariĝis kiel diverskolora rabobirdo, kiun ĉirkaŭe atakis aliaj rabobirdoj. Venu, kolektiĝu, ĉiuj bestoj de la kampo, venu, por formanĝi ĝin."],[12,10,"Multo da paŝtistoj ruinigis Mian vinberĝardenon, dispremis per la piedoj Mian kampoparton, Mian plej amatan kampoparton ili faris senfrukta dezerto.","Multo da paŝtistoj ruinigis Mian vinberĝardenon, dispremis per la piedoj Mian kampoparton, Mian plej amatan kampoparton ili faris senfrukta dezerto."],[12,11,"Ili faris ĝin dezerto, kaj ĝia dezerteco plendas antaŭ Mi; la tuta lando estas dezertigita, kaj neniu zorgas pri tio.","Ili faris ĝin dezerto, kaj ĝia dezerteco plendas antaŭ Mi; la tuta lando estas dezertigita, kaj neniu zorgas pri tio."],[12,12,"Sur ĉiujn altaĵojn en la dezerto venis ruinigantoj, ĉar la glavo de la Eternulo ekstermas ĉion de unu rando de la lando ĝis la alia; neniu karno estas indulgata.","Sur ĉiujn altaĵojn en la dezerto venis ruinigantoj, ĉar la glavo de la Eternulo ekstermas ĉion de unu rando de la lando ĝis la alia; neniu karno estas indulgata."],[12,13,"Ili semis tritikon, sed rikoltis dornojn; ili elspezis, sed ne profitis; viaj enspezoj estos hontindaj, pro la flama kolero de la Eternulo.","Ili semis tritikon, sed rikoltis dornojn; ili elspezis, sed ne profitis; viaj enspezoj estos hontindaj, pro la flama kolero de la Eternulo."],[12,14,"Tiele diras la Eternulo pri ĉiuj malbonaj najbaroj, kiuj tuŝis la posedaĵon, kiun Mi heredigis al Mia popolo Izrael: Jen Mi elŝiros ilin el ilia lando, kaj la domon de Jehuda Mi eltiros el inter ili.","Tiele diras la Eternulo pri ĉiuj malbonaj najbaroj, kiuj tuŝis la posedaĵon, kiun Mi heredigis al Mia popolo Izrael: Jen Mi elŝiros ilin el ilia lando, kaj la domon de Jehuda Mi eltiros el inter ili."],[12,15,"Kaj kiam Mi estos elŝirinta ilin, Mi denove kompatos ilin kaj revenigos ĉiun al lia heredaĵo kaj ĉiun en lian landon.","Kaj kiam Mi estos elŝirinta ilin, Mi denove kompatos ilin kaj revenigos ĉiun al lia heredaĵo kaj ĉiun en lian landon."],[12,16,"Kaj se ili lernos la agmanieron de Mia popolo, por ĵuri per Mia nomo: Kiel vivas la Eternulo, simile al tio, kiel ili lernigis al Mia popolo ĵuri per Baal, tiam ili estos konstrue aranĝitaj inter Mia popolo.","Kaj se ili lernos la agmanieron de Mia popolo, por ĵuri per Mia nomo: Kiel vivas la Eternulo, simile al tio, kiel ili lernigis al Mia popolo ĵuri per Baal, tiam ili estos konstrue aranĝitaj inter Mia popolo."],[12,17,"Sed se ili ne aŭskultos, tiam Mi tute elŝiros tiun popolon kaj ekstermos ĝin, diras la Eternulo.","Sed se ili ne aŭskultos, tiam Mi tute elŝiros tiun popolon kaj ekstermos ĝin, diras la Eternulo."],[13,1,"Tiele diris al mi la Eternulo: Iru, aĉetu al vi tolan zonon kaj metu ĝin sur viajn lumbojn, sed en akvon ĝin ne metu.","Tiele diris al mi la Eternulo: Iru, aĉetu al vi tolan zonon kaj metu ĝin sur viajn lumbojn, sed en akvon ĝin ne metu."],[13,2,"Kaj mi aĉetis la zonon konforme al la vorto de la Eternulo kaj metis ĝin sur miajn lumbojn.","Kaj mi aĉetis la zonon konforme al la vorto de la Eternulo kaj metis ĝin sur miajn lumbojn."],[13,3,"Kaj duafoje aperis al mi la vorto de la Eternulo, dirante:","Kaj duafoje aperis al mi la vorto de la Eternulo, dirante:"],[13,4,"Prenu la zonon, kiun vi aĉetis, kiu estas sur viaj lumboj, leviĝu kaj iru al Eŭfrato, kaj kaŝu ĝin tie en fendo de roko.","Prenu la zonon, kiun vi aĉetis, kiu estas sur viaj lumboj, leviĝu kaj iru al Eŭfrato, kaj kaŝu ĝin tie en fendo de roko."],[13,5,"Kaj mi iris kaj kaŝis ĝin apud Eŭfrato, kiel la Eternulo al mi ordonis.","Kaj mi iris kaj kaŝis ĝin apud Eŭfrato, kiel la Eternulo al mi ordonis."],[13,6,"Post longa tempo la Eternulo diris al mi: Leviĝu, iru al Eŭfrato, kaj prenu de tie la zonon, pri kiu Mi ordonis al vi, ke vi kaŝu ĝin tie.","Post longa tempo la Eternulo diris al mi: Leviĝu, iru al Eŭfrato, kaj prenu de tie la zonon, pri kiu Mi ordonis al vi, ke vi kaŝu ĝin tie."],[13,7,"Kaj mi iris al Eŭfrato, elfosis kaj prenis la zonon el la loko, kie mi ĝin kaŝis; kaj jen montriĝis, ke la zono tute putriĝis kaj jam por nenio taŭgas.","Kaj mi iris al Eŭfrato, elfosis kaj prenis la zonon el la loko, kie mi ĝin kaŝis; kaj jen montriĝis, ke la zono tute putriĝis kaj jam por nenio taŭgas."],[13,8,"Kaj aperis al mi la vorto de la Eternulo, dirante:","Kaj aperis al mi la vorto de la Eternulo, dirante:"],[13,9,"Tiele diras la Eternulo: Tiele Mi putrigos la fieron de Jehuda kaj la grandan fieron de Jerusalem.","Tiele diras la Eternulo: Tiele Mi putrigos la fieron de Jehuda kaj la grandan fieron de Jerusalem."],[13,10,"Tiu malbona popolo, kiu ne volas obei Miajn vortojn, kiu sekvas la obstinecon de sia koro, kaj sekvas aliajn diojn, servante al ili kaj adorkliniĝante al ili, fariĝos kiel ĉi tiu zono, kiu jam taŭgas por nenio.","Tiu malbona popolo, kiu ne volas obei Miajn vortojn, kiu sekvas la obstinecon de sia koro, kaj sekvas aliajn diojn, servante al ili kaj adorkliniĝante al ili, fariĝos kiel ĉi tiu zono, kiu jam taŭgas por nenio."],[13,11,"Kiel zono estas alligata al la lumboj de homo, tiel Mi alligis al Mi la tutan domon de Izrael kaj la tutan domon de Jehuda, diras la Eternulo, por ke ili estu Mia popolo, Mia nomo, gloro, kaj ornamo; sed ili ne obeis.","Kiel zono estas alligata al la lumboj de homo, tiel Mi alligis al Mi la tutan domon de Izrael kaj la tutan domon de Jehuda, diras la Eternulo, por ke ili estu Mia popolo, Mia nomo, gloro, kaj ornamo; sed ili ne obeis."],[13,12,"Kaj diru al ili ĉi tion: Tiele diras la Eternulo, Dio de Izrael: Ĉiu vinkruĉo estos plenigata de vino. Ili diros al vi: Ĉu ni ne scias, ke ĉiu vinkruĉo estos plenigata de vino?","Kaj diru al ili ĉi tion: Tiele diras la Eternulo, Dio de Izrael: Ĉiu vinkruĉo estos plenigata de vino. Ili diros al vi: Ĉu ni ne scias, ke ĉiu vinkruĉo estos plenigata de vino?"],[13,13,"Sed vi diru al ili: Tiele diras la Eternulo: Jen Mi plenigos ĝis ebrieco ĉiujn loĝantojn de ĉi tiu lando, la reĝojn, kiuj sidas sur la trono de David, la pastrojn, la profetojn, kaj ĉiujn loĝantojn de Jerusalem;","Sed vi diru al ili: Tiele diras la Eternulo: Jen Mi plenigos ĝis ebrieco ĉiujn loĝantojn de ĉi tiu lando, la reĝojn, kiuj sidas sur la trono de David, la pastrojn, la profetojn, kaj ĉiujn loĝantojn de Jerusalem;"],[13,14,"kaj Mi interfrapigos ilin reciproke, la patrojn kaj la filojn kune, diras la Eternulo, Mi ne kompatos, ne preterlasos, ne indulgos, ekstermante ilin.","kaj Mi interfrapigos ilin reciproke, la patrojn kaj la filojn kune, diras la Eternulo, Mi ne kompatos, ne preterlasos, ne indulgos, ekstermante ilin."],[13,15,"Aŭskultu kaj atentu; ne tenu vin alte, ĉar la Eternulo parolas.","Aŭskultu kaj atentu; ne tenu vin alte, ĉar la Eternulo parolas."],[13,16,"Donu honoron al la Eternulo, via Dio, antaŭ ol Li venigos mallumon, kaj antaŭ ol viaj piedoj falpuŝiĝos sur la mallumaj montoj; tiam vi atendos lumon, sed Li donos anstataŭ ĝi ombron de morto, densan nebulon.","Donu honoron al la Eternulo, via Dio, antaŭ ol Li venigos mallumon, kaj antaŭ ol viaj piedoj falpuŝiĝos sur la mallumaj montoj; tiam vi atendos lumon, sed Li donos anstataŭ ĝi ombron de morto, densan nebulon."],[13,17,"Se vi ne aŭskultos, tiam mia animo kaŝe ploros pro via fiero, ĝi ploros maldolĉe, kaj el miaj okuloj fluegos larmoj, ĉar kaptita estos la paŝtataro de la Eternulo.","Se vi ne aŭskultos, tiam mia animo kaŝe ploros pro via fiero, ĝi ploros maldolĉe, kaj el miaj okuloj fluegos larmoj, ĉar kaptita estos la paŝtataro de la Eternulo."],[13,18,"Diru al la reĝo kaj al la reĝino: Sidiĝu pli malalte, ĉar la krono de via majesto defalis de via kapo.","Diru al la reĝo kaj al la reĝino: Sidiĝu pli malalte, ĉar la krono de via majesto defalis de via kapo."],[13,19,"La sudaj urboj estas fermitaj, kaj neniu ilin malfermos; la tuta Judujo estas forkondukita en kaptitecon, ĝi tuta estas forkondukita.","La sudaj urboj estas fermitaj, kaj neniu ilin malfermos; la tuta Judujo estas forkondukita en kaptitecon, ĝi tuta estas forkondukita."],[13,20,"Levu viajn okulojn, kaj rigardu tiujn, kiuj venas de nordo. Kie estas la paŝtataro, kiu estas komisiita al vi, via bela ŝafaro?","Levu viajn okulojn, kaj rigardu tiujn, kiuj venas de nordo. Kie estas la paŝtataro, kiu estas komisiita al vi, via bela ŝafaro?"],[13,21,"Kion vi diros, kiam Li punvizitos vin? vi lernigis ja ilin esti kontraŭ vi, esti ĉefoj kaj ordonantoj. Ĉu ne atakos vin doloroj kiel naskantan virinon?","Kion vi diros, kiam Li punvizitos vin? vi lernigis ja ilin esti kontraŭ vi, esti ĉefoj kaj ordonantoj. Ĉu ne atakos vin doloroj kiel naskantan virinon?"],[13,22,"Eble vi diros en via koro: Pro kio trafis min ĉi tio? Pro la multo de viaj malbonagoj estas levitaj la randoj de viaj vestoj kaj malhonoritaj viaj kalkanoj.","Eble vi diros en via koro: Pro kio trafis min ĉi tio? Pro la multo de viaj malbonagoj estas levitaj la randoj de viaj vestoj kaj malhonoritaj viaj kalkanoj."],[13,23,"Ĉu negro povas ŝanĝi sian haŭton aŭ leopardo siajn makulojn? tiel ankaŭ vi, ĉu vi povas fari bonon, alkutimiĝinte al malbono?","Ĉu negro povas ŝanĝi sian haŭton aŭ leopardo siajn makulojn? tiel ankaŭ vi, ĉu vi povas fari bonon, alkutimiĝinte al malbono?"],[13,24,"Tial Mi disblovos ilin kiel pajlopecetojn, kiujn dispelas la vento el la dezerto.","Tial Mi disblovos ilin kiel pajlopecetojn, kiujn dispelas la vento el la dezerto."],[13,25,"Tio estos via sorto, via parto, destinita de Mi, diras la Eternulo, pro tio, ke vi forgesis Min kaj fidis malveraĵon.","Tio estos via sorto, via parto, destinita de Mi, diras la Eternulo, pro tio, ke vi forgesis Min kaj fidis malveraĵon."],[13,26,"Kaj Mi levos la randojn de viaj vestoj ĝis via vizaĝo, kaj montriĝos via hontindaĵo,","Kaj Mi levos la randojn de viaj vestoj ĝis via vizaĝo, kaj montriĝos via hontindaĵo,"],[13,27,"via adulto, via voluptegeco, viaj malĉastaj pensoj. Sur la montetoj de la kampo Mi vidis viajn abomenindaĵojn. Ve al vi, ho Jerusalem! ĉu vi ne puriĝos? kiam do fine?","via adulto, via voluptegeco, viaj malĉastaj pensoj. Sur la montetoj de la kampo Mi vidis viajn abomenindaĵojn. Ve al vi, ho Jerusalem! ĉu vi ne puriĝos? kiam do fine?"],[14,1,"Vorto de la Eternulo, kiu aperis al Jeremia koncerne la senpluvecon.","Vorto de la Eternulo, kiu aperis al Jeremia koncerne la senpluvecon."],[14,2,"Judujo funebras, ĝiaj pordegoj malĝoje nigriĝis, klinite al la tero, kaj plora kriado leviĝas el Jerusalem.","Judujo funebras, ĝiaj pordegoj malĝoje nigriĝis, klinite al la tero, kaj plora kriado leviĝas el Jerusalem."],[14,3,"Ĝiaj potenculoj sendas siajn subulojn, por alporti akvon; ĉi tiuj venas al la putoj, sed ne trovas akvon; ili alportas returne siajn vazojn malplenajn, ili hontas, konsterniĝas, kaj kovras sian kapon.","Ĝiaj potenculoj sendas siajn subulojn, por alporti akvon; ĉi tiuj venas al la putoj, sed ne trovas akvon; ili alportas returne siajn vazojn malplenajn, ili hontas, konsterniĝas, kaj kovras sian kapon."],[14,4,"Ĉar la tero dezertiĝis pro tio, ke ne estis pluvo, tial konsterniĝis la terkultivistoj kaj kovris sian kapon.","Ĉar la tero dezertiĝis pro tio, ke ne estis pluvo, tial konsterniĝis la terkultivistoj kaj kovris sian kapon."],[14,5,"Eĉ cervino, naskinta sur la kampo, forlasas sian idon, ĉar ne ekzistas verdaĵo.","Eĉ cervino, naskinta sur la kampo, forlasas sian idon, ĉar ne ekzistas verdaĵo."],[14,6,"Sovaĝaj azenoj staras sur montetoj, glutas aeron kiel ŝakaloj; senbriliĝis iliaj okuloj, ĉar ne ekzistas herbo.","Sovaĝaj azenoj staras sur montetoj, glutas aeron kiel ŝakaloj; senbriliĝis iliaj okuloj, ĉar ne ekzistas herbo."],[14,7,"Se niaj malbonagoj akuzas nin, ho Eternulo, tiam agu pro Via nomo; ĉar granda estas nia perfido, ni pekis antaŭ Vi.","Se niaj malbonagoj akuzas nin, ho Eternulo, tiam agu pro Via nomo; ĉar granda estas nia perfido, ni pekis antaŭ Vi."],[14,8,"Ho espero de Izrael kaj lia savanto en tempo de malfeliĉo! kial Vi estas kiel fremdulo en la lando, kiel pasanto, kiu eniris nur por tradormi la nokton?","Ho espero de Izrael kaj lia savanto en tempo de malfeliĉo! kial Vi estas kiel fremdulo en la lando, kiel pasanto, kiu eniris nur por tradormi la nokton?"],[14,9,"Kial Vi estas kiel homo konfuzita, kiel fortulo, kiu ne povas helpi? Vi estas ja meze de ni, ho Eternulo, kaj ni portas sur ni Vian nomon; ne forlasu nin.","Kial Vi estas kiel homo konfuzita, kiel fortulo, kiu ne povas helpi? Vi estas ja meze de ni, ho Eternulo, kaj ni portas sur ni Vian nomon; ne forlasu nin."],[14,10,"Tiele diras la Eternulo pri ĉi tiu popolo: Ili amas vagi, ili ne retenas siajn piedojn; tial la Eternulo ne estas favora al ili, nun Li memoras iliajn malbonagojn kaj punas iliajn pekojn.","Tiele diras la Eternulo pri ĉi tiu popolo: Ili amas vagi, ili ne retenas siajn piedojn; tial la Eternulo ne estas favora al ili, nun Li memoras iliajn malbonagojn kaj punas iliajn pekojn."],[14,11,"Kaj la Eternulo diris al mi: Ne preĝu por ĉi tiu popolo, por ĝia bono.","Kaj la Eternulo diris al mi: Ne preĝu por ĉi tiu popolo, por ĝia bono."],[14,12,"Se ili fastos, Mi ne aŭskultos ilian preĝon, kaj se ili alportos bruloferojn kaj farunoferojn, Mi ne estos favora al ili; sed Mi ekstermos ilin per glavo, per malsato, kaj per pesto.","Se ili fastos, Mi ne aŭskultos ilian preĝon, kaj se ili alportos bruloferojn kaj farunoferojn, Mi ne estos favora al ili; sed Mi ekstermos ilin per glavo, per malsato, kaj per pesto."],[14,13,"Tiam mi diris: Ho Sinjoro, ho Eternulo! jen la profetoj diras al ili: Vi ne vidos glavon, kaj malsato ne estos ĉe vi, ĉar veran pacon Mi donos al vi sur ĉi tiu loko.","Tiam mi diris: Ho Sinjoro, ho Eternulo! jen la profetoj diras al ili: Vi ne vidos glavon, kaj malsato ne estos ĉe vi, ĉar veran pacon Mi donos al vi sur ĉi tiu loko."],[14,14,"Sed la Eternulo diris al mi: Malveraĵon profetas tiuj profetoj en Mia nomo; Mi ne sendis ilin, ne donis al ili ordonojn, kaj ne parolis al ili; ili profetas al vi viziojn mensogajn, sorĉaĵon, idolaĵon, kaj trompaĵon de sia koro.","Sed la Eternulo diris al mi: Malveraĵon profetas tiuj profetoj en Mia nomo; Mi ne sendis ilin, ne donis al ili ordonojn, kaj ne parolis al ili; ili profetas al vi viziojn mensogajn, sorĉaĵon, idolaĵon, kaj trompaĵon de sia koro."],[14,15,"Tial tiele diras la Eternulo pri la profetoj: Ĉar ili profetas en Mia nomo, kvankam Mi ne sendis ilin, kaj ili diras, ke glavo kaj malsato ne estos en ĉi tiu lando — per glavo kaj malsato estos ekstermitaj tiuj profetoj;","Tial tiele diras la Eternulo pri la profetoj: Ĉar ili profetas en Mia nomo, kvankam Mi ne sendis ilin, kaj ili diras, ke glavo kaj malsato ne estos en ĉi tiu lando — per glavo kaj malsato estos ekstermitaj tiuj profetoj;"],[14,16,"kaj la popolo, al kiu ili profetas, estos disĵetita sur la stratojn de Jerusalem per malsato kaj glavo, kaj neniu ilin enterigos — ili, iliaj edzinoj, iliaj filoj, kaj iliaj filinoj; kaj Mi elverŝos sur ilin ilian malbonecon.","kaj la popolo, al kiu ili profetas, estos disĵetita sur la stratojn de Jerusalem per malsato kaj glavo, kaj neniu ilin enterigos — ili, iliaj edzinoj, iliaj filoj, kaj iliaj filinoj; kaj Mi elverŝos sur ilin ilian malbonecon."],[14,17,"Kaj diru al ili jenon: Miaj okuloj fluigas larmojn nokte kaj tage kaj ne ĉesas, ĉar granda malfeliĉo trafis la virgulinon, la filinon de mia popolo, frapo tre doloriga.","Kaj diru al ili jenon: Miaj okuloj fluigas larmojn nokte kaj tage kaj ne ĉesas, ĉar granda malfeliĉo trafis la virgulinon, la filinon de mia popolo, frapo tre doloriga."],[14,18,"Kiam mi eliras sur la kampon, mi vidas homojn, mortigitajn per glavo; kiam mi eniras en la urbon, mi vidas homojn, senfortigitajn de malsato; ankaŭ la profetoj kaj pastroj formigris en landon, kiun ili ne konas.","Kiam mi eliras sur la kampon, mi vidas homojn, mortigitajn per glavo; kiam mi eniras en la urbon, mi vidas homojn, senfortigitajn de malsato; ankaŭ la profetoj kaj pastroj formigris en landon, kiun ili ne konas."],[14,19,"Ĉu Vi tute forpuŝis Jehudan? ĉu Via animo eksentis abomenon kontraŭ Cion? kial Vi frapis nin tiel, ke neniu povas nin resanigi? Ni esperis pacon, sed venis nenio bona; ni esperis tempon de resaniĝo, sed ni havas nur teruron.","Ĉu Vi tute forpuŝis Jehudan? ĉu Via animo eksentis abomenon kontraŭ Cion? kial Vi frapis nin tiel, ke neniu povas nin resanigi? Ni esperis pacon, sed venis nenio bona; ni esperis tempon de resaniĝo, sed ni havas nur teruron."],[14,20,"Ni konfesas, ho Eternulo, nian malpiecon kaj la malbonagojn de niaj patroj; ĉar ni pekis antaŭ Vi.","Ni konfesas, ho Eternulo, nian malpiecon kaj la malbonagojn de niaj patroj; ĉar ni pekis antaŭ Vi."],[14,21,"Pro Via nomo ne malestimegu nin, ne malaltigu la tronon de Via gloro; memoru kaj ne rompu Vian interligon kun ni.","Pro Via nomo ne malestimegu nin, ne malaltigu la tronon de Via gloro; memoru kaj ne rompu Vian interligon kun ni."],[14,22,"Ĉu inter la idoloj de la nacioj ekzistas tiaj, kiuj povas doni pluvon? ĉu la ĉielo per si mem donas pluvegon? Vi estas ja la Eternulo, nia Dio, kaj ni esperas al Vi, ĉar Vi faras ĉion ĉi tion.","Ĉu inter la idoloj de la nacioj ekzistas tiaj, kiuj povas doni pluvon? ĉu la ĉielo per si mem donas pluvegon? Vi estas ja la Eternulo, nia Dio, kaj ni esperas al Vi, ĉar Vi faras ĉion ĉi tion."],[15,1,"Kaj la Eternulo diris al mi: Eĉ se stariĝus antaŭ Mi Moseo kaj Samuel, eĉ tiam Mia animo ne estos kun tiu popolo; forpelu ilin de antaŭ Mia vizaĝo, ili foriru.","Kaj la Eternulo diris al mi: Eĉ se stariĝus antaŭ Mi Moseo kaj Samuel, eĉ tiam Mia animo ne estos kun tiu popolo; forpelu ilin de antaŭ Mia vizaĝo, ili foriru."],[15,2,"Kaj se ili diros al vi: Kien ni iru? tiam diru al ili, ke tiele diras la Eternulo: Kiu estas destinita por la morto, tiu iru al la morto; kiu estas destinita por la glavo, tiu iru al la glavo; kiu estas destinita por la malsato, tiu iru al la malsato; kiu estas destinita por kaptiteco, tiu iru en kaptitecon.","Kaj se ili diros al vi: Kien ni iru? tiam diru al ili, ke tiele diras la Eternulo: Kiu estas destinita por la morto, tiu iru al la morto; kiu estas destinita por la glavo, tiu iru al la glavo; kiu estas destinita por la malsato, tiu iru al la malsato; kiu estas destinita por kaptiteco, tiu iru en kaptitecon."],[15,3,"Mi punos ilin per kvar specoj, diras la Eternulo: per glavo, por mortigi; per hundoj, por treni; per birdoj de la ĉielo kaj per bestoj de la tero, por formanĝi kaj ekstermi.","Mi punos ilin per kvar specoj, diras la Eternulo: per glavo, por mortigi; per hundoj, por treni; per birdoj de la ĉielo kaj per bestoj de la tero, por formanĝi kaj ekstermi."],[15,4,"Mi faros ilin objekto de teruro por ĉiuj regnoj de la tero, pro Manase, filo de Ĥizkija, reĝo de Judujo, pro tio, kion li faris en Jerusalem.","Mi faros ilin objekto de teruro por ĉiuj regnoj de la tero, pro Manase, filo de Ĥizkija, reĝo de Judujo, pro tio, kion li faris en Jerusalem."],[15,5,"Ĉar kiu kompatos vin, ho Jerusalem, kaj kiu afliktiĝos pri vi? kiu sin turnos, por demandi pri via farto?","Ĉar kiu kompatos vin, ho Jerusalem, kaj kiu afliktiĝos pri vi? kiu sin turnos, por demandi pri via farto?"],[15,6,"Vi forlasis Min, diras la Eternulo, vi iris malantaŭen; tial Mi etendas Mian manon sur vin kaj pereigas vin; Mi laciĝis de kompatado.","Vi forlasis Min, diras la Eternulo, vi iris malantaŭen; tial Mi etendas Mian manon sur vin kaj pereigas vin; Mi laciĝis de kompatado."],[15,7,"Mi disŝutis ilin per ŝutilo tra la pordegojn de la lando, Mi seninfanigis kaj pereigis Mian popolon; kaj tamen ili ne returnis sin de sia vojo.","Mi disŝutis ilin per ŝutilo tra la pordegojn de la lando, Mi seninfanigis kaj pereigis Mian popolon; kaj tamen ili ne returnis sin de sia vojo."],[15,8,"Mi faros, ke da vidvinoj ĉe ili estos pli ol da sablo ĉe la maro; en ilian ĉefurbon Mi venigos junan militiston, kiu ruinigas meze de la tago; Mi ĵetos sur ĝin subite timon kaj teruron.","Mi faros, ke da vidvinoj ĉe ili estos pli ol da sablo ĉe la maro; en ilian ĉefurbon Mi venigos junan militiston, kiu ruinigas meze de la tago; Mi ĵetos sur ĝin subite timon kaj teruron."],[15,9,"Naskintino de sep infanoj estas senforta, eliras ŝia animo; subiras ŝia suno, kiam estas ankoraŭ tago; ŝi estas kovrita de honto kaj de malhonoro. Kaj tiujn, kiuj restis, Mi transdonos al glavo antaŭ iliaj malamikoj, diras la Eternulo.","Naskintino de sep infanoj estas senforta, eliras ŝia animo; subiras ŝia suno, kiam estas ankoraŭ tago; ŝi estas kovrita de honto kaj de malhonoro. Kaj tiujn, kiuj restis, Mi transdonos al glavo antaŭ iliaj malamikoj, diras la Eternulo."],[15,10,"Ho ve al vi, mia patrino, ke vi naskis min kiel homon, kontraŭ kiu ĉiu malpacas kaj kiun ĉiu atakas sur la tuta tero! Mi ne pruntedonis procentege, mi ne prenis prunte; tamen ĉiuj min malbenas.","Ho ve al vi, mia patrino, ke vi naskis min kiel homon, kontraŭ kiu ĉiu malpacas kaj kiun ĉiu atakas sur la tuta tero! Mi ne pruntedonis procentege, mi ne prenis prunte; tamen ĉiuj min malbenas."],[15,11,"La Eternulo diris: Mi liberigos vin por bono, Mi helpos vin en la tempo malbona kaj en la tempo de premado kontraŭ la malamiko.","La Eternulo diris: Mi liberigos vin por bono, Mi helpos vin en la tempo malbona kaj en la tempo de premado kontraŭ la malamiko."],[15,12,"Ĉu oni rompas feron per fero el nordo kaj per kupro?","Ĉu oni rompas feron per fero el nordo kaj per kupro?"],[15,13,"Vian riĉaĵon kaj viajn trezorojn Mi fordonos al rabado, sen ia pago, pro ĉiuj viaj pekoj en ĉiuj viaj limoj.","Vian riĉaĵon kaj viajn trezorojn Mi fordonos al rabado, sen ia pago, pro ĉiuj viaj pekoj en ĉiuj viaj limoj."],[15,14,"Kaj Mi transirigos vin al viaj malamikoj en landon, kiun vi ne konas; ĉar fajro, kiu ekflamis en Mia kolero, brulos sur vi.","Kaj Mi transirigos vin al viaj malamikoj en landon, kiun vi ne konas; ĉar fajro, kiu ekflamis en Mia kolero, brulos sur vi."],[15,15,"Vi scias, ho Eternulo; rememoru min, kaj vizitu min, kaj venĝu pro mi al miaj persekutantoj; pro Via toleremeco ne pereigu min; sciu, ke pro Vi mi suferas malhonoron.","Vi scias, ho Eternulo; rememoru min, kaj vizitu min, kaj venĝu pro mi al miaj persekutantoj; pro Via toleremeco ne pereigu min; sciu, ke pro Vi mi suferas malhonoron."],[15,16,"Kiam mi trovis Viajn vortojn, mi ilin englutis; kaj Via vorto fariĝis mia ĝojo kaj gajeco de mia koro; ĉar mi portas sur mi Vian nomon, ho Eternulo, Dio Cebaot.","Kiam mi trovis Viajn vortojn, mi ilin englutis; kaj Via vorto fariĝis mia ĝojo kaj gajeco de mia koro; ĉar mi portas sur mi Vian nomon, ho Eternulo, Dio Cebaot."],[15,17,"Mi ne sidis en interkonsiliĝo de mokantoj kaj ne ĝojis kun ili; mi sidis solece antaŭ Via mano, ĉar Vi plenigis min per indigno.","Mi ne sidis en interkonsiliĝo de mokantoj kaj ne ĝojis kun ili; mi sidis solece antaŭ Via mano, ĉar Vi plenigis min per indigno."],[15,18,"Kial mia malsano estas senfina, kaj mia vundo tiel malfacila, ke ĝi ne povas resaniĝi? Vi fariĝis por mi kiel malaperanta fonto de akvo nefidebla.","Kial mia malsano estas senfina, kaj mia vundo tiel malfacila, ke ĝi ne povas resaniĝi? Vi fariĝis por mi kiel malaperanta fonto de akvo nefidebla."],[15,19,"Tial tiele diras la Eternulo: Se vi revenos, tiam Mi denove starigos vin antaŭ Mi; se el senvaloraĵo vi eltiros la valoraĵon, vi fariĝos kiel Mia buŝo; ili revenos al vi, sed vi ne revenos al ili.","Tial tiele diras la Eternulo: Se vi revenos, tiam Mi denove starigos vin antaŭ Mi; se el senvaloraĵo vi eltiros la valoraĵon, vi fariĝos kiel Mia buŝo; ili revenos al vi, sed vi ne revenos al ili."],[15,20,"Kaj Mi starigos vin por tiu popolo kiel fortikan kupran muron; ili batalos kontraŭ vi, sed ne venkos vin; ĉar Mi estas kun vi, por vin helpi kaj savi, diras la Eternulo.","Kaj Mi starigos vin por tiu popolo kiel fortikan kupran muron; ili batalos kontraŭ vi, sed ne venkos vin; ĉar Mi estas kun vi, por vin helpi kaj savi, diras la Eternulo."],[15,21,"Mi savos vin el la mano de malbonuloj, kaj Mi liberigos vin el la mano de tiranoj.","Mi savos vin el la mano de malbonuloj, kaj Mi liberigos vin el la mano de tiranoj."],[16,1,"Kaj aperis al mi la vorto de la Eternulo, dirante:","Kaj aperis al mi la vorto de la Eternulo, dirante:"],[16,2,"Ne prenu al vi edzinon, kaj ne havu filojn nek filinojn, sur ĉi tiu loko.","Ne prenu al vi edzinon, kaj ne havu filojn nek filinojn, sur ĉi tiu loko."],[16,3,"Ĉar tiele diras la Eternulo pri la filoj kaj filinoj, kiuj naskiĝas sur ĉi tiu loko, pri iliaj patrinoj, kiuj naskas ilin, kaj pri iliaj patroj, kiuj naskigas ilin en ĉi tiu lando:","Ĉar tiele diras la Eternulo pri la filoj kaj filinoj, kiuj naskiĝas sur ĉi tiu loko, pri iliaj patrinoj, kiuj naskas ilin, kaj pri iliaj patroj, kiuj naskigas ilin en ĉi tiu lando:"],[16,4,"Per diversaj doloraj mortoj ili mortos; ili ne estos priplorataj nek enterigitaj, ili estos kiel sterko sur la supraĵo de la tero; de glavo kaj de malsato ili pereos, kaj iliaj kadavroj estos manĝaĵo por la birdoj de la ĉielo kaj por la bestoj de la tero.","Per diversaj doloraj mortoj ili mortos; ili ne estos priplorataj nek enterigitaj, ili estos kiel sterko sur la supraĵo de la tero; de glavo kaj de malsato ili pereos, kaj iliaj kadavroj estos manĝaĵo por la birdoj de la ĉielo kaj por la bestoj de la tero."],[16,5,"Ĉar tiele diras la Eternulo: Ne eniru en la domon de plorado, ne iru funebri, kaj ne konsolu ilin; ĉar Mi forprenis de tiu popolo Mian pacon, diras la Eternulo, la favorkorecon kaj la kompaton.","Ĉar tiele diras la Eternulo: Ne eniru en la domon de plorado, ne iru funebri, kaj ne konsolu ilin; ĉar Mi forprenis de tiu popolo Mian pacon, diras la Eternulo, la favorkorecon kaj la kompaton."],[16,6,"Mortos la granduloj kaj la malgranduloj en tiu lando; ili ne estos enterigitaj nek priplorataj; oni ne faros al si tranĉojn nek kalvaĵon pro ili.","Mortos la granduloj kaj la malgranduloj en tiu lando; ili ne estos enterigitaj nek priplorataj; oni ne faros al si tranĉojn nek kalvaĵon pro ili."],[16,7,"Oni ne disdonos inter ili panon de funebro, por konsoli ilin pri la mortinto, kaj oni ne trinkigos al ili kalikon de konsolo pri ilia patro kaj pri ilia patrino.","Oni ne disdonos inter ili panon de funebro, por konsoli ilin pri la mortinto, kaj oni ne trinkigos al ili kalikon de konsolo pri ilia patro kaj pri ilia patrino."],[16,8,"Ankaŭ en la domon de festeno ne iru, por sidi kun ili, por manĝi kaj trinki.","Ankaŭ en la domon de festeno ne iru, por sidi kun ili, por manĝi kaj trinki."],[16,9,"Ĉar tiele diras la Eternulo Cebaot, Dio de Izrael: Jen Mi forigos de ĉi tiu loko antaŭ viaj okuloj kaj dum via vivo la sonojn de ĝojo kaj la sonojn de gajeco, la voĉon de fianĉo kaj la voĉon de fianĉino.","Ĉar tiele diras la Eternulo Cebaot, Dio de Izrael: Jen Mi forigos de ĉi tiu loko antaŭ viaj okuloj kaj dum via vivo la sonojn de ĝojo kaj la sonojn de gajeco, la voĉon de fianĉo kaj la voĉon de fianĉino."],[16,10,"Kiam vi diros al tiu popolo ĉiujn ĉi tiujn vortojn, kaj ili diros al vi: Pro kio la Eternulo eldiris pri ni tiun tutan grandan malfeliĉon? kia estas nia krimo, kaj kia estas nia peko, kiun ni pekis antaŭ la Eternulo, nia Dio? —","Kiam vi diros al tiu popolo ĉiujn ĉi tiujn vortojn, kaj ili diros al vi: Pro kio la Eternulo eldiris pri ni tiun tutan grandan malfeliĉon? kia estas nia krimo, kaj kia estas nia peko, kiun ni pekis antaŭ la Eternulo, nia Dio? —"],[16,11,"tiam diru al ili: Pro tio, ke viaj patroj forlasis Min, diras la Eternulo, kaj sekvis aliajn diojn kaj servis kaj adorkliniĝis al ili, dum Min ili forlasis kaj Mian instruon ne obeis;","tiam diru al ili: Pro tio, ke viaj patroj forlasis Min, diras la Eternulo, kaj sekvis aliajn diojn kaj servis kaj adorkliniĝis al ili, dum Min ili forlasis kaj Mian instruon ne obeis;"],[16,12,"kaj vi agas ankoraŭ pli malbone ol viaj patroj, kaj ĉiu el vi sekvas la obstinecon de sia malbona koro, ne aŭskultante Min;","kaj vi agas ankoraŭ pli malbone ol viaj patroj, kaj ĉiu el vi sekvas la obstinecon de sia malbona koro, ne aŭskultante Min;"],[16,13,"tial Mi elĵetos vin el ĉi tiu lando en landon, kiun ne konis vi nek viaj patroj, kaj vi servos tie al aliaj dioj tage kaj nokte, ĉar Mi ne donos al vi indulgon.","tial Mi elĵetos vin el ĉi tiu lando en landon, kiun ne konis vi nek viaj patroj, kaj vi servos tie al aliaj dioj tage kaj nokte, ĉar Mi ne donos al vi indulgon."],[16,14,"Pro tio jen venos tempo, diras la Eternulo, kiam oni ne plu diros: Vivas la Eternulo, kiu elkondukis la Izraelidojn el la lando Egipta;","Pro tio jen venos tempo, diras la Eternulo, kiam oni ne plu diros: Vivas la Eternulo, kiu elkondukis la Izraelidojn el la lando Egipta;"],[16,15,"sed: Vivas la Eternulo, kiu elkondukis la Izraelidojn el la lando norda, kaj el ĉiuj landoj, kien Li dispelis ilin; ĉar Mi revenigos ilin en ilian landon, kiun Mi donis al iliaj patroj.","sed: Vivas la Eternulo, kiu elkondukis la Izraelidojn el la lando norda, kaj el ĉiuj landoj, kien Li dispelis ilin; ĉar Mi revenigos ilin en ilian landon, kiun Mi donis al iliaj patroj."],[16,16,"Jen Mi sendos multe da fiŝkaptistoj, diras la Eternulo, por kapti ilin; poste Mi sendos multe da ĉasistoj, por ĉasi ilin de ĉiu monto, de ĉiu monteto, kaj el la fendoj de la rokoj.","Jen Mi sendos multe da fiŝkaptistoj, diras la Eternulo, por kapti ilin; poste Mi sendos multe da ĉasistoj, por ĉasi ilin de ĉiu monto, de ĉiu monteto, kaj el la fendoj de la rokoj."],[16,17,"Ĉar Miaj okuloj vidas ĉiujn iliajn vojojn; ili ne estas kovritaj antaŭ Mi, kaj iliaj malbonagoj ne estas kaŝitaj antaŭ Miaj okuloj.","Ĉar Miaj okuloj vidas ĉiujn iliajn vojojn; ili ne estas kovritaj antaŭ Mi, kaj iliaj malbonagoj ne estas kaŝitaj antaŭ Miaj okuloj."],[16,18,"Antaŭ ĉio Mi duoble pagos pro iliaj malbonagoj kaj iliaj pekoj, pro tio, ke ili malpurigis Mian landon: per la kadavroj de siaj idoloj kaj per siaj abomenindaĵoj ili plenigis Mian heredaĵon.","Antaŭ ĉio Mi duoble pagos pro iliaj malbonagoj kaj iliaj pekoj, pro tio, ke ili malpurigis Mian landon: per la kadavroj de siaj idoloj kaj per siaj abomenindaĵoj ili plenigis Mian heredaĵon."],[16,19,"Ho Eternulo, mia forto kaj mia fortikeco kaj mia rifuĝo en tempo de malfeliĉo! al Vi venos nacioj de la randoj de la tero, kaj diros: Nur malverajn diojn heredis niaj patroj; ili estas vantaĵo, ili taŭgas por nenio.","Ho Eternulo, mia forto kaj mia fortikeco kaj mia rifuĝo en tempo de malfeliĉo! al Vi venos nacioj de la randoj de la tero, kaj diros: Nur malverajn diojn heredis niaj patroj; ili estas vantaĵo, ili taŭgas por nenio."],[16,20,"Ĉu povas homo fari al si diojn? ili ne estas ja dioj.","Ĉu povas homo fari al si diojn? ili ne estas ja dioj."],[16,21,"Tial jen Mi prudentigos ilin; tiun fojon Mi sentigos al ili Mian manon kaj Mian forton; kaj ili ekscios, ke Mia nomo estas Eternulo.","Tial jen Mi prudentigos ilin; tiun fojon Mi sentigos al ili Mian manon kaj Mian forton; kaj ili ekscios, ke Mia nomo estas Eternulo."],[17,1,"La peko de Jehuda estas skribita per fera skribilo, per diamanta pinto, sur la tabelo de ilia koro kaj sur la kornoj de iliaj altaroj.","La peko de Jehuda estas skribita per fera skribilo, per diamanta pinto, sur la tabelo de ilia koro kaj sur la kornoj de iliaj altaroj."],[17,2,"Iliaj filoj bone memoras iliajn altarojn kaj iliajn sanktajn stangojn ĉe la verdaj arboj sur la altaj montetoj.","Iliaj filoj bone memoras iliajn altarojn kaj iliajn sanktajn stangojn ĉe la verdaj arboj sur la altaj montetoj."],[17,3,"Ĉu Mia monto estas sur la kampo? vian havon kaj ĉiujn viajn trezorojn Mi fordonos por disrabo, viajn altaĵojn pro la pekoj en ĉiuj viaj limoj.","Ĉu Mia monto estas sur la kampo? vian havon kaj ĉiujn viajn trezorojn Mi fordonos por disrabo, viajn altaĵojn pro la pekoj en ĉiuj viaj limoj."],[17,4,"Kaj vi estos elpuŝita el la heredaĵo, kiun Mi donis al vi, kaj Mi servigos vin al viaj malamikoj en lando, kiun vi ne konas; ĉar vi ekbruligis fajron de Mia kolero, ĝi flamos eterne.","Kaj vi estos elpuŝita el la heredaĵo, kiun Mi donis al vi, kaj Mi servigos vin al viaj malamikoj en lando, kiun vi ne konas; ĉar vi ekbruligis fajron de Mia kolero, ĝi flamos eterne."],[17,5,"Tiele diras la Eternulo: Malbenita estas la homo, kiu fidas homon kaj faris karnon lia apogo kaj kies koro forturnis sin de la Eternulo.","Tiele diras la Eternulo: Malbenita estas la homo, kiu fidas homon kaj faris karnon lia apogo kaj kies koro forturnis sin de la Eternulo."],[17,6,"Li estos kiel nuda arbo en la dezerto; li ne vidos, kiam venos bono; li loĝos sur sunbruligita loko, en lando senfrukta kaj ne loĝata.","Li estos kiel nuda arbo en la dezerto; li ne vidos, kiam venos bono; li loĝos sur sunbruligita loko, en lando senfrukta kaj ne loĝata."],[17,7,"Benita estas la homo, kiu fidas la Eternulon, kaj la Eternulo estos lia apogo.","Benita estas la homo, kiu fidas la Eternulon, kaj la Eternulo estos lia apogo."],[17,8,"Li estos kiel arbo, plantita ĉe akvo kaj etendanta siajn radikojn al torento; ĝi ne timas, kiam venas varmego; ĝiaj folioj restas verdaj, kaj en tempo de sekeco ĝi ne zorgas kaj ne ĉesas doni fruktojn.","Li estos kiel arbo, plantita ĉe akvo kaj etendanta siajn radikojn al torento; ĝi ne timas, kiam venas varmego; ĝiaj folioj restas verdaj, kaj en tempo de sekeco ĝi ne zorgas kaj ne ĉesas doni fruktojn."],[17,9,"Malica estas ĉies koro, kaj nefidinda; kiu povas ĝin ekkoni?","Malica estas ĉies koro, kaj nefidinda; kiu povas ĝin ekkoni?"],[17,10,"Sed Mi, la Eternulo, trapenetras la koron, esploras la internon, por redoni al ĉiu laŭ lia konduto, laŭ la fruktoj de liaj agoj.","Sed Mi, la Eternulo, trapenetras la koron, esploras la internon, por redoni al ĉiu laŭ lia konduto, laŭ la fruktoj de liaj agoj."],[17,11,"Perdriko kovas ovojn, kiujn ĝi ne naskis; tia estas tiu, kiu akiras riĉecon per rimedoj maljustaj: en la mezo de sia vivo li ĝin perdos, kaj en la fino li restos malsaĝulo.","Perdriko kovas ovojn, kiujn ĝi ne naskis; tia estas tiu, kiu akiras riĉecon per rimedoj maljustaj: en la mezo de sia vivo li ĝin perdos, kaj en la fino li restos malsaĝulo."],[17,12,"Sed la loko de nia sanktejo estas trono de gloro, alta de tempo antikva.","Sed la loko de nia sanktejo estas trono de gloro, alta de tempo antikva."],[17,13,"Ho Eternulo, espero de Izrael! ĉiuj, kiuj forlasas Vin, estos hontigitaj, la defalintoj estos skribitaj sur la tero; ĉar ili forlasis la Eternulon, la fonton de viva akvo.","Ho Eternulo, espero de Izrael! ĉiuj, kiuj forlasas Vin, estos hontigitaj, la defalintoj estos skribitaj sur la tero; ĉar ili forlasis la Eternulon, la fonton de viva akvo."],[17,14,"Sanigu min, ho Eternulo, kaj mi estos sanigita; savu min, kaj mi estos savita; ĉar Vi estas mia gloro.","Sanigu min, ho Eternulo, kaj mi estos sanigita; savu min, kaj mi estos savita; ĉar Vi estas mia gloro."],[17,15,"Jen ili diras al mi: Kie estas la vorto de la Eternulo? ĝi plenumiĝu.","Jen ili diras al mi: Kie estas la vorto de la Eternulo? ĝi plenumiĝu."],[17,16,"Sed mi ne forklinis min de tio, esti paŝtisto laŭ Via montro; la tagon de malfeliĉo mi ne deziris, tion Vi scias; kio eliris el mia buŝo, tio estis ĝusta antaŭ Via vizaĝo.","Sed mi ne forklinis min de tio, esti paŝtisto laŭ Via montro; la tagon de malfeliĉo mi ne deziris, tion Vi scias; kio eliris el mia buŝo, tio estis ĝusta antaŭ Via vizaĝo."],[17,17,"Ne estu por mi terura, Vi, mia rifuĝejo en la tago de mizero!","Ne estu por mi terura, Vi, mia rifuĝejo en la tago de mizero!"],[17,18,"Miaj persekutantoj estu hontigitaj, sed mi ne estu hontigita; ili tremu, sed mi ne tremu; venigu sur ilin tagon de mizero, kaj frapu ilin per duobla frapo.","Miaj persekutantoj estu hontigitaj, sed mi ne estu hontigita; ili tremu, sed mi ne tremu; venigu sur ilin tagon de mizero, kaj frapu ilin per duobla frapo."],[17,19,"Tiele diris al mi la Eternulo: Iru kaj stariĝu en la pordego de la simpla popolo, tiu pordego, tra kiu eniras kaj eliras la reĝoj de Judujo, kaj en ĉiuj pordegoj de Jerusalem;","Tiele diris al mi la Eternulo: Iru kaj stariĝu en la pordego de la simpla popolo, tiu pordego, tra kiu eniras kaj eliras la reĝoj de Judujo, kaj en ĉiuj pordegoj de Jerusalem;"],[17,20,"kaj diru al ili: Aŭskultu la vorton de la Eternulo, ho reĝoj de Judujo, kaj ĉiuj Judoj kaj ĉiuj loĝantoj de Jerusalem, kiuj iras tra ĉi tiuj pordegoj.","kaj diru al ili: Aŭskultu la vorton de la Eternulo, ho reĝoj de Judujo, kaj ĉiuj Judoj kaj ĉiuj loĝantoj de Jerusalem, kiuj iras tra ĉi tiuj pordegoj."],[17,21,"Tiele diras la Eternulo: Gardu viajn animojn, kaj ne portu ŝarĝojn en la tago sabata, kaj ne enportu ilin tra la pordegoj de Jerusalem;","Tiele diras la Eternulo: Gardu viajn animojn, kaj ne portu ŝarĝojn en la tago sabata, kaj ne enportu ilin tra la pordegoj de Jerusalem;"],[17,22,"kaj ne elportu ŝarĝon el viaj domoj en la tago sabata, kaj faru nenian laboron, sed sanktigu la tagon sabatan, kiel Mi ordonis al viaj patroj.","kaj ne elportu ŝarĝon el viaj domoj en la tago sabata, kaj faru nenian laboron, sed sanktigu la tagon sabatan, kiel Mi ordonis al viaj patroj."],[17,23,"Sed ili ne aŭskultis kaj ne alklinis sian orelon, sed obstinigis sian nukon, por ne aŭskulti kaj por ne akcepti moralinstruon.","Sed ili ne aŭskultis kaj ne alklinis sian orelon, sed obstinigis sian nukon, por ne aŭskulti kaj por ne akcepti moralinstruon."],[17,24,"Se vi aŭskultos Min, diras la Eternulo, kaj ne portos ŝarĝon tra la pordegoj de ĉi tiu urbo en la tago sabata, sed vi sanktigos la tagon sabatan, farante en ĝi nenian laboron:","Se vi aŭskultos Min, diras la Eternulo, kaj ne portos ŝarĝon tra la pordegoj de ĉi tiu urbo en la tago sabata, sed vi sanktigos la tagon sabatan, farante en ĝi nenian laboron:"],[17,25,"tiam tra la pordegoj de ĉi tiu urbo irados reĝoj kaj princoj, sidantaj sur la trono de David, veturantaj sur ĉaroj kaj ĉevaloj, ili kaj iliaj princoj, la Judoj kaj la loĝantoj de Jerusalem, kaj ĉi tiu urbo estos loĝata eterne.","tiam tra la pordegoj de ĉi tiu urbo irados reĝoj kaj princoj, sidantaj sur la trono de David, veturantaj sur ĉaroj kaj ĉevaloj, ili kaj iliaj princoj, la Judoj kaj la loĝantoj de Jerusalem, kaj ĉi tiu urbo estos loĝata eterne."],[17,26,"Kaj oni venados el la urboj de Judujo, el la ĉirkaŭaĵoj de Jerusalem, el la lando de Benjamen, de la ebenaĵo, de la montoj, kaj de sudo, alportante bruloferojn kaj buĉoferojn kaj farunoferojn kaj olibanon kaj dankajn donacojn en la domon de la Eternulo.","Kaj oni venados el la urboj de Judujo, el la ĉirkaŭaĵoj de Jerusalem, el la lando de Benjamen, de la ebenaĵo, de la montoj, kaj de sudo, alportante bruloferojn kaj buĉoferojn kaj farunoferojn kaj olibanon kaj dankajn donacojn en la domon de la Eternulo."],[17,27,"Sed se vi ne obeos Min, ke vi sanktigu la tagon sabatan kaj ne portu ŝarĝon, irante tra la pordegoj de Jerusalem en la tago sabata: tiam Mi ekbruligos en ĝiaj pordegoj fajron, kiu ekstermos la palacojn de Jerusalem kaj ne estingiĝos.","Sed se vi ne obeos Min, ke vi sanktigu la tagon sabatan kaj ne portu ŝarĝon, irante tra la pordegoj de Jerusalem en la tago sabata: tiam Mi ekbruligos en ĝiaj pordegoj fajron, kiu ekstermos la palacojn de Jerusalem kaj ne estingiĝos."],[18,1,"Jen estas la vorto, kiu aperis al Jeremia de la Eternulo:","Jen estas la vorto, kiu aperis al Jeremia de la Eternulo:"],[18,2,"Leviĝu kaj iru en la domon de la potisto, kaj tie Mi aŭdigos al vi Miajn vortojn.","Leviĝu kaj iru en la domon de la potisto, kaj tie Mi aŭdigos al vi Miajn vortojn."],[18,3,"Kaj mi iris en la domon de la potisto, kaj jen li laboras sur la stablo.","Kaj mi iris en la domon de la potisto, kaj jen li laboras sur la stablo."],[18,4,"Kaj kiam difektiĝis en la mano de la potisto la vazo, kiun li estis faranta el argilo, li faris denove alian vazon, kian al li plaĉis fari.","Kaj kiam difektiĝis en la mano de la potisto la vazo, kiun li estis faranta el argilo, li faris denove alian vazon, kian al li plaĉis fari."],[18,5,"Tiam aperis al mi la jena vorto de la Eternulo:","Tiam aperis al mi la jena vorto de la Eternulo:"],[18,6,"Ĉu Mi ne povas agi kun vi, ho domo de Izrael, kiel tiu potisto? diras la Eternulo; jen kiel la argilo en la mano de la potisto, tiel vi estas en Mia mano, ho domo de Izrael.","Ĉu Mi ne povas agi kun vi, ho domo de Izrael, kiel tiu potisto? diras la Eternulo; jen kiel la argilo en la mano de la potisto, tiel vi estas en Mia mano, ho domo de Izrael."],[18,7,"Unu momenton Mi decidas pri popolo kaj pri regno, ke Mi ĝin elŝiros, disfrapos, kaj pereigos;","Unu momenton Mi decidas pri popolo kaj pri regno, ke Mi ĝin elŝiros, disfrapos, kaj pereigos;"],[18,8,"sed se tiu popolo pentas sian malbonecon, pro kiu Mi decidis pri ĝi, tiam Mi ankaŭ pentas pri la malfeliĉo, kiun Mi intencis fari al ĝi.","sed se tiu popolo pentas sian malbonecon, pro kiu Mi decidis pri ĝi, tiam Mi ankaŭ pentas pri la malfeliĉo, kiun Mi intencis fari al ĝi."],[18,9,"Alian fojon Mi decidas pri popolo kaj pri regno, ke Mi ĝin fortikigos kaj enradikigos;","Alian fojon Mi decidas pri popolo kaj pri regno, ke Mi ĝin fortikigos kaj enradikigos;"],[18,10,"sed se ĝi faras malbonon antaŭ Miaj okuloj, ne aŭskultante Mian voĉon, tiam Mi pentas pri la bono, kiun Mi intencis fari al ĝi.","sed se ĝi faras malbonon antaŭ Miaj okuloj, ne aŭskultante Mian voĉon, tiam Mi pentas pri la bono, kiun Mi intencis fari al ĝi."],[18,11,"Kaj nun diru al la Judoj kaj al la loĝantoj de Jerusalem jene: Tiele diras la Eternulo: Jen Mi preparas por vi malbonon kaj havas intencon kontraŭ vi; revenu do ĉiu de sia malbona vojo, kaj rebonigu vian konduton kaj viajn agojn.","Kaj nun diru al la Judoj kaj al la loĝantoj de Jerusalem jene: Tiele diras la Eternulo: Jen Mi preparas por vi malbonon kaj havas intencon kontraŭ vi; revenu do ĉiu de sia malbona vojo, kaj rebonigu vian konduton kaj viajn agojn."],[18,12,"Sed ili diras: Vane, ni sekvos niajn intencojn, kaj ĉiu el ni agos laŭ la obstineco de sia malbona koro.","Sed ili diras: Vane, ni sekvos niajn intencojn, kaj ĉiu el ni agos laŭ la obstineco de sia malbona koro."],[18,13,"Tial tiele diras la Eternulo: Demandu inter la nacioj, ĉu iu aŭdis ion similan; multe da abomenindaĵoj faris la filino de Izrael.","Tial tiele diras la Eternulo: Demandu inter la nacioj, ĉu iu aŭdis ion similan; multe da abomenindaĵoj faris la filino de Izrael."],[18,14,"Ĉu la neĝo de Lebanon ĉesas liveri akvon al Miaj kampoj? ĉu ĉesigas sian iradon la malvarma akvo, fluanta de malproksime?","Ĉu la neĝo de Lebanon ĉesas liveri akvon al Miaj kampoj? ĉu ĉesigas sian iradon la malvarma akvo, fluanta de malproksime?"],[18,15,"Sed Mia popolo forgesis Min, incensas al idoloj; per sia konduto ili senordigas la vojojn eternajn, por iri laŭ vojo ne ebenigita,","Sed Mia popolo forgesis Min, incensas al idoloj; per sia konduto ili senordigas la vojojn eternajn, por iri laŭ vojo ne ebenigita,"],[18,16,"por fari sian landon dezerto, eterna mokataĵo, tiel, ke ĉiu, kiu trapasas ĝin, miras kaj balancas la kapon.","por fari sian landon dezerto, eterna mokataĵo, tiel, ke ĉiu, kiu trapasas ĝin, miras kaj balancas la kapon."],[18,17,"Kiel per orienta vento Mi disblovos ilin antaŭ la malamiko; la nukon kaj ne la vizaĝon Mi montros al ili en la tago de ilia pereo.","Kiel per orienta vento Mi disblovos ilin antaŭ la malamiko; la nukon kaj ne la vizaĝon Mi montros al ili en la tago de ilia pereo."],[18,18,"Ili diris: Ni iru kaj interkonsiliĝu kontraŭ Jeremia; ĉar ne malaperis la leĝinstruo ĉe la pastro, nek konsilo ĉe la saĝulo, nek parolo ĉe la profeto; venu, ni batu lin per la lango, kaj ni ne atentu liajn vortojn.","Ili diris: Ni iru kaj interkonsiliĝu kontraŭ Jeremia; ĉar ne malaperis la leĝinstruo ĉe la pastro, nek konsilo ĉe la saĝulo, nek parolo ĉe la profeto; venu, ni batu lin per la lango, kaj ni ne atentu liajn vortojn."],[18,19,"Atentu min, ho Eternulo, kaj aŭskultu la voĉon de miaj kontraŭuloj.","Atentu min, ho Eternulo, kaj aŭskultu la voĉon de miaj kontraŭuloj."],[18,20,"Ĉu oni devas repagi bonon per malbono? ĉar ili fosis foson por mia animo. Memoru, kiel mi staris antaŭ Vi, por paroli bonon pri ili, por forklini de ili Vian koleron.","Ĉu oni devas repagi bonon per malbono? ĉar ili fosis foson por mia animo. Memoru, kiel mi staris antaŭ Vi, por paroli bonon pri ili, por forklini de ili Vian koleron."],[18,21,"Tial elmetu iliajn filojn al malsato kaj transdonu ilin al glavo; iliaj edzinoj fariĝu seninfanaj kaj vidvinoj, iliaj viroj estu frapitaj de morto, iliaj junuloj estu mortigitaj de glavo en milito.","Tial elmetu iliajn filojn al malsato kaj transdonu ilin al glavo; iliaj edzinoj fariĝu seninfanaj kaj vidvinoj, iliaj viroj estu frapitaj de morto, iliaj junuloj estu mortigitaj de glavo en milito."],[18,22,"Kriado estu aŭdata el iliaj domoj, kiam Vi subite venigos sur ilin amasojn, pro tio, ke ili fosis foson, por kapti min, kaj reton ili metis antaŭ miajn piedojn.","Kriado estu aŭdata el iliaj domoj, kiam Vi subite venigos sur ilin amasojn, pro tio, ke ili fosis foson, por kapti min, kaj reton ili metis antaŭ miajn piedojn."],[18,23,"Vi, ho Eternulo, scias ĉiujn iliajn intencojn kontraŭ mi, por mortigi min; ne pardonu ilian malbonagon, kaj ilian pekon antaŭ Vi ne elviŝu; faligu ilin antaŭ Vi; agu kontraŭ ili en la tempo de Via kolero.","Vi, ho Eternulo, scias ĉiujn iliajn intencojn kontraŭ mi, por mortigi min; ne pardonu ilian malbonagon, kaj ilian pekon antaŭ Vi ne elviŝu; faligu ilin antaŭ Vi; agu kontraŭ ili en la tempo de Via kolero."],[19,1,"Tiele diris la Eternulo: Iru kaj aĉetu argilan kruĉon de potisto, kaj, preninte kelkajn el la plejaĝuloj de la popolo kaj el la plejaĝuloj de la pastroj,","Tiele diris la Eternulo: Iru kaj aĉetu argilan kruĉon de potisto, kaj, preninte kelkajn el la plejaĝuloj de la popolo kaj el la plejaĝuloj de la pastroj,"],[19,2,"iru en la valon de la filo de Hinom, kiu estas antaŭ la Pordego de Argilaĵoj, kaj proklamu tie la vortojn, kiujn Mi diros al vi.","iru en la valon de la filo de Hinom, kiu estas antaŭ la Pordego de Argilaĵoj, kaj proklamu tie la vortojn, kiujn Mi diros al vi."],[19,3,"Kaj diru: Aŭskultu la vorton de la Eternulo, ho reĝoj de Judujo kaj loĝantoj de Jerusalem! tiele diras la Eternulo Cebaot, Dio de Izrael: Jen Mi venigos sur ĉi tiun lokon tian malfeliĉon, ke al ĉiu, kiu aŭdos pri ĝi, eksonoros liaj oreloj.","Kaj diru: Aŭskultu la vorton de la Eternulo, ho reĝoj de Judujo kaj loĝantoj de Jerusalem! tiele diras la Eternulo Cebaot, Dio de Izrael: Jen Mi venigos sur ĉi tiun lokon tian malfeliĉon, ke al ĉiu, kiu aŭdos pri ĝi, eksonoros liaj oreloj."],[19,4,"Pro tio, ke ili forlasis Min, kaj malpurigis ĉi tiun lokon, kaj incensis sur ĝi al aliaj dioj, kiujn ne konis ili nek iliaj patroj nek la reĝoj de Judujo, kaj plenigis ĉi tiun lokon per sango de senkulpuloj;","Pro tio, ke ili forlasis Min, kaj malpurigis ĉi tiun lokon, kaj incensis sur ĝi al aliaj dioj, kiujn ne konis ili nek iliaj patroj nek la reĝoj de Judujo, kaj plenigis ĉi tiun lokon per sango de senkulpuloj;"],[19,5,"kaj konstruis altaĵojn al Baal, por forbruligi siajn filojn kiel bruloferojn al Baal, kion Mi ne ordonis kaj ne diris, kaj kio eĉ ne venis en Mian kapon:","kaj konstruis altaĵojn al Baal, por forbruligi siajn filojn kiel bruloferojn al Baal, kion Mi ne ordonis kaj ne diris, kaj kio eĉ ne venis en Mian kapon:"],[19,6,"pro tio jen venos tempo, diras la Eternulo, kiam oni jam nomos ĉi tiun lokon ne Tofet kaj valo de la filo de Hinom, sed valo de mortigado.","pro tio jen venos tempo, diras la Eternulo, kiam oni jam nomos ĉi tiun lokon ne Tofet kaj valo de la filo de Hinom, sed valo de mortigado."],[19,7,"Kaj Mi detruos sur ĉi tiu loko la planon de Judujo kaj Jerusalem; kaj Mi faligos ilin de glavo antaŭ iliaj malamikoj, kaj de la mano de tiuj, kiuj serĉas ilian animon, kaj Mi donos iliajn kadavrojn kiel manĝaĵon al la birdoj de la ĉielo kaj al la bestoj de la tero.","Kaj Mi detruos sur ĉi tiu loko la planon de Judujo kaj Jerusalem; kaj Mi faligos ilin de glavo antaŭ iliaj malamikoj, kaj de la mano de tiuj, kiuj serĉas ilian animon, kaj Mi donos iliajn kadavrojn kiel manĝaĵon al la birdoj de la ĉielo kaj al la bestoj de la tero."],[19,8,"Kaj Mi faros ĉi tiun urbon dezerto kaj mokataĵo; ĉiu, kiu preterpasos ĝin, miros kaj mokos ĉiujn ĝiajn frapojn.","Kaj Mi faros ĉi tiun urbon dezerto kaj mokataĵo; ĉiu, kiu preterpasos ĝin, miros kaj mokos ĉiujn ĝiajn frapojn."],[19,9,"Kaj Mi manĝigos al ili la karnon de iliaj filoj kaj la karnon de iliaj filinoj, kaj ĉiu manĝos la karnon de sia proksimulo, dum la sieĝo, kaj en la premado, per kiu premos ilin iliaj malamikoj kaj la serĉantoj de iliaj animoj.","Kaj Mi manĝigos al ili la karnon de iliaj filoj kaj la karnon de iliaj filinoj, kaj ĉiu manĝos la karnon de sia proksimulo, dum la sieĝo, kaj en la premado, per kiu premos ilin iliaj malamikoj kaj la serĉantoj de iliaj animoj."],[19,10,"Kaj disrompu la kruĉon antaŭ la okuloj de tiuj viroj, kiuj venis kun vi;","Kaj disrompu la kruĉon antaŭ la okuloj de tiuj viroj, kiuj venis kun vi;"],[19,11,"kaj diru al ili: Tiele diras la Eternulo Cebaot: Tiele Mi disrompos ĉi tiun popolon kaj ĉi tiun urbon, kiel oni disrompas vazon de potisto, ke ĝi ne povas esti tutaĵigita; kaj oni enterigos en Tofet, ĉar ne ekzistos alia loko por enterigado.","kaj diru al ili: Tiele diras la Eternulo Cebaot: Tiele Mi disrompos ĉi tiun popolon kaj ĉi tiun urbon, kiel oni disrompas vazon de potisto, ke ĝi ne povas esti tutaĵigita; kaj oni enterigos en Tofet, ĉar ne ekzistos alia loko por enterigado."],[19,12,"Tiele Mi agos kun ĉi tiu loko, diras la Eternulo, kaj kun ĝiaj loĝantoj, kaj Mi faros ĉi tiun lokon simila al Tofet.","Tiele Mi agos kun ĉi tiu loko, diras la Eternulo, kaj kun ĝiaj loĝantoj, kaj Mi faros ĉi tiun lokon simila al Tofet."],[19,13,"Kaj la domoj de Jerusalem kaj la domoj de la reĝoj de Judujo estos malpuraj, kiel la loko Tofet, ĉiuj domoj, sur kies tegmentoj oni incensis al la tuta armeo de la ĉielo kaj verŝis verŝoferojn al aliaj dioj.","Kaj la domoj de Jerusalem kaj la domoj de la reĝoj de Judujo estos malpuraj, kiel la loko Tofet, ĉiuj domoj, sur kies tegmentoj oni incensis al la tuta armeo de la ĉielo kaj verŝis verŝoferojn al aliaj dioj."],[19,14,"Kaj Jeremia venis de Tofet, kien sendis lin la Eternulo por profeti; kaj li stariĝis sur la korto de la domo de la Eternulo, kaj diris al la tuta popolo:","Kaj Jeremia venis de Tofet, kien sendis lin la Eternulo por profeti; kaj li stariĝis sur la korto de la domo de la Eternulo, kaj diris al la tuta popolo:"],[19,15,"Tiele diras la Eternulo Cebaot, Dio de Izrael: Jen Mi venigos sur ĉi tiun urbon kaj sur ĉiujn ĝiajn vilaĝojn la tutan malfeliĉon, kiun Mi eldiris pri ĝi; ĉar ili obstinigis sian nukon kaj ne aŭskultas Miajn vortojn.","Tiele diras la Eternulo Cebaot, Dio de Izrael: Jen Mi venigos sur ĉi tiun urbon kaj sur ĉiujn ĝiajn vilaĝojn la tutan malfeliĉon, kiun Mi eldiris pri ĝi; ĉar ili obstinigis sian nukon kaj ne aŭskultas Miajn vortojn."],[20,1,"Kiam la pastro Paŝĥur, filo de Imer, la ĉefa oficisto en la domo de la Eternulo, aŭdis, kiel Jeremia profetis ĉion diritan,","Kiam la pastro Paŝĥur, filo de Imer, la ĉefa oficisto en la domo de la Eternulo, aŭdis, kiel Jeremia profetis ĉion diritan,"],[20,2,"Paŝĥur batis la profeton Jeremia, kaj metis lin en karceron, kiu estis en la supra Pordego de Benjamen ĉe la domo de la Eternulo.","Paŝĥur batis la profeton Jeremia, kaj metis lin en karceron, kiu estis en la supra Pordego de Benjamen ĉe la domo de la Eternulo."],[20,3,"La sekvantan tagon Paŝĥur ellasis Jeremian el la karcero; tiam Jeremia diris al li: La Eternulo nomas vin ne Paŝĥur, sed Teruro-ĉirkaŭe.","La sekvantan tagon Paŝĥur ellasis Jeremian el la karcero; tiam Jeremia diris al li: La Eternulo nomas vin ne Paŝĥur, sed Teruro-ĉirkaŭe."],[20,4,"Ĉar tiele diras la Eternulo: Jen Mi faros vin teruro por vi mem kaj por ĉiuj viaj amikoj, kaj ili falos de la glavo de siaj malamikoj; viaj okuloj tion vidos; kaj la tutan Judujon Mi transdonos en la manojn de la reĝo de Babel, kiu ekzilos ilin en Babelon kaj mortigos ilin per la glavo.","Ĉar tiele diras la Eternulo: Jen Mi faros vin teruro por vi mem kaj por ĉiuj viaj amikoj, kaj ili falos de la glavo de siaj malamikoj; viaj okuloj tion vidos; kaj la tutan Judujon Mi transdonos en la manojn de la reĝo de Babel, kiu ekzilos ilin en Babelon kaj mortigos ilin per la glavo."],[20,5,"Kaj la tutan havon de ĉi tiu urbo kaj ĝian tutan laborakiron kaj ĉiujn ĝiajn valoraĵojn kaj ĉiujn trezorojn de la reĝoj de Judujo Mi transdonos en la manon de iliaj malamikoj, kiuj prirabos kaj prenos kaj forportos ilin en Babelon.","Kaj la tutan havon de ĉi tiu urbo kaj ĝian tutan laborakiron kaj ĉiujn ĝiajn valoraĵojn kaj ĉiujn trezorojn de la reĝoj de Judujo Mi transdonos en la manon de iliaj malamikoj, kiuj prirabos kaj prenos kaj forportos ilin en Babelon."],[20,6,"Kaj vi, Paŝĥur, kaj ĉiuj loĝantoj de via domo iros en kaptitecon, venos Babelon, kaj tie vi mortos, kaj tie vi estos enterigitaj, vi kaj ĉiuj viaj amikoj, al kiuj vi profetis malvere.","Kaj vi, Paŝĥur, kaj ĉiuj loĝantoj de via domo iros en kaptitecon, venos Babelon, kaj tie vi mortos, kaj tie vi estos enterigitaj, vi kaj ĉiuj viaj amikoj, al kiuj vi profetis malvere."],[20,7,"Ho Eternulo, Vi fortiris min post Vi, kaj mi lasis fortiri min; Vi estas pli forta ol mi kaj venkis min; kaj mi fariĝis objekto de ĉiutaga mokado, ĉiu mokas min.","Ho Eternulo, Vi fortiris min post Vi, kaj mi lasis fortiri min; Vi estas pli forta ol mi kaj venkis min; kaj mi fariĝis objekto de ĉiutaga mokado, ĉiu mokas min."],[20,8,"Ĉar de la tempo, kiam mi ekparolis, kriis pri maljusteco, vokis pri rabado, la vorto de la Eternulo fariĝis por mi kaŭzo de honto kaj de ĉiutaga mokado.","Ĉar de la tempo, kiam mi ekparolis, kriis pri maljusteco, vokis pri rabado, la vorto de la Eternulo fariĝis por mi kaŭzo de honto kaj de ĉiutaga mokado."],[20,9,"Mi diris al mi: Mi ne rememorigos pri Li, mi ne plu parolos en Lia nomo; sed tio fariĝis en mia koro kiel flamanta fajro, penetrinta en miajn ostojn, kaj mi laciĝis de retenado kaj ne plu povis elteni.","Mi diris al mi: Mi ne rememorigos pri Li, mi ne plu parolos en Lia nomo; sed tio fariĝis en mia koro kiel flamanta fajro, penetrinta en miajn ostojn, kaj mi laciĝis de retenado kaj ne plu povis elteni."],[20,10,"Ĉar mi aŭdas la insultadon de multaj kaj minacadon ĉirkaŭe: Akuzu, ni akuzu lin! Ĉiuj, kiuj vivas pace kun mi, observas min de flanke: Eble li forlogiĝos, tiam ni venkos lin kaj venĝos al li.","Ĉar mi aŭdas la insultadon de multaj kaj minacadon ĉirkaŭe: Akuzu, ni akuzu lin! Ĉiuj, kiuj vivas pace kun mi, observas min de flanke: Eble li forlogiĝos, tiam ni venkos lin kaj venĝos al li."],[20,11,"Sed la Eternulo estas kun mi kiel potenca heroo, tial miaj persekutantoj falos kaj ne venkos; ili estos forte hontigitaj pro tio, ke ili agis tiel malprudente; la honto estos eterna, ne forgesiĝos.","Sed la Eternulo estas kun mi kiel potenca heroo, tial miaj persekutantoj falos kaj ne venkos; ili estos forte hontigitaj pro tio, ke ili agis tiel malprudente; la honto estos eterna, ne forgesiĝos."],[20,12,"Ho Eternulo Cebaot, kiu elprovas virtulon kaj vidas la internon kaj la koron! faru, ke mi vidu Vian venĝon sur ili, ĉar al Vi mi transdonis mian proceson.","Ho Eternulo Cebaot, kiu elprovas virtulon kaj vidas la internon kaj la koron! faru, ke mi vidu Vian venĝon sur ili, ĉar al Vi mi transdonis mian proceson."],[20,13,"Kantu al la Eternulo, gloru la Eternulon; ĉar Li savas la animon de malriĉulo el la mano de malbonaguloj.","Kantu al la Eternulo, gloru la Eternulon; ĉar Li savas la animon de malriĉulo el la mano de malbonaguloj."],[20,14,"Malbenita estu la tago, en kiu mi naskiĝis; la tago, en kiu mia patrino min naskis, ne estu benita.","Malbenita estu la tago, en kiu mi naskiĝis; la tago, en kiu mia patrino min naskis, ne estu benita."],[20,15,"Malbenita estu la homo, kiu sciigis al mia patro kaj diris: Virseksa infano estas naskita al vi, kaj per tio li faris al li grandan ĝojon.","Malbenita estu la homo, kiu sciigis al mia patro kaj diris: Virseksa infano estas naskita al vi, kaj per tio li faris al li grandan ĝojon."],[20,16,"Tiu homo estu kiel la urboj, kiujn la Eternulo senkompate ruinigis; li aŭdu kriadon matene kaj ploregadon tagmeze.","Tiu homo estu kiel la urboj, kiujn la Eternulo senkompate ruinigis; li aŭdu kriadon matene kaj ploregadon tagmeze."],[20,17,"Kial mi ne estis mortigita en la utero, ke mia patrino estu mia tombo kaj ŝia ventro restu graveda por ĉiam?","Kial mi ne estis mortigita en la utero, ke mia patrino estu mia tombo kaj ŝia ventro restu graveda por ĉiam?"],[20,18,"Kial mi eliris el la utero, por vidi malfacilan penadon kaj mizeron kaj por ke mia vivo pasu en honto?","Kial mi eliris el la utero, por vidi malfacilan penadon kaj mizeron kaj por ke mia vivo pasu en honto?"],[21,1,"Jen estas la vorto, kiu aperis al Jeremia de la Eternulo, kiam la reĝo Cidkija sendis al li Paŝĥuron, filon de Malkija, kaj la pastron Cefanja, filo de Maaseja, por diri:","Jen estas la vorto, kiu aperis al Jeremia de la Eternulo, kiam la reĝo Cidkija sendis al li Paŝĥuron, filon de Malkija, kaj la pastron Cefanja, filo de Maaseja, por diri:"],[21,2,"Volu demandi pri ni la Eternulon, ĉar Nebukadnecar, reĝo de Babel, militas kontraŭ ni; eble la Eternulo faros al ni ion similan al ĉiuj Liaj mirakloj, kaj tiu foriros de ni.","Volu demandi pri ni la Eternulon, ĉar Nebukadnecar, reĝo de Babel, militas kontraŭ ni; eble la Eternulo faros al ni ion similan al ĉiuj Liaj mirakloj, kaj tiu foriros de ni."],[21,3,"Kaj Jeremia diris al ili: Tiele diru al Cidkija:","Kaj Jeremia diris al ili: Tiele diru al Cidkija:"],[21,4,"Tiele diras la Eternulo, Dio de Izrael: Jen Mi returnos la batalilojn, kiuj estas en viaj manoj kaj per kiuj vi batalas kontraŭ la reĝo de Babel, kaj kontraŭ la Ĥaldeoj, kiuj sieĝas vin ekstere de la murego, kaj Mi kolektos ilin meze de ĉi tiu urbo.","Tiele diras la Eternulo, Dio de Izrael: Jen Mi returnos la batalilojn, kiuj estas en viaj manoj kaj per kiuj vi batalas kontraŭ la reĝo de Babel, kaj kontraŭ la Ĥaldeoj, kiuj sieĝas vin ekstere de la murego, kaj Mi kolektos ilin meze de ĉi tiu urbo."],[21,5,"Kaj Mi batalos kontraŭ vi per mano etendita kaj per forta brako, en kolero, furiozo, kaj granda indigno.","Kaj Mi batalos kontraŭ vi per mano etendita kaj per forta brako, en kolero, furiozo, kaj granda indigno."],[21,6,"Kaj Mi frapos la loĝantojn de ĉi tiu urbo, la homojn kaj la brutojn; de granda pesto ili mortos.","Kaj Mi frapos la loĝantojn de ĉi tiu urbo, la homojn kaj la brutojn; de granda pesto ili mortos."],[21,7,"Kaj post tio, diras la Eternulo, Cidkijan, reĝon de Judujo, kaj liajn servantojn, kaj la popolon, kaj tiujn, kiuj en ĉi tiu urbo restis de la pesto, de la glavo, kaj de la malsato, Mi transdonos en la manon de Nebukadnecar, reĝo de Babel, en la manon de iliaj malamikoj, kaj en la manon de tiuj, kiuj deziras ilian morton; kaj li mortigos ilin per glavo; li ne hezitos, ne indulgos, kaj ne kompatos.","Kaj post tio, diras la Eternulo, Cidkijan, reĝon de Judujo, kaj liajn servantojn, kaj la popolon, kaj tiujn, kiuj en ĉi tiu urbo restis de la pesto, de la glavo, kaj de la malsato, Mi transdonos en la manon de Nebukadnecar, reĝo de Babel, en la manon de iliaj malamikoj, kaj en la manon de tiuj, kiuj deziras ilian morton; kaj li mortigos ilin per glavo; li ne hezitos, ne indulgos, kaj ne kompatos."],[21,8,"Kaj al ĉi tiu popolo diru: Tiele diras la Eternulo: Jen Mi proponas al vi vojon de vivo kaj vojon de morto:","Kaj al ĉi tiu popolo diru: Tiele diras la Eternulo: Jen Mi proponas al vi vojon de vivo kaj vojon de morto:"],[21,9,"kiu restos en ĉi tiu urbo, tiu mortos de glavo aŭ de malsato aŭ de pesto; kaj kiu eliros kaj transdonos sin al la Ĥaldeoj, kiuj vin sieĝas, tiu restos vivanta, kaj lia animo estos lia akiro.","kiu restos en ĉi tiu urbo, tiu mortos de glavo aŭ de malsato aŭ de pesto; kaj kiu eliros kaj transdonos sin al la Ĥaldeoj, kiuj vin sieĝas, tiu restos vivanta, kaj lia animo estos lia akiro."],[21,10,"Ĉar Mi turnis Mian vizaĝon kontraŭ ĉi tiun urbon por malbono, ne por bono, diras la Eternulo; en la manon de la reĝo de Babel ĝi estos transdonita, kaj li forbruligos ĝin per fajro.","Ĉar Mi turnis Mian vizaĝon kontraŭ ĉi tiun urbon por malbono, ne por bono, diras la Eternulo; en la manon de la reĝo de Babel ĝi estos transdonita, kaj li forbruligos ĝin per fajro."],[21,11,"Kaj koncerne la domon de la reĝo de Judujo aŭskultu la vorton de la Eternulo:","Kaj koncerne la domon de la reĝo de Judujo aŭskultu la vorton de la Eternulo:"],[21,12,"Domo de David! diras la Eternulo: Frue matene faru juĝon kaj savu prematon el la mano de premanto, por ke Mia kolero ne aperu kiel fajro kaj ĝi ne ekflamu pro viaj malbonagoj tiel, ke neniu povos ĝin estingi.","Domo de David! diras la Eternulo: Frue matene faru juĝon kaj savu prematon el la mano de premanto, por ke Mia kolero ne aperu kiel fajro kaj ĝi ne ekflamu pro viaj malbonagoj tiel, ke neniu povos ĝin estingi."],[21,13,"Jen Mi iras kontraŭ vin, kiu staras en la valo, roko sur la ebenaĵo, diras la Eternulo, kontraŭ vin, kiuj diras: Kiu atakos nin? kaj kiu eniros en niajn loĝejojn?","Jen Mi iras kontraŭ vin, kiu staras en la valo, roko sur la ebenaĵo, diras la Eternulo, kontraŭ vin, kiuj diras: Kiu atakos nin? kaj kiu eniros en niajn loĝejojn?"],[21,14,"Kaj Mi punos vin laŭ la fruktoj de viaj agoj, diras la Eternulo; kaj Mi ekbruligos fajron en ĝia arbaro, por ke ĝi ekstermu ĝian tutan ĉirkaŭaĵon.","Kaj Mi punos vin laŭ la fruktoj de viaj agoj, diras la Eternulo; kaj Mi ekbruligos fajron en ĝia arbaro, por ke ĝi ekstermu ĝian tutan ĉirkaŭaĵon."],[22,1,"Tiele diris la Eternulo: Iru en la domon de la reĝo de Judujo, kaj diru tie jenon:","Tiele diris la Eternulo: Iru en la domon de la reĝo de Judujo, kaj diru tie jenon:"],[22,2,"diru: Aŭskultu la vorton de la Eternulo, ho reĝo de Judujo, kiu sidas sur la trono de David, vi, kaj viaj servantoj, kaj via popolo, kiu iras tra ĉi tiuj pordegoj.","diru: Aŭskultu la vorton de la Eternulo, ho reĝo de Judujo, kiu sidas sur la trono de David, vi, kaj viaj servantoj, kaj via popolo, kiu iras tra ĉi tiuj pordegoj."],[22,3,"Tiele diras la Eternulo: Faru juĝon kaj juston, kaj savu prematon el la mano de premanto; ne ofendu kaj ne premu fremdulon, orfon, aŭ vidvinon, kaj sangon senkulpan ne verŝu sur ĉi tiu loko.","Tiele diras la Eternulo: Faru juĝon kaj juston, kaj savu prematon el la mano de premanto; ne ofendu kaj ne premu fremdulon, orfon, aŭ vidvinon, kaj sangon senkulpan ne verŝu sur ĉi tiu loko."],[22,4,"Ĉar se vi plenumos ĉi tiun diron, tiam tra la pordegoj de ĉi tiu domo irados reĝoj, sidantaj sur la trono de David, veturantaj sur ĉaroj kaj sur ĉevaloj, li mem kaj liaj servantoj kaj lia popolo.","Ĉar se vi plenumos ĉi tiun diron, tiam tra la pordegoj de ĉi tiu domo irados reĝoj, sidantaj sur la trono de David, veturantaj sur ĉaroj kaj sur ĉevaloj, li mem kaj liaj servantoj kaj lia popolo."],[22,5,"Sed se vi ne obeos tiujn vortojn, tiam — Mi ĵuras per Mi, diras la Eternulo — ĉi tiu domo fariĝos ruino.","Sed se vi ne obeos tiujn vortojn, tiam — Mi ĵuras per Mi, diras la Eternulo — ĉi tiu domo fariĝos ruino."],[22,6,"Ĉar tiele diras la Eternulo koncerne la domon de la reĝo de Judujo: Vi estas al Mi Gilead, supro de Lebanon; kaj tamen Mi faros vin dezerto, urboj ne loĝataj.","Ĉar tiele diras la Eternulo koncerne la domon de la reĝo de Judujo: Vi estas al Mi Gilead, supro de Lebanon; kaj tamen Mi faros vin dezerto, urboj ne loĝataj."],[22,7,"Mi starigos kontraŭ vi ekstermantojn, ĉiun kun liaj bataliloj, kaj ili dehakos viajn plej bonajn cedrojn kaj ĵetos en fajron.","Mi starigos kontraŭ vi ekstermantojn, ĉiun kun liaj bataliloj, kaj ili dehakos viajn plej bonajn cedrojn kaj ĵetos en fajron."],[22,8,"Kaj multe da nacioj preterpasos ĉi tiun urbon, kaj ili diros unu al la alia: Pro kio la Eternulo agis tiele kun ĉi tiu granda urbo?","Kaj multe da nacioj preterpasos ĉi tiun urbon, kaj ili diros unu al la alia: Pro kio la Eternulo agis tiele kun ĉi tiu granda urbo?"],[22,9,"Kaj oni respondos: Pro tio, ke ili forlasis la interligon de la Eternulo, ilia Dio, kaj adorkliniĝis al aliaj dioj kaj servis al ili.","Kaj oni respondos: Pro tio, ke ili forlasis la interligon de la Eternulo, ilia Dio, kaj adorkliniĝis al aliaj dioj kaj servis al ili."],[22,10,"Ne ploru pri mortinto kaj ne funebru pri li; sed ploru forte pri tiu, kiu foriras, ĉar li ne plu revenos kaj ne revidos la landon de sia naskiĝo.","Ne ploru pri mortinto kaj ne funebru pri li; sed ploru forte pri tiu, kiu foriras, ĉar li ne plu revenos kaj ne revidos la landon de sia naskiĝo."],[22,11,"Ĉar tiele diras la Eternulo pri Ŝalum, filo de Joŝija, reĝo de Judujo, kiu reĝis post sia patro Joŝija kaj foriris de ĉi tiu loko: Li ne plu revenos ĉi tien;","Ĉar tiele diras la Eternulo pri Ŝalum, filo de Joŝija, reĝo de Judujo, kiu reĝis post sia patro Joŝija kaj foriris de ĉi tiu loko: Li ne plu revenos ĉi tien;"],[22,12,"sed sur la loko, kien oni transloĝigis lin en kaptitecon, tie li mortos, kaj ĉi tiun landon li ne plu vidos.","sed sur la loko, kien oni transloĝigis lin en kaptitecon, tie li mortos, kaj ĉi tiun landon li ne plu vidos."],[22,13,"Ve al tiu, kiu konstruas sian domon per malbonagoj kaj siajn ĉambrojn en maljusteco; kiu devigas sian proksimulon labori vane kaj ne donas al li lian prolaboran pagon;","Ve al tiu, kiu konstruas sian domon per malbonagoj kaj siajn ĉambrojn en maljusteco; kiu devigas sian proksimulon labori vane kaj ne donas al li lian prolaboran pagon;"],[22,14,"kiu diras: Mi konstruos al mi grandan domon kaj vastajn ĉambrojn; kaj trahakas al si fenestrojn kaj kadras ilin per cedro kaj kolorigas per cinabro.","kiu diras: Mi konstruos al mi grandan domon kaj vastajn ĉambrojn; kaj trahakas al si fenestrojn kaj kadras ilin per cedro kaj kolorigas per cinabro."],[22,15,"Ĉu vi reĝos per tio, ke vi ĉirkaŭis vin per cedraĵo? via patro ja ankaŭ manĝis kaj trinkis, sed li agis laŭjuĝe kaj juste, kaj tiam estis al li bone.","Ĉu vi reĝos per tio, ke vi ĉirkaŭis vin per cedraĵo? via patro ja ankaŭ manĝis kaj trinkis, sed li agis laŭjuĝe kaj juste, kaj tiam estis al li bone."],[22,16,"Li juĝadis la aferojn de premito kaj malriĉulo, kaj tiam estis bone. Ĉu ne tio signifas koni Min? diras la Eternulo.","Li juĝadis la aferojn de premito kaj malriĉulo, kaj tiam estis bone. Ĉu ne tio signifas koni Min? diras la Eternulo."],[22,17,"Sed viaj okuloj kaj via koro celas nur malhonestan profiton, verŝadon de senkulpa sango, faradon de rabado kaj de premado.","Sed viaj okuloj kaj via koro celas nur malhonestan profiton, verŝadon de senkulpa sango, faradon de rabado kaj de premado."],[22,18,"Tial tiele diras la Eternulo pri Jehojakim, filo de Joŝija, reĝo de Judujo: Oni ne lamentos pri li: Ho ve, mia frato! ho ve, fratino! oni ne lamentos pri li: Ho ve, sinjoro! ho ve, glorulo!","Tial tiele diras la Eternulo pri Jehojakim, filo de Joŝija, reĝo de Judujo: Oni ne lamentos pri li: Ho ve, mia frato! ho ve, fratino! oni ne lamentos pri li: Ho ve, sinjoro! ho ve, glorulo!"],[22,19,"Per enterigo de azeno li estos enterigita: oni trenos lin kaj ĵetos malproksimen de la pordegoj de Jerusalem.","Per enterigo de azeno li estos enterigita: oni trenos lin kaj ĵetos malproksimen de la pordegoj de Jerusalem."],[22,20,"Supreniru sur Lebanonon kaj kriu, kaj en Baŝan laŭtigu vian voĉon, kaj kriu de Abarim; ĉar disbatitaj estas ĉiuj viaj amantoj.","Supreniru sur Lebanonon kaj kriu, kaj en Baŝan laŭtigu vian voĉon, kaj kriu de Abarim; ĉar disbatitaj estas ĉiuj viaj amantoj."],[22,21,"Mi parolis al vi, kiam vi estis ankoraŭ en bona stato, sed vi diris: Mi ne volas aŭskulti. Tia estis via konduto detempe de via juneco, ke vi ne aŭskultis Mian voĉon.","Mi parolis al vi, kiam vi estis ankoraŭ en bona stato, sed vi diris: Mi ne volas aŭskulti. Tia estis via konduto detempe de via juneco, ke vi ne aŭskultis Mian voĉon."],[22,22,"Ĉiujn viajn paŝtistojn forblovos la vento, kaj viaj amantoj iros en kaptitecon; tiam vin kovros honto kaj malhonoro pro ĉiuj viaj malbonagoj.","Ĉiujn viajn paŝtistojn forblovos la vento, kaj viaj amantoj iros en kaptitecon; tiam vin kovros honto kaj malhonoro pro ĉiuj viaj malbonagoj."],[22,23,"Vi sidas sur Lebanon, vi faris al vi neston inter cedroj; kiel mizera vi estos, kiam atakos vin doloroj, kiel doloroj de naskantino!","Vi sidas sur Lebanon, vi faris al vi neston inter cedroj; kiel mizera vi estos, kiam atakos vin doloroj, kiel doloroj de naskantino!"],[22,24,"Kiel Mi vivas, diras la Eternulo, se Konja, filo de Jehojakim, reĝo de Judujo, eĉ estus sigelringo sur Mia dekstra mano, eĉ de tie Mi vin deŝirus.","Kiel Mi vivas, diras la Eternulo, se Konja, filo de Jehojakim, reĝo de Judujo, eĉ estus sigelringo sur Mia dekstra mano, eĉ de tie Mi vin deŝirus."],[22,25,"Kaj Mi transdonos vin en la manon de tiuj, kiuj celas vian morton, kaj en la manon de tiuj, kiujn vi timegas, en la manon de Nebukadnecar, reĝo de Babel, kaj en la manon de la Ĥaldeoj.","Kaj Mi transdonos vin en la manon de tiuj, kiuj celas vian morton, kaj en la manon de tiuj, kiujn vi timegas, en la manon de Nebukadnecar, reĝo de Babel, kaj en la manon de la Ĥaldeoj."],[22,26,"Kaj Mi ĵetos vin, kaj vian patrinon, kiu naskis vin, en alian landon, kie vi ne naskiĝis; kaj tie vi mortos.","Kaj Mi ĵetos vin, kaj vian patrinon, kiu naskis vin, en alian landon, kie vi ne naskiĝis; kaj tie vi mortos."],[22,27,"Sed en la landon, kien ili tre dezirus reveni, tien ili ne revenos.","Sed en la landon, kien ili tre dezirus reveni, tien ili ne revenos."],[22,28,"Ĉu ĉi tiu homo, Konja, estas objekto malestimata, forpuŝita? ĉu li estas vazo neamata? kial ili estas forĵetitaj, li kaj lia idaro, ĵetitaj en landon, kiun ili ne konis?","Ĉu ĉi tiu homo, Konja, estas objekto malestimata, forpuŝita? ĉu li estas vazo neamata? kial ili estas forĵetitaj, li kaj lia idaro, ĵetitaj en landon, kiun ili ne konis?"],[22,29,"Ho tero, tero, tero! aŭskultu la vorton de la Eternulo!","Ho tero, tero, tero! aŭskultu la vorton de la Eternulo!"],[22,30,"Tiele diras la Eternulo: Enskribu ĉi tiun homon kiel seninfanan, kiel homon, kiu ne havos sukceson en sia vivo; ĉar neniu el lia idaro sukcesos sidi sur la trono de David aŭ regos iam en Judujo.","Tiele diras la Eternulo: Enskribu ĉi tiun homon kiel seninfanan, kiel homon, kiu ne havos sukceson en sia vivo; ĉar neniu el lia idaro sukcesos sidi sur la trono de David aŭ regos iam en Judujo."],[23,1,"Ve al la paŝtistoj, kiuj pereigas kaj diskurigas la ŝafojn de Mia paŝtataro! diras la Eternulo.","Ve al la paŝtistoj, kiuj pereigas kaj diskurigas la ŝafojn de Mia paŝtataro! diras la Eternulo."],[23,2,"Tial tiele diras la Eternulo, Dio de Izrael, pri la paŝtistoj, kiuj paŝtas Mian popolon: Vi diskurigis Miajn ŝafojn kaj dispelis ilin kaj ne observis ilin; jen Mi punos sur vi viajn malbonajn agojn, diras la Eternulo.","Tial tiele diras la Eternulo, Dio de Izrael, pri la paŝtistoj, kiuj paŝtas Mian popolon: Vi diskurigis Miajn ŝafojn kaj dispelis ilin kaj ne observis ilin; jen Mi punos sur vi viajn malbonajn agojn, diras la Eternulo."],[23,3,"Sed Mi kolektos la restaĵon de Miaj ŝafoj el ĉiuj landoj, kien Mi dispelis ilin, kaj Mi revenigos ilin sur ilian paŝtejon; kaj ili donos fruktojn kaj multiĝos.","Sed Mi kolektos la restaĵon de Miaj ŝafoj el ĉiuj landoj, kien Mi dispelis ilin, kaj Mi revenigos ilin sur ilian paŝtejon; kaj ili donos fruktojn kaj multiĝos."],[23,4,"Kaj Mi starigos super ili paŝtistojn, por ke ili paŝtu ilin; kaj ili jam ne timos kaj ne tremos kaj ne estos atakataj, diras la Eternulo.","Kaj Mi starigos super ili paŝtistojn, por ke ili paŝtu ilin; kaj ili jam ne timos kaj ne tremos kaj ne estos atakataj, diras la Eternulo."],[23,5,"Jen venos tempo, diras la Eternulo, kaj Mi aperigos de David markoton virtan, kaj ekregos reĝo, kaj li estos prudenta, kaj li farados juĝon kaj justecon sur la tero.","Jen venos tempo, diras la Eternulo, kaj Mi aperigos de David markoton virtan, kaj ekregos reĝo, kaj li estos prudenta, kaj li farados juĝon kaj justecon sur la tero."],[23,6,"En lia tempo Jehuda estos savita kaj Izrael loĝos sendanĝere; kaj jen estas la nomo, per kiu oni lin nomos: La Eternulo estas nia justeco.","En lia tempo Jehuda estos savita kaj Izrael loĝos sendanĝere; kaj jen estas la nomo, per kiu oni lin nomos: La Eternulo estas nia justeco."],[23,7,"Pro tio jen venos tempo, diras la Eternulo, kiam oni ne plu diros: Vivas la Eternulo, kiu elkondukis la Izraelidojn el la lando Egipta;","Pro tio jen venos tempo, diras la Eternulo, kiam oni ne plu diros: Vivas la Eternulo, kiu elkondukis la Izraelidojn el la lando Egipta;"],[23,8,"sed: Vivas la Eternulo, kiu elirigis kaj venigis la idaron de la domo de Izrael el la lando norda, kaj el ĉiuj landoj, kien Mi dispelis ilin; kaj ili ekloĝos en sia lando.","sed: Vivas la Eternulo, kiu elirigis kaj venigis la idaron de la domo de Izrael el la lando norda, kaj el ĉiuj landoj, kien Mi dispelis ilin; kaj ili ekloĝos en sia lando."],[23,9,"Pri la profetoj. Disŝiriĝas en mi mia koro, ĉiuj miaj ostoj tremas; mi fariĝis kiel ebriulo, kiel homo, senfortigita de vino, antaŭ la Eternulo kaj antaŭ Liaj sanktaj vortoj.","Pri la profetoj. Disŝiriĝas en mi mia koro, ĉiuj miaj ostoj tremas; mi fariĝis kiel ebriulo, kiel homo, senfortigita de vino, antaŭ la Eternulo kaj antaŭ Liaj sanktaj vortoj."],[23,10,"Ĉar la lando estas plena de adultuloj, ĉar la lando ploras de malbeno; sekiĝis la paŝtejoj de la stepo; ilia celado estas malpia, kaj ilia forto estas en malvereco.","Ĉar la lando estas plena de adultuloj, ĉar la lando ploras de malbeno; sekiĝis la paŝtejoj de la stepo; ilia celado estas malpia, kaj ilia forto estas en malvereco."],[23,11,"Ĉar profeto kaj pastro hipokritas; eĉ en Mia domo Mi trovas iliajn malbonagojn, diras la Eternulo.","Ĉar profeto kaj pastro hipokritas; eĉ en Mia domo Mi trovas iliajn malbonagojn, diras la Eternulo."],[23,12,"Pro tio ilia vojo estos kiel glitigaj lokoj en mallumo: ili glitos tie kaj falos; ĉar Mi venigos sur ilin malfeliĉon en la jaro, kiam Mi punvizitos ilin, diras la Eternulo.","Pro tio ilia vojo estos kiel glitigaj lokoj en mallumo: ili glitos tie kaj falos; ĉar Mi venigos sur ilin malfeliĉon en la jaro, kiam Mi punvizitos ilin, diras la Eternulo."],[23,13,"Ĉe la profetoj de Samario Mi vidis stultecon: ili profetis en la nomo de Baal, kaj erarigis Mian popolon Izrael;","Ĉe la profetoj de Samario Mi vidis stultecon: ili profetis en la nomo de Baal, kaj erarigis Mian popolon Izrael;"],[23,14,"sed ĉe la profetoj de Jerusalem Mi vidis ion teruran: ili adultas, iras vojon de mensogoj, kaj subtenas la manojn de malbonaguloj, por ke neniu el ili konvertu sin de sia malboneco; ili ĉiuj fariĝis por Mi kiel Sodom, kaj la loĝantoj de la urbo kiel Gomora.","sed ĉe la profetoj de Jerusalem Mi vidis ion teruran: ili adultas, iras vojon de mensogoj, kaj subtenas la manojn de malbonaguloj, por ke neniu el ili konvertu sin de sia malboneco; ili ĉiuj fariĝis por Mi kiel Sodom, kaj la loĝantoj de la urbo kiel Gomora."],[23,15,"Tial tiele diras la Eternulo Cebaot pri la profetoj: Jen Mi manĝigos al ili vermuton kaj trinkigos al ili akvon maldolĉan; ĉar de la profetoj de Jerusalem disvastiĝas malpieco en la tuta lando.","Tial tiele diras la Eternulo Cebaot pri la profetoj: Jen Mi manĝigos al ili vermuton kaj trinkigos al ili akvon maldolĉan; ĉar de la profetoj de Jerusalem disvastiĝas malpieco en la tuta lando."],[23,16,"Tiele diras la Eternulo Cebaot: Ne aŭskultu la vortojn de la profetoj, kiuj profetas al vi; ili trompas vin; ili predikas vizion de sia koro, sed ne el la buŝo de la Eternulo.","Tiele diras la Eternulo Cebaot: Ne aŭskultu la vortojn de la profetoj, kiuj profetas al vi; ili trompas vin; ili predikas vizion de sia koro, sed ne el la buŝo de la Eternulo."],[23,17,"Ili diras al Miaj malŝatantoj: La Eternulo diris, ke al vi estos paco; kaj al ĉiu, kiu sekvas la obstinecon de sia koro, ili diras: Ne trafos vin malfeliĉo.","Ili diras al Miaj malŝatantoj: La Eternulo diris, ke al vi estos paco; kaj al ĉiu, kiu sekvas la obstinecon de sia koro, ili diras: Ne trafos vin malfeliĉo."],[23,18,"Sed kiu staris en la konsilo de la Eternulo, kaj vidis kaj aŭdis Lian vorton? kiu aŭdis Lian vorton kaj komprenis?","Sed kiu staris en la konsilo de la Eternulo, kaj vidis kaj aŭdis Lian vorton? kiu aŭdis Lian vorton kaj komprenis?"],[23,19,"Jen eliros ventego de la Eternulo en kolero, ventego turniĝanta; ĝi falos sur la kapon de la malpiuloj.","Jen eliros ventego de la Eternulo en kolero, ventego turniĝanta; ĝi falos sur la kapon de la malpiuloj."],[23,20,"Ne kvietiĝos la kolero de la Eternulo, ĝis Li estos farinta kaj ĝis Li estos plenuminta la intencojn de Sia koro; en la tempo estonta vi tion komprenos.","Ne kvietiĝos la kolero de la Eternulo, ĝis Li estos farinta kaj ĝis Li estos plenuminta la intencojn de Sia koro; en la tempo estonta vi tion komprenos."],[23,21,"Mi ne sendis tiujn profetojn, sed ili mem kuris; Mi nenion diris al ili, tamen ili profetas.","Mi ne sendis tiujn profetojn, sed ili mem kuris; Mi nenion diris al ili, tamen ili profetas."],[23,22,"Se ili estus starintaj en Mia konsilo, ili aŭdigus Miajn vortojn al Mia popolo kaj deturnus ilin de ilia malbona vojo kaj de iliaj malbonaj agoj.","Se ili estus starintaj en Mia konsilo, ili aŭdigus Miajn vortojn al Mia popolo kaj deturnus ilin de ilia malbona vojo kaj de iliaj malbonaj agoj."],[23,23,"Ĉu Mi estas nur Dio de proksime? diras la Eternulo; ĉu Mi ne estas ankaŭ Dio de malproksime?","Ĉu Mi estas nur Dio de proksime? diras la Eternulo; ĉu Mi ne estas ankaŭ Dio de malproksime?"],[23,24,"Ĉu homo povas kaŝi sin en tia sekreta loko, kie Mi lin ne vidus? diras la Eternulo; ĉu ne Mi plenigas la ĉielon kaj la teron? diras la Eternulo.","Ĉu homo povas kaŝi sin en tia sekreta loko, kie Mi lin ne vidus? diras la Eternulo; ĉu ne Mi plenigas la ĉielon kaj la teron? diras la Eternulo."],[23,25,"Mi aŭdas, kion diras la profetoj, kiuj en Mia nomo profetas malveraĵon; ili diras: Mi sonĝis, mi sonĝis.","Mi aŭdas, kion diras la profetoj, kiuj en Mia nomo profetas malveraĵon; ili diras: Mi sonĝis, mi sonĝis."],[23,26,"Kiel longe tio daŭros en la koro de la profetoj, kiuj profetas malveraĵon, profetas la trompaĵon de sia koro?","Kiel longe tio daŭros en la koro de la profetoj, kiuj profetas malveraĵon, profetas la trompaĵon de sia koro?"],[23,27,"Ili pensas, ke ili forgesigos al Mia popolo Mian nomon per siaj sonĝoj, kiujn ili rakontas unu al la alia, tiel same, kiel iliaj patroj forgesis Mian nomon pro Baal.","Ili pensas, ke ili forgesigos al Mia popolo Mian nomon per siaj sonĝoj, kiujn ili rakontas unu al la alia, tiel same, kiel iliaj patroj forgesis Mian nomon pro Baal."],[23,28,"Profeto, kiu vidis sonĝon, rakontu sonĝon; kaj tiu, al kiu aperis Mia vorto, raportu Mian vorton vere. Kio komuna estas inter pajlo kaj greno? diras la Eternulo.","Profeto, kiu vidis sonĝon, rakontu sonĝon; kaj tiu, al kiu aperis Mia vorto, raportu Mian vorton vere. Kio komuna estas inter pajlo kaj greno? diras la Eternulo."],[23,29,"Ĉu Mia vorto ne estas kiel fajro, diras la Eternulo, kaj kiel martelo, kiu disbatas rokon?","Ĉu Mia vorto ne estas kiel fajro, diras la Eternulo, kaj kiel martelo, kiu disbatas rokon?"],[23,30,"Tial jen Mi turnos Min kontraŭ la profetojn, diras la Eternulo, kiuj ŝtelas Miajn vortojn unu de la alia.","Tial jen Mi turnos Min kontraŭ la profetojn, diras la Eternulo, kiuj ŝtelas Miajn vortojn unu de la alia."],[23,31,"Jen Mi turnos Min kontraŭ la profetojn, diras la Eternulo, kiuj esprimas sian propran parolon, kaj diras: Li diris.","Jen Mi turnos Min kontraŭ la profetojn, diras la Eternulo, kiuj esprimas sian propran parolon, kaj diras: Li diris."],[23,32,"Jen Mi turnos Min kontraŭ tiujn, kiuj profetas malverajn sonĝojn, diras la Eternulo, kaj rakontas ilin kaj erarigas Mian popolon per siaj mensogaĵoj kaj per sia senprudenteco, dum Mi ne sendis ilin kaj ne donis al ili ordonojn, kaj ili ja alportas al ĉi tiu popolo nenian utilon, diras la Eternulo.","Jen Mi turnos Min kontraŭ tiujn, kiuj profetas malverajn sonĝojn, diras la Eternulo, kaj rakontas ilin kaj erarigas Mian popolon per siaj mensogaĵoj kaj per sia senprudenteco, dum Mi ne sendis ilin kaj ne donis al ili ordonojn, kaj ili ja alportas al ĉi tiu popolo nenian utilon, diras la Eternulo."],[23,33,"Se ĉi tiu popolo aŭ profeto aŭ pastro demandos vin, dirante: Kia estas la ŝarĝo de la Eternulo? tiam diru al ili koncerne la ŝarĝon: Mi forlasos vin, diras la Eternulo.","Se ĉi tiu popolo aŭ profeto aŭ pastro demandos vin, dirante: Kia estas la ŝarĝo de la Eternulo? tiam diru al ili koncerne la ŝarĝon: Mi forlasos vin, diras la Eternulo."],[23,34,"Kaj se iu el la profetoj aŭ pastroj aŭ el la popolo diros: Ŝarĝo de la Eternulo, Mi punos tiun homon kaj lian domon.","Kaj se iu el la profetoj aŭ pastroj aŭ el la popolo diros: Ŝarĝo de la Eternulo, Mi punos tiun homon kaj lian domon."],[23,35,"Nur tiel diru ĉiu al sia proksimulo kaj ĉiu al sia frato: Kion respondis la Eternulo? aŭ: Kion diris la Eternulo?","Nur tiel diru ĉiu al sia proksimulo kaj ĉiu al sia frato: Kion respondis la Eternulo? aŭ: Kion diris la Eternulo?"],[23,36,"Kaj la esprimon: Ŝarĝo de la Eternulo, ne plu uzu; ĉar por ĉiu homo lia vorto fariĝos ŝarĝo, pro tio, ke vi malĝustigas la vortojn de la vivanta Dio, de la Eternulo Cebaot, nia Dio.","Kaj la esprimon: Ŝarĝo de la Eternulo, ne plu uzu; ĉar por ĉiu homo lia vorto fariĝos ŝarĝo, pro tio, ke vi malĝustigas la vortojn de la vivanta Dio, de la Eternulo Cebaot, nia Dio."],[23,37,"Tiele diru al la profeto: Kion respondis al vi la Eternulo? kion diris la Eternulo?","Tiele diru al la profeto: Kion respondis al vi la Eternulo? kion diris la Eternulo?"],[23,38,"Sed se vi diros: Ŝarĝo de la Eternulo, tiam tiele diras la Eternulo: Ĉar vi eldiris tiujn vortojn: Ŝarĝo de la Eternulo, dum Mi sendis, por diri al vi, ke vi ne uzu la esprimon: Ŝarĝo de la Eternulo:","Sed se vi diros: Ŝarĝo de la Eternulo, tiam tiele diras la Eternulo: Ĉar vi eldiris tiujn vortojn: Ŝarĝo de la Eternulo, dum Mi sendis, por diri al vi, ke vi ne uzu la esprimon: Ŝarĝo de la Eternulo:"],[23,39,"tial jen Mi tute forlasos kaj forpelos de antaŭ Mia vizaĝo vin, kaj la urbon, kiun Mi donis al vi kaj al viaj patroj;","tial jen Mi tute forlasos kaj forpelos de antaŭ Mia vizaĝo vin, kaj la urbon, kiun Mi donis al vi kaj al viaj patroj;"],[23,40,"kaj Mi metos sur vin eternan honton kaj eternan malhonoron, kiu ne forgesiĝos.","kaj Mi metos sur vin eternan honton kaj eternan malhonoron, kiu ne forgesiĝos."],[24,1,"La Eternulo montris al mi: jen estas du korboj kun figoj, starigitaj antaŭ la templo de la Eternulo, post kiam Nebukadnecar, reĝo de Babel, forkondukis el Jerusalem Jeĥonjan, filon de Jehojakim, reĝon de Judujo, kaj la princojn de Judujo kaj la ĉarpentistojn kaj seruristojn, kaj venigis ilin en Babelon.","La Eternulo montris al mi: jen estas du korboj kun figoj, starigitaj antaŭ la templo de la Eternulo, post kiam Nebukadnecar, reĝo de Babel, forkondukis el Jerusalem Jeĥonjan, filon de Jehojakim, reĝon de Judujo, kaj la princojn de Judujo kaj la ĉarpentistojn kaj seruristojn, kaj venigis ilin en Babelon."],[24,2,"Unu korbo estis kun figoj tre bonaj, kiel estas la figoj plej frue maturiĝintaj; la dua korbo estis kun figoj tre malbonaj, kiujn pro ilia malboneco oni ne povas manĝi.","Unu korbo estis kun figoj tre bonaj, kiel estas la figoj plej frue maturiĝintaj; la dua korbo estis kun figoj tre malbonaj, kiujn pro ilia malboneco oni ne povas manĝi."],[24,3,"Kaj la Eternulo diris al mi: Kion vi vidas, Jeremia? Kaj mi respondis: Figojn; la bonaj figoj estas tre bonaj, kaj la malbonaj estas tre malbonaj, tiel, ke pro ilia malboneco oni ne povas ilin manĝi.","Kaj la Eternulo diris al mi: Kion vi vidas, Jeremia? Kaj mi respondis: Figojn; la bonaj figoj estas tre bonaj, kaj la malbonaj estas tre malbonaj, tiel, ke pro ilia malboneco oni ne povas ilin manĝi."],[24,4,"Tiam aperis al mi la vorto de la Eternulo, dirante:","Tiam aperis al mi la vorto de la Eternulo, dirante:"],[24,5,"Tiele diras la Eternulo, Dio de Izrael: Simile al ĉi tiuj bonaj figoj, Mi distingos por bono la forkondukitajn Judojn, kiujn Mi forsendis de ĉi tiu loko en la landon Ĥaldean;","Tiele diras la Eternulo, Dio de Izrael: Simile al ĉi tiuj bonaj figoj, Mi distingos por bono la forkondukitajn Judojn, kiujn Mi forsendis de ĉi tiu loko en la landon Ĥaldean;"],[24,6,"kaj Mi direktos sur ilin Miajn okulojn por bono, kaj Mi revenigos ilin en ĉi tiun landon, kaj Mi aranĝos ilin, ne ruinigos, Mi plantos ilin, ne elŝiros.","kaj Mi direktos sur ilin Miajn okulojn por bono, kaj Mi revenigos ilin en ĉi tiun landon, kaj Mi aranĝos ilin, ne ruinigos, Mi plantos ilin, ne elŝiros."],[24,7,"Kaj Mi donos al ili koron, ke ili konu Min, ke Mi estas la Eternulo; ili estos Mia popolo, kaj Mi estos ilia Dio; ĉar ili konvertiĝos al Mi per sia tuta koro.","Kaj Mi donos al ili koron, ke ili konu Min, ke Mi estas la Eternulo; ili estos Mia popolo, kaj Mi estos ilia Dio; ĉar ili konvertiĝos al Mi per sia tuta koro."],[24,8,"Sed koncerne la malbonajn figojn, kiujn oni ne povas manĝi pro ilia malboneco, tiele diras la Eternulo: Al ili Mi similigos Cidkijan, reĝon de Judujo, kaj liajn princojn, kaj la restintajn Jerusalemanojn, kiuj restis en ĉi tiu lando kaj kiuj loĝas en la lando Egipta;","Sed koncerne la malbonajn figojn, kiujn oni ne povas manĝi pro ilia malboneco, tiele diras la Eternulo: Al ili Mi similigos Cidkijan, reĝon de Judujo, kaj liajn princojn, kaj la restintajn Jerusalemanojn, kiuj restis en ĉi tiu lando kaj kiuj loĝas en la lando Egipta;"],[24,9,"kaj Mi donos al ili suferadon kaj mizeron en ĉiuj regnoj de la tero, Mi faros ilin objekto de honto, de ekzemplo, de moko, kaj de malbeno sur ĉiuj lokoj, kien Mi dispelos ilin;","kaj Mi donos al ili suferadon kaj mizeron en ĉiuj regnoj de la tero, Mi faros ilin objekto de honto, de ekzemplo, de moko, kaj de malbeno sur ĉiuj lokoj, kien Mi dispelos ilin;"],[24,10,"kaj Mi sendos sur ilin glavon, malsaton, kaj peston, ĝis Mi ekstermos ilin el la lando, kiun Mi donis al ili kaj al iliaj patroj.","kaj Mi sendos sur ilin glavon, malsaton, kaj peston, ĝis Mi ekstermos ilin el la lando, kiun Mi donis al ili kaj al iliaj patroj."],[25,1,"Jen estas la vorto, kiu aperis al Jeremia pri la tuta Juda popolo en la kvara jaro de Jehojakim, filo de Joŝija, reĝo de Judujo, tio estas en la unua jaro de Nebukadnecar, reĝo de Babel,","Jen estas la vorto, kiu aperis al Jeremia pri la tuta Juda popolo en la kvara jaro de Jehojakim, filo de Joŝija, reĝo de Judujo, tio estas en la unua jaro de Nebukadnecar, reĝo de Babel,"],[25,2,"kaj kiun la profeto Jeremia proklamis al la tuta Juda popolo kaj al ĉiuj loĝantoj de Jerusalem, dirante:","kaj kiun la profeto Jeremia proklamis al la tuta Juda popolo kaj al ĉiuj loĝantoj de Jerusalem, dirante:"],[25,3,"De post la dek-tria jaro de Joŝija, filo de Amon, reĝo de Judujo, ĝis la nuna tago, en la daŭro de dudek tri jaroj, aperadis al mi la vorto de la Eternulo, kaj mi paroladis al vi, konstante paroladis; sed vi ne aŭskultis.","De post la dek-tria jaro de Joŝija, filo de Amon, reĝo de Judujo, ĝis la nuna tago, en la daŭro de dudek tri jaroj, aperadis al mi la vorto de la Eternulo, kaj mi paroladis al vi, konstante paroladis; sed vi ne aŭskultis."],[25,4,"La Eternulo sendis al vi ĉiujn Siajn servantojn, la profetojn; ĉiutage Li sendadis; sed vi ne aŭskultis, vi ne alklinis vian orelon, por aŭskulti.","La Eternulo sendis al vi ĉiujn Siajn servantojn, la profetojn; ĉiutage Li sendadis; sed vi ne aŭskultis, vi ne alklinis vian orelon, por aŭskulti."],[25,5,"Ili diris: Deturnu vin ĉiu de sia malbona vojo kaj de viaj malbonaj agoj, kaj loĝu sur la tero, kiun la Eternulo donis al vi kaj al viaj patroj de ĉiam kaj por ĉiam;","Ili diris: Deturnu vin ĉiu de sia malbona vojo kaj de viaj malbonaj agoj, kaj loĝu sur la tero, kiun la Eternulo donis al vi kaj al viaj patroj de ĉiam kaj por ĉiam;"],[25,6,"kaj ne sekvu aliajn diojn, servante kaj adorkliniĝante al ili, kaj ne kolerigu Min per la faritaĵo de viaj manoj, por ke Mi ne faru al vi malbonon.","kaj ne sekvu aliajn diojn, servante kaj adorkliniĝante al ili, kaj ne kolerigu Min per la faritaĵo de viaj manoj, por ke Mi ne faru al vi malbonon."],[25,7,"Sed vi ne aŭskultis Min, diras la Eternulo; vi kolerigis Min per la faritaĵo de viaj manoj por via malbono.","Sed vi ne aŭskultis Min, diras la Eternulo; vi kolerigis Min per la faritaĵo de viaj manoj por via malbono."],[25,8,"Tial tiele diras la Eternulo Cebaot: Pro tio, ke vi ne aŭskultis Miajn vortojn,","Tial tiele diras la Eternulo Cebaot: Pro tio, ke vi ne aŭskultis Miajn vortojn,"],[25,9,"jen Mi sendos kaj kolektos ĉiujn nordajn gentojn, diras la Eternulo, kaj Mian servanton Nebukadnecar, reĝo de Babel, kaj Mi venigos ilin sur ĉi tiun landon kaj sur ĝiajn loĝantojn kaj sur ĉiujn naciojn ĉirkaŭe; kaj Mi elmetos ilin al ekstermo, kaj Mi faros ilin ruinoj, mokataĵo, kaj eterna dezertaĵo.","jen Mi sendos kaj kolektos ĉiujn nordajn gentojn, diras la Eternulo, kaj Mian servanton Nebukadnecar, reĝo de Babel, kaj Mi venigos ilin sur ĉi tiun landon kaj sur ĝiajn loĝantojn kaj sur ĉiujn naciojn ĉirkaŭe; kaj Mi elmetos ilin al ekstermo, kaj Mi faros ilin ruinoj, mokataĵo, kaj eterna dezertaĵo."],[25,10,"Kaj Mi ĉesigos ĉe ili la sonojn de ĝojo kaj la sonojn de gajeco, la voĉon de fianĉo kaj la voĉon de fianĉino, la bruon de muelilo kaj la lumon de lucerno.","Kaj Mi ĉesigos ĉe ili la sonojn de ĝojo kaj la sonojn de gajeco, la voĉon de fianĉo kaj la voĉon de fianĉino, la bruon de muelilo kaj la lumon de lucerno."],[25,11,"Kaj ĉi tiu tuta lando fariĝos ruino kaj dezerto; kaj tiuj nacioj servos al la reĝo de Babel dum sepdek jaroj.","Kaj ĉi tiu tuta lando fariĝos ruino kaj dezerto; kaj tiuj nacioj servos al la reĝo de Babel dum sepdek jaroj."],[25,12,"Sed kiam finiĝos la sepdek jaroj, Mi punos la reĝon de Babel kaj tiun nacion, diras la Eternulo, pro ĝiaj malbonagoj, kaj la landon Ĥaldean, kaj Mi faros ĝin eterna dezerto.","Sed kiam finiĝos la sepdek jaroj, Mi punos la reĝon de Babel kaj tiun nacion, diras la Eternulo, pro ĝiaj malbonagoj, kaj la landon Ĥaldean, kaj Mi faros ĝin eterna dezerto."],[25,13,"Kaj Mi plenumos super tiu lando ĉiujn Miajn vortojn, kiujn Mi diris pri ĝi, ĉion, kio estas skribita en ĉi tiu libro, kion Jeremia profetis pri ĉiuj nacioj.","Kaj Mi plenumos super tiu lando ĉiujn Miajn vortojn, kiujn Mi diris pri ĝi, ĉion, kio estas skribita en ĉi tiu libro, kion Jeremia profetis pri ĉiuj nacioj."],[25,14,"Ĉar ankaŭ ilin sklavigos potencaj nacioj kaj grandaj reĝoj, kaj Mi repagos al ili laŭ iliaj agoj kaj laŭ la faroj de iliaj manoj.","Ĉar ankaŭ ilin sklavigos potencaj nacioj kaj grandaj reĝoj, kaj Mi repagos al ili laŭ iliaj agoj kaj laŭ la faroj de iliaj manoj."],[25,15,"Ĉar tiele diras al mi la Eternulo, Dio de Izrael: Prenu el Mia mano ĉi tiun pokalon de la vino de furiozo, kaj trinkigu el ĝi ĉiujn naciojn, al kiuj Mi sendas vin.","Ĉar tiele diras al mi la Eternulo, Dio de Izrael: Prenu el Mia mano ĉi tiun pokalon de la vino de furiozo, kaj trinkigu el ĝi ĉiujn naciojn, al kiuj Mi sendas vin."],[25,16,"Ili trinku, ili ŝanceliĝu kaj freneziĝu antaŭ la glavo, kiun Mi sendos sur ilin.","Ili trinku, ili ŝanceliĝu kaj freneziĝu antaŭ la glavo, kiun Mi sendos sur ilin."],[25,17,"Kaj mi prenis la pokalon el la mano de la Eternulo, kaj trinkigis al ĉiuj popoloj, al kiuj sendis min la Eternulo:","Kaj mi prenis la pokalon el la mano de la Eternulo, kaj trinkigis al ĉiuj popoloj, al kiuj sendis min la Eternulo:"],[25,18,"al Jerusalem kaj al la urboj de Judujo, al iliaj reĝoj kaj al iliaj eminentuloj, por fari ilin dezertaĵo kaj ruino, mokataĵo kaj malbenataĵo, kiel tio estas nun;","al Jerusalem kaj al la urboj de Judujo, al iliaj reĝoj kaj al iliaj eminentuloj, por fari ilin dezertaĵo kaj ruino, mokataĵo kaj malbenataĵo, kiel tio estas nun;"],[25,19,"al Faraono, reĝo de Egiptujo, kaj al liaj servantoj kaj al liaj eminentuloj kaj al lia tuta popolo;","al Faraono, reĝo de Egiptujo, kaj al liaj servantoj kaj al liaj eminentuloj kaj al lia tuta popolo;"],[25,20,"kaj al ĉiuj diversgentaj popoloj kaj al ĉiuj reĝoj de la lando Uc kaj al ĉiuj reĝoj de la lando Filiŝta kaj al Aŝkelon kaj al Gaza kaj al Ekron kaj al la restaĵo de Aŝdod;","kaj al ĉiuj diversgentaj popoloj kaj al ĉiuj reĝoj de la lando Uc kaj al ĉiuj reĝoj de la lando Filiŝta kaj al Aŝkelon kaj al Gaza kaj al Ekron kaj al la restaĵo de Aŝdod;"],[25,21,"al Edom kaj al Moab kaj al la Amonidoj;","al Edom kaj al Moab kaj al la Amonidoj;"],[25,22,"kaj al ĉiuj reĝoj de Tiro kaj al ĉiuj reĝoj de Cidon kaj al la reĝoj de la insuloj trans la maro;","kaj al ĉiuj reĝoj de Tiro kaj al ĉiuj reĝoj de Cidon kaj al la reĝoj de la insuloj trans la maro;"],[25,23,"al Dedan, al Tema, al Buz, kaj al ĉiuj, kiuj tondas la harojn sur la tempioj;","al Dedan, al Tema, al Buz, kaj al ĉiuj, kiuj tondas la harojn sur la tempioj;"],[25,24,"kaj al ĉiuj reĝoj de Arabujo, kaj al ĉiuj reĝoj de la diversgentaj popoloj, loĝantaj en la dezerto;","kaj al ĉiuj reĝoj de Arabujo, kaj al ĉiuj reĝoj de la diversgentaj popoloj, loĝantaj en la dezerto;"],[25,25,"kaj al ĉiuj reĝoj de Zimri kaj al ĉiuj reĝoj de Elam kaj al ĉiuj reĝoj de Medujo;","kaj al ĉiuj reĝoj de Zimri kaj al ĉiuj reĝoj de Elam kaj al ĉiuj reĝoj de Medujo;"],[25,26,"kaj al ĉiuj reĝoj de la nordo, la proksimaj kaj la malproksimaj, unu kontraŭ la alia, kaj al ĉiuj regnoj de la mondo, kiuj troviĝas sur la tero; kaj la reĝo de Ŝeŝaĥ trinkos post ili.","kaj al ĉiuj reĝoj de la nordo, la proksimaj kaj la malproksimaj, unu kontraŭ la alia, kaj al ĉiuj regnoj de la mondo, kiuj troviĝas sur la tero; kaj la reĝo de Ŝeŝaĥ trinkos post ili."],[25,27,"Kaj diru al ili: Tiele diras la Eternulo Cebaot, Dio de Izrael: Trinku kaj ebriiĝu, vomu kaj falu, kaj ne leviĝu antaŭ la glavo, kiun Mi sendas sur vin.","Kaj diru al ili: Tiele diras la Eternulo Cebaot, Dio de Izrael: Trinku kaj ebriiĝu, vomu kaj falu, kaj ne leviĝu antaŭ la glavo, kiun Mi sendas sur vin."],[25,28,"Kaj se ili ne volos preni la pokalon el via mano, por trinki, tiam diru al ili: Tiele diras la Eternulo Cebaot: Vi nepre devas trinki.","Kaj se ili ne volos preni la pokalon el via mano, por trinki, tiam diru al ili: Tiele diras la Eternulo Cebaot: Vi nepre devas trinki."],[25,29,"Ĉar jen sur la urbon, kiu portas sur si Mian nomon, Mi komencas sendi suferojn; ĉu vi do restos senpunaj? vi ne restos sen puno, ĉar Mi vokas glavon sur ĉiujn loĝantojn de la tero, diras la Eternulo Cebaot.","Ĉar jen sur la urbon, kiu portas sur si Mian nomon, Mi komencas sendi suferojn; ĉu vi do restos senpunaj? vi ne restos sen puno, ĉar Mi vokas glavon sur ĉiujn loĝantojn de la tero, diras la Eternulo Cebaot."],[25,30,"Profetu al ili ĉion ĉi tion, kaj diru al ili: La Eternulo ekbruos de alte, kaj el Sia sankta loĝejo Li aŭdigos Sian voĉon; Li forte ekbruos kontraŭ Sian restadejon; kanton de vinpremantoj Li eksonigos super ĉiuj loĝantoj de la tero.","Profetu al ili ĉion ĉi tion, kaj diru al ili: La Eternulo ekbruos de alte, kaj el Sia sankta loĝejo Li aŭdigos Sian voĉon; Li forte ekbruos kontraŭ Sian restadejon; kanton de vinpremantoj Li eksonigos super ĉiuj loĝantoj de la tero."],[25,31,"La bruo atingos ĝis la fino de la tero; ĉar la Eternulo havos juĝon kontraŭ la popoloj, Li juĝos ĉiun karnon; la malpiulojn Li transdonos al glavo, diras la Eternulo.","La bruo atingos ĝis la fino de la tero; ĉar la Eternulo havos juĝon kontraŭ la popoloj, Li juĝos ĉiun karnon; la malpiulojn Li transdonos al glavo, diras la Eternulo."],[25,32,"Tiele diras la Eternulo Cebaot: Jen plago iros de popolo al popolo, kaj granda ventego leviĝos de la randoj de la tero.","Tiele diras la Eternulo Cebaot: Jen plago iros de popolo al popolo, kaj granda ventego leviĝos de la randoj de la tero."],[25,33,"Kaj la mortigitoj de la Eternulo en tiu tago estos de unu fino de la tero ĝis la alia fino de la tero; ili ne estos priplorataj, ne estos kolektataj, nek enterigataj; ili fariĝos sterko sur la supraĵo de la tero.","Kaj la mortigitoj de la Eternulo en tiu tago estos de unu fino de la tero ĝis la alia fino de la tero; ili ne estos priplorataj, ne estos kolektataj, nek enterigataj; ili fariĝos sterko sur la supraĵo de la tero."],[25,34,"Ploru, ho paŝtistoj, kriu kaj rulu vin en polvo, ho regantoj de la ŝafoj; ĉar venis por vi la tempo de buĉo; Mi disĵetos vin, kaj vi disfalos, kiel multekosta vazo.","Ploru, ho paŝtistoj, kriu kaj rulu vin en polvo, ho regantoj de la ŝafoj; ĉar venis por vi la tempo de buĉo; Mi disĵetos vin, kaj vi disfalos, kiel multekosta vazo."],[25,35,"Kaj ne ekzistos forkuro por la paŝtistoj, nek forsaviĝo por la regantoj de la ŝafaro.","Kaj ne ekzistos forkuro por la paŝtistoj, nek forsaviĝo por la regantoj de la ŝafaro."],[25,36,"Estos aŭdata kriado de la paŝtistoj kaj plorado de la regantoj de la ŝafaro, ĉar la Eternulo faros ekstermon en ilia ŝafaro.","Estos aŭdata kriado de la paŝtistoj kaj plorado de la regantoj de la ŝafaro, ĉar la Eternulo faros ekstermon en ilia ŝafaro."],[25,37,"Disfalos la pacaj loĝejoj antaŭ la flama kolero de la Eternulo.","Disfalos la pacaj loĝejoj antaŭ la flama kolero de la Eternulo."],[25,38,"Li forlasis Sian laŭbon kiel leono; ilia lando fariĝis dezerto de la kolero de la atakanto kaj de Lia flama kolero.","Li forlasis Sian laŭbon kiel leono; ilia lando fariĝis dezerto de la kolero de la atakanto kaj de Lia flama kolero."],[26,1,"En la komenco de la reĝado de Jehojakim, filo de Joŝija, reĝo de Judujo, aperis jena vorto de la Eternulo:","En la komenco de la reĝado de Jehojakim, filo de Joŝija, reĝo de Judujo, aperis jena vorto de la Eternulo:"],[26,2,"Tiele diras la Eternulo: Stariĝu sur la korto de la domo de la Eternulo, kaj parolu pri ĉiuj urboj de Judujo, kiuj venas en la domon de la Eternulo por adorkliniĝi, ĉiujn vortojn, kiujn Mi ordonis al vi diri al ili; ne mankigu eĉ unu vorton.","Tiele diras la Eternulo: Stariĝu sur la korto de la domo de la Eternulo, kaj parolu pri ĉiuj urboj de Judujo, kiuj venas en la domon de la Eternulo por adorkliniĝi, ĉiujn vortojn, kiujn Mi ordonis al vi diri al ili; ne mankigu eĉ unu vorton."],[26,3,"Eble ili aŭskultos kaj returnos sin ĉiu de sia malbona vojo; kaj tiam Mi fordecidos la malbonon, kiun Mi intencas fari al ili pro iliaj malbonaj agoj.","Eble ili aŭskultos kaj returnos sin ĉiu de sia malbona vojo; kaj tiam Mi fordecidos la malbonon, kiun Mi intencas fari al ili pro iliaj malbonaj agoj."],[26,4,"Kaj diru al ili: Tiele diras la Eternulo: Se vi ne obeos Min, por agadi laŭ Mia instruo, kiun Mi donis al vi,","Kaj diru al ili: Tiele diras la Eternulo: Se vi ne obeos Min, por agadi laŭ Mia instruo, kiun Mi donis al vi,"],[26,5,"por obei la vortojn de Miaj servantoj, la profetoj, kiujn Mi sendas al vi, kiujn Mi konstante sendadis, sed vi ilin ne aŭskultis:","por obei la vortojn de Miaj servantoj, la profetoj, kiujn Mi sendas al vi, kiujn Mi konstante sendadis, sed vi ilin ne aŭskultis:"],[26,6,"tiam Mi agos kun ĉi tiu domo kiel kun Ŝilo, kaj ĉi tiun urbon Mi faros malbeno por ĉiuj popoloj de la tero.","tiam Mi agos kun ĉi tiu domo kiel kun Ŝilo, kaj ĉi tiun urbon Mi faros malbeno por ĉiuj popoloj de la tero."],[26,7,"Kaj aŭdis la pastroj kaj la profetoj kaj la tuta popolo, kiel Jeremia parolis tiujn vortojn en la domo de la Eternulo.","Kaj aŭdis la pastroj kaj la profetoj kaj la tuta popolo, kiel Jeremia parolis tiujn vortojn en la domo de la Eternulo."],[26,8,"Kiam Jeremia finis la paroladon de ĉio, kion la Eternulo ordonis diri al la tuta popolo, tiam kaptis lin la pastroj kaj la profetoj kaj la tuta popolo, dirante: Vi devas morti!","Kiam Jeremia finis la paroladon de ĉio, kion la Eternulo ordonis diri al la tuta popolo, tiam kaptis lin la pastroj kaj la profetoj kaj la tuta popolo, dirante: Vi devas morti!"],[26,9,"Kial vi profetas en la nomo de la Eternulo, dirante: Ĉi tiu domo fariĝos kiel Ŝilo, kaj ĉi tiu urbo dezertiĝos tiel, ke estos en ĝi neniu loĝanto? Kaj la tuta popolo amasiĝis ĉirkaŭ Jeremia en la domo de la Eternulo.","Kial vi profetas en la nomo de la Eternulo, dirante: Ĉi tiu domo fariĝos kiel Ŝilo, kaj ĉi tiu urbo dezertiĝos tiel, ke estos en ĝi neniu loĝanto? Kaj la tuta popolo amasiĝis ĉirkaŭ Jeremia en la domo de la Eternulo."],[26,10,"Kiam la eminentuloj de Judujo aŭdis pri tio, ili iris el la reĝa domo en la domon de la Eternulo kaj sidiĝis ĉe la enirejo de la nova pordego de la domo de la Eternulo.","Kiam la eminentuloj de Judujo aŭdis pri tio, ili iris el la reĝa domo en la domon de la Eternulo kaj sidiĝis ĉe la enirejo de la nova pordego de la domo de la Eternulo."],[26,11,"Kaj la pastroj kaj la profetoj diris al la eminentuloj kaj al la tuta popolo jene: Al morto estas kondamninda ĉi tiu homo, ĉar li profetis kontraŭ ĉi tiu urbo, kiel vi aŭdis per viaj oreloj.","Kaj la pastroj kaj la profetoj diris al la eminentuloj kaj al la tuta popolo jene: Al morto estas kondamninda ĉi tiu homo, ĉar li profetis kontraŭ ĉi tiu urbo, kiel vi aŭdis per viaj oreloj."],[26,12,"Tiam Jeremia diris al ĉiuj eminentuloj kaj al la tuta popolo jene: La Eternulo sendis min, por profeti kontraŭ ĉi tiu domo kaj ĉi tiu urbo ĉion, kion vi aŭdis.","Tiam Jeremia diris al ĉiuj eminentuloj kaj al la tuta popolo jene: La Eternulo sendis min, por profeti kontraŭ ĉi tiu domo kaj ĉi tiu urbo ĉion, kion vi aŭdis."],[26,13,"Plibonigu do nun viajn vojojn kaj vian konduton, kaj obeu la voĉon de la Eternulo, via Dio; kaj tiam la Eternulo fordecidos la malbonon, kiun Li diris pri vi.","Plibonigu do nun viajn vojojn kaj vian konduton, kaj obeu la voĉon de la Eternulo, via Dio; kaj tiam la Eternulo fordecidos la malbonon, kiun Li diris pri vi."],[26,14,"Kaj mi estas nun en viaj manoj; faru kun mi tion, kion vi trovas bona kaj justa.","Kaj mi estas nun en viaj manoj; faru kun mi tion, kion vi trovas bona kaj justa."],[26,15,"Sed sciu, ke se vi min mortigos, vi ŝarĝos per senkulpa sango vin kaj ĉi tiun urbon kaj ĝiajn loĝantojn; ĉar vere la Eternulo sendis min al vi, por diri en viajn orelojn ĉiujn tiujn vortojn.","Sed sciu, ke se vi min mortigos, vi ŝarĝos per senkulpa sango vin kaj ĉi tiun urbon kaj ĝiajn loĝantojn; ĉar vere la Eternulo sendis min al vi, por diri en viajn orelojn ĉiujn tiujn vortojn."],[26,16,"Tiam la eminentuloj kaj la tuta popolo diris al la pastroj kaj al la profetoj: Ĉi tiu homo ne estas kondamninda al morto, ĉar li parolis al ni en la nomo de la Eternulo, nia Dio.","Tiam la eminentuloj kaj la tuta popolo diris al la pastroj kaj al la profetoj: Ĉi tiu homo ne estas kondamninda al morto, ĉar li parolis al ni en la nomo de la Eternulo, nia Dio."],[26,17,"Kaj leviĝis kelkaj el la plejaĝuloj de la lando, kaj diris al la tuta amaso de la popolo jene:","Kaj leviĝis kelkaj el la plejaĝuloj de la lando, kaj diris al la tuta amaso de la popolo jene:"],[26,18,"Miĥa, la Moreŝetano, profetis en la tempo de Ĥizkija, reĝo de Judujo, kaj diris al la tuta Juda popolo jene: Tiele diras la Eternulo Cebaot: Cion estos plugita kiel kampo, Jerusalem fariĝos ruinaĵo, kaj la monto de la templo fariĝos arbara altaĵo.","Miĥa, la Moreŝetano, profetis en la tempo de Ĥizkija, reĝo de Judujo, kaj diris al la tuta Juda popolo jene: Tiele diras la Eternulo Cebaot: Cion estos plugita kiel kampo, Jerusalem fariĝos ruinaĵo, kaj la monto de la templo fariĝos arbara altaĵo."],[26,19,"Ĉu mortigis lin Ĥizkija, reĝo de Judujo, kaj ĉiuj Judoj? ili timis ja la Eternulon kaj preĝis antaŭ la Eternulo, kaj la Eternulo fordecidis la malbonon, kiun Li diris pri ili. Kaj ni farus grandan malbonon kontraŭ niaj animoj.","Ĉu mortigis lin Ĥizkija, reĝo de Judujo, kaj ĉiuj Judoj? ili timis ja la Eternulon kaj preĝis antaŭ la Eternulo, kaj la Eternulo fordecidis la malbonon, kiun Li diris pri ili. Kaj ni farus grandan malbonon kontraŭ niaj animoj."],[26,20,"Ankaŭ alia homo profetis en la nomo de la Eternulo, Urija, filo de Ŝemaja, el Kirjat-Jearim; li profetis kontraŭ ĉi tiu urbo kaj ĉi tiu lando, simile al ĉio, kion diris Jeremia.","Ankaŭ alia homo profetis en la nomo de la Eternulo, Urija, filo de Ŝemaja, el Kirjat-Jearim; li profetis kontraŭ ĉi tiu urbo kaj ĉi tiu lando, simile al ĉio, kion diris Jeremia."],[26,21,"Kaj liajn vortojn aŭdis la reĝo Jehojakim kaj ĉiuj liaj potenculoj kaj ĉiuj eminentuloj, kaj la reĝo intencis mortigi lin; sed Urija tion aŭdis, kaj ektimis, kaj forkuris kaj venis en Egiptujon.","Kaj liajn vortojn aŭdis la reĝo Jehojakim kaj ĉiuj liaj potenculoj kaj ĉiuj eminentuloj, kaj la reĝo intencis mortigi lin; sed Urija tion aŭdis, kaj ektimis, kaj forkuris kaj venis en Egiptujon."],[26,22,"Kaj la reĝo Jehojakim sendis homojn en Egiptujon: Elnatanon, filon de Aĥbor, kune kun aliaj homoj li sendis en Egiptujon;","Kaj la reĝo Jehojakim sendis homojn en Egiptujon: Elnatanon, filon de Aĥbor, kune kun aliaj homoj li sendis en Egiptujon;"],[26,23,"kaj ili elkondukis Urijan el Egiptujo kaj venigis lin al la reĝo Jehojakim; kaj ĉi tiu mortigis lin per glavo kaj ĵetis lian kadavron inter la tombojn de la simpla popolo.","kaj ili elkondukis Urijan el Egiptujo kaj venigis lin al la reĝo Jehojakim; kaj ĉi tiu mortigis lin per glavo kaj ĵetis lian kadavron inter la tombojn de la simpla popolo."],[26,24,"Tamen la mano de Aĥikam, filo de Ŝafan, protektis Jeremian, ne lasante transdoni lin en la manojn de la popolo, por mortigi lin.","Tamen la mano de Aĥikam, filo de Ŝafan, protektis Jeremian, ne lasante transdoni lin en la manojn de la popolo, por mortigi lin."],[27,1,"En la komenco de la reĝado de Jehojakim, filo de Joŝija, reĝo de Judujo, aperis de la Eternulo jena vorto al Jeremia:","En la komenco de la reĝado de Jehojakim, filo de Joŝija, reĝo de Judujo, aperis de la Eternulo jena vorto al Jeremia:"],[27,2,"Tiele diras al mi la Eternulo: Faru al vi ligilojn kaj jugon, kaj metu tion sur vian kolon;","Tiele diras al mi la Eternulo: Faru al vi ligilojn kaj jugon, kaj metu tion sur vian kolon;"],[27,3,"kaj sendu tion al la reĝo de Edom kaj al la reĝo de Moab kaj al la reĝo de la Amonidoj kaj al la reĝo de Tiro kaj al la reĝo de Cidon, per la senditoj, kiuj venis Jerusalemon al Cidkija, reĝo de Judujo;","kaj sendu tion al la reĝo de Edom kaj al la reĝo de Moab kaj al la reĝo de la Amonidoj kaj al la reĝo de Tiro kaj al la reĝo de Cidon, per la senditoj, kiuj venis Jerusalemon al Cidkija, reĝo de Judujo;"],[27,4,"kaj komisiu al ili, ke ili diru al siaj sinjoroj jene: Tiele diras la Eternulo Cebaot, Dio de Izrael: Tiele diru al viaj sinjoroj:","kaj komisiu al ili, ke ili diru al siaj sinjoroj jene: Tiele diras la Eternulo Cebaot, Dio de Izrael: Tiele diru al viaj sinjoroj:"],[27,5,"Per Mia granda forto kaj per Mia etendita brako Mi kreis la teron, la homojn kaj la bestojn, kiuj estas sur la tero; kaj Mi donas tion al tiu, kiu plaĉas al Mi.","Per Mia granda forto kaj per Mia etendita brako Mi kreis la teron, la homojn kaj la bestojn, kiuj estas sur la tero; kaj Mi donas tion al tiu, kiu plaĉas al Mi."],[27,6,"Kaj nun Mi transdonas ĉiujn tiujn landojn en la manon de Mia servanto Nebukadnecar, reĝo de Babel, kaj eĉ la bestojn de la kampo Mi transdonas al li, por ke ili servu al li.","Kaj nun Mi transdonas ĉiujn tiujn landojn en la manon de Mia servanto Nebukadnecar, reĝo de Babel, kaj eĉ la bestojn de la kampo Mi transdonas al li, por ke ili servu al li."],[27,7,"Kaj servos al li ĉiuj popoloj, ankaŭ al lia filo kaj al la filo de lia filo, ĝis venos la tempo ankaŭ por lia lando kaj lin sklavigos potencaj popoloj kaj grandaj reĝoj.","Kaj servos al li ĉiuj popoloj, ankaŭ al lia filo kaj al la filo de lia filo, ĝis venos la tempo ankaŭ por lia lando kaj lin sklavigos potencaj popoloj kaj grandaj reĝoj."],[27,8,"Kaj se ia popolo kaj regno ne servos al li, al Nebukadnecar, reĝo de Babel, kaj ne metos sian kolon sub la jugon de la reĝo de Babel, Mi punos tiun popolon per glavo kaj malsato kaj pesto, diras la Eternulo, ĝis Mi ekstermos ilin per lia mano.","Kaj se ia popolo kaj regno ne servos al li, al Nebukadnecar, reĝo de Babel, kaj ne metos sian kolon sub la jugon de la reĝo de Babel, Mi punos tiun popolon per glavo kaj malsato kaj pesto, diras la Eternulo, ĝis Mi ekstermos ilin per lia mano."],[27,9,"Ne aŭskultu do viajn profetojn, nek viajn magiistojn, nek viajn sonĝoklarigistojn, nek viajn aŭguristojn, nek viajn sorĉistojn, kiuj diras al vi jene: Ne servu al la reĝo de Babel.","Ne aŭskultu do viajn profetojn, nek viajn magiistojn, nek viajn sonĝoklarigistojn, nek viajn aŭguristojn, nek viajn sorĉistojn, kiuj diras al vi jene: Ne servu al la reĝo de Babel."],[27,10,"Ĉar ili profetas al vi malveraĵon, por malproksimigi vin de via lando, por ke Mi elpelu vin kaj vi pereu.","Ĉar ili profetas al vi malveraĵon, por malproksimigi vin de via lando, por ke Mi elpelu vin kaj vi pereu."],[27,11,"Sed tiun popolon, kiu metos sian kolon sub la jugon de la reĝo de Babel kaj servos al li, tiun Mi restigos trankvile sur ĝia tero, diras la Eternulo, por prilaboradi ĝin kaj loĝi sur ĝi.","Sed tiun popolon, kiu metos sian kolon sub la jugon de la reĝo de Babel kaj servos al li, tiun Mi restigos trankvile sur ĝia tero, diras la Eternulo, por prilaboradi ĝin kaj loĝi sur ĝi."],[27,12,"Kaj al Cidkija, reĝo de Judujo, mi diris tiajn samajn vortojn, nome: Metu vian kolon sub la jugon de la reĝo de Babel, kaj servu al li kaj al lia popolo, kaj restu vivantaj.","Kaj al Cidkija, reĝo de Judujo, mi diris tiajn samajn vortojn, nome: Metu vian kolon sub la jugon de la reĝo de Babel, kaj servu al li kaj al lia popolo, kaj restu vivantaj."],[27,13,"Por kio vi volus morti, vi kaj via popolo, de glavo, de malsato, kaj de pesto, kiel la Eternulo decidis pri popolo, kiu ne servos al la reĝo de Babel?","Por kio vi volus morti, vi kaj via popolo, de glavo, de malsato, kaj de pesto, kiel la Eternulo decidis pri popolo, kiu ne servos al la reĝo de Babel?"],[27,14,"Ne aŭskultu la vortojn de la profetoj, kiuj diras al vi, ke vi ne servu al la reĝo de Babel; ĉar ili profetas al vi malveraĵon.","Ne aŭskultu la vortojn de la profetoj, kiuj diras al vi, ke vi ne servu al la reĝo de Babel; ĉar ili profetas al vi malveraĵon."],[27,15,"Ĉar Mi ne sendis ilin, diras la Eternulo, kaj ili malvere profetas en Mia nomo, por ke Mi elpelu vin, kaj por ke vi pereu, vi kaj la profetoj, kiuj profetas al vi.","Ĉar Mi ne sendis ilin, diras la Eternulo, kaj ili malvere profetas en Mia nomo, por ke Mi elpelu vin, kaj por ke vi pereu, vi kaj la profetoj, kiuj profetas al vi."],[27,16,"Kaj al la pastroj kaj al la tuta ĉi tiu popolo mi diris jene: Tiele diras la Eternulo: Ne aŭskultu la vortojn de viaj profetoj, kiuj profetas al vi jene: Jen la vazoj de la domo de la Eternulo nun baldaŭ estos revenigitaj el Babel; ĉar malveraĵon ili profetas al vi.","Kaj al la pastroj kaj al la tuta ĉi tiu popolo mi diris jene: Tiele diras la Eternulo: Ne aŭskultu la vortojn de viaj profetoj, kiuj profetas al vi jene: Jen la vazoj de la domo de la Eternulo nun baldaŭ estos revenigitaj el Babel; ĉar malveraĵon ili profetas al vi."],[27,17,"Ne aŭskultu ilin; servu al la reĝo de Babel, por ke vi vivu; por kio ĉi tiu urbo fariĝu dezerto?","Ne aŭskultu ilin; servu al la reĝo de Babel, por ke vi vivu; por kio ĉi tiu urbo fariĝu dezerto?"],[27,18,"Se ili estas profetoj kaj se ili havas la vorton de la Eternulo, ili elpetegu de la Eternulo Cebaot, ke la vazoj, kiuj restis en la domo de la Eternulo kaj en la domo de la reĝo de Judujo kaj en Jerusalem, ne transiru en Babelon.","Se ili estas profetoj kaj se ili havas la vorton de la Eternulo, ili elpetegu de la Eternulo Cebaot, ke la vazoj, kiuj restis en la domo de la Eternulo kaj en la domo de la reĝo de Judujo kaj en Jerusalem, ne transiru en Babelon."],[27,19,"Ĉar tiele diras la Eternulo Cebaot pri la kolonoj, pri la maro, pri la bazoj, kaj pri la ceteraj vazoj, kiuj restis en ĉi tiu urbo","Ĉar tiele diras la Eternulo Cebaot pri la kolonoj, pri la maro, pri la bazoj, kaj pri la ceteraj vazoj, kiuj restis en ĉi tiu urbo"],[27,20,"kaj kiujn ne prenis Nebukadnecar, reĝo de Babel, kiam li forkondukis Jeĥonjan, filon de Jehojakim, reĝon de Judujo, el Jerusalem en Babelon, kaj ankaŭ ĉiujn eminentulojn de Judujo kaj Jerusalem;","kaj kiujn ne prenis Nebukadnecar, reĝo de Babel, kiam li forkondukis Jeĥonjan, filon de Jehojakim, reĝon de Judujo, el Jerusalem en Babelon, kaj ankaŭ ĉiujn eminentulojn de Judujo kaj Jerusalem;"],[27,21,"tiele diras la Eternulo Cebaot, Dio de Izrael, pri la vazoj, kiuj restis en la domo de la Eternulo kaj en la domo de la reĝo de Judujo kaj en Jerusalem:","tiele diras la Eternulo Cebaot, Dio de Izrael, pri la vazoj, kiuj restis en la domo de la Eternulo kaj en la domo de la reĝo de Judujo kaj en Jerusalem:"],[27,22,"En Babelon ili estos forportitaj, kaj tie ili restos, ĝis la tago, kiam Mi rememoros ilin, diras la Eternulo, kaj prenigos kaj reportigos ilin sur ĉi tiun lokon.","En Babelon ili estos forportitaj, kaj tie ili restos, ĝis la tago, kiam Mi rememoros ilin, diras la Eternulo, kaj prenigos kaj reportigos ilin sur ĉi tiun lokon."],[28,1,"En tiu sama jaro, en la komenco de la reĝado de Cidkija, reĝo de Judujo, en la kvara jaro, en la kvina monato, Ĥananja, filo de Azur, profeto el Gibeon, diris al mi en la domo de la Eternulo, antaŭ la okuloj de la pastroj kaj de la tuta popolo, jene:","En tiu sama jaro, en la komenco de la reĝado de Cidkija, reĝo de Judujo, en la kvara jaro, en la kvina monato, Ĥananja, filo de Azur, profeto el Gibeon, diris al mi en la domo de la Eternulo, antaŭ la okuloj de la pastroj kaj de la tuta popolo, jene:"],[28,2,"Tiele diras la Eternulo Cebaot, Dio de Izrael: Mi rompos la jugon de la reĝo de Babel;","Tiele diras la Eternulo Cebaot, Dio de Izrael: Mi rompos la jugon de la reĝo de Babel;"],[28,3,"post du jaroj Mi revenigos sur ĉi tiun lokon ĉiujn vazojn de la domo de la Eternulo, kiujn Nebukadnecar, reĝo de Babel, prenis de ĉi tiu loko kaj forportis en Babelon.","post du jaroj Mi revenigos sur ĉi tiun lokon ĉiujn vazojn de la domo de la Eternulo, kiujn Nebukadnecar, reĝo de Babel, prenis de ĉi tiu loko kaj forportis en Babelon."],[28,4,"Kaj Jeĥonjan, filon de Jehojakim, reĝon de Judujo, kaj ĉiujn forkondukitajn Judojn, kiuj venis en Babelon, Mi revenigos sur ĉi tiun lokon, diras la Eternulo; ĉar Mi rompos la jugon de la reĝo de Babel.","Kaj Jeĥonjan, filon de Jehojakim, reĝon de Judujo, kaj ĉiujn forkondukitajn Judojn, kiuj venis en Babelon, Mi revenigos sur ĉi tiun lokon, diras la Eternulo; ĉar Mi rompos la jugon de la reĝo de Babel."],[28,5,"Tiam la profeto Jeremia respondis al la profeto Ĥananja antaŭ la okuloj de la pastroj, kaj de la tuta popolo, kiu staris en la domo de la Eternulo;","Tiam la profeto Jeremia respondis al la profeto Ĥananja antaŭ la okuloj de la pastroj, kaj de la tuta popolo, kiu staris en la domo de la Eternulo;"],[28,6,"kaj la profeto Jeremia diris: Amen, tiel la Eternulo faru; la Eternulo plenumu viajn vortojn, kiujn vi profetis, kaj Li revenigu el Babel sur ĉi tiun lokon la vazojn de la domo de la Eternulo kaj ĉiujn forkondukitojn.","kaj la profeto Jeremia diris: Amen, tiel la Eternulo faru; la Eternulo plenumu viajn vortojn, kiujn vi profetis, kaj Li revenigu el Babel sur ĉi tiun lokon la vazojn de la domo de la Eternulo kaj ĉiujn forkondukitojn."],[28,7,"Tamen aŭskultu la vorton, kiun mi diros en viajn orelojn kaj en la orelojn de la tuta popolo:","Tamen aŭskultu la vorton, kiun mi diros en viajn orelojn kaj en la orelojn de la tuta popolo:"],[28,8,"La profetoj, kiuj de antikva tempo estis antaŭ mi kaj antaŭ vi, profetis al multaj landoj kaj al grandaj regnoj militon, malfeliĉon, aŭ peston.","La profetoj, kiuj de antikva tempo estis antaŭ mi kaj antaŭ vi, profetis al multaj landoj kaj al grandaj regnoj militon, malfeliĉon, aŭ peston."],[28,9,"Se profeto antaŭdiris pacon, tiam post la plenumiĝo de la vorto de la profeto oni ekkonis lin kiel profeton, kiun vere sendis la Eternulo.","Se profeto antaŭdiris pacon, tiam post la plenumiĝo de la vorto de la profeto oni ekkonis lin kiel profeton, kiun vere sendis la Eternulo."],[28,10,"Kaj la profeto Ĥananja deprenis la jugon de la kolo de la profeto Jeremia kaj rompis ĝin.","Kaj la profeto Ĥananja deprenis la jugon de la kolo de la profeto Jeremia kaj rompis ĝin."],[28,11,"Kaj Ĥananja diris antaŭ la okuloj de la tuta popolo jene: Tiele diras la Eternulo: Simile al ĉi tio Mi rompos la jugon de Nebukadnecar, reĝo de Babel, post du jaroj, deprenante ĝin de la kolo de ĉiuj popoloj. Kaj la profeto Jeremia iris sian vojon.","Kaj Ĥananja diris antaŭ la okuloj de la tuta popolo jene: Tiele diras la Eternulo: Simile al ĉi tio Mi rompos la jugon de Nebukadnecar, reĝo de Babel, post du jaroj, deprenante ĝin de la kolo de ĉiuj popoloj. Kaj la profeto Jeremia iris sian vojon."],[28,12,"Kaj aperis jena vorto de la Eternulo al Jeremia, post kiam la profeto Ĥananja forrompis la jugon de la kolo de la profeto Jeremia:","Kaj aperis jena vorto de la Eternulo al Jeremia, post kiam la profeto Ĥananja forrompis la jugon de la kolo de la profeto Jeremia:"],[28,13,"Iru kaj diru al Ĥananja jene: Tiele diras la Eternulo: Jugon lignan vi rompis, sed vi faru anstataŭ ĝi jugon feran.","Iru kaj diru al Ĥananja jene: Tiele diras la Eternulo: Jugon lignan vi rompis, sed vi faru anstataŭ ĝi jugon feran."],[28,14,"Ĉar tiele diras la Eternulo Cebaot, Dio de Izrael: Feran jugon Mi metis sur la kolon de ĉiuj tiuj popoloj, ke ili servu al Nebukadnecar, reĝo de Babel, kaj ili servos al li; eĉ la bestojn de la kampo Mi transdonis al li.","Ĉar tiele diras la Eternulo Cebaot, Dio de Izrael: Feran jugon Mi metis sur la kolon de ĉiuj tiuj popoloj, ke ili servu al Nebukadnecar, reĝo de Babel, kaj ili servos al li; eĉ la bestojn de la kampo Mi transdonis al li."],[28,15,"Tiam la profeto Jeremia diris al la profeto Ĥananja: Aŭskultu, Ĥananja; la Eternulo vin ne sendis, kaj vi kredigas al ĉi tiu popolo malveraĵon.","Tiam la profeto Jeremia diris al la profeto Ĥananja: Aŭskultu, Ĥananja; la Eternulo vin ne sendis, kaj vi kredigas al ĉi tiu popolo malveraĵon."],[28,16,"Pro tio tiele diras la Eternulo: Jen Mi forigos vin de sur la tero; en ĉi tiu jaro vi mortos, ĉar vi parolis kontraŭ la volo de la Eternulo.","Pro tio tiele diras la Eternulo: Jen Mi forigos vin de sur la tero; en ĉi tiu jaro vi mortos, ĉar vi parolis kontraŭ la volo de la Eternulo."],[28,17,"Kaj la profeto Ĥananja mortis en tiu jaro, en la sepa monato.","Kaj la profeto Ĥananja mortis en tiu jaro, en la sepa monato."],[29,1,"Jen estas la vortoj de la letero, kiun la profeto Jeremia sendis el Jerusalem al la plej gravaj plejaĝuloj, kiuj estis forkondukitaj, kaj al la pastroj, al la profetoj, kaj al la tuta popolo, kiujn Nebukadnecar forkondukis el Jerusalem en Babelon","Jen estas la vortoj de la letero, kiun la profeto Jeremia sendis el Jerusalem al la plej gravaj plejaĝuloj, kiuj estis forkondukitaj, kaj al la pastroj, al la profetoj, kaj al la tuta popolo, kiujn Nebukadnecar forkondukis el Jerusalem en Babelon"],[29,2,"(post kiam la reĝo Jeĥonja, kaj la reĝino, kaj la korteganoj, la eminentuloj de Judujo kaj Jerusalem, la ĉarpentistoj kaj forĝistoj foriris el Jerusalem);","(post kiam la reĝo Jeĥonja, kaj la reĝino, kaj la korteganoj, la eminentuloj de Judujo kaj Jerusalem, la ĉarpentistoj kaj forĝistoj foriris el Jerusalem);"],[29,3,"per Eleasa, filo de Ŝafan, kaj Gemarja, filo de Ĥilkija (kiujn Cidkija, reĝo de Judujo, sendis en Babelon, al Nebukadnecar, reĝo de Babel), li sendis jenajn vortojn:","per Eleasa, filo de Ŝafan, kaj Gemarja, filo de Ĥilkija (kiujn Cidkija, reĝo de Judujo, sendis en Babelon, al Nebukadnecar, reĝo de Babel), li sendis jenajn vortojn:"],[29,4,"Tiele diras la Eternulo Cebaot, Dio de Izrael, al ĉiuj elpelitoj, kiujn Mi elpelis el Jerusalem en Babelon:","Tiele diras la Eternulo Cebaot, Dio de Izrael, al ĉiuj elpelitoj, kiujn Mi elpelis el Jerusalem en Babelon:"],[29,5,"Konstruu domojn kaj loĝu, plantu ĝardenojn kaj manĝu iliajn fruktojn;","Konstruu domojn kaj loĝu, plantu ĝardenojn kaj manĝu iliajn fruktojn;"],[29,6,"prenu edzinojn kaj naskigu filojn kaj filinojn, prenu edzinojn por viaj filoj kaj edzinigu viajn filinojn, por ke ili nasku filojn kaj filinojn; multiĝu tie kaj ne malmultiĝu.","prenu edzinojn kaj naskigu filojn kaj filinojn, prenu edzinojn por viaj filoj kaj edzinigu viajn filinojn, por ke ili nasku filojn kaj filinojn; multiĝu tie kaj ne malmultiĝu."],[29,7,"Zorgu pri la bonstato de tiu urbo, kien Mi transloĝigis vin, kaj preĝu por ĝi al la Eternulo; ĉar ĉe ĝia bonstato vi ankaŭ havos bonstaton.","Zorgu pri la bonstato de tiu urbo, kien Mi transloĝigis vin, kaj preĝu por ĝi al la Eternulo; ĉar ĉe ĝia bonstato vi ankaŭ havos bonstaton."],[29,8,"Ĉar tiele diras la Eternulo Cebaot, Dio de Izrael: Viaj profetoj, kiuj estas inter vi, kaj viaj magiistoj ne forlogu vin; kaj ne atentu viajn sonĝojn, kiujn vi sonĝas;","Ĉar tiele diras la Eternulo Cebaot, Dio de Izrael: Viaj profetoj, kiuj estas inter vi, kaj viaj magiistoj ne forlogu vin; kaj ne atentu viajn sonĝojn, kiujn vi sonĝas;"],[29,9,"ĉar malveraĵon ili profetas al vi en Mia nomo; Mi ne sendis ilin, diras la Eternulo.","ĉar malveraĵon ili profetas al vi en Mia nomo; Mi ne sendis ilin, diras la Eternulo."],[29,10,"Ĉar tiele diras la Eternulo: Kiam en Babel pasos sepdek jaroj, Mi rememoros vin kaj plenumos super vi Mian bonan vorton, revenigante vin sur ĉi tiun lokon.","Ĉar tiele diras la Eternulo: Kiam en Babel pasos sepdek jaroj, Mi rememoros vin kaj plenumos super vi Mian bonan vorton, revenigante vin sur ĉi tiun lokon."],[29,11,"Ĉar Mi scias la intencojn, kiujn Mi havas koncerne vin, diras la Eternulo, intencojn al bono kaj ne al malbono, por doni al vi estontecon kaj esperon.","Ĉar Mi scias la intencojn, kiujn Mi havas koncerne vin, diras la Eternulo, intencojn al bono kaj ne al malbono, por doni al vi estontecon kaj esperon."],[29,12,"Vi vokos al Mi, kaj vi iros, kaj vi preĝos al Mi; kaj Mi aŭskultos vin.","Vi vokos al Mi, kaj vi iros, kaj vi preĝos al Mi; kaj Mi aŭskultos vin."],[29,13,"Vi serĉos Min, kaj trovos, se vi serĉos Min per via tuta koro.","Vi serĉos Min, kaj trovos, se vi serĉos Min per via tuta koro."],[29,14,"Kaj Mi estos trovita de vi, diras la Eternulo, kaj Mi revenigos viajn kaptitojn, kaj Mi kolektos vin el ĉiuj popoloj kaj de ĉiuj lokoj, kien Mi forpelis vin, diras la Eternulo; kaj Mi revenigos vin sur la lokon, de kiu Mi transloĝigis vin.","Kaj Mi estos trovita de vi, diras la Eternulo, kaj Mi revenigos viajn kaptitojn, kaj Mi kolektos vin el ĉiuj popoloj kaj de ĉiuj lokoj, kien Mi forpelis vin, diras la Eternulo; kaj Mi revenigos vin sur la lokon, de kiu Mi transloĝigis vin."],[29,15,"Vane vi diras: La Eternulo starigis al ni profetojn en Babel.","Vane vi diras: La Eternulo starigis al ni profetojn en Babel."],[29,16,"Ĉar tiele diras la Eternulo pri la reĝo, kiu sidas sur la trono de David, kaj pri la tuta popolo, kiu loĝas en ĉi tiu urbo, pri viaj fratoj, kiuj ne iris kun vi en ekzilon;","Ĉar tiele diras la Eternulo pri la reĝo, kiu sidas sur la trono de David, kaj pri la tuta popolo, kiu loĝas en ĉi tiu urbo, pri viaj fratoj, kiuj ne iris kun vi en ekzilon;"],[29,17,"tiele diras la Eternulo Cebaot: Jen Mi sendos sur ilin glavon kaj malsaton kaj peston, kaj Mi similigos ilin al malbonaj figoj, kiujn oni ne povas manĝi pro ilia malboneco;","tiele diras la Eternulo Cebaot: Jen Mi sendos sur ilin glavon kaj malsaton kaj peston, kaj Mi similigos ilin al malbonaj figoj, kiujn oni ne povas manĝi pro ilia malboneco;"],[29,18,"Mi persekutos ilin per glavo, per malsato, kaj per pesto, kaj Mi faros ilin objekto de teruro por ĉiuj regnoj de la tero, objekto de malbeno, mirego, moko, kaj malhonoro inter ĉiuj popoloj, kien Mi dispelos ilin;","Mi persekutos ilin per glavo, per malsato, kaj per pesto, kaj Mi faros ilin objekto de teruro por ĉiuj regnoj de la tero, objekto de malbeno, mirego, moko, kaj malhonoro inter ĉiuj popoloj, kien Mi dispelos ilin;"],[29,19,"pro tio, ke ili ne aŭskultis Miajn vortojn, diras la Eternulo; Mi sendadis al ili Miajn servantojn, la profetojn, Mi konstante sendadis, sed vi ne aŭskultis, diras la Eternulo.","pro tio, ke ili ne aŭskultis Miajn vortojn, diras la Eternulo; Mi sendadis al ili Miajn servantojn, la profetojn, Mi konstante sendadis, sed vi ne aŭskultis, diras la Eternulo."],[29,20,"Kaj vi, ĉiuj forkondukitoj, kiujn Mi foririgis el Jerusalem en Babelon, aŭskultu la vorton de la Eternulo.","Kaj vi, ĉiuj forkondukitoj, kiujn Mi foririgis el Jerusalem en Babelon, aŭskultu la vorton de la Eternulo."],[29,21,"Tiele diras la Eternulo Cebaot, Dio de Izrael, pri Aĥab, filo de Kolaja, kaj pri Cidkija, filo de Maaseja, kiuj profetis al vi en Mia nomo malveraĵon: Jen Mi transdonos ilin en la manon de Nebukadnecar, reĝo de Babel, kaj li mortigos ilin antaŭ viaj okuloj.","Tiele diras la Eternulo Cebaot, Dio de Izrael, pri Aĥab, filo de Kolaja, kaj pri Cidkija, filo de Maaseja, kiuj profetis al vi en Mia nomo malveraĵon: Jen Mi transdonos ilin en la manon de Nebukadnecar, reĝo de Babel, kaj li mortigos ilin antaŭ viaj okuloj."],[29,22,"Kaj ĉe ĉiuj ekzilitoj de Judujo, kiuj estas en Babel, ilia nomo fariĝos objekto de malbeno, kaj oni dirados: La Eternulo faru al vi tion, kion, kion al Cidkija kaj Aĥab, kiujn la reĝo de Babel rostigis sur fajro —","Kaj ĉe ĉiuj ekzilitoj de Judujo, kiuj estas en Babel, ilia nomo fariĝos objekto de malbeno, kaj oni dirados: La Eternulo faru al vi tion, kion, kion al Cidkija kaj Aĥab, kiujn la reĝo de Babel rostigis sur fajro —"],[29,23,"pro tio, ke ili faris abomenindaĵon en Izrael, adultis kun la edzinoj de siaj proksimuloj, kaj parolis en Mia nomo malveraĵon, kiun Mi ne ordonis al ili. Tion Mi scias kaj atestas, diras la Eternulo.","pro tio, ke ili faris abomenindaĵon en Izrael, adultis kun la edzinoj de siaj proksimuloj, kaj parolis en Mia nomo malveraĵon, kiun Mi ne ordonis al ili. Tion Mi scias kaj atestas, diras la Eternulo."],[29,24,"Kaj al Ŝemaja, la Neĥelamano, diru jene:","Kaj al Ŝemaja, la Neĥelamano, diru jene:"],[29,25,"Tiele diras la Eternulo Cebaot, Dio de Izrael: Pro tio, ke vi sendis en via nomo leterojn al la tuta popolo, kiu estas en Jerusalem, kaj al la pastro Cefanja, filo de Maaseja, kaj al ĉiuj pastroj, kun la sekvanta enhavo:","Tiele diras la Eternulo Cebaot, Dio de Izrael: Pro tio, ke vi sendis en via nomo leterojn al la tuta popolo, kiu estas en Jerusalem, kaj al la pastro Cefanja, filo de Maaseja, kaj al ĉiuj pastroj, kun la sekvanta enhavo:"],[29,26,"La Eternulo starigis vin pastro anstataŭ la pastro Jehojada, por ke vi estu kontrolanto en la domo de la Eternulo super ĉiu frenezulo, kiu prezentas sin kiel profeto, kaj vi metu lin en malliberejon kaj karceron;","La Eternulo starigis vin pastro anstataŭ la pastro Jehojada, por ke vi estu kontrolanto en la domo de la Eternulo super ĉiu frenezulo, kiu prezentas sin kiel profeto, kaj vi metu lin en malliberejon kaj karceron;"],[29,27,"kial do vi ne faris punparolon al Jeremia, la Anatotano, kiu prezentas sin al vi kiel profeto?","kial do vi ne faris punparolon al Jeremia, la Anatotano, kiu prezentas sin al vi kiel profeto?"],[29,28,"Ĉar ankaŭ al ni en Babelon li sendis, por diri: La kaptiteco estos longa; konstruu domojn kaj loĝu, plantu ĝardenojn kaj manĝu iliajn fruktojn.","Ĉar ankaŭ al ni en Babelon li sendis, por diri: La kaptiteco estos longa; konstruu domojn kaj loĝu, plantu ĝardenojn kaj manĝu iliajn fruktojn."],[29,29,"Kaj la pastro Cefanja tralegis tiun leteron en la orelojn de la profeto Jeremia.","Kaj la pastro Cefanja tralegis tiun leteron en la orelojn de la profeto Jeremia."],[29,30,"Tial aperis jena vorto de la Eternulo al Jeremia:","Tial aperis jena vorto de la Eternulo al Jeremia:"],[29,31,"Sendu al ĉiuj ekzilitoj, por diri: Tiele diras la Eternulo pri Ŝemaja, la Neĥelamano: Pro tio, ke Ŝemaja profetis al vi, kvankam Mi ne sendis lin, kaj li fidigis vin per malveraĵo —","Sendu al ĉiuj ekzilitoj, por diri: Tiele diras la Eternulo pri Ŝemaja, la Neĥelamano: Pro tio, ke Ŝemaja profetis al vi, kvankam Mi ne sendis lin, kaj li fidigis vin per malveraĵo —"],[29,32,"pro tio tiele diras la Eternulo: Jen Mi punos Ŝemajan, la Neĥelamanon, kaj lian idaron: neniu restos ĉe li meze de ĉi tiu popolo, kaj li ne vidos la bonon, kiun Mi faros al Mia popolo, diras la Eternulo; ĉar li parolis kontraŭ la volo de la Eternulo.","pro tio tiele diras la Eternulo: Jen Mi punos Ŝemajan, la Neĥelamanon, kaj lian idaron: neniu restos ĉe li meze de ĉi tiu popolo, kaj li ne vidos la bonon, kiun Mi faros al Mia popolo, diras la Eternulo; ĉar li parolis kontraŭ la volo de la Eternulo."],[30,1,"Jena vorto aperis de la Eternulo al Jeremia:","Jena vorto aperis de la Eternulo al Jeremia:"],[30,2,"Tiele diras la Eternulo, Dio de Izrael: Enskribu al vi en libron ĉiujn vortojn, kiujn Mi diris al vi.","Tiele diras la Eternulo, Dio de Izrael: Enskribu al vi en libron ĉiujn vortojn, kiujn Mi diris al vi."],[30,3,"Ĉar jen venos tempo, diras la Eternulo, kiam Mi revenigos la kaptitojn de Mia popolo Izrael kaj Jehuda, diras la Eternulo, kaj Mi revenigos ilin en la landon, kiun Mi donis al iliaj patroj, kaj ili ĝin posedos.","Ĉar jen venos tempo, diras la Eternulo, kiam Mi revenigos la kaptitojn de Mia popolo Izrael kaj Jehuda, diras la Eternulo, kaj Mi revenigos ilin en la landon, kiun Mi donis al iliaj patroj, kaj ili ĝin posedos."],[30,4,"Kaj jen estas la vortoj, kiujn diris la Eternulo pri Izrael kaj Jehuda:","Kaj jen estas la vortoj, kiujn diris la Eternulo pri Izrael kaj Jehuda:"],[30,5,"Tiele diras la Eternulo: Voĉon de tumulto kaj de teruro ni aŭdas, ne de paco.","Tiele diras la Eternulo: Voĉon de tumulto kaj de teruro ni aŭdas, ne de paco."],[30,6,"Demandu kaj rigardu, ĉu viro naskas? kial do Mi vidas, ke ĉiu viro tenas siajn manojn ĉe siaj lumboj, kiel naskantino, kaj ĉies vizaĝoj verdiĝis?","Demandu kaj rigardu, ĉu viro naskas? kial do Mi vidas, ke ĉiu viro tenas siajn manojn ĉe siaj lumboj, kiel naskantino, kaj ĉies vizaĝoj verdiĝis?"],[30,7,"Ho ve, kiel granda estas tiu tago! ne ekzistas simila al ĝi; tempo de mizero ĝi estas por Jakob, sed li estos savita el ĝi.","Ho ve, kiel granda estas tiu tago! ne ekzistas simila al ĝi; tempo de mizero ĝi estas por Jakob, sed li estos savita el ĝi."],[30,8,"En tiu tempo, diras la Eternulo Cebaot, Mi forrompos lian jugon de via kolo, kaj viajn ligilojn Mi disŝiros, kaj fremduloj ne plu servigos lin.","En tiu tempo, diras la Eternulo Cebaot, Mi forrompos lian jugon de via kolo, kaj viajn ligilojn Mi disŝiros, kaj fremduloj ne plu servigos lin."],[30,9,"Sed ili servos al la Eternulo, sia Dio, kaj al David, sia reĝo, kiun Mi restarigos al ili.","Sed ili servos al la Eternulo, sia Dio, kaj al David, sia reĝo, kiun Mi restarigos al ili."],[30,10,"Kaj vi ne timu, ho Mia servanto Jakob, diras la Eternulo, kaj ne tremu, ho Izrael; ĉar jen Mi savos vin el malproksime kaj vian idaron el la lando de ilia kaptiteco, kaj Jakob revenos kaj vivos trankvile kaj pace, kaj neniu lin timigos.","Kaj vi ne timu, ho Mia servanto Jakob, diras la Eternulo, kaj ne tremu, ho Izrael; ĉar jen Mi savos vin el malproksime kaj vian idaron el la lando de ilia kaptiteco, kaj Jakob revenos kaj vivos trankvile kaj pace, kaj neniu lin timigos."],[30,11,"Ĉar Mi estos kun vi, diras la Eternulo, por savi vin; ĉar Mi ekstermos ĉiujn popolojn, inter kiujn Mi disĵetis vin, sed vin Mi ne ekstermos; Mi nur punos vin modere, por ke Mi ne lasu vin tute sen puno.","Ĉar Mi estos kun vi, diras la Eternulo, por savi vin; ĉar Mi ekstermos ĉiujn popolojn, inter kiujn Mi disĵetis vin, sed vin Mi ne ekstermos; Mi nur punos vin modere, por ke Mi ne lasu vin tute sen puno."],[30,12,"Ĉar tiele diras la Eternulo: Danĝera estas via vundo, kaj via ulcero estas dolorplena.","Ĉar tiele diras la Eternulo: Danĝera estas via vundo, kaj via ulcero estas dolorplena."],[30,13,"Neniu juĝos vian aferon, por sanigi vian vundon; bona kuracado ne ekzistas por vi.","Neniu juĝos vian aferon, por sanigi vian vundon; bona kuracado ne ekzistas por vi."],[30,14,"Ĉiuj viaj amikoj forgesis vin, ili vin ne serĉas; ĉar per frapo de malamiko Mi frapis vin, per kruela puno, pro viaj multaj malbonagoj, pro la forteco de viaj pekoj.","Ĉiuj viaj amikoj forgesis vin, ili vin ne serĉas; ĉar per frapo de malamiko Mi frapis vin, per kruela puno, pro viaj multaj malbonagoj, pro la forteco de viaj pekoj."],[30,15,"Kial vi krias pri via vundo, pri via danĝera malsano? Mi tion faris al vi pro viaj multaj malbonagoj, pro la forteco de viaj pekoj.","Kial vi krias pri via vundo, pri via danĝera malsano? Mi tion faris al vi pro viaj multaj malbonagoj, pro la forteco de viaj pekoj."],[30,16,"Tamen ĉiuj viaj manĝegantoj estos manĝegitaj; kaj ĉiuj viaj premantoj, ĉiuj, iros en kaptitecon; viaj ruinigintoj estos ruinigitaj; kaj ĉiuj viajn rabintojn Mi faros rabitaj.","Tamen ĉiuj viaj manĝegantoj estos manĝegitaj; kaj ĉiuj viaj premantoj, ĉiuj, iros en kaptitecon; viaj ruinigintoj estos ruinigitaj; kaj ĉiuj viajn rabintojn Mi faros rabitaj."],[30,17,"Mi donos al vi kuracon, kaj Mi resanigos vin de viaj vundoj, diras la Eternulo; ĉar ili nomis vin forpuŝitino, ho Cion, pri kiu neniu demandas.","Mi donos al vi kuracon, kaj Mi resanigos vin de viaj vundoj, diras la Eternulo; ĉar ili nomis vin forpuŝitino, ho Cion, pri kiu neniu demandas."],[30,18,"Tiele diras la Eternulo: Jen Mi revenigos el kaptiteco la tendojn de Jakob, kaj liajn loĝejojn Mi kompatos; kaj la urbo estos konstruita sur sia monteto, kaj la templo estos starigita laŭ sia ordo.","Tiele diras la Eternulo: Jen Mi revenigos el kaptiteco la tendojn de Jakob, kaj liajn loĝejojn Mi kompatos; kaj la urbo estos konstruita sur sia monteto, kaj la templo estos starigita laŭ sia ordo."],[30,19,"Kaj eliros el ili dankado kaj voĉo de gajuloj; Mi multigos ilin, kaj ili ne malmultiĝos; Mi donos al ili honoron, kaj ili ne malaltiĝos.","Kaj eliros el ili dankado kaj voĉo de gajuloj; Mi multigos ilin, kaj ili ne malmultiĝos; Mi donos al ili honoron, kaj ili ne malaltiĝos."],[30,20,"Kaj ili havos filojn kiel antaŭe, kaj ilia komunumo forte staros antaŭ Mi, kaj Mi punos ĉiujn iliajn premintojn.","Kaj ili havos filojn kiel antaŭe, kaj ilia komunumo forte staros antaŭ Mi, kaj Mi punos ĉiujn iliajn premintojn."],[30,21,"Kaj ilia potenculo estos el ili mem, kaj ilia reganto devenos el ilia propra mezo; Mi alproksimigos lin, kaj li aliros al Mi; ĉar kiu alia kuraĝos en sia koro alproksimiĝi al Mi? diras la Eternulo.","Kaj ilia potenculo estos el ili mem, kaj ilia reganto devenos el ilia propra mezo; Mi alproksimigos lin, kaj li aliros al Mi; ĉar kiu alia kuraĝos en sia koro alproksimiĝi al Mi? diras la Eternulo."],[30,22,"Kaj vi estos Mia popolo, kaj Mi estos via Dio.","Kaj vi estos Mia popolo, kaj Mi estos via Dio."],[30,23,"Jen eliros ventego de la Eternulo en kolero, ventego detruanta; ĝi falos sur la kapon de la malpiuloj.","Jen eliros ventego de la Eternulo en kolero, ventego detruanta; ĝi falos sur la kapon de la malpiuloj."],[30,24,"Ne kvietiĝos la flama kolero de la Eternulo, ĝis Li estos farinta kaj ĝis Li estos plenuminta la intencojn de Sia koro; en la tempo estonta vi tion komprenos.","Ne kvietiĝos la flama kolero de la Eternulo, ĝis Li estos farinta kaj ĝis Li estos plenuminta la intencojn de Sia koro; en la tempo estonta vi tion komprenos."],[31,1,"En tiu tempo, diras la Eternulo, Mi estos Dio de ĉiuj familioj de Izrael, kaj ili estos Mia popolo.","En tiu tempo, diras la Eternulo, Mi estos Dio de ĉiuj familioj de Izrael, kaj ili estos Mia popolo."],[31,2,"Tiele diras la Eternulo: En la dezerto trovis favoron popolo, kiu restis ne ekstermita de la glavo; Izrael iras al sia trankviliĝo.","Tiele diras la Eternulo: En la dezerto trovis favoron popolo, kiu restis ne ekstermita de la glavo; Izrael iras al sia trankviliĝo."],[31,3,"De malproksime aperis al mi la Eternulo, dirante: Mi ekamis vin per amo eterna, tial Mi altiris vin favorkore.","De malproksime aperis al mi la Eternulo, dirante: Mi ekamis vin per amo eterna, tial Mi altiris vin favorkore."],[31,4,"Denove Mi aranĝos vin, kaj vi estos aranĝita, ho virgulino de Izrael; denove vi ornamos vin per viaj tamburinoj kaj eliros en dancrondojn de gajuloj.","Denove Mi aranĝos vin, kaj vi estos aranĝita, ho virgulino de Izrael; denove vi ornamos vin per viaj tamburinoj kaj eliros en dancrondojn de gajuloj."],[31,5,"Denove vi plantos vinberĝardenojn sur la montoj de Samario; oni plantos kaj ricevos fruktojn.","Denove vi plantos vinberĝardenojn sur la montoj de Samario; oni plantos kaj ricevos fruktojn."],[31,6,"Ĉar venos la tempo, kiam gardistoj sur la monto de Efraim vokos: Leviĝu, kaj ni iru sur Cionon al la Eternulo, nia Dio.","Ĉar venos la tempo, kiam gardistoj sur la monto de Efraim vokos: Leviĝu, kaj ni iru sur Cionon al la Eternulo, nia Dio."],[31,7,"Ĉar tiele diras la Eternulo: Kantu ĝojon al Jakob kaj ĝojkriu antaŭ la kapoj de la nacioj, proklamu, gloru, kaj diru: Savu, ho Eternulo, Vian popolon, la restaĵon de Izrael.","Ĉar tiele diras la Eternulo: Kantu ĝojon al Jakob kaj ĝojkriu antaŭ la kapoj de la nacioj, proklamu, gloru, kaj diru: Savu, ho Eternulo, Vian popolon, la restaĵon de Izrael."],[31,8,"Jen Mi venigos ilin el la lando norda, kaj kolektos ilin de la randoj de la tero, kune kun la blinduloj kaj lamuloj, gravedulinoj kaj naskintinoj; en granda amaso ili revenos ĉi tien.","Jen Mi venigos ilin el la lando norda, kaj kolektos ilin de la randoj de la tero, kune kun la blinduloj kaj lamuloj, gravedulinoj kaj naskintinoj; en granda amaso ili revenos ĉi tien."],[31,9,"Kun ploro ili venos, kun preĝoj Mi kondukos ilin; Mi irigos ilin apud torentoj da akvo, laŭ vojo ĝusta, sur kiu ili ne falpuŝiĝos; ĉar Mi fariĝis patro por Izrael, kaj Efraim estas Mia unuenaskito.","Kun ploro ili venos, kun preĝoj Mi kondukos ilin; Mi irigos ilin apud torentoj da akvo, laŭ vojo ĝusta, sur kiu ili ne falpuŝiĝos; ĉar Mi fariĝis patro por Izrael, kaj Efraim estas Mia unuenaskito."],[31,10,"Aŭskultu la vorton de la Eternulo, ho nacioj, kaj sciigu al la malproksimaj insuloj, kaj diru: La disĵetinto de Izrael kolektos lin kaj gardos lin, kiel paŝtanto sian paŝtataron.","Aŭskultu la vorton de la Eternulo, ho nacioj, kaj sciigu al la malproksimaj insuloj, kaj diru: La disĵetinto de Izrael kolektos lin kaj gardos lin, kiel paŝtanto sian paŝtataron."],[31,11,"Ĉar la Eternulo elaĉetis Jakobon kaj liberigis lin el la mano de plifortulo.","Ĉar la Eternulo elaĉetis Jakobon kaj liberigis lin el la mano de plifortulo."],[31,12,"Kaj ili venos kaj kantos sur la altaĵo de Cion; kaj ili rapidos al la bonaĵoj de la Eternulo, al la greno, al la mosto, al la oleo, al la ŝafidoj kaj bovidoj; kaj ilia animo estos kiel akvoriĉa ĝardeno, kaj ili ne plu havos malĝojon.","Kaj ili venos kaj kantos sur la altaĵo de Cion; kaj ili rapidos al la bonaĵoj de la Eternulo, al la greno, al la mosto, al la oleo, al la ŝafidoj kaj bovidoj; kaj ilia animo estos kiel akvoriĉa ĝardeno, kaj ili ne plu havos malĝojon."],[31,13,"Tiam virgulino gajos en la dancrondo, kaj kune ankaŭ junuloj kaj maljunuloj; kaj Mi ŝanĝos ilian malĝojon en ĝojon, Mi konsolos ilin kaj gajigos ilin post ilia aflikto.","Tiam virgulino gajos en la dancrondo, kaj kune ankaŭ junuloj kaj maljunuloj; kaj Mi ŝanĝos ilian malĝojon en ĝojon, Mi konsolos ilin kaj gajigos ilin post ilia aflikto."],[31,14,"Kaj la animon de la pastroj Mi satigos per grasaĵoj, kaj Mia popolo satiĝos per Miaj bonaĵoj, diras la Eternulo.","Kaj la animon de la pastroj Mi satigos per grasaĵoj, kaj Mia popolo satiĝos per Miaj bonaĵoj, diras la Eternulo."],[31,15,"Tiele diras la Eternulo: Voĉo estas aŭdata en Rama, ĝemado kaj maldolĉa plorado: Raĥel priploras siajn filojn, ne volas konsoliĝi pri siaj infanoj, ĉar ili forestas.","Tiele diras la Eternulo: Voĉo estas aŭdata en Rama, ĝemado kaj maldolĉa plorado: Raĥel priploras siajn filojn, ne volas konsoliĝi pri siaj infanoj, ĉar ili forestas."],[31,16,"Tiele diras la Eternulo: Detenu vian voĉon de plorado kaj viajn okulojn de larmoj; ĉar ekzistas rekompenco por via laboro, diras la Eternulo, kaj ili revenos el la lando de la malamiko.","Tiele diras la Eternulo: Detenu vian voĉon de plorado kaj viajn okulojn de larmoj; ĉar ekzistas rekompenco por via laboro, diras la Eternulo, kaj ili revenos el la lando de la malamiko."],[31,17,"Kaj ekzistas espero por via idaro, diras la Eternulo, kaj la filoj revenos en siajn limojn.","Kaj ekzistas espero por via idaro, diras la Eternulo, kaj la filoj revenos en siajn limojn."],[31,18,"Mi aŭdis, kiel Efraim diras pentante: Vi punis min, kaj mi estas punita, kiel bovido ne dresita; konvertu min, kaj mi konvertiĝos; ĉar Vi, ho Eternulo, estas mia Dio.","Mi aŭdis, kiel Efraim diras pentante: Vi punis min, kaj mi estas punita, kiel bovido ne dresita; konvertu min, kaj mi konvertiĝos; ĉar Vi, ho Eternulo, estas mia Dio."],[31,19,"Kiam mi konvertiĝis, mi pentis; kaj kiam mi estis punita, mi batis min sur la femurojn; mi hontis kaj mi ruĝiĝis, ĉar mi portas la malhonoron de mia juneco.","Kiam mi konvertiĝis, mi pentis; kaj kiam mi estis punita, mi batis min sur la femurojn; mi hontis kaj mi ruĝiĝis, ĉar mi portas la malhonoron de mia juneco."],[31,20,"Ĉu Efraim ne estas Mia kara filo, Mia amata infano? ĉar kion ajn Mi parolis pri li, Mi tamen ankoraŭ rememoras lin; tial Mia interno afliktiĝas pri li; Mi certe korfavoros lin, diras la Eternulo.","Ĉu Efraim ne estas Mia kara filo, Mia amata infano? ĉar kion ajn Mi parolis pri li, Mi tamen ankoraŭ rememoras lin; tial Mia interno afliktiĝas pri li; Mi certe korfavoros lin, diras la Eternulo."],[31,21,"Starigu al vi gvidajn ŝtonojn, aranĝu al vi vojsignojn, atentu la vojon, laŭ kiu vi iris; revenu, virgulino de Izrael, revenu en ĉi tiujn viajn urbojn.","Starigu al vi gvidajn ŝtonojn, aranĝu al vi vojsignojn, atentu la vojon, laŭ kiu vi iris; revenu, virgulino de Izrael, revenu en ĉi tiujn viajn urbojn."],[31,22,"Ĝis kiam vi turnados vin, ho defalinta filino? Ĉar la Eternulo kreis ion novan sur la tero: virino ĉirkaŭos viron.","Ĝis kiam vi turnados vin, ho defalinta filino? Ĉar la Eternulo kreis ion novan sur la tero: virino ĉirkaŭos viron."],[31,23,"Tiele diras la Eternulo Cebaot, Dio de Izrael: Ankoraŭ oni parolos jenajn vortojn en la Juda lando kaj en ĝiaj urboj, kiam Mi revenigos iliajn kaptitojn: La Eternulo vin benu, ho loĝejo de justeco, sankta monto!","Tiele diras la Eternulo Cebaot, Dio de Izrael: Ankoraŭ oni parolos jenajn vortojn en la Juda lando kaj en ĝiaj urboj, kiam Mi revenigos iliajn kaptitojn: La Eternulo vin benu, ho loĝejo de justeco, sankta monto!"],[31,24,"Kaj loĝos apud ĝi Jehuda kune kun ĉiuj siaj urboj, la terkultivistoj kaj la vagantoj kun paŝtataroj.","Kaj loĝos apud ĝi Jehuda kune kun ĉiuj siaj urboj, la terkultivistoj kaj la vagantoj kun paŝtataroj."],[31,25,"Ĉar Mi sensoifigos animon lacan, kaj ĉiun animon malĝojan Mi satigos.","Ĉar Mi sensoifigos animon lacan, kaj ĉiun animon malĝojan Mi satigos."],[31,26,"Ĉe tio mi vekiĝis kaj ekrigardis, kaj mia sonĝo estis agrabla por mi.","Ĉe tio mi vekiĝis kaj ekrigardis, kaj mia sonĝo estis agrabla por mi."],[31,27,"Jen venos la tempo, diras la Eternulo, kiam Mi prisemos la domon de Izrael kaj la domon de Jehuda per semo de homo kaj semo de bruto.","Jen venos la tempo, diras la Eternulo, kiam Mi prisemos la domon de Izrael kaj la domon de Jehuda per semo de homo kaj semo de bruto."],[31,28,"Kaj tiel same, kiel Mi maldormis super ili, por elradikigi, elŝiri, detrui, pereigi, kaj malfeliĉigi, tiel Mi maldormos super ili, por konstrui kaj planti, diras la Eternulo.","Kaj tiel same, kiel Mi maldormis super ili, por elradikigi, elŝiri, detrui, pereigi, kaj malfeliĉigi, tiel Mi maldormos super ili, por konstrui kaj planti, diras la Eternulo."],[31,29,"En tiu tempo oni ne plu diros: La patroj manĝis nematurajn vinberojn, kaj la dentoj de la filoj agaciĝis;","En tiu tempo oni ne plu diros: La patroj manĝis nematurajn vinberojn, kaj la dentoj de la filoj agaciĝis;"],[31,30,"sed ĉiu mortos pro sia propra kulpo, la dentoj agaciĝos ĉe tiu, kiu manĝis la nematurajn vinberojn.","sed ĉiu mortos pro sia propra kulpo, la dentoj agaciĝos ĉe tiu, kiu manĝis la nematurajn vinberojn."],[31,31,"Jen venos la tempo, diras la Eternulo, kiam Mi faros kun la domo de Izrael kaj la domo de Jehuda interligon novan:","Jen venos la tempo, diras la Eternulo, kiam Mi faros kun la domo de Izrael kaj la domo de Jehuda interligon novan:"],[31,32,"ne tian, kiel la interligo, kiun Mi faris kun iliaj patroj, en la tago, kiam Mi prenis ilian manon, por elkonduki ilin el la lando Egipta, la interligo, kiun ili malobeis kaj Mi devis altrudi al ili, diras la Eternulo;","ne tian, kiel la interligo, kiun Mi faris kun iliaj patroj, en la tago, kiam Mi prenis ilian manon, por elkonduki ilin el la lando Egipta, la interligo, kiun ili malobeis kaj Mi devis altrudi al ili, diras la Eternulo;"],[31,33,"sed jen estas la interligo, kiun Mi faros kun la domo de Izrael post tiu tempo, diras la Eternulo: Mi metos Mian leĝon en ilian internon, kaj sur ilia koro Mi ĝin skribos, kaj Mi estos ilia Dio, kaj ili estos Mia popolo.","sed jen estas la interligo, kiun Mi faros kun la domo de Izrael post tiu tempo, diras la Eternulo: Mi metos Mian leĝon en ilian internon, kaj sur ilia koro Mi ĝin skribos, kaj Mi estos ilia Dio, kaj ili estos Mia popolo."],[31,34,"Kaj ne plu instruos ĉiu sian proksimulon kaj ĉiu sian fraton, dirante: Ekkonu la Eternulon; ĉar ĉiuj Min konos, de iliaj malgranduloj ĝis iliaj granduloj, diras la Eternulo; ĉar Mi pardonos iliajn kulpojn, kaj iliajn pekojn Mi ne plu rememoros.","Kaj ne plu instruos ĉiu sian proksimulon kaj ĉiu sian fraton, dirante: Ekkonu la Eternulon; ĉar ĉiuj Min konos, de iliaj malgranduloj ĝis iliaj granduloj, diras la Eternulo; ĉar Mi pardonos iliajn kulpojn, kaj iliajn pekojn Mi ne plu rememoros."],[31,35,"Tiele diras la Eternulo, kiu donas la sunon por lumo en la tago, leĝojn al la luno kaj al la steloj por lumo en la nokto; kiu kvietigas la maron, kiam bruas ĝiaj ondoj; kaj kies nomo estas Eternulo Cebaot:","Tiele diras la Eternulo, kiu donas la sunon por lumo en la tago, leĝojn al la luno kaj al la steloj por lumo en la nokto; kiu kvietigas la maron, kiam bruas ĝiaj ondoj; kaj kies nomo estas Eternulo Cebaot:"],[31,36,"Se ĉi tiuj leĝoj neniiĝos antaŭ Mi, diras la Eternulo, tiam ankaŭ la idaro de Izrael ĉesos esti eterne popolo antaŭ Mi.","Se ĉi tiuj leĝoj neniiĝos antaŭ Mi, diras la Eternulo, tiam ankaŭ la idaro de Izrael ĉesos esti eterne popolo antaŭ Mi."],[31,37,"Tiele diras la Eternulo: Se oni povos mezuri la ĉielon supre kaj esplori la fundamenton de la tero malsupre, tiam Mi forpuŝos la tutan idaron de Izrael pro ĉio, kion ili faris, diras la Eternulo.","Tiele diras la Eternulo: Se oni povos mezuri la ĉielon supre kaj esplori la fundamenton de la tero malsupre, tiam Mi forpuŝos la tutan idaron de Izrael pro ĉio, kion ili faris, diras la Eternulo."],[31,38,"Jen venos la tempo, diras la Eternulo, kiam denove konstruiĝos la urbo al la Eternulo, de la turo Ĥananel ĝis la Pordego Angula.","Jen venos la tempo, diras la Eternulo, kiam denove konstruiĝos la urbo al la Eternulo, de la turo Ĥananel ĝis la Pordego Angula."],[31,39,"Kaj la mezura ŝnuro iros pluen ĝis la monteto Gareb kaj turniĝos al Goa.","Kaj la mezura ŝnuro iros pluen ĝis la monteto Gareb kaj turniĝos al Goa."],[31,40,"Kaj la tuta valo de kadavroj kaj de cindro, kaj ĉiuj kampoj ĝis la torento Kidron, ĝis la angulo de la Pordego de Ĉevaloj oriente, estos sanktaj al la Eternulo, ne detruiĝos kaj ne plu ruiniĝos eterne.","Kaj la tuta valo de kadavroj kaj de cindro, kaj ĉiuj kampoj ĝis la torento Kidron, ĝis la angulo de la Pordego de Ĉevaloj oriente, estos sanktaj al la Eternulo, ne detruiĝos kaj ne plu ruiniĝos eterne."],[32,1,"Jen estas la vorto, kiu aperis al Jeremia de la Eternulo en la deka jaro de Cidkija, reĝo de Judujo, tio estas en la dek-oka jaro de Nebukadnecar.","Jen estas la vorto, kiu aperis al Jeremia de la Eternulo en la deka jaro de Cidkija, reĝo de Judujo, tio estas en la dek-oka jaro de Nebukadnecar."],[32,2,"Tiam la militistaro de la reĝo de Babel sieĝis Jerusalemon, kaj la profeto Jeremia estis malliberigita sur la korto de la malliberejo, kiu estis apud la domo de la reĝo de Judujo.","Tiam la militistaro de la reĝo de Babel sieĝis Jerusalemon, kaj la profeto Jeremia estis malliberigita sur la korto de la malliberejo, kiu estis apud la domo de la reĝo de Judujo."],[32,3,"Tie malliberigis lin Cidkija, reĝo de Judujo, dirante: Kial vi profetas, parolante, ke tiele diras la Eternulo: Jen Mi transdonos ĉi tiun urbon en la manon de la reĝo de Babel, kiu ĝin venkoprenos;","Tie malliberigis lin Cidkija, reĝo de Judujo, dirante: Kial vi profetas, parolante, ke tiele diras la Eternulo: Jen Mi transdonos ĉi tiun urbon en la manon de la reĝo de Babel, kiu ĝin venkoprenos;"],[32,4,"kaj Cidkija, reĝo de Judujo, ne saviĝos el la manoj de la Ĥaldeoj, sed li estos transdonita en la manon de la reĝo de Babel, kies buŝo parolos kun lia buŝo kaj kies okuloj rigardos liajn okulojn;","kaj Cidkija, reĝo de Judujo, ne saviĝos el la manoj de la Ĥaldeoj, sed li estos transdonita en la manon de la reĝo de Babel, kies buŝo parolos kun lia buŝo kaj kies okuloj rigardos liajn okulojn;"],[32,5,"kaj en Babelon li forkondukos Cidkijan, kaj ĉi tiu restos tie, ĝis Mi vizitos lin, diras la Eternulo; se vi militos kontraŭ la Ĥaldeoj, vi ne sukcesos?","kaj en Babelon li forkondukos Cidkijan, kaj ĉi tiu restos tie, ĝis Mi vizitos lin, diras la Eternulo; se vi militos kontraŭ la Ĥaldeoj, vi ne sukcesos?"],[32,6,"Kaj Jeremia diris: Aperis al mi la vorto de la Eternulo, dirante:","Kaj Jeremia diris: Aperis al mi la vorto de la Eternulo, dirante:"],[32,7,"Jen Ĥanamel, filo de via onklo Ŝalum, iras al vi, por diri: Aĉetu al vi mian kampon, kiu estas en Anatot, ĉar al vi apartenas la rajto de parenco, por aĉeti.","Jen Ĥanamel, filo de via onklo Ŝalum, iras al vi, por diri: Aĉetu al vi mian kampon, kiu estas en Anatot, ĉar al vi apartenas la rajto de parenco, por aĉeti."],[32,8,"Kaj venis al mi Ĥanamel, filo de mia onklo, konforme al la vorto de la Eternulo, sur la korton de la malliberejo, kaj li diris al mi: Aĉetu, mi petas, mian kampon, kiu estas en Anatot, en la lando de Benjamen; ĉar al vi apartenas la rajto de heredo kaj la rajto de elaĉeto; aĉetu al vi. Tiam mi komprenis, ke tio estas vorto de la Eternulo.","Kaj venis al mi Ĥanamel, filo de mia onklo, konforme al la vorto de la Eternulo, sur la korton de la malliberejo, kaj li diris al mi: Aĉetu, mi petas, mian kampon, kiu estas en Anatot, en la lando de Benjamen; ĉar al vi apartenas la rajto de heredo kaj la rajto de elaĉeto; aĉetu al vi. Tiam mi komprenis, ke tio estas vorto de la Eternulo."],[32,9,"Kaj mi aĉetis de Ĥanamel, filo de mia onklo, la kampon, kiu estis en Anatot, kaj mi pesis al li la monon, dek sep siklojn da arĝento.","Kaj mi aĉetis de Ĥanamel, filo de mia onklo, la kampon, kiu estis en Anatot, kaj mi pesis al li la monon, dek sep siklojn da arĝento."],[32,10,"Kaj mi skribis dokumenton kaj sigelis; kaj mi invitis atestantojn, kaj pesis la arĝenton per pesilo.","Kaj mi skribis dokumenton kaj sigelis; kaj mi invitis atestantojn, kaj pesis la arĝenton per pesilo."],[32,11,"Kaj mi prenis la dokumenton de aĉeto, la sigelitan laŭ juro kaj leĝo, kaj la nefermitan.","Kaj mi prenis la dokumenton de aĉeto, la sigelitan laŭ juro kaj leĝo, kaj la nefermitan."],[32,12,"Kaj mi donis la dokumenton de aĉeto al Baruĥ, filo de Nerija, filo de Maĥseja, antaŭ la okuloj de mia kuzo Ĥanamel, kaj antaŭ la okuloj de la atestantoj, kiuj subskribis la dokumenton de aĉeto, kaj antaŭ la okuloj de ĉiuj Judoj, kiuj sidis sur la korto de la malliberejo.","Kaj mi donis la dokumenton de aĉeto al Baruĥ, filo de Nerija, filo de Maĥseja, antaŭ la okuloj de mia kuzo Ĥanamel, kaj antaŭ la okuloj de la atestantoj, kiuj subskribis la dokumenton de aĉeto, kaj antaŭ la okuloj de ĉiuj Judoj, kiuj sidis sur la korto de la malliberejo."],[32,13,"Kaj mi ordonis al Baruĥ antaŭ iliaj okuloj, dirante:","Kaj mi ordonis al Baruĥ antaŭ iliaj okuloj, dirante:"],[32,14,"Tiele diras la Eternulo Cebaot, Dio de Izrael: Prenu ĉi tiujn dokumentojn, ĉi tiun dokumenton de aĉeto, la sigelitan, kaj ĉi tiun nefermitan, kaj metu ilin en argilan vazon, por ke ili konserviĝu dum longa tempo.","Tiele diras la Eternulo Cebaot, Dio de Izrael: Prenu ĉi tiujn dokumentojn, ĉi tiun dokumenton de aĉeto, la sigelitan, kaj ĉi tiun nefermitan, kaj metu ilin en argilan vazon, por ke ili konserviĝu dum longa tempo."],[32,15,"Ĉar tiele diras la Eternulo Cebaot, Dio de Izrael: Oni denove aĉetos domojn, kampojn, kaj vinberĝardenojn en ĉi tiu lando.","Ĉar tiele diras la Eternulo Cebaot, Dio de Izrael: Oni denove aĉetos domojn, kampojn, kaj vinberĝardenojn en ĉi tiu lando."],[32,16,"Kaj, transdoninte la dokumentojn de aĉeto al Baruĥ, filo de Nerija, mi ekpreĝis al la Eternulo, dirante:","Kaj, transdoninte la dokumentojn de aĉeto al Baruĥ, filo de Nerija, mi ekpreĝis al la Eternulo, dirante:"],[32,17,"Ho Sinjoro, ho Eternulo! Vi kreis la ĉielon kaj la teron per Via granda forto kaj per Via etendita brako; nenia afero estas nefarebla por Vi;","Ho Sinjoro, ho Eternulo! Vi kreis la ĉielon kaj la teron per Via granda forto kaj per Via etendita brako; nenia afero estas nefarebla por Vi;"],[32,18,"Vi faras favorkoraĵon al miloj, kaj pro la malbonagoj de la patroj Vi repagas al iliaj filoj post ili. Vi, Dio granda, potenca, kies nomo estas Eternulo Cebaot,","Vi faras favorkoraĵon al miloj, kaj pro la malbonagoj de la patroj Vi repagas al iliaj filoj post ili. Vi, Dio granda, potenca, kies nomo estas Eternulo Cebaot,"],[32,19,"granda en Siaj decidoj kaj potenca en Siaj agoj; Vi, kies okuloj estas malfermitaj super ĉiuj vojoj de la homidoj, por redoni al ĉiu laŭ lia konduto kaj laŭ la fruktoj de liaj agoj;","granda en Siaj decidoj kaj potenca en Siaj agoj; Vi, kies okuloj estas malfermitaj super ĉiuj vojoj de la homidoj, por redoni al ĉiu laŭ lia konduto kaj laŭ la fruktoj de liaj agoj;"],[32,20,"Vi, kiu faris signojn kaj miraklojn en la lando Egipta ĝis la nuna tago super Izrael kaj super la aliaj homoj, kaj faris al Vi gloran nomon, kiel ĝi estas nune;","Vi, kiu faris signojn kaj miraklojn en la lando Egipta ĝis la nuna tago super Izrael kaj super la aliaj homoj, kaj faris al Vi gloran nomon, kiel ĝi estas nune;"],[32,21,"kaj Vi elkondukis Vian popolon Izrael el la lando Egipta per signoj kaj per mirakloj, per forta mano, per etendita brako, kaj per granda teruro;","kaj Vi elkondukis Vian popolon Izrael el la lando Egipta per signoj kaj per mirakloj, per forta mano, per etendita brako, kaj per granda teruro;"],[32,22,"kaj Vi donis al ili ĉi tiun landon, pri kiu Vi ĵuris al iliaj patroj, ke Vi donos al ili, landon, en kiu fluas lakto kaj mielo;","kaj Vi donis al ili ĉi tiun landon, pri kiu Vi ĵuris al iliaj patroj, ke Vi donos al ili, landon, en kiu fluas lakto kaj mielo;"],[32,23,"kaj ili venis kaj ekposedis ĝin, tamen ili ne aŭskultis Vian voĉon kaj ne sekvis Vian instruon, ne faris ĉion, kion Vi ordonis al ili; kaj Vi venigis sur ilin ĉi tiun tutan malfeliĉon.","kaj ili venis kaj ekposedis ĝin, tamen ili ne aŭskultis Vian voĉon kaj ne sekvis Vian instruon, ne faris ĉion, kion Vi ordonis al ili; kaj Vi venigis sur ilin ĉi tiun tutan malfeliĉon."],[32,24,"Jen remparoj alproksimiĝas al la urbo, por venkopreni ĝin, kaj la urbo pro la glavo, malsato, kaj pesto estas transdonata en la manojn de la Ĥaldeoj, kiuj militas kontraŭ ĝi; kion Vi diris, tio fariĝas, kaj Vi tion vidas.","Jen remparoj alproksimiĝas al la urbo, por venkopreni ĝin, kaj la urbo pro la glavo, malsato, kaj pesto estas transdonata en la manojn de la Ĥaldeoj, kiuj militas kontraŭ ĝi; kion Vi diris, tio fariĝas, kaj Vi tion vidas."],[32,25,"Kaj Vi, Sinjoro, ho Eternulo, diris al mi: Aĉetu al vi la kampon pro mono, kaj starigu atestantojn; dume la urbo estas transdonata en la manojn de la Ĥaldeoj.","Kaj Vi, Sinjoro, ho Eternulo, diris al mi: Aĉetu al vi la kampon pro mono, kaj starigu atestantojn; dume la urbo estas transdonata en la manojn de la Ĥaldeoj."],[32,26,"Tiam la vorto de la Eternulo aperis al Jeremia, dirante:","Tiam la vorto de la Eternulo aperis al Jeremia, dirante:"],[32,27,"Jen Mi, la Eternulo, estas Dio de ĉiu karno; ĉu ekzistas por Mi io nefarebla?","Jen Mi, la Eternulo, estas Dio de ĉiu karno; ĉu ekzistas por Mi io nefarebla?"],[32,28,"Tial tiele diras la Eternulo: Jen Mi transdonas ĉi tiun urbon en la manojn de la Ĥaldeoj, kaj en la manon de Nebukadnecar, reĝo de Babel, kaj li venkoprenos ĝin.","Tial tiele diras la Eternulo: Jen Mi transdonas ĉi tiun urbon en la manojn de la Ĥaldeoj, kaj en la manon de Nebukadnecar, reĝo de Babel, kaj li venkoprenos ĝin."],[32,29,"Kaj venos la Ĥaldeoj, kiuj militas kontraŭ ĉi tiu urbo, kaj ekbruligos ĉi tiun urbon per fajro, kaj forbruligos ĝin, kaj la domojn, sur kies tegmentoj oni incensadis al Baal kaj faradis verŝoferojn al aliaj dioj, por kolerigi Min.","Kaj venos la Ĥaldeoj, kiuj militas kontraŭ ĉi tiu urbo, kaj ekbruligos ĉi tiun urbon per fajro, kaj forbruligos ĝin, kaj la domojn, sur kies tegmentoj oni incensadis al Baal kaj faradis verŝoferojn al aliaj dioj, por kolerigi Min."],[32,30,"Ĉar la Izraelidoj kaj la Judoj faradis nur malbonon antaŭ Miaj okuloj detempe de sia juneco; ĉar la Izraelidoj nur kolerigadis Min per la faroj de siaj manoj, diras la Eternulo.","Ĉar la Izraelidoj kaj la Judoj faradis nur malbonon antaŭ Miaj okuloj detempe de sia juneco; ĉar la Izraelidoj nur kolerigadis Min per la faroj de siaj manoj, diras la Eternulo."],[32,31,"Ĉar nur por Mia kolero kaj por Mia ĉagreno ekzistis ĉi tiu urbo de la tago, kiam oni konstruis ĝin, ĝis la nuna tago, tiel, ke Mi devas forpuŝi ĝin de antaŭ Mia vizaĝo,","Ĉar nur por Mia kolero kaj por Mia ĉagreno ekzistis ĉi tiu urbo de la tago, kiam oni konstruis ĝin, ĝis la nuna tago, tiel, ke Mi devas forpuŝi ĝin de antaŭ Mia vizaĝo,"],[32,32,"pro ĉiuj malbonaĵoj de la Izraelidoj kaj Jehudaidoj, kiujn ili faris, por Min kolerigi, ili, iliaj reĝoj, iliaj princoj, iliaj pastroj, iliaj profetoj, la Judoj, kaj la loĝantoj de Jerusalem.","pro ĉiuj malbonaĵoj de la Izraelidoj kaj Jehudaidoj, kiujn ili faris, por Min kolerigi, ili, iliaj reĝoj, iliaj princoj, iliaj pastroj, iliaj profetoj, la Judoj, kaj la loĝantoj de Jerusalem."],[32,33,"Ili turnis al Mi la dorson, ne la vizaĝon; Mi instruadis ilin, konstante instruadis, sed ili ne aŭskultis, ne akceptis admonon.","Ili turnis al Mi la dorson, ne la vizaĝon; Mi instruadis ilin, konstante instruadis, sed ili ne aŭskultis, ne akceptis admonon."],[32,34,"Siajn abomenindaĵojn ili metis en la domon, kiu estas nomata per Mia nomo, kaj ili malpurigis ĝin.","Siajn abomenindaĵojn ili metis en la domon, kiu estas nomata per Mia nomo, kaj ili malpurigis ĝin."],[32,35,"Kaj ili aranĝis la altaĵojn de Baal, kiuj estas en la valo de la filo de Hinom, por bruligi siajn filojn kaj filinojn al Moleĥ, kion Mi ne ordonis al ili, kaj pri kio ne venis al Mi en la kapon, ke ili faros tiun abomenindaĵon, por pekigi Judujon.","Kaj ili aranĝis la altaĵojn de Baal, kiuj estas en la valo de la filo de Hinom, por bruligi siajn filojn kaj filinojn al Moleĥ, kion Mi ne ordonis al ili, kaj pri kio ne venis al Mi en la kapon, ke ili faros tiun abomenindaĵon, por pekigi Judujon."],[32,36,"Kaj tamen tiele diras la Eternulo, Dio de Izrael, pri ĉi tiu urbo, pri kiu vi diras, ke ĝi estas transdonata en la manon de la reĝo de Babel per glavo, malsato, kaj pesto:","Kaj tamen tiele diras la Eternulo, Dio de Izrael, pri ĉi tiu urbo, pri kiu vi diras, ke ĝi estas transdonata en la manon de la reĝo de Babel per glavo, malsato, kaj pesto:"],[32,37,"Jen Mi kolektos ilin el ĉiuj landoj, kien Mi dispelis ilin en Mia kolero, en Mia furiozo, kaj en granda indigno; kaj Mi revenigos ilin sur ĉi tiun lokon kaj loĝigos ilin sendanĝere.","Jen Mi kolektos ilin el ĉiuj landoj, kien Mi dispelis ilin en Mia kolero, en Mia furiozo, kaj en granda indigno; kaj Mi revenigos ilin sur ĉi tiun lokon kaj loĝigos ilin sendanĝere."],[32,38,"Kaj ili estos Mia popolo, kaj Mi estos ilia Dio.","Kaj ili estos Mia popolo, kaj Mi estos ilia Dio."],[32,39,"Kaj Mi donos al ili unu koron kaj unu vojon, ke ili ĉiam timu Min, por ke estu bone al ili kaj al iliaj idoj post ili.","Kaj Mi donos al ili unu koron kaj unu vojon, ke ili ĉiam timu Min, por ke estu bone al ili kaj al iliaj idoj post ili."],[32,40,"Kaj Mi faros kun ili interligon eternan, ke Mi ne dekliniĝos de ili en Mia bonfarado al ili; kaj timon je Mi Mi metos en ilian koron, ke ili ne forturniĝu de Mi.","Kaj Mi faros kun ili interligon eternan, ke Mi ne dekliniĝos de ili en Mia bonfarado al ili; kaj timon je Mi Mi metos en ilian koron, ke ili ne forturniĝu de Mi."],[32,41,"Kaj Mi ĝojos pri ili, bonfarante al ili, kaj Mi plantos ilin en ĉi tiu lando fidele, per Mia tuta koro kaj per Mia tuta animo.","Kaj Mi ĝojos pri ili, bonfarante al ili, kaj Mi plantos ilin en ĉi tiu lando fidele, per Mia tuta koro kaj per Mia tuta animo."],[32,42,"Ĉar tiele diras la Eternulo: Kiel Mi venigis sur ĉi tiun popolon tiun tutan grandan malbonon, tiel Mi venigos sur ilin la tutan bonon, kiun Mi eldiris pri ili.","Ĉar tiele diras la Eternulo: Kiel Mi venigis sur ĉi tiun popolon tiun tutan grandan malbonon, tiel Mi venigos sur ilin la tutan bonon, kiun Mi eldiris pri ili."],[32,43,"Kaj kampoj estos aĉetataj en ĉi tiu lando, pri kiu vi diras, ke ĝi estas dezerta, ke ne troviĝas en ĝi homoj nek brutoj, ke ĝi estas transdonita en la manojn de la Ĥaldeoj.","Kaj kampoj estos aĉetataj en ĉi tiu lando, pri kiu vi diras, ke ĝi estas dezerta, ke ne troviĝas en ĝi homoj nek brutoj, ke ĝi estas transdonita en la manojn de la Ĥaldeoj."],[32,44,"Oni aĉetos kampojn per mono, oni enskribos en dokumentojn kaj sigelos, kaj starigos atestantojn, en la lando en Benjamen, en la ĉirkaŭaĵo de Jerusalem, en la urboj de Judujo, en la urboj de la montoj, en la urboj de la valoj, kaj en la urboj de la sudo; ĉar Mi revenigos ilin el la kaptiteco, diras la Eternulo.","Oni aĉetos kampojn per mono, oni enskribos en dokumentojn kaj sigelos, kaj starigos atestantojn, en la lando en Benjamen, en la ĉirkaŭaĵo de Jerusalem, en la urboj de Judujo, en la urboj de la montoj, en la urboj de la valoj, kaj en la urboj de la sudo; ĉar Mi revenigos ilin el la kaptiteco, diras la Eternulo."],[33,1,"La vorto de la Eternulo aperis al Jeremia duafoje, kiam li estis ankoraŭ tenata sur la korto de la malliberejo, nome:","La vorto de la Eternulo aperis al Jeremia duafoje, kiam li estis ankoraŭ tenata sur la korto de la malliberejo, nome:"],[33,2,"Tiele diras la Eternulo, kiu ĉion faris, la Eternulo, kiu ĉion kreis, por ĝin fortikigi, kaj kies nomo estas Eternulo:","Tiele diras la Eternulo, kiu ĉion faris, la Eternulo, kiu ĉion kreis, por ĝin fortikigi, kaj kies nomo estas Eternulo:"],[33,3,"Voku al Mi, kaj Mi respondos al vi, kaj Mi sciigos al vi grandajn kaj gravajn aferojn, kiujn vi ne scias.","Voku al Mi, kaj Mi respondos al vi, kaj Mi sciigos al vi grandajn kaj gravajn aferojn, kiujn vi ne scias."],[33,4,"Ĉar tiele diras la Eternulo, Dio de Izrael, pri la domoj de ĉi tiu urbo, kaj pri la domoj de la reĝoj de Judujo, kiuj estas detruitaj por remparoj kaj por glavoj","Ĉar tiele diras la Eternulo, Dio de Izrael, pri la domoj de ĉi tiu urbo, kaj pri la domoj de la reĝoj de Judujo, kiuj estas detruitaj por remparoj kaj por glavoj"],[33,5,"de tiuj, kiuj venis, por batali kontraŭ la Ĥaldeoj kaj plenigi ilin per kadavroj de homoj, kiujn Mi frapis en Mia kolero kaj en Mia indigno; ĉar Mi kaŝis Mian vizaĝon for de ĉi tiu urbo pro ĉiuj iliaj malbonagoj:","de tiuj, kiuj venis, por batali kontraŭ la Ĥaldeoj kaj plenigi ilin per kadavroj de homoj, kiujn Mi frapis en Mia kolero kaj en Mia indigno; ĉar Mi kaŝis Mian vizaĝon for de ĉi tiu urbo pro ĉiuj iliaj malbonagoj:"],[33,6,"Jen Mi redonos al ĝi bonstaton kaj kuracon, kaj Mi resanigos ilin, kaj Mi malkovros por ili abundon da paco kaj vero.","Jen Mi redonos al ĝi bonstaton kaj kuracon, kaj Mi resanigos ilin, kaj Mi malkovros por ili abundon da paco kaj vero."],[33,7,"Kaj Mi revenigos la kaptitojn de Jehuda kaj la kaptitojn de Izrael, kaj Mi aranĝos ilin kiel antaŭe.","Kaj Mi revenigos la kaptitojn de Jehuda kaj la kaptitojn de Izrael, kaj Mi aranĝos ilin kiel antaŭe."],[33,8,"Kaj Mi purigos ilin de ĉiuj iliaj malbonagoj, per kiuj ili pekis antaŭ Mi; kaj Mi pardonos ĉiujn iliajn krimojn, per kiuj ili pekis antaŭ Mi kaj defalis de Mi.","Kaj Mi purigos ilin de ĉiuj iliaj malbonagoj, per kiuj ili pekis antaŭ Mi; kaj Mi pardonos ĉiujn iliajn krimojn, per kiuj ili pekis antaŭ Mi kaj defalis de Mi."],[33,9,"Kaj tio fariĝos por Mi agrabla nomo, laŭdo kaj gloro antaŭ ĉiuj nacioj de la tero, kiuj aŭdos pri la tuta bono, kiun Mi faras al ili, kaj ili ektimos kaj ektremos pro la tuta bono kaj la tuta bonstato, kiun Mi donos al ĝi.","Kaj tio fariĝos por Mi agrabla nomo, laŭdo kaj gloro antaŭ ĉiuj nacioj de la tero, kiuj aŭdos pri la tuta bono, kiun Mi faras al ili, kaj ili ektimos kaj ektremos pro la tuta bono kaj la tuta bonstato, kiun Mi donos al ĝi."],[33,10,"Tiele diras la Eternulo: Sur ĉi tiu loko — pri kiu vi diras, ke ĝi estas dezertigita tiel, ke jam ne ekzistas homoj nek brutoj en la urboj de Judujo kaj sur la stratoj de Jerusalem, kiuj fariĝis malplenaj pro foresto de homoj kaj de loĝantoj kaj de brutoj —","Tiele diras la Eternulo: Sur ĉi tiu loko — pri kiu vi diras, ke ĝi estas dezertigita tiel, ke jam ne ekzistas homoj nek brutoj en la urboj de Judujo kaj sur la stratoj de Jerusalem, kiuj fariĝis malplenaj pro foresto de homoj kaj de loĝantoj kaj de brutoj —"],[33,11,"ankoraŭ estos aŭdataj sonoj de ĝojo kaj sonoj de gajeco, voĉo de fianĉo kaj voĉo de fianĉino, voĉo de homoj, kiuj parolos: Laŭdu la Eternulon Cebaot, ĉar la Eternulo estas bona, ĉar eterna estas Lia favorkoreco; kaj kiuj alportados dankoferojn en la domon de la Eternulo; ĉar Mi revenigos la forkaptitojn de la lando kiel antaŭe, diras la Eternulo.","ankoraŭ estos aŭdataj sonoj de ĝojo kaj sonoj de gajeco, voĉo de fianĉo kaj voĉo de fianĉino, voĉo de homoj, kiuj parolos: Laŭdu la Eternulon Cebaot, ĉar la Eternulo estas bona, ĉar eterna estas Lia favorkoreco; kaj kiuj alportados dankoferojn en la domon de la Eternulo; ĉar Mi revenigos la forkaptitojn de la lando kiel antaŭe, diras la Eternulo."],[33,12,"Tiele diras la Eternulo Cebaot: Sur ĉi tiu loko, kiu dezertiĝis tiel, ke tie ne troviĝas homo nek bruto, kaj en ĉiuj ĝiaj urboj denove troviĝos loĝejoj de paŝtistoj, kiuj ripozigos tie siajn ŝafojn;","Tiele diras la Eternulo Cebaot: Sur ĉi tiu loko, kiu dezertiĝis tiel, ke tie ne troviĝas homo nek bruto, kaj en ĉiuj ĝiaj urboj denove troviĝos loĝejoj de paŝtistoj, kiuj ripozigos tie siajn ŝafojn;"],[33,13,"en la urboj de la montoj, en la urboj de la valoj, en la urboj de la sudo, en la lando de Benjamen, en la ĉirkaŭaĵo de Jerusalem, kaj en la urboj de Judujo denove pasados ŝafoj sub la mano de kalkulanto, diras la Eternulo.","en la urboj de la montoj, en la urboj de la valoj, en la urboj de la sudo, en la lando de Benjamen, en la ĉirkaŭaĵo de Jerusalem, kaj en la urboj de Judujo denove pasados ŝafoj sub la mano de kalkulanto, diras la Eternulo."],[33,14,"Jen venos tempo, diras la Eternulo, kiam Mi plenumos la bonan vorton, kiun Mi diris pri la domo de Izrael kaj pri la domo de Jehuda.","Jen venos tempo, diras la Eternulo, kiam Mi plenumos la bonan vorton, kiun Mi diris pri la domo de Izrael kaj pri la domo de Jehuda."],[33,15,"En tiuj tagoj kaj en tiu tempo Mi elkreskigos al David markoton virtan, kiu faros juĝon kaj justecon sur la tero.","En tiuj tagoj kaj en tiu tempo Mi elkreskigos al David markoton virtan, kiu faros juĝon kaj justecon sur la tero."],[33,16,"En tiu tempo Judujo estos savita, kaj Jerusalem ekvivos sendanĝere, kaj oni nomos ĝin jene: La Eternulo estas nia justeco.","En tiu tempo Judujo estos savita, kaj Jerusalem ekvivos sendanĝere, kaj oni nomos ĝin jene: La Eternulo estas nia justeco."],[33,17,"Ĉar tiele diras la Eternulo: Ne mankos ĉe David viro, sidanta sur la trono de la domo de Izrael.","Ĉar tiele diras la Eternulo: Ne mankos ĉe David viro, sidanta sur la trono de la domo de Izrael."],[33,18,"Kaj ĉe la pastroj Levidoj neniam mankos antaŭ Mi viro, alportanta bruloferon kaj fumiganta farunoferon kaj faranta buĉoferon.","Kaj ĉe la pastroj Levidoj neniam mankos antaŭ Mi viro, alportanta bruloferon kaj fumiganta farunoferon kaj faranta buĉoferon."],[33,19,"Kaj aperis vorto de la Eternulo al Jeremia, dirante:","Kaj aperis vorto de la Eternulo al Jeremia, dirante:"],[33,20,"Tiele diras la Eternulo: Se oni povos ĉesigi Mian interligon pri la tago kaj Mian interligon pri la nokto, kaj la tago kaj nokto ne estu en sia tempo:","Tiele diras la Eternulo: Se oni povos ĉesigi Mian interligon pri la tago kaj Mian interligon pri la nokto, kaj la tago kaj nokto ne estu en sia tempo:"],[33,21,"tiam povos esti ĉesigita Mia interligo kun Mia servanto David, ke ne estu ĉe li filo, reĝanta sur lia trono, kaj kun la Levidoj pastroj, Miaj servistoj.","tiam povos esti ĉesigita Mia interligo kun Mia servanto David, ke ne estu ĉe li filo, reĝanta sur lia trono, kaj kun la Levidoj pastroj, Miaj servistoj."],[33,22,"Kiel nekalkulebla estas la armeo de la ĉielo kaj nemezurebla la sablo de la maro, tiel Mi multigos la idaron de Mia servanto David, kaj la Levidojn, kiuj faras servadon al Mi.","Kiel nekalkulebla estas la armeo de la ĉielo kaj nemezurebla la sablo de la maro, tiel Mi multigos la idaron de Mia servanto David, kaj la Levidojn, kiuj faras servadon al Mi."],[33,23,"Kaj aperis vorto de la Eternulo al Jeremia, dirante:","Kaj aperis vorto de la Eternulo al Jeremia, dirante:"],[33,24,"Ĉu vi ne vidas, kiel ĉi tiu popolo parolas kaj diras: La du gentojn, kiujn la Eternulo elektis, Li forpuŝis? Kaj ili malestimas Mian popolon, kvazaŭ ĝi jam ne estus popolo antaŭ ili.","Ĉu vi ne vidas, kiel ĉi tiu popolo parolas kaj diras: La du gentojn, kiujn la Eternulo elektis, Li forpuŝis? Kaj ili malestimas Mian popolon, kvazaŭ ĝi jam ne estus popolo antaŭ ili."],[33,25,"Tiele diras la Eternulo: Se Mi ne farus interligon pri tago kaj nokto kaj Miajn leĝojn pri la ĉielo kaj la tero,","Tiele diras la Eternulo: Se Mi ne farus interligon pri tago kaj nokto kaj Miajn leĝojn pri la ĉielo kaj la tero,"],[33,26,"tiam Mi forpuŝus la idaron de Jakob kaj de Mia servanto David, ne prenante el lia idaro regantojn super la idaro de Abraham, Isaak, kaj Jakob; ĉar Mi revenigos iliajn forkaptitojn kaj kompatos ilin.","tiam Mi forpuŝus la idaron de Jakob kaj de Mia servanto David, ne prenante el lia idaro regantojn super la idaro de Abraham, Isaak, kaj Jakob; ĉar Mi revenigos iliajn forkaptitojn kaj kompatos ilin."],[34,1,"Jen estas la vorto, kiu aperis al Jeremia de la Eternulo, kiam Nebukadnecar, reĝo de Babel, kaj lia tuta militistaro, kaj ĉiuj regnoj de la tero, kiuj estis sub la regado de lia mano, kaj ĉiuj popoloj militis kontraŭ Jerusalem kaj kontraŭ ĉiuj ĝiaj urboj:","Jen estas la vorto, kiu aperis al Jeremia de la Eternulo, kiam Nebukadnecar, reĝo de Babel, kaj lia tuta militistaro, kaj ĉiuj regnoj de la tero, kiuj estis sub la regado de lia mano, kaj ĉiuj popoloj militis kontraŭ Jerusalem kaj kontraŭ ĉiuj ĝiaj urboj:"],[34,2,"Tiele diras la Eternulo, Dio de Izrael: Iru kaj parolu al Cidkija, reĝo de Judujo, kaj diru al li: Tiele diras la Eternulo: Jen Mi transdonos ĉi tiun urbon en la manon de la reĝo de Babel, kaj li forbruligos ĝin per fajro;","Tiele diras la Eternulo, Dio de Izrael: Iru kaj parolu al Cidkija, reĝo de Judujo, kaj diru al li: Tiele diras la Eternulo: Jen Mi transdonos ĉi tiun urbon en la manon de la reĝo de Babel, kaj li forbruligos ĝin per fajro;"],[34,3,"kaj vi ne saviĝos el lia mano, sed vi estos kaptita kaj transdonita en lian manon, kaj viaj okuloj rigardos la okulojn de la reĝo de Babel, kaj lia buŝo parolos kun via buŝo, kaj vi iros en Babelon.","kaj vi ne saviĝos el lia mano, sed vi estos kaptita kaj transdonita en lian manon, kaj viaj okuloj rigardos la okulojn de la reĝo de Babel, kaj lia buŝo parolos kun via buŝo, kaj vi iros en Babelon."],[34,4,"Tamen aŭskultu la vorton de la Eternulo, ho Cidkija, reĝo de Judujo: Tiele diras la Eternulo pri vi: Vi ne mortos de glavo;","Tamen aŭskultu la vorton de la Eternulo, ho Cidkija, reĝo de Judujo: Tiele diras la Eternulo pri vi: Vi ne mortos de glavo;"],[34,5,"vi mortos en paco; kaj kiel oni faris brulon al viaj patroj, la antaŭaj reĝoj, kiuj estis antaŭ vi, tiel oni faros brulon al vi, kaj oni priploros vin: Ho ve, sinjoro! Ĉar Mi parolis la vorton, diras la Eternulo.","vi mortos en paco; kaj kiel oni faris brulon al viaj patroj, la antaŭaj reĝoj, kiuj estis antaŭ vi, tiel oni faros brulon al vi, kaj oni priploros vin: Ho ve, sinjoro! Ĉar Mi parolis la vorton, diras la Eternulo."],[34,6,"Kaj la profeto Jeremia raportis al Cidkija, reĝo de Judujo, ĉiujn tiujn vortojn en Jerusalem,","Kaj la profeto Jeremia raportis al Cidkija, reĝo de Judujo, ĉiujn tiujn vortojn en Jerusalem,"],[34,7,"dum la militistaro de la reĝo de Babel militis kontraŭ Jerusalem, kaj kontraŭ ĉiuj restintaj urboj de Judujo, kontraŭ Laĥiŝ kaj kontraŭ Azeka; ĉar ili restis ankoraŭ el la fortikaĵaj urboj de Judujo.","dum la militistaro de la reĝo de Babel militis kontraŭ Jerusalem, kaj kontraŭ ĉiuj restintaj urboj de Judujo, kontraŭ Laĥiŝ kaj kontraŭ Azeka; ĉar ili restis ankoraŭ el la fortikaĵaj urboj de Judujo."],[34,8,"Jen estas la vorto, kiu aperis al Jeremia de la Eternulo, post kiam la reĝo Cidkija faris interligon kun la tuta popolo de Jerusalem, proklamante al ili liberecon;","Jen estas la vorto, kiu aperis al Jeremia de la Eternulo, post kiam la reĝo Cidkija faris interligon kun la tuta popolo de Jerusalem, proklamante al ili liberecon;"],[34,9,"ke ĉiu forliberigu sian sklavon kaj sian sklavinon, Hebreon kaj Hebreinon, por ke inter ili neniu el la Judoj tenu sian fraton en sklaveco.","ke ĉiu forliberigu sian sklavon kaj sian sklavinon, Hebreon kaj Hebreinon, por ke inter ili neniu el la Judoj tenu sian fraton en sklaveco."],[34,10,"Kaj obeis ĉiuj potenculoj kaj la tuta popolo, kiuj aliĝis al la interligo, por ke ĉiu forliberigu sian sklavon kaj sian sklavinon, por ne plu teni ilin en sklaveco; ili obeis kaj forliberigis.","Kaj obeis ĉiuj potenculoj kaj la tuta popolo, kiuj aliĝis al la interligo, por ke ĉiu forliberigu sian sklavon kaj sian sklavinon, por ne plu teni ilin en sklaveco; ili obeis kaj forliberigis."],[34,11,"Sed poste ili denove reprenis la sklavojn kaj la sklavinojn, kiujn ili forliberigis, kaj devigis ilin fariĝi sklavoj kaj sklavinoj.","Sed poste ili denove reprenis la sklavojn kaj la sklavinojn, kiujn ili forliberigis, kaj devigis ilin fariĝi sklavoj kaj sklavinoj."],[34,12,"Tiam aperis la vorto de la Eternulo al Jeremia, dirante:","Tiam aperis la vorto de la Eternulo al Jeremia, dirante:"],[34,13,"Tiele diras la Eternulo, Dio de Izrael: Mi faris interligon kun viaj patroj en la tempo, kiam Mi elkondukis ilin el la lando Egipta, el la domo de sklaveco, dirante:","Tiele diras la Eternulo, Dio de Izrael: Mi faris interligon kun viaj patroj en la tempo, kiam Mi elkondukis ilin el la lando Egipta, el la domo de sklaveco, dirante:"],[34,14,"En ĉiu sepa jaro forliberigu ĉiu sian fraton Hebreon, kiu estas vendita al vi kaj servis al vi ses jarojn, kaj permesu al li foriri de vi tute libera; sed viaj patroj ne aŭskultis Min kaj ne alklinis sian orelon.","En ĉiu sepa jaro forliberigu ĉiu sian fraton Hebreon, kiu estas vendita al vi kaj servis al vi ses jarojn, kaj permesu al li foriri de vi tute libera; sed viaj patroj ne aŭskultis Min kaj ne alklinis sian orelon."],[34,15,"Nun vi pentis, kaj faris bonon antaŭ Miaj okuloj, proklamante liberecon unu por la alia, kaj vi faris interligon antaŭ Mi en la domo, kiu estas nomata per Mia nomo;","Nun vi pentis, kaj faris bonon antaŭ Miaj okuloj, proklamante liberecon unu por la alia, kaj vi faris interligon antaŭ Mi en la domo, kiu estas nomata per Mia nomo;"],[34,16,"sed vi ŝanĝiĝis, kaj malsanktigis Mian nomon, kaj reprenis al vi ĉiu sian sklavon kaj sian sklavinon, kiujn vi forliberigis, ke ili estu memstaraj, kaj vi devigis ilin, ke ili estu por vi sklavoj kaj sklavinoj.","sed vi ŝanĝiĝis, kaj malsanktigis Mian nomon, kaj reprenis al vi ĉiu sian sklavon kaj sian sklavinon, kiujn vi forliberigis, ke ili estu memstaraj, kaj vi devigis ilin, ke ili estu por vi sklavoj kaj sklavinoj."],[34,17,"Tial tiele diras la Eternulo: Vi ne obeis Min, ke vi proklamu liberecon ĉiu al sia frato kaj unu al la alia; jen Mi proklamas koncerne vin liberecon al la glavo, pesto, kaj malsato, kaj Mi faros vin objekto de teruro por ĉiuj regnoj de la tero.","Tial tiele diras la Eternulo: Vi ne obeis Min, ke vi proklamu liberecon ĉiu al sia frato kaj unu al la alia; jen Mi proklamas koncerne vin liberecon al la glavo, pesto, kaj malsato, kaj Mi faros vin objekto de teruro por ĉiuj regnoj de la tero."],[34,18,"Kaj Mi transdonos la homojn, kiuj malobeis Mian interligon, kiuj ne plenumis la vortojn de la interligo, kiun ili faris antaŭ Mi, kiam ili dishakis la bovidon en du partojn kaj trairis tra la dishakitaj partoj:","Kaj Mi transdonos la homojn, kiuj malobeis Mian interligon, kiuj ne plenumis la vortojn de la interligo, kiun ili faris antaŭ Mi, kiam ili dishakis la bovidon en du partojn kaj trairis tra la dishakitaj partoj:"],[34,19,"la eminentulojn de Judujo kaj la eminentulojn de Jerusalem, la korteganojn kaj la pastrojn, kaj la tutan popolon de la lando, kiuj trairis tra la dishakitaj partoj de la bovido;","la eminentulojn de Judujo kaj la eminentulojn de Jerusalem, la korteganojn kaj la pastrojn, kaj la tutan popolon de la lando, kiuj trairis tra la dishakitaj partoj de la bovido;"],[34,20,"Mi transdonos ilin en la manojn de iliaj malamikoj, kaj en la manojn de tiuj, kiuj celas ilian morton; kaj iliaj kadavroj estos manĝaĵo por la birdoj de la ĉielo kaj por la bestoj de la tero.","Mi transdonos ilin en la manojn de iliaj malamikoj, kaj en la manojn de tiuj, kiuj celas ilian morton; kaj iliaj kadavroj estos manĝaĵo por la birdoj de la ĉielo kaj por la bestoj de la tero."],[34,21,"Kaj Cidkijan, reĝon de Judujo, kaj liajn eminentulojn Mi transdonos en la manojn de iliaj malamikoj, kaj en la manojn de tiuj, kiuj celas ilian morton, kaj en la manojn de la militistaro de la reĝo de Babel, kiu foriris de vi.","Kaj Cidkijan, reĝon de Judujo, kaj liajn eminentulojn Mi transdonos en la manojn de iliaj malamikoj, kaj en la manojn de tiuj, kiuj celas ilian morton, kaj en la manojn de la militistaro de la reĝo de Babel, kiu foriris de vi."],[34,22,"Jen Mi faros ordonon, diras la Eternulo, kaj Mi revenigos ilin al ĉi tiu urbo, kaj ili atakos ĝin kaj venkoprenos ĝin kaj forbruligos ĝin per fajro, kaj la urbojn de Judujo Mi faros dezerto tiel, ke neniu en ĝi loĝos.","Jen Mi faros ordonon, diras la Eternulo, kaj Mi revenigos ilin al ĉi tiu urbo, kaj ili atakos ĝin kaj venkoprenos ĝin kaj forbruligos ĝin per fajro, kaj la urbojn de Judujo Mi faros dezerto tiel, ke neniu en ĝi loĝos."],[35,1,"Jen estas la vorto, kiu aperis al Jeremia de la Eternulo en la tempo de Jehojakim, filo de Joŝija, reĝo de Judujo:","Jen estas la vorto, kiu aperis al Jeremia de la Eternulo en la tempo de Jehojakim, filo de Joŝija, reĝo de Judujo:"],[35,2,"Iru en la domon de la Reĥabidoj, kaj parolu al ili, kaj venigu ilin en la domon de la Eternulo en unu el la ĉambroj, kaj trinkigu al ili vinon.","Iru en la domon de la Reĥabidoj, kaj parolu al ili, kaj venigu ilin en la domon de la Eternulo en unu el la ĉambroj, kaj trinkigu al ili vinon."],[35,3,"Kaj mi prenis Jaazanjan, filon de Jeremia, filo de Ĥabacinja, kaj liajn fratojn kaj ĉiujn liajn filojn kaj la tutan domon de la Reĥabidoj;","Kaj mi prenis Jaazanjan, filon de Jeremia, filo de Ĥabacinja, kaj liajn fratojn kaj ĉiujn liajn filojn kaj la tutan domon de la Reĥabidoj;"],[35,4,"kaj mi venigis ilin en la domon de la Eternulo, en la ĉambron de la filoj de Ĥanan, filo de Jigdalja, homo de Dio, kiu estas apud la ĉambro de la princoj, super la ĉambro de Maaseja, filo de Ŝalum, gardisto de pordego.","kaj mi venigis ilin en la domon de la Eternulo, en la ĉambron de la filoj de Ĥanan, filo de Jigdalja, homo de Dio, kiu estas apud la ĉambro de la princoj, super la ĉambro de Maaseja, filo de Ŝalum, gardisto de pordego."],[35,5,"Kaj mi starigis antaŭ la filoj de la domo de la Reĥabidoj pokalojn plenajn de vino, kaj kalikojn, kaj mi diris al ili: Trinku vinon.","Kaj mi starigis antaŭ la filoj de la domo de la Reĥabidoj pokalojn plenajn de vino, kaj kalikojn, kaj mi diris al ili: Trinku vinon."],[35,6,"Sed ili diris: Ni ne trinkas vinon, ĉar nia patro Jonadab, filo de Reĥab, ordonis al ni, dirante: Ne trinku vinon, vi kaj viaj infanoj, eterne;","Sed ili diris: Ni ne trinkas vinon, ĉar nia patro Jonadab, filo de Reĥab, ordonis al ni, dirante: Ne trinku vinon, vi kaj viaj infanoj, eterne;"],[35,7,"kaj domon ne konstruu, kaj semon ne semu, kaj vinberĝardenon ne plantu kaj ne posedu, sed loĝu en tendoj dum via tuta vivo, por ke vi vivu longan tempon sur la tero, sur kiu vi loĝas fremdule.","kaj domon ne konstruu, kaj semon ne semu, kaj vinberĝardenon ne plantu kaj ne posedu, sed loĝu en tendoj dum via tuta vivo, por ke vi vivu longan tempon sur la tero, sur kiu vi loĝas fremdule."],[35,8,"Kaj ni obeis la voĉon de nia patro Jonadab, filo de Reĥab, en ĉio, kion li ordonis al ni, ne trinkante vinon dum nia tuta vivo, nek ni, nek niaj edzinoj, nek niaj filoj, nek niaj filinoj,","Kaj ni obeis la voĉon de nia patro Jonadab, filo de Reĥab, en ĉio, kion li ordonis al ni, ne trinkante vinon dum nia tuta vivo, nek ni, nek niaj edzinoj, nek niaj filoj, nek niaj filinoj,"],[35,9,"kaj ne konstruante domojn por nia loĝado, kaj ne havante por ni vinberĝardenon, nek kampon, nek semadon;","kaj ne konstruante domojn por nia loĝado, kaj ne havante por ni vinberĝardenon, nek kampon, nek semadon;"],[35,10,"sed ni loĝas en tendoj, kaj obeas, kaj faras ĉion tiel, kiel ordonis al ni nia patro Jonadab.","sed ni loĝas en tendoj, kaj obeas, kaj faras ĉion tiel, kiel ordonis al ni nia patro Jonadab."],[35,11,"Kaj kiam Nebukadnecar, reĝo de Babel, venis kontraŭ la landon, ni diris: Venu, ni iru en Jerusalemon, for de la militistaro de la Ĥaldeoj kaj de la militistaro de Sirio; kaj ni restis en Jerusalem.","Kaj kiam Nebukadnecar, reĝo de Babel, venis kontraŭ la landon, ni diris: Venu, ni iru en Jerusalemon, for de la militistaro de la Ĥaldeoj kaj de la militistaro de Sirio; kaj ni restis en Jerusalem."],[35,12,"Kaj aperis vorto de la Eternulo al Jeremia, dirante:","Kaj aperis vorto de la Eternulo al Jeremia, dirante:"],[35,13,"Tiele diras la Eternulo Cebaot, Dio de Izrael: Iru kaj diru al la Judujanoj kaj al la loĝantoj de Jerusalem: Ĉu vi ne akceptos moralinstruon, obeante Miajn vortojn? diras la Eternulo.","Tiele diras la Eternulo Cebaot, Dio de Izrael: Iru kaj diru al la Judujanoj kaj al la loĝantoj de Jerusalem: Ĉu vi ne akceptos moralinstruon, obeante Miajn vortojn? diras la Eternulo."],[35,14,"Plenumataj estas la vortoj de Jonadab, filo de Reĥab, kiujn li ordonis al siaj filoj, ke ili ne trinku vinon, kaj ili ne trinkas ĝis nun, ĉar ili obeas la ordonon de sia patro; sed Mi diris al vi, konstante diradis, kaj vi ne obeis Min.","Plenumataj estas la vortoj de Jonadab, filo de Reĥab, kiujn li ordonis al siaj filoj, ke ili ne trinku vinon, kaj ili ne trinkas ĝis nun, ĉar ili obeas la ordonon de sia patro; sed Mi diris al vi, konstante diradis, kaj vi ne obeis Min."],[35,15,"Mi sendis al vi ĉiujn Miajn servantojn, la profetojn, Mi konstante sendadis, dirante: Deturnu vin ĉiu de sia malbona vojo, plibonigu vian konduton, ne sekvu aliajn diojn, servante al ili, tiam vi restos sur la tero, kiun Mi donis al vi kaj al viaj patroj; sed vi ne alklinis vian orelon kaj ne obeis Min.","Mi sendis al vi ĉiujn Miajn servantojn, la profetojn, Mi konstante sendadis, dirante: Deturnu vin ĉiu de sia malbona vojo, plibonigu vian konduton, ne sekvu aliajn diojn, servante al ili, tiam vi restos sur la tero, kiun Mi donis al vi kaj al viaj patroj; sed vi ne alklinis vian orelon kaj ne obeis Min."],[35,16,"La filoj de Jonadab, filo de Reĥab, plenumis la ordonon de sia patro, kiun li donis al ili; sed ĉi tiu popolo ne obeis Min.","La filoj de Jonadab, filo de Reĥab, plenumis la ordonon de sia patro, kiun li donis al ili; sed ĉi tiu popolo ne obeis Min."],[35,17,"Tial tiele diras la Eternulo, Dio Cebaot, Dio de Izrael: Jen Mi venigos sur Judujon kaj sur ĉiujn loĝantojn de Jerusalem la tutan malbonon, kiun Mi eldiris pri ili, pro tio, ke Mi parolis al ili kaj ili ne aŭskultis, Mi vokis al ili kaj ili ne respondis.","Tial tiele diras la Eternulo, Dio Cebaot, Dio de Izrael: Jen Mi venigos sur Judujon kaj sur ĉiujn loĝantojn de Jerusalem la tutan malbonon, kiun Mi eldiris pri ili, pro tio, ke Mi parolis al ili kaj ili ne aŭskultis, Mi vokis al ili kaj ili ne respondis."],[35,18,"Sed al la domo de la Reĥabidoj Jeremia diris: Tiele diras la Eternulo Cebaot, Dio de Izrael: Pro tio, ke vi obeis la ordonon de via patro Jonadab kaj observis ĉiujn liajn ordonojn, kaj agis konforme al ĉio, kion li rekomendis al vi,","Sed al la domo de la Reĥabidoj Jeremia diris: Tiele diras la Eternulo Cebaot, Dio de Izrael: Pro tio, ke vi obeis la ordonon de via patro Jonadab kaj observis ĉiujn liajn ordonojn, kaj agis konforme al ĉio, kion li rekomendis al vi,"],[35,19,"pro tio tiele diras la Eternulo Cebaot, Dio de Izrael: Neniam mankos ĉe Jonadab, filo de Reĥab, viro, staranta antaŭ Mi.","pro tio tiele diras la Eternulo Cebaot, Dio de Izrael: Neniam mankos ĉe Jonadab, filo de Reĥab, viro, staranta antaŭ Mi."],[36,1,"En la kvara jaro de Jehojakim, filo de Joŝija, reĝo de Judujo, aperis jena vorto al Jeremia de la Eternulo:","En la kvara jaro de Jehojakim, filo de Joŝija, reĝo de Judujo, aperis jena vorto al Jeremia de la Eternulo:"],[36,2,"Prenu al vi libron-rulaĵon, kaj skribu en ĝin ĉiujn vortojn, kiujn Mi diris al vi pri Izrael kaj pri Jehuda kaj pri ĉiuj nacioj, de la tago, en kiu Mi parolis al vi, de la tempo de Joŝija ĝis la nuna tago.","Prenu al vi libron-rulaĵon, kaj skribu en ĝin ĉiujn vortojn, kiujn Mi diris al vi pri Izrael kaj pri Jehuda kaj pri ĉiuj nacioj, de la tago, en kiu Mi parolis al vi, de la tempo de Joŝija ĝis la nuna tago."],[36,3,"Eble la domo de Jehuda aŭdos pri la tuta malbono, kiun Mi intencas fari al ili, kaj ili returniĝos ĉiu de sia malbona vojo, por ke Mi pardonu ilian malbonagon kaj ilian pekon.","Eble la domo de Jehuda aŭdos pri la tuta malbono, kiun Mi intencas fari al ili, kaj ili returniĝos ĉiu de sia malbona vojo, por ke Mi pardonu ilian malbonagon kaj ilian pekon."],[36,4,"Kaj Jeremia alvokis Baruĥon, filon de Nerija; kaj Baruĥ enskribis en libron-rulaĵon sub diktado de Jeremia ĉiujn vortojn de la Eternulo, kiujn Li diris al li.","Kaj Jeremia alvokis Baruĥon, filon de Nerija; kaj Baruĥ enskribis en libron-rulaĵon sub diktado de Jeremia ĉiujn vortojn de la Eternulo, kiujn Li diris al li."],[36,5,"Kaj Jeremia donis jenan ordonon al Baruĥ: Mi estas malliberigita, mi ne povas iri en la domon de la Eternulo;","Kaj Jeremia donis jenan ordonon al Baruĥ: Mi estas malliberigita, mi ne povas iri en la domon de la Eternulo;"],[36,6,"iru do vi, kaj legu laŭ la libro, kiun vi skribis sub mia diktado, la vortojn de la Eternulo en la orelojn de la popolo en la domo de la Eternulo en tago de fasto; kaj ankaŭ en la orelojn de ĉiuj Judoj, kiuj venis el siaj urboj, legu tion.","iru do vi, kaj legu laŭ la libro, kiun vi skribis sub mia diktado, la vortojn de la Eternulo en la orelojn de la popolo en la domo de la Eternulo en tago de fasto; kaj ankaŭ en la orelojn de ĉiuj Judoj, kiuj venis el siaj urboj, legu tion."],[36,7,"Eble falos ilia preĝo antaŭ la Eternulo, kaj ili returniĝos ĉiu de sia malbona vojo; ĉar granda estas la kolero kaj indigno, kiujn la Eternulo esprimis pri ĉi tiu popolo.","Eble falos ilia preĝo antaŭ la Eternulo, kaj ili returniĝos ĉiu de sia malbona vojo; ĉar granda estas la kolero kaj indigno, kiujn la Eternulo esprimis pri ĉi tiu popolo."],[36,8,"Kaj Baruĥ, filo de Nerija, plenumis ĉion, kion ordonis la profeto Jeremia, kaj li voĉlegis el la libro la vortojn de la Eternulo en la domo de la Eternulo.","Kaj Baruĥ, filo de Nerija, plenumis ĉion, kion ordonis la profeto Jeremia, kaj li voĉlegis el la libro la vortojn de la Eternulo en la domo de la Eternulo."],[36,9,"En la kvina jaro de Jehojakim, filo de Joŝija, reĝo de Judujo, en la naŭa monato, oni proklamis faston antaŭ la Eternulo al la tuta popolo en Jerusalem, kaj al la tuta popolo, kiu venis el la urboj de Judujo en Jerusalemon.","En la kvina jaro de Jehojakim, filo de Joŝija, reĝo de Judujo, en la naŭa monato, oni proklamis faston antaŭ la Eternulo al la tuta popolo en Jerusalem, kaj al la tuta popolo, kiu venis el la urboj de Judujo en Jerusalemon."],[36,10,"Kaj Baruĥ voĉlegis el la libro la vortojn de Jeremia en la domo de la Eternulo, en la ĉambro de Gemarja, filo de la kanceliero Ŝafan, sur la supra korto, ĉe la nova pordego de la domo de la Eternulo, laŭte al la tuta popolo.","Kaj Baruĥ voĉlegis el la libro la vortojn de Jeremia en la domo de la Eternulo, en la ĉambro de Gemarja, filo de la kanceliero Ŝafan, sur la supra korto, ĉe la nova pordego de la domo de la Eternulo, laŭte al la tuta popolo."],[36,11,"Kaj Miĥaja, filo de Gemarja, filo de Ŝafan, aŭdis el la libro ĉiujn vortojn de la Eternulo;","Kaj Miĥaja, filo de Gemarja, filo de Ŝafan, aŭdis el la libro ĉiujn vortojn de la Eternulo;"],[36,12,"kaj li iris en la domon de la reĝo, en la ĉambron de la kanceliero. Kaj jen tie sidis ĉiuj eminentuloj: la kanceliero Eliŝama, Delaja, filo de Ŝemaja, Elnatan, filo de Aĥbor, Gemarja, filo de Ŝafan, Cidkija, filo de Ĥananja, kaj ĉiuj eminentuloj.","kaj li iris en la domon de la reĝo, en la ĉambron de la kanceliero. Kaj jen tie sidis ĉiuj eminentuloj: la kanceliero Eliŝama, Delaja, filo de Ŝemaja, Elnatan, filo de Aĥbor, Gemarja, filo de Ŝafan, Cidkija, filo de Ĥananja, kaj ĉiuj eminentuloj."],[36,13,"Kaj Miĥaja raportis al ili ĉiujn vortojn, kiujn li aŭdis, kiam Baruĥ legis el la libro en la orelojn de la popolo.","Kaj Miĥaja raportis al ili ĉiujn vortojn, kiujn li aŭdis, kiam Baruĥ legis el la libro en la orelojn de la popolo."],[36,14,"Tiam ĉiuj eminentuloj sendis al Baruĥ Jehudin, filon de Netanja, filo de Ŝelemja, filo de Kuŝi, por diri: La skribrulaĵon, el kiu vi legis en la orelojn de la popolo, prenu en vian manon, kaj venu. Kaj Baruĥ, filo de Nerija, prenis kun si la skribrulaĵon, kaj venis al ili.","Tiam ĉiuj eminentuloj sendis al Baruĥ Jehudin, filon de Netanja, filo de Ŝelemja, filo de Kuŝi, por diri: La skribrulaĵon, el kiu vi legis en la orelojn de la popolo, prenu en vian manon, kaj venu. Kaj Baruĥ, filo de Nerija, prenis kun si la skribrulaĵon, kaj venis al ili."],[36,15,"Kaj ili diris al li: Sidiĝu, kaj voĉlegu ĝin al ni. Kaj Baruĥ voĉlegis al ili.","Kaj ili diris al li: Sidiĝu, kaj voĉlegu ĝin al ni. Kaj Baruĥ voĉlegis al ili."],[36,16,"Kiam ili aŭdis ĉiujn vortojn, ili eksentis teruron unu antaŭ la alia, kaj ili diris al Baruĥ: Ni raportos al la reĝo ĉiujn ĉi tiujn vortojn.","Kiam ili aŭdis ĉiujn vortojn, ili eksentis teruron unu antaŭ la alia, kaj ili diris al Baruĥ: Ni raportos al la reĝo ĉiujn ĉi tiujn vortojn."],[36,17,"Kaj ili demandis Baruĥon, dirante: Diru al ni, kiamaniere vi skribis ĉiujn tiujn vortojn el lia buŝo?","Kaj ili demandis Baruĥon, dirante: Diru al ni, kiamaniere vi skribis ĉiujn tiujn vortojn el lia buŝo?"],[36,18,"Kaj Baruĥ respondis al ili: El sia buŝo li elparolis al mi ĉiujn tiujn vortojn, kaj mi skribis en la libron per inko.","Kaj Baruĥ respondis al ili: El sia buŝo li elparolis al mi ĉiujn tiujn vortojn, kaj mi skribis en la libron per inko."],[36,19,"Kaj la eminentuloj diris al Baruĥ: Iru kaj kaŝiĝu, vi kaj Jeremia, ke neniu sciu, kie vi estas.","Kaj la eminentuloj diris al Baruĥ: Iru kaj kaŝiĝu, vi kaj Jeremia, ke neniu sciu, kie vi estas."],[36,20,"Ili venis al la reĝo en la palacon, kaj la skribrulaĵon ili restigis en la ĉambro de la kanceliero Eliŝama; kaj ili raportis al la reĝo ĉiujn vortojn.","Ili venis al la reĝo en la palacon, kaj la skribrulaĵon ili restigis en la ĉambro de la kanceliero Eliŝama; kaj ili raportis al la reĝo ĉiujn vortojn."],[36,21,"Tiam la reĝo sendis Jehudin, por preni la skribrulaĵon; kaj Jehudi prenis ĝin el la ĉambro de la kanceliero Eliŝama, kaj voĉlegis ĝin al la reĝo, kaj al ĉiuj eminentuloj, kiuj staris apud la reĝo.","Tiam la reĝo sendis Jehudin, por preni la skribrulaĵon; kaj Jehudi prenis ĝin el la ĉambro de la kanceliero Eliŝama, kaj voĉlegis ĝin al la reĝo, kaj al ĉiuj eminentuloj, kiuj staris apud la reĝo."],[36,22,"La reĝo sidis en la vintra domo en la naŭa monato, kaj antaŭ li brulis fajrujo.","La reĝo sidis en la vintra domo en la naŭa monato, kaj antaŭ li brulis fajrujo."],[36,23,"Kaj ĉiufoje, kiam Jehudi tralegis tri aŭ kvar kolumnojn, la reĝo detranĉis ilin per tranĉileto de skribisto, kaj ĵetis en la fajron, kiu estis en la fajrujo, ĝis la tuta skribrulaĵo forbrulis sur la fajro, kiu estis en la fajrujo.","Kaj ĉiufoje, kiam Jehudi tralegis tri aŭ kvar kolumnojn, la reĝo detranĉis ilin per tranĉileto de skribisto, kaj ĵetis en la fajron, kiu estis en la fajrujo, ĝis la tuta skribrulaĵo forbrulis sur la fajro, kiu estis en la fajrujo."],[36,24,"Kaj ne timis kaj ne disŝiris siajn vestojn la reĝo, nek ĉiuj liaj servantoj, kiuj aŭdis ĉiujn tiujn vortojn.","Kaj ne timis kaj ne disŝiris siajn vestojn la reĝo, nek ĉiuj liaj servantoj, kiuj aŭdis ĉiujn tiujn vortojn."],[36,25,"Kvankam Elnatan kaj Delaja kaj Gemarja petis la reĝon, ke li ne forbruligu la skribrulaĵon, li ne obeis ilin.","Kvankam Elnatan kaj Delaja kaj Gemarja petis la reĝon, ke li ne forbruligu la skribrulaĵon, li ne obeis ilin."],[36,26,"Kaj la reĝo ordonis al Jeraĥmeel, filo de la reĝo, al Seraja, filo de Azriel, kaj al Ŝelemja, filo de Abdeel, kapti la skribiston Baruĥ kaj la profeton Jeremia; sed la Eternulo ilin kaŝis.","Kaj la reĝo ordonis al Jeraĥmeel, filo de la reĝo, al Seraja, filo de Azriel, kaj al Ŝelemja, filo de Abdeel, kapti la skribiston Baruĥ kaj la profeton Jeremia; sed la Eternulo ilin kaŝis."],[36,27,"Kaj aperis jena vorto de la Eternulo al Jeremia, post kiam la reĝo forbruligis la skribrulaĵon, kaj la vortojn, kiujn Baruĥ skribis sub diktado de Jeremia:","Kaj aperis jena vorto de la Eternulo al Jeremia, post kiam la reĝo forbruligis la skribrulaĵon, kaj la vortojn, kiujn Baruĥ skribis sub diktado de Jeremia:"],[36,28,"Prenu al vi denove alian skribrulaĵon, kaj skribu sur ĝi ĉiujn antaŭajn vortojn, kiuj estis sur la unua skribrulaĵo, kiun forbruligis Jehojakim, reĝo de Judujo.","Prenu al vi denove alian skribrulaĵon, kaj skribu sur ĝi ĉiujn antaŭajn vortojn, kiuj estis sur la unua skribrulaĵo, kiun forbruligis Jehojakim, reĝo de Judujo."],[36,29,"Kaj pri Jehojakim, reĝo de Judujo, diru: Tiele diras la Eternulo: Vi forbruligis tiun skribrulaĵon, dirante: Kial vi skribis sur ĝi, ke venos la reĝo de Babel kaj ruinigos ĉi tiun landon kaj ekstermos sur ĝi homojn kaj brutojn?","Kaj pri Jehojakim, reĝo de Judujo, diru: Tiele diras la Eternulo: Vi forbruligis tiun skribrulaĵon, dirante: Kial vi skribis sur ĝi, ke venos la reĝo de Babel kaj ruinigos ĉi tiun landon kaj ekstermos sur ĝi homojn kaj brutojn?"],[36,30,"Tial tiele diras la Eternulo pri Jehojakim, reĝo de Judujo: Ne estos ĉe li sidanto sur la trono de David, kaj lia kadavro estos ĵetita al la varmego de la tago kaj al la malvarmo de la nokto;","Tial tiele diras la Eternulo pri Jehojakim, reĝo de Judujo: Ne estos ĉe li sidanto sur la trono de David, kaj lia kadavro estos ĵetita al la varmego de la tago kaj al la malvarmo de la nokto;"],[36,31,"kaj Mi punos lin kaj lian idaron kaj liajn servantojn, pro ilia malbonago; kaj Mi venigos sur ilin kaj sur la loĝantojn de Jerusalem kaj sur la Judujanojn la tutan malbonon, pri kiu Mi diris al ili, sed ili ne aŭskultis.","kaj Mi punos lin kaj lian idaron kaj liajn servantojn, pro ilia malbonago; kaj Mi venigos sur ilin kaj sur la loĝantojn de Jerusalem kaj sur la Judujanojn la tutan malbonon, pri kiu Mi diris al ili, sed ili ne aŭskultis."],[36,32,"Kaj Jeremia prenis alian skribrulaĵon, kaj donis ĝin al la skribisto Baruĥ, filo de Nerija; kaj tiu skribis sur ĝi sub diktado de Jeremia ĉiujn vortojn de la libro, kiun Jehojakim, reĝo de Judujo, forbruligis per fajro; kaj al ili estis aldonitaj ankoraŭ multaj similaj vortoj.","Kaj Jeremia prenis alian skribrulaĵon, kaj donis ĝin al la skribisto Baruĥ, filo de Nerija; kaj tiu skribis sur ĝi sub diktado de Jeremia ĉiujn vortojn de la libro, kiun Jehojakim, reĝo de Judujo, forbruligis per fajro; kaj al ili estis aldonitaj ankoraŭ multaj similaj vortoj."],[37,1,"Kaj ekreĝis la reĝo Cidkija, filo de Joŝija, anstataŭ Konja, filo de Jehojakim, ĉar Nebukadnecar, reĝo de Babel, faris lin reĝo en la Juda lando.","Kaj ekreĝis la reĝo Cidkija, filo de Joŝija, anstataŭ Konja, filo de Jehojakim, ĉar Nebukadnecar, reĝo de Babel, faris lin reĝo en la Juda lando."],[37,2,"Li kaj liaj servantoj kaj la popolo de la lando ne obeis la vortojn de la Eternulo, kiujn Li diris per la profeto Jeremia.","Li kaj liaj servantoj kaj la popolo de la lando ne obeis la vortojn de la Eternulo, kiujn Li diris per la profeto Jeremia."],[37,3,"Tamen la reĝo Cidkija sendis Jehuĥalon, filon de Ŝelemja, kaj Cefanjan, filon de la pastro Maaseja, al la profeto Jeremia, por diri: Preĝu, mi petas, por ni al la Eternulo, nia Dio.","Tamen la reĝo Cidkija sendis Jehuĥalon, filon de Ŝelemja, kaj Cefanjan, filon de la pastro Maaseja, al la profeto Jeremia, por diri: Preĝu, mi petas, por ni al la Eternulo, nia Dio."],[37,4,"Jeremia tiam iradis libere inter la popolo, kaj oni ne metis lin en malliberejon.","Jeremia tiam iradis libere inter la popolo, kaj oni ne metis lin en malliberejon."],[37,5,"Dume la militistaro de Faraono eliris el Egiptujo, kaj kiam la Ĥaldeoj, kiuj sieĝis Jerusalemon, tion aŭdis, ili foriris de Jerusalem.","Dume la militistaro de Faraono eliris el Egiptujo, kaj kiam la Ĥaldeoj, kiuj sieĝis Jerusalemon, tion aŭdis, ili foriris de Jerusalem."],[37,6,"Kaj aperis vorto de la Eternulo al la profeto Jeremia, dirante:","Kaj aperis vorto de la Eternulo al la profeto Jeremia, dirante:"],[37,7,"Tiele diras la Eternulo, Dio de Izrael: Tiele diru al la reĝo de Judujo, kiu sendis vin al Mi, por demandi Min: Jen la militistaro de Faraono, kiu eliris kun helpo al vi, iros returne en sian landon Egiptujo.","Tiele diras la Eternulo, Dio de Izrael: Tiele diru al la reĝo de Judujo, kiu sendis vin al Mi, por demandi Min: Jen la militistaro de Faraono, kiu eliris kun helpo al vi, iros returne en sian landon Egiptujo."],[37,8,"Kaj la Ĥaldeoj revenos kaj militos kontraŭ ĉi tiu urbo, kaj prenos ĝin kaj forbruligos ĝin per fajro.","Kaj la Ĥaldeoj revenos kaj militos kontraŭ ĉi tiu urbo, kaj prenos ĝin kaj forbruligos ĝin per fajro."],[37,9,"Tiele diras la Eternulo: Ne trompu vin mem, dirante: La Ĥaldeoj foriros de ni; ĉar ili ne foriros.","Tiele diras la Eternulo: Ne trompu vin mem, dirante: La Ĥaldeoj foriros de ni; ĉar ili ne foriros."],[37,10,"Ĉar se vi eĉ venkobatus la tutan militistaron de la Ĥaldeoj, kiu militas kontraŭ vi, kaj restus el ili nur kelkaj vunditoj, ĉi tiuj leviĝus ĉiu el sia tendo kaj forbruligus ĉi tiun urbon per fajro.","Ĉar se vi eĉ venkobatus la tutan militistaron de la Ĥaldeoj, kiu militas kontraŭ vi, kaj restus el ili nur kelkaj vunditoj, ĉi tiuj leviĝus ĉiu el sia tendo kaj forbruligus ĉi tiun urbon per fajro."],[37,11,"Kiam la militistaro de la Ĥaldeoj, timante la militistaron de Faraono, foriris de Jerusalem,","Kiam la militistaro de la Ĥaldeoj, timante la militistaron de Faraono, foriris de Jerusalem,"],[37,12,"tiam Jeremia eliris el Jerusalem, por iri en la landon de Benjamen, por ricevi sian tiean heredaĵon inter la popolo.","tiam Jeremia eliris el Jerusalem, por iri en la landon de Benjamen, por ricevi sian tiean heredaĵon inter la popolo."],[37,13,"Sed kiam li estis ĉe la Pordego de Benjamen, tie estis la gardistestro, kies nomo estis Jirija, filo de Ŝelemja, filo de Ĥananja; li kaptis la profeton Jeremia, dirante: Vi volas transkuri al la Ĥaldeoj.","Sed kiam li estis ĉe la Pordego de Benjamen, tie estis la gardistestro, kies nomo estis Jirija, filo de Ŝelemja, filo de Ĥananja; li kaptis la profeton Jeremia, dirante: Vi volas transkuri al la Ĥaldeoj."],[37,14,"Jeremia diris: Tio estas malvero, mi ne volas transkuri al la Ĥaldeoj. Sed tiu ne aŭskultis lin; kaj Jirija kaptis Jeremian kaj alkondukis lin al la eminentuloj.","Jeremia diris: Tio estas malvero, mi ne volas transkuri al la Ĥaldeoj. Sed tiu ne aŭskultis lin; kaj Jirija kaptis Jeremian kaj alkondukis lin al la eminentuloj."],[37,15,"La eminentuloj ekkoleris kontraŭ Jeremia, kaj batis lin, kaj metis lin en malliberejon, en la domo de la skribisto Jonatan, ĉar tiun domon oni faris malliberejo.","La eminentuloj ekkoleris kontraŭ Jeremia, kaj batis lin, kaj metis lin en malliberejon, en la domo de la skribisto Jonatan, ĉar tiun domon oni faris malliberejo."],[37,16,"Post kiam Jeremia venis en la malliberejon kaj en karceron, kaj Jeremia estis sidinta tie longan tempon,","Post kiam Jeremia venis en la malliberejon kaj en karceron, kaj Jeremia estis sidinta tie longan tempon,"],[37,17,"la reĝo Cidkija sendis kaj prenis lin, kaj la reĝo sekrete en sia domo demandis lin, dirante: Ĉu estas ia vorto de la Eternulo? Kaj Jeremia diris: Estas: vi estos transdonita en la manon de la reĝo de Babel.","la reĝo Cidkija sendis kaj prenis lin, kaj la reĝo sekrete en sia domo demandis lin, dirante: Ĉu estas ia vorto de la Eternulo? Kaj Jeremia diris: Estas: vi estos transdonita en la manon de la reĝo de Babel."],[37,18,"Kaj Jeremia diris al la reĝo Cidkija: Per kio mi pekis antaŭ vi aŭ antaŭ viaj servantoj aŭ antaŭ ĉi tiu popolo, ke vi metis min en malliberejon?","Kaj Jeremia diris al la reĝo Cidkija: Per kio mi pekis antaŭ vi aŭ antaŭ viaj servantoj aŭ antaŭ ĉi tiu popolo, ke vi metis min en malliberejon?"],[37,19,"Kaj kie estas viaj profetoj, kiuj profetis al vi, ke la reĝo de Babel ne venos kontraŭ vin kaj kontraŭ ĉi tiun landon?","Kaj kie estas viaj profetoj, kiuj profetis al vi, ke la reĝo de Babel ne venos kontraŭ vin kaj kontraŭ ĉi tiun landon?"],[37,20,"Nun aŭskultu, mia sinjoro, ho reĝo, mia petego falu antaŭ vi: ne revenigu min en la domon de la skribisto Jonatan, mi ne mortu tie.","Nun aŭskultu, mia sinjoro, ho reĝo, mia petego falu antaŭ vi: ne revenigu min en la domon de la skribisto Jonatan, mi ne mortu tie."],[37,21,"Tiam la reĝo Cidkija ordonis, ke oni tenu Jeremian sur la korto de la malliberejo; kaj oni donadis al li bulon da pano ĉiutage el la strato de la bakistoj, ĝis konsumiĝis la tuta pano en la urbo. Tiamaniere Jeremia restis sur la korto de la malliberejo.","Tiam la reĝo Cidkija ordonis, ke oni tenu Jeremian sur la korto de la malliberejo; kaj oni donadis al li bulon da pano ĉiutage el la strato de la bakistoj, ĝis konsumiĝis la tuta pano en la urbo. Tiamaniere Jeremia restis sur la korto de la malliberejo."],[38,1,"Ŝefatja, filo de Matan, Gedalja, filo de Paŝĥur, Juĥal, filo de Ŝelemja, kaj Paŝĥur, filo de Malkija, aŭdis la vortojn, kiujn Jeremia parolis al la tuta popolo, dirante:","Ŝefatja, filo de Matan, Gedalja, filo de Paŝĥur, Juĥal, filo de Ŝelemja, kaj Paŝĥur, filo de Malkija, aŭdis la vortojn, kiujn Jeremia parolis al la tuta popolo, dirante:"],[38,2,"Tiele diras la Eternulo: Kiu restos en ĉi tiu urbo, tiu mortos de glavo, de malsato, aŭ de pesto; sed kiu eliros al la Ĥaldeoj, tiu restos vivanta, lia animo estos lia akiro, kaj li vivos.","Tiele diras la Eternulo: Kiu restos en ĉi tiu urbo, tiu mortos de glavo, de malsato, aŭ de pesto; sed kiu eliros al la Ĥaldeoj, tiu restos vivanta, lia animo estos lia akiro, kaj li vivos."],[38,3,"Tiele diras la Eternulo: Ĉi tiu urbo estos transdonita en la manojn de la militistaro de la reĝo de Babel, kaj li venkoprenos ĝin.","Tiele diras la Eternulo: Ĉi tiu urbo estos transdonita en la manojn de la militistaro de la reĝo de Babel, kaj li venkoprenos ĝin."],[38,4,"Tiam la eminentuloj diris al la reĝo: Oni devas mortigi ĉi tiun homon, ĉar li senfortigas la manojn de la militistoj, kiuj restis en ĉi tiu urbo, kaj la manojn de la tuta popolo, parolante al ili tiajn vortojn; ĉar ĉi tiu homo deziras al ĉi tiu popolo ne pacon, sed nur malbonon.","Tiam la eminentuloj diris al la reĝo: Oni devas mortigi ĉi tiun homon, ĉar li senfortigas la manojn de la militistoj, kiuj restis en ĉi tiu urbo, kaj la manojn de la tuta popolo, parolante al ili tiajn vortojn; ĉar ĉi tiu homo deziras al ĉi tiu popolo ne pacon, sed nur malbonon."],[38,5,"Kaj la reĝo Cidkija diris: Jen li estas en viaj manoj, ĉar la reĝo nenion povas fari kontraŭ via volo.","Kaj la reĝo Cidkija diris: Jen li estas en viaj manoj, ĉar la reĝo nenion povas fari kontraŭ via volo."],[38,6,"Tiam ili prenis Jeremian, kaj ĵetis lin en la kavon de Malkija, filo de la reĝo, kiu troviĝis sur la korto de la malliberejo, kaj oni mallevis Jeremian per ŝnuroj; en la kavo ne estis akvo, sed nur ŝlimo, kaj Jeremia eniĝis en la ŝlimon.","Tiam ili prenis Jeremian, kaj ĵetis lin en la kavon de Malkija, filo de la reĝo, kiu troviĝis sur la korto de la malliberejo, kaj oni mallevis Jeremian per ŝnuroj; en la kavo ne estis akvo, sed nur ŝlimo, kaj Jeremia eniĝis en la ŝlimon."],[38,7,"Kaj Ebed-Meleĥ, Etiopo, eŭnuko, kiu estis en la domo de la reĝo, aŭdis, ke oni ĵetis Jeremian en la kavon; la reĝo tiam sidis ĉe la Pordejo de Benjamen.","Kaj Ebed-Meleĥ, Etiopo, eŭnuko, kiu estis en la domo de la reĝo, aŭdis, ke oni ĵetis Jeremian en la kavon; la reĝo tiam sidis ĉe la Pordejo de Benjamen."],[38,8,"Tiam Ebed-Meleĥ eliris el la domo de la reĝo, kaj ekparolis al la reĝo, dirante:","Tiam Ebed-Meleĥ eliris el la domo de la reĝo, kaj ekparolis al la reĝo, dirante:"],[38,9,"Mia sinjoro, ho reĝo! malbone agis tiuj homoj, ke ili tion faris al la profeto Jeremia, ke ili ĵetis lin en la kavon: li mortos tie de malsato, ĉar jam en ekzistas pano en la urbo.","Mia sinjoro, ho reĝo! malbone agis tiuj homoj, ke ili tion faris al la profeto Jeremia, ke ili ĵetis lin en la kavon: li mortos tie de malsato, ĉar jam en ekzistas pano en la urbo."],[38,10,"Tiam la reĝo ordonis al la Etiopo Ebed-Meleĥ, dirante: Prenu kun vi de ĉi tie tridek homojn, kaj eltiru la profeton Jeremia el la kavo, antaŭ ol li mortos.","Tiam la reĝo ordonis al la Etiopo Ebed-Meleĥ, dirante: Prenu kun vi de ĉi tie tridek homojn, kaj eltiru la profeton Jeremia el la kavo, antaŭ ol li mortos."],[38,11,"Kaj Ebed-Meleĥ prenis kun si la homojn kaj iris en la domon de la reĝo sub la trezorejon, kaj prenis de tie malnovajn kaj eluzitajn ĉifonojn kaj mallevis ilin per ŝnuroj al Jeremia en la kavon.","Kaj Ebed-Meleĥ prenis kun si la homojn kaj iris en la domon de la reĝo sub la trezorejon, kaj prenis de tie malnovajn kaj eluzitajn ĉifonojn kaj mallevis ilin per ŝnuroj al Jeremia en la kavon."],[38,12,"Kaj la Etiopo Ebed-Meleĥ diris al Jeremia: Metu la eluzitajn ĉifonojn sub viajn akselojn sub la ŝnurojn; kaj Jeremia tiel faris.","Kaj la Etiopo Ebed-Meleĥ diris al Jeremia: Metu la eluzitajn ĉifonojn sub viajn akselojn sub la ŝnurojn; kaj Jeremia tiel faris."],[38,13,"Kaj oni ektiris Jeremian per la ŝnuroj kaj eltiris lin el la kavo; kaj Jeremia restis sur la korto de la malliberejo.","Kaj oni ektiris Jeremian per la ŝnuroj kaj eltiris lin el la kavo; kaj Jeremia restis sur la korto de la malliberejo."],[38,14,"Kaj la reĝo Cidkija sendis, kaj venigis la profeton Jeremia al si, al la tria enirejo de la domo de la Eternulo; kaj la reĝo diris al Jeremia: Mi demandos de vi ion, kaŝu antaŭ mi nenion.","Kaj la reĝo Cidkija sendis, kaj venigis la profeton Jeremia al si, al la tria enirejo de la domo de la Eternulo; kaj la reĝo diris al Jeremia: Mi demandos de vi ion, kaŝu antaŭ mi nenion."],[38,15,"Kaj Jeremia diris al Cidkija: Se mi diros al vi, vi ja mortigos min; kaj se mi donos al vi konsilon, vi ja ne obeos min.","Kaj Jeremia diris al Cidkija: Se mi diros al vi, vi ja mortigos min; kaj se mi donos al vi konsilon, vi ja ne obeos min."],[38,16,"Tiam la reĝo Cidkija sekrete ĵuris al Jeremia, dirante: Mi ĵuras per la Eternulo, kiu kreis al ni ĉi tiun animon, ke mi ne mortigos vin, kaj ne transdonos vin en la manojn de tiuj homoj, kiuj celas vian morton.","Tiam la reĝo Cidkija sekrete ĵuris al Jeremia, dirante: Mi ĵuras per la Eternulo, kiu kreis al ni ĉi tiun animon, ke mi ne mortigos vin, kaj ne transdonos vin en la manojn de tiuj homoj, kiuj celas vian morton."],[38,17,"Kaj Jeremia diris al Cidkija: Tiele diras la Eternulo, Dio Cebaot, Dio de Izrael: Se vi eliros al la eminentuloj de la reĝo de Babel, via animo restos vivanta, kaj ĉi tiu urbo ne estos forbruligita per fajro, kaj vi kaj via domo vivos;","Kaj Jeremia diris al Cidkija: Tiele diras la Eternulo, Dio Cebaot, Dio de Izrael: Se vi eliros al la eminentuloj de la reĝo de Babel, via animo restos vivanta, kaj ĉi tiu urbo ne estos forbruligita per fajro, kaj vi kaj via domo vivos;"],[38,18,"sed se vi ne eliros al la eminentuloj de la reĝo de Babel, tiam ĉi tiu urbo estos transdonita en la manojn de la Ĥaldeoj, kaj ili forbruligos ĝin per fajro, kaj vi ne saviĝos el iliaj manoj.","sed se vi ne eliros al la eminentuloj de la reĝo de Babel, tiam ĉi tiu urbo estos transdonita en la manojn de la Ĥaldeoj, kaj ili forbruligos ĝin per fajro, kaj vi ne saviĝos el iliaj manoj."],[38,19,"Kaj la reĝo Cidkija diris al Jeremia: Mi timas la Judojn, kiuj transkuris al la Ĥaldeoj, ke oni ne transdonu min en iliajn manojn, por ke ili mokturmentu min.","Kaj la reĝo Cidkija diris al Jeremia: Mi timas la Judojn, kiuj transkuris al la Ĥaldeoj, ke oni ne transdonu min en iliajn manojn, por ke ili mokturmentu min."],[38,20,"Tiam Jeremia diris: Oni ne transdonos vin; aŭskultu la voĉon de la Eternulo pri tio, kion mi diras al vi; tiam estos bone al vi, kaj via animo restos vivanta.","Tiam Jeremia diris: Oni ne transdonos vin; aŭskultu la voĉon de la Eternulo pri tio, kion mi diras al vi; tiam estos bone al vi, kaj via animo restos vivanta."],[38,21,"Sed se vi ne volos eliri, en tia okazo jen estas tio, kion la Eternulo vidigis al mi:","Sed se vi ne volos eliri, en tia okazo jen estas tio, kion la Eternulo vidigis al mi:"],[38,22,"Jen ĉiuj virinoj, kiuj restis en la domo de la reĝo de Judujo, estos elkondukitaj al la eminentuloj de la reĝo de Babel, kaj ili diros: Viaj konsolantoj forlogis vin kaj superfortis vin; viaj piedoj enprofundiĝis en koton, kaj tiuj foriĝis de vi.","Jen ĉiuj virinoj, kiuj restis en la domo de la reĝo de Judujo, estos elkondukitaj al la eminentuloj de la reĝo de Babel, kaj ili diros: Viaj konsolantoj forlogis vin kaj superfortis vin; viaj piedoj enprofundiĝis en koton, kaj tiuj foriĝis de vi."],[38,23,"Kaj ĉiujn viajn edzinojn kaj viajn filojn oni forkondukos al la Ĥaldeoj, kaj vi ne saviĝos el iliaj manoj; vi estos kaptita en la manojn de la reĝo de Babel, kaj ĉi tiu urbo estos forbruligita per fajro.","Kaj ĉiujn viajn edzinojn kaj viajn filojn oni forkondukos al la Ĥaldeoj, kaj vi ne saviĝos el iliaj manoj; vi estos kaptita en la manojn de la reĝo de Babel, kaj ĉi tiu urbo estos forbruligita per fajro."],[38,24,"Kaj Cidkija diris al Jeremia: Neniu devas scii tiujn vortojn, alie vi mortos.","Kaj Cidkija diris al Jeremia: Neniu devas scii tiujn vortojn, alie vi mortos."],[38,25,"Se la eminentuloj aŭdos, ke mi parolis kun vi, kaj ili venos al vi, kaj diros al vi: Sciigu al ni, kion vi diris al la reĝo, ne kaŝu antaŭ ni, por ke ni ne mortigu vin, kaj kion la reĝo diris al vi:","Se la eminentuloj aŭdos, ke mi parolis kun vi, kaj ili venos al vi, kaj diros al vi: Sciigu al ni, kion vi diris al la reĝo, ne kaŝu antaŭ ni, por ke ni ne mortigu vin, kaj kion la reĝo diris al vi:"],[38,26,"tiam respondu al ili: Mi humile petegis la reĝon, ke li ne revenigu min en la domon de Jonatan, mi ne mortu tie.","tiam respondu al ili: Mi humile petegis la reĝon, ke li ne revenigu min en la domon de Jonatan, mi ne mortu tie."],[38,27,"Kaj venis ĉiuj eminentuloj al Jeremia kaj demandis lin, kaj li respondis al ili konforme al ĉiuj vortoj, kiujn ordonis la reĝo; kaj ili silente foriris de li, ĉar ili nenion eksciis.","Kaj venis ĉiuj eminentuloj al Jeremia kaj demandis lin, kaj li respondis al ili konforme al ĉiuj vortoj, kiujn ordonis la reĝo; kaj ili silente foriris de li, ĉar ili nenion eksciis."],[38,28,"Kaj Jeremia restis sur la korto de la malliberejo ĝis la tago, en kiu Jerusalem estis venkoprenita; kaj li tie estis, kiam Jerusalem estis venkoprenita.","Kaj Jeremia restis sur la korto de la malliberejo ĝis la tago, en kiu Jerusalem estis venkoprenita; kaj li tie estis, kiam Jerusalem estis venkoprenita."],[39,1,"En la naŭa jaro de Cidkija, reĝo de Judujo, en la deka monato, venis Nebukadnecar, reĝo de Babel, kun sia tuta militistaro al Jerusalem, kaj eksieĝis ĝin.","En la naŭa jaro de Cidkija, reĝo de Judujo, en la deka monato, venis Nebukadnecar, reĝo de Babel, kun sia tuta militistaro al Jerusalem, kaj eksieĝis ĝin."],[39,2,"En la dek-unua jaro de Cidkija, en la kvara monato, en la naŭa tago de la monato, oni faris enrompon en la urbon.","En la dek-unua jaro de Cidkija, en la kvara monato, en la naŭa tago de la monato, oni faris enrompon en la urbon."],[39,3,"Kaj eniris ĉiuj eminentuloj de la reĝo de Babel, kaj haltis ĉe la Meza Pordego: Nergal-Ŝarecer, Samgar-Nebu, Sarseĥim Rab-saris, Nergal-Ŝarecer Rab-mag, kaj ĉiuj ceteraj eminentuloj de la reĝo de Babel.","Kaj eniris ĉiuj eminentuloj de la reĝo de Babel, kaj haltis ĉe la Meza Pordego: Nergal-Ŝarecer, Samgar-Nebu, Sarseĥim Rab-saris, Nergal-Ŝarecer Rab-mag, kaj ĉiuj ceteraj eminentuloj de la reĝo de Babel."],[39,4,"Kiam ilin ekvidis Cidkija, reĝo de Judujo, kaj ĉiuj militistoj, ili forkuris, kaj eliris en la nokto el la urbo tra la ĝardeno de la reĝo, tra la pordego inter la du muregoj, kaj ili iris sur la vojon, kiu kondukas al la stepo.","Kiam ilin ekvidis Cidkija, reĝo de Judujo, kaj ĉiuj militistoj, ili forkuris, kaj eliris en la nokto el la urbo tra la ĝardeno de la reĝo, tra la pordego inter la du muregoj, kaj ili iris sur la vojon, kiu kondukas al la stepo."],[39,5,"Sed la Ĥaldea militistaro postkuris ilin, kaj atingis Cidkijan sur la stepo de Jeriĥo kaj kaptis lin, kaj alkondukis lin al Nebukadnecar, reĝo de Babel, en Riblan, en la lando Ĥamat, kaj ĉi tiu eldiris verdikton kontraŭ li.","Sed la Ĥaldea militistaro postkuris ilin, kaj atingis Cidkijan sur la stepo de Jeriĥo kaj kaptis lin, kaj alkondukis lin al Nebukadnecar, reĝo de Babel, en Riblan, en la lando Ĥamat, kaj ĉi tiu eldiris verdikton kontraŭ li."],[39,6,"Kaj la reĝo de Babel buĉis la filojn de Cidkija en Ribla antaŭ liaj okuloj, kaj ĉiujn eminentulojn de Judujo la reĝo de Babel buĉis.","Kaj la reĝo de Babel buĉis la filojn de Cidkija en Ribla antaŭ liaj okuloj, kaj ĉiujn eminentulojn de Judujo la reĝo de Babel buĉis."],[39,7,"Kaj la okulojn de Cidkija li blindigis, kaj li ligis lin per katenoj, por forkonduki lin en Babelon.","Kaj la okulojn de Cidkija li blindigis, kaj li ligis lin per katenoj, por forkonduki lin en Babelon."],[39,8,"Kaj la domon de la reĝo kaj la domojn de la popolo la Ĥaldeoj forbruligis per fajro, kaj la muregojn de Jerusalem ili detruis.","Kaj la domon de la reĝo kaj la domojn de la popolo la Ĥaldeoj forbruligis per fajro, kaj la muregojn de Jerusalem ili detruis."],[39,9,"Kaj la ceteran popolon, kiu restis en la urbo, kaj la transkurintojn, kiuj transkuris al li, kaj la tutan reston de la popolo Nebuzaradan, estro de la korpogardistoj, forkondukis en Babelon.","Kaj la ceteran popolon, kiu restis en la urbo, kaj la transkurintojn, kiuj transkuris al li, kaj la tutan reston de la popolo Nebuzaradan, estro de la korpogardistoj, forkondukis en Babelon."],[39,10,"Sed la malriĉulojn el la popolo, kiuj nenion havis, Nebuzaradan, estro de la korpogardistoj, restigis en la lando Juda kaj donis al ili tiam vinberĝardenojn kaj kampojn.","Sed la malriĉulojn el la popolo, kiuj nenion havis, Nebuzaradan, estro de la korpogardistoj, restigis en la lando Juda kaj donis al ili tiam vinberĝardenojn kaj kampojn."],[39,11,"Sed pri Jeremia Nebukadnecar, reĝo de Babel, ordonis al Nebuzaradan, la estro de la korpogardistoj, jene:","Sed pri Jeremia Nebukadnecar, reĝo de Babel, ordonis al Nebuzaradan, la estro de la korpogardistoj, jene:"],[39,12,"Prenu lin, kaj atentu pri li, kaj faru al li nenion malbonan, sed agu kun li nur tiel, kiel li diros al vi.","Prenu lin, kaj atentu pri li, kaj faru al li nenion malbonan, sed agu kun li nur tiel, kiel li diros al vi."],[39,13,"Kaj sendis Nebuzaradan, estro de la korpogardistoj, kaj Nebuŝazban Rab-saris, kaj Nergal-Ŝarecar Rab-mag, kaj ĉiuj estroj de la reĝo de Babel;","Kaj sendis Nebuzaradan, estro de la korpogardistoj, kaj Nebuŝazban Rab-saris, kaj Nergal-Ŝarecar Rab-mag, kaj ĉiuj estroj de la reĝo de Babel;"],[39,14,"ili sendis, kaj prenis Jeremian el la korto de la malliberejo, kaj transdonis lin al Gedalja, filo de Aĥikam, filo de Ŝafan, ke li konduku lin en sian domon; kaj li ekvivis inter la popolo.","ili sendis, kaj prenis Jeremian el la korto de la malliberejo, kaj transdonis lin al Gedalja, filo de Aĥikam, filo de Ŝafan, ke li konduku lin en sian domon; kaj li ekvivis inter la popolo."],[39,15,"Kaj al Jeremia aperis jena vorto de la Eternulo, kiam li estis ankoraŭ tenata sur la korto de la malliberejo:","Kaj al Jeremia aperis jena vorto de la Eternulo, kiam li estis ankoraŭ tenata sur la korto de la malliberejo:"],[39,16,"Iru kaj diru al la Etiopo Ebed-Meleĥ jene: Tiele diras la Eternulo Cebaot, Dio de Izrael: Jen Mi plenumos Miajn vortojn pri ĉi tiu urbo al malbono, ne al bono, kaj ili plenumiĝos antaŭ via vizaĝo en tiu tempo.","Iru kaj diru al la Etiopo Ebed-Meleĥ jene: Tiele diras la Eternulo Cebaot, Dio de Izrael: Jen Mi plenumos Miajn vortojn pri ĉi tiu urbo al malbono, ne al bono, kaj ili plenumiĝos antaŭ via vizaĝo en tiu tempo."],[39,17,"Sed vin Mi savos en tiu tempo, diras la Eternulo, kaj vi ne estos transdonita en la manojn de tiuj homoj, kiujn vi timas.","Sed vin Mi savos en tiu tempo, diras la Eternulo, kaj vi ne estos transdonita en la manojn de tiuj homoj, kiujn vi timas."],[39,18,"Ĉar Mi forsavos vin, kaj vi ne falos de glavo, kaj via animo estos via akiro; ĉar vi fidis Min, diras la Eternulo.","Ĉar Mi forsavos vin, kaj vi ne falos de glavo, kaj via animo estos via akiro; ĉar vi fidis Min, diras la Eternulo."],[40,1,"Jen estas la vorto, kiu aperis al Jeremia de la Eternulo, post kiam Nebuzaradan, estro de la korpogardistoj, forliberigis lin el Rama, kiam li prenis lin, ligitan per ĉenoj, inter ĉiuj kaptitoj de Jerusalem kaj Judujo, forkondukataj en Babelon.","Jen estas la vorto, kiu aperis al Jeremia de la Eternulo, post kiam Nebuzaradan, estro de la korpogardistoj, forliberigis lin el Rama, kiam li prenis lin, ligitan per ĉenoj, inter ĉiuj kaptitoj de Jerusalem kaj Judujo, forkondukataj en Babelon."],[40,2,"Kaj la estro de la korpogardistoj prenis Jeremian, kaj diris al li: La Eternulo, via Dio, eldiris ĉi tiun malfeliĉon kontraŭ ĉi tiu loko;","Kaj la estro de la korpogardistoj prenis Jeremian, kaj diris al li: La Eternulo, via Dio, eldiris ĉi tiun malfeliĉon kontraŭ ĉi tiu loko;"],[40,3,"kaj la Eternulo tion venigis, kaj faris, kiel Li diris, ĉar vi pekis antaŭ la Eternulo kaj ne aŭskultis Lian voĉon; pro tio fariĝis al vi tia afero.","kaj la Eternulo tion venigis, kaj faris, kiel Li diris, ĉar vi pekis antaŭ la Eternulo kaj ne aŭskultis Lian voĉon; pro tio fariĝis al vi tia afero."],[40,4,"Kaj nun jen hodiaŭ mi liberigis vin de la katenoj, kiuj estis sur viaj manoj; se plaĉas al vi iri kun mi en Babelon, iru, kaj mi zorgos pri vi; se ne plaĉas al vi iri kun mi en Babelon, ne faru tion; vidu, la tuta lando estas antaŭ vi; kien plaĉas al vi iri, tien iru.","Kaj nun jen hodiaŭ mi liberigis vin de la katenoj, kiuj estis sur viaj manoj; se plaĉas al vi iri kun mi en Babelon, iru, kaj mi zorgos pri vi; se ne plaĉas al vi iri kun mi en Babelon, ne faru tion; vidu, la tuta lando estas antaŭ vi; kien plaĉas al vi iri, tien iru."],[40,5,"(Dum li ankoraŭ ne foriris,) Iru al Gedalja, filo de Aĥikam, filo de Ŝafan, kiun la reĝo de Babel starigis kiel estron super la urboj de Judujo, kaj restu kun li inter la popolo; aŭ kien plaĉas al vi iri, tien iru. Kaj la estro de la korpogardistoj donis al li manĝaĵon kaj donacon kaj forliberigis lin.","(Dum li ankoraŭ ne foriris,) Iru al Gedalja, filo de Aĥikam, filo de Ŝafan, kiun la reĝo de Babel starigis kiel estron super la urboj de Judujo, kaj restu kun li inter la popolo; aŭ kien plaĉas al vi iri, tien iru. Kaj la estro de la korpogardistoj donis al li manĝaĵon kaj donacon kaj forliberigis lin."],[40,6,"Kaj Jeremia venis al Gedalja, filo de Aĥikam, en Micpan, kaj ekloĝis kun li inter la popolo, kiu restis en la lando.","Kaj Jeremia venis al Gedalja, filo de Aĥikam, en Micpan, kaj ekloĝis kun li inter la popolo, kiu restis en la lando."],[40,7,"Kiam ĉiuj militestroj, kiuj estis sur la kampo, ili kaj iliaj homoj, aŭdis, ke la reĝo de Babel starigis Gedaljan, filon de Aĥikam, kiel estron de la lando, kaj ke li metis sub lian regadon la virojn, virinojn, infanojn, kaj malriĉulojn de la lando, kiuj ne estis transloĝigitaj en Babelon,","Kiam ĉiuj militestroj, kiuj estis sur la kampo, ili kaj iliaj homoj, aŭdis, ke la reĝo de Babel starigis Gedaljan, filon de Aĥikam, kiel estron de la lando, kaj ke li metis sub lian regadon la virojn, virinojn, infanojn, kaj malriĉulojn de la lando, kiuj ne estis transloĝigitaj en Babelon,"],[40,8,"tiam ili venis al Gedalja en Micpan: Iŝmael, filo de Netanja, Joĥanan kaj Jonatan, filoj de Kareaĥ, Seraja, filo de Tanĥumet, la filoj de Efaj, Netofaano, kaj Jezanja, filo de Maaĥatano, ili kaj iliaj homoj.","tiam ili venis al Gedalja en Micpan: Iŝmael, filo de Netanja, Joĥanan kaj Jonatan, filoj de Kareaĥ, Seraja, filo de Tanĥumet, la filoj de Efaj, Netofaano, kaj Jezanja, filo de Maaĥatano, ili kaj iliaj homoj."],[40,9,"Kaj Gedalja, filo de Aĥikam, filo de Ŝafan, ĵuris al ili kaj al iliaj homoj, dirante: Ne timu servi al la Ĥaldeoj, restu en la lando kaj servu al la reĝo de Babel, kaj tiam estos al vi bone.","Kaj Gedalja, filo de Aĥikam, filo de Ŝafan, ĵuris al ili kaj al iliaj homoj, dirante: Ne timu servi al la Ĥaldeoj, restu en la lando kaj servu al la reĝo de Babel, kaj tiam estos al vi bone."],[40,10,"Mi restas en Micpa, por ke mi povu stariĝi antaŭ la vizaĝo de la Ĥaldeoj, kiuj venos al ni; sed vi enkolektu vinon kaj somerajn fruktojn kaj oleon kaj metu en viajn vazojn, kaj restu en viaj urboj, kiujn vi okupis.","Mi restas en Micpa, por ke mi povu stariĝi antaŭ la vizaĝo de la Ĥaldeoj, kiuj venos al ni; sed vi enkolektu vinon kaj somerajn fruktojn kaj oleon kaj metu en viajn vazojn, kaj restu en viaj urboj, kiujn vi okupis."],[40,11,"Ankaŭ ĉiuj Judoj, kiuj estis ĉe la Moabidoj, ĉe la Amonidoj, ĉe la Edomidoj, kaj en ĉiuj landoj, aŭdis, ke la reĝo de Babel restigis parton de la Judoj, kaj ke li starigis kiel reganton super ili Gedaljan, filon de Aĥikam, filo de Ŝafan.","Ankaŭ ĉiuj Judoj, kiuj estis ĉe la Moabidoj, ĉe la Amonidoj, ĉe la Edomidoj, kaj en ĉiuj landoj, aŭdis, ke la reĝo de Babel restigis parton de la Judoj, kaj ke li starigis kiel reganton super ili Gedaljan, filon de Aĥikam, filo de Ŝafan."],[40,12,"Kaj ĉiuj tiuj Judoj revenis de ĉiuj lokoj, kien ili estis dispelitaj, kaj venis en la landon Judan al Gedalja en Micpan, kaj ili enkolektis tre multe da vino kaj da someraj fruktoj.","Kaj ĉiuj tiuj Judoj revenis de ĉiuj lokoj, kien ili estis dispelitaj, kaj venis en la landon Judan al Gedalja en Micpan, kaj ili enkolektis tre multe da vino kaj da someraj fruktoj."],[40,13,"Sed Joĥanan, filo de Kareaĥ, kaj ĉiuj militestroj, kiuj estis sur la kampo, venis al Gedalja en Micpan.","Sed Joĥanan, filo de Kareaĥ, kaj ĉiuj militestroj, kiuj estis sur la kampo, venis al Gedalja en Micpan."],[40,14,"Kaj ili diris al li: Ĉu vi scias, ke Baalis, reĝo de la Amonidoj, sendis Iŝmaelon, filon de Netanja, por ke li mortigu vin? Sed Gedalja, filo de Aĥikam, ne kredis al ili.","Kaj ili diris al li: Ĉu vi scias, ke Baalis, reĝo de la Amonidoj, sendis Iŝmaelon, filon de Netanja, por ke li mortigu vin? Sed Gedalja, filo de Aĥikam, ne kredis al ili."],[40,15,"Tiam Joĥanan, filo de Kareaĥ, diris sekrete al Gedalja en Micpa jene: Permesu, ke mi iru kaj mortigu Iŝmaelon, filon de Netanja, kaj neniu tion scios; kial li vin mortigu, ke ĉiuj Judoj, kiuj kolektiĝis al vi, diskuru, kaj la restaĵo de la Judoj pereu?","Tiam Joĥanan, filo de Kareaĥ, diris sekrete al Gedalja en Micpa jene: Permesu, ke mi iru kaj mortigu Iŝmaelon, filon de Netanja, kaj neniu tion scios; kial li vin mortigu, ke ĉiuj Judoj, kiuj kolektiĝis al vi, diskuru, kaj la restaĵo de la Judoj pereu?"],[40,16,"Sed Gedalja, filo de Aĥikam, diris al Joĥanan, filo de Kareaĥ: Ne faru tion, ĉar malveron vi parolas pri Iŝmael.","Sed Gedalja, filo de Aĥikam, diris al Joĥanan, filo de Kareaĥ: Ne faru tion, ĉar malveron vi parolas pri Iŝmael."],[41,1,"En la sepa monato Iŝmael, filo de Netanja, filo de Eliŝama, el la reĝa idaro, unu el la eminentuloj de la reĝo, kaj kun li dek viroj, venis al Gedalja, filo de Aĥikam, en Micpan, kaj ili kune tie manĝis en Micpa.","En la sepa monato Iŝmael, filo de Netanja, filo de Eliŝama, el la reĝa idaro, unu el la eminentuloj de la reĝo, kaj kun li dek viroj, venis al Gedalja, filo de Aĥikam, en Micpan, kaj ili kune tie manĝis en Micpa."],[41,2,"Kaj leviĝis Iŝmael, filo de Netanja, kaj la dek viroj, kiuj estis kun li, kaj frapis Gedaljan, filon de Aĥikam, filo de Ŝafan, per glavo, kaj mortigis lin, kiun la reĝo de Babel starigis kiel reganton super la lando.","Kaj leviĝis Iŝmael, filo de Netanja, kaj la dek viroj, kiuj estis kun li, kaj frapis Gedaljan, filon de Aĥikam, filo de Ŝafan, per glavo, kaj mortigis lin, kiun la reĝo de Babel starigis kiel reganton super la lando."],[41,3,"Kaj ĉiujn Judojn, kiuj estis kun li, Gedalja, en Micpa, kaj la Ĥaldeojn, kiuj tie troviĝis, la militistojn, Iŝmael mortigis.","Kaj ĉiujn Judojn, kiuj estis kun li, Gedalja, en Micpa, kaj la Ĥaldeojn, kiuj tie troviĝis, la militistojn, Iŝmael mortigis."],[41,4,"En la dua tago post la mortigo de Gedalja, kiam neniu ankoraŭ sciis pri tio,","En la dua tago post la mortigo de Gedalja, kiam neniu ankoraŭ sciis pri tio,"],[41,5,"venis viroj el Ŝeĥem, el Ŝilo, kaj el Samario, okdek homoj, kun razitaj barboj kaj disŝiritaj vestoj, kun tranĉoj sur la korpo, kaj en iliaj manoj estis donacoj kaj olibano, por alporti ilin en la domon de la Eternulo.","venis viroj el Ŝeĥem, el Ŝilo, kaj el Samario, okdek homoj, kun razitaj barboj kaj disŝiritaj vestoj, kun tranĉoj sur la korpo, kaj en iliaj manoj estis donacoj kaj olibano, por alporti ilin en la domon de la Eternulo."],[41,6,"Kaj Iŝmael, filo de Netanja, eliris al ili renkonte el Micpa, irante kaj plorante; kaj kiam li atingis ilin, li diris al ili: Iru al Gedalja, filo de Aĥikam.","Kaj Iŝmael, filo de Netanja, eliris al ili renkonte el Micpa, irante kaj plorante; kaj kiam li atingis ilin, li diris al ili: Iru al Gedalja, filo de Aĥikam."],[41,7,"Sed kiam ili venis en la mezon de la urbo, Iŝmael, filo de Netanja, kune kun la homoj, kiuj estis kun li, buĉis ilin kaj ĵetis en kavon.","Sed kiam ili venis en la mezon de la urbo, Iŝmael, filo de Netanja, kune kun la homoj, kiuj estis kun li, buĉis ilin kaj ĵetis en kavon."],[41,8,"Tamen troviĝis inter ili dek homoj, kiuj diris al Iŝmael: Ne mortigu nin, ĉar ni havas sur la kampo abundajn provizojn da tritiko, hordeo, oleo, kaj mielo. Kaj li haltis, kaj ne mortigis ilin kune kun iliaj fratoj.","Tamen troviĝis inter ili dek homoj, kiuj diris al Iŝmael: Ne mortigu nin, ĉar ni havas sur la kampo abundajn provizojn da tritiko, hordeo, oleo, kaj mielo. Kaj li haltis, kaj ne mortigis ilin kune kun iliaj fratoj."],[41,9,"La kavo, en kiun Iŝmael ĵetis ĉiujn kadavrojn de la homoj, kiujn li mortigis samtempe kiel Gedaljan, estis tiu, kiun faris la reĝo Asa kontraŭ Baaŝa, reĝo de Izrael; ĝin Iŝmael, filo de Netanja, plenigis per mortigitoj.","La kavo, en kiun Iŝmael ĵetis ĉiujn kadavrojn de la homoj, kiujn li mortigis samtempe kiel Gedaljan, estis tiu, kiun faris la reĝo Asa kontraŭ Baaŝa, reĝo de Izrael; ĝin Iŝmael, filo de Netanja, plenigis per mortigitoj."],[41,10,"Kaj Iŝmael kaptis la tutan restaĵon de la popolo, kiu estis en Micpa, la reĝidinojn, kaj la tutan popolon, kiu restis en Micpa, kaj super kiu Nebuzaradan, la estro de la korpogardistoj, estrigis Gedaljan, filon de Aĥikam; ilin kaptis Iŝmael, filo de Netanja, kaj li pretiĝis, por transiri al la Amonidoj.","Kaj Iŝmael kaptis la tutan restaĵon de la popolo, kiu estis en Micpa, la reĝidinojn, kaj la tutan popolon, kiu restis en Micpa, kaj super kiu Nebuzaradan, la estro de la korpogardistoj, estrigis Gedaljan, filon de Aĥikam; ilin kaptis Iŝmael, filo de Netanja, kaj li pretiĝis, por transiri al la Amonidoj."],[41,11,"Sed Joĥanan, filo de Kareaĥ, kaj ĉiuj militestroj, kiuj estis kun li, aŭdis pri la tuta malbono, kiun faris Iŝmael, filo de Netanja;","Sed Joĥanan, filo de Kareaĥ, kaj ĉiuj militestroj, kiuj estis kun li, aŭdis pri la tuta malbono, kiun faris Iŝmael, filo de Netanja;"],[41,12,"kaj ili prenis ĉiujn virojn, kaj iris, por batali kontraŭ Iŝmael, filo de Netanja; kaj ili trovis lin ĉe la granda akvo, kiu estas en Gibeon.","kaj ili prenis ĉiujn virojn, kaj iris, por batali kontraŭ Iŝmael, filo de Netanja; kaj ili trovis lin ĉe la granda akvo, kiu estas en Gibeon."],[41,13,"Kiam la tuta popolo, kiu estis ĉe Iŝmael, ekvidis Joĥananon, filon de Kareaĥ, kaj ĉiujn militestrojn, kiuj estis kun li, ĝi ekĝojis.","Kiam la tuta popolo, kiu estis ĉe Iŝmael, ekvidis Joĥananon, filon de Kareaĥ, kaj ĉiujn militestrojn, kiuj estis kun li, ĝi ekĝojis."],[41,14,"Kaj la tuta popolo, kiun Iŝmael forkondukis el Micpa, deturnis sin, kaj iris al Joĥanan, filo de Kareaĥ.","Kaj la tuta popolo, kiun Iŝmael forkondukis el Micpa, deturnis sin, kaj iris al Joĥanan, filo de Kareaĥ."],[41,15,"Sed Iŝmael, filo de Netanja, forkuris de Joĥanan kun ok homoj kaj iris al la Amonidoj.","Sed Iŝmael, filo de Netanja, forkuris de Joĥanan kun ok homoj kaj iris al la Amonidoj."],[41,16,"Joĥanan, filo de Kareaĥ, kaj ĉiuj militestroj, kiuj estis kun li, prenis la tutan restaĵon de la popolo, kiun li revenigis de Iŝmael, filo de Netanja, el Micpa, post kiam ĉi tiu mortigis Gedaljan, filon de Aĥikam: virojn, militistojn, virinojn, infanojn, kaj eŭnukojn, kiujn li revenigis el Gibeon.","Joĥanan, filo de Kareaĥ, kaj ĉiuj militestroj, kiuj estis kun li, prenis la tutan restaĵon de la popolo, kiun li revenigis de Iŝmael, filo de Netanja, el Micpa, post kiam ĉi tiu mortigis Gedaljan, filon de Aĥikam: virojn, militistojn, virinojn, infanojn, kaj eŭnukojn, kiujn li revenigis el Gibeon."],[41,17,"Kaj ili iris kaj haltis ĉe la gastejo Kimham, apud Bet-Leĥem, por direkti sin al Egiptujo,","Kaj ili iris kaj haltis ĉe la gastejo Kimham, apud Bet-Leĥem, por direkti sin al Egiptujo,"],[41,18,"for de la Ĥaldeoj; ĉar ili timis ilin pro tio, ke Iŝmael, filo de Netanja, mortigis Gedaljan, filon de Aĥikam, kiun la reĝo de Babel estrigis super la lando.","for de la Ĥaldeoj; ĉar ili timis ilin pro tio, ke Iŝmael, filo de Netanja, mortigis Gedaljan, filon de Aĥikam, kiun la reĝo de Babel estrigis super la lando."],[42,1,"Kaj aliris ĉiuj militestroj, kaj Joĥanan, filo de Kareaĥ, kaj Jezanja, filo de Hoŝaja, kaj la tuta popolo, de la malgrandaj ĝis la grandaj,","Kaj aliris ĉiuj militestroj, kaj Joĥanan, filo de Kareaĥ, kaj Jezanja, filo de Hoŝaja, kaj la tuta popolo, de la malgrandaj ĝis la grandaj,"],[42,2,"kaj diris al la profeto Jeremia: Ni humile petegas vin, preĝu por ni al la Eternulo, via Dio, por ĉi tiu tuta restaĵo; ĉar el multaj ni restis malmultaj, kiel viaj okuloj nin vidas.","kaj diris al la profeto Jeremia: Ni humile petegas vin, preĝu por ni al la Eternulo, via Dio, por ĉi tiu tuta restaĵo; ĉar el multaj ni restis malmultaj, kiel viaj okuloj nin vidas."],[42,3,"Kaj la Eternulo, via Dio, sciigu al ni la vojon, kiun ni devas iri, kaj kion ni devas fari.","Kaj la Eternulo, via Dio, sciigu al ni la vojon, kiun ni devas iri, kaj kion ni devas fari."],[42,4,"Kaj la profeto Jeremia diris al ili: Mi aŭdis; jen mi preĝos al la Eternulo, via Dio, konforme al viaj vortoj, kaj ĉion, kion la Eternulo respondos al vi, mi raportos al vi; mi nenion kaŝos antaŭ vi.","Kaj la profeto Jeremia diris al ili: Mi aŭdis; jen mi preĝos al la Eternulo, via Dio, konforme al viaj vortoj, kaj ĉion, kion la Eternulo respondos al vi, mi raportos al vi; mi nenion kaŝos antaŭ vi."],[42,5,"Kaj ili diris al Jeremia: La Eternulo estu inter ni atestanto vera kaj fidela, ke ni agos konforme al ĉio, kun kio la Eternulo, via Dio, sendos vin al ni;","Kaj ili diris al Jeremia: La Eternulo estu inter ni atestanto vera kaj fidela, ke ni agos konforme al ĉio, kun kio la Eternulo, via Dio, sendos vin al ni;"],[42,6,"ĉu estos bone, ĉu estos malbone, ni aŭskultos la voĉon de la Eternulo, nia Dio, al kiu ni vin sendas, por ke estu al ni bone, se ni aŭskultos la voĉon de la Eternulo, nia Dio.","ĉu estos bone, ĉu estos malbone, ni aŭskultos la voĉon de la Eternulo, nia Dio, al kiu ni vin sendas, por ke estu al ni bone, se ni aŭskultos la voĉon de la Eternulo, nia Dio."],[42,7,"Post dek tagoj aperis la vorto de la Eternulo al Jeremia;","Post dek tagoj aperis la vorto de la Eternulo al Jeremia;"],[42,8,"kaj li vokis Joĥananon, filon de Kareaĥ, kaj ĉiujn militestrojn, kiuj estis kun li, kaj la tutan popolon, de la malgrandaj ĝis la grandaj,","kaj li vokis Joĥananon, filon de Kareaĥ, kaj ĉiujn militestrojn, kiuj estis kun li, kaj la tutan popolon, de la malgrandaj ĝis la grandaj,"],[42,9,"kaj diris al ili: Tiele diras la Eternulo, Dio de Izrael, al kiu vi min sendis, por faligi vian petegon antaŭ Li:","kaj diris al ili: Tiele diras la Eternulo, Dio de Izrael, al kiu vi min sendis, por faligi vian petegon antaŭ Li:"],[42,10,"Se vi restos en ĉi tiu lando, Mi vin aranĝos kaj ne ruinigos, Mi vin plantos kaj ne elradikigos; ĉar Mi pentas pri la malbono, kiun Mi faris al vi.","Se vi restos en ĉi tiu lando, Mi vin aranĝos kaj ne ruinigos, Mi vin plantos kaj ne elradikigos; ĉar Mi pentas pri la malbono, kiun Mi faris al vi."],[42,11,"Ne timu la reĝon de Babel, kiun vi nun timas; ne timu lin, diras la Eternulo, ĉar Mi estas kun vi, por helpi vin kaj por savi vin el lia mano.","Ne timu la reĝon de Babel, kiun vi nun timas; ne timu lin, diras la Eternulo, ĉar Mi estas kun vi, por helpi vin kaj por savi vin el lia mano."],[42,12,"Mi estos favorkora al vi, ke li vin kompatu kaj vin loĝigu sur via tero.","Mi estos favorkora al vi, ke li vin kompatu kaj vin loĝigu sur via tero."],[42,13,"Sed se vi diros: Ni ne volas loĝi en ĉi tiu lando, kaj vi ne obeos la voĉon de la Eternulo, via Dio,","Sed se vi diros: Ni ne volas loĝi en ĉi tiu lando, kaj vi ne obeos la voĉon de la Eternulo, via Dio,"],[42,14,"dirante: Ne, ni iros en la landon Egiptan, kie ni ne vidos militon kaj ne aŭdos sonon de trumpeto kaj ne malsatos koncerne panon, kaj tie ni restos:","dirante: Ne, ni iros en la landon Egiptan, kie ni ne vidos militon kaj ne aŭdos sonon de trumpeto kaj ne malsatos koncerne panon, kaj tie ni restos:"],[42,15,"tiam aŭskultu la vorton de la Eternulo, ho restaĵo de Jehuda: tiele diras la Eternulo Cebaot, Dio de Izrael: Se vi turnos vian vizaĝon, por iri en Egiptujon, kaj vi iros, por tie ekloĝi:","tiam aŭskultu la vorton de la Eternulo, ho restaĵo de Jehuda: tiele diras la Eternulo Cebaot, Dio de Izrael: Se vi turnos vian vizaĝon, por iri en Egiptujon, kaj vi iros, por tie ekloĝi:"],[42,16,"tiam la glavo, kiun vi timas, atingos vin tie, en la lando Egipta, kaj la malsato, pri kiu vi zorgas, persekutos vin tie en Egiptujo, kaj tie vi mortos.","tiam la glavo, kiun vi timas, atingos vin tie, en la lando Egipta, kaj la malsato, pri kiu vi zorgas, persekutos vin tie en Egiptujo, kaj tie vi mortos."],[42,17,"Tiamaniere ĉiuj homoj, kiuj turnis sian vizaĝon, por iri en Egiptujon, por tie ekloĝi, mortos de glavo, de malsato, kaj de pesto, kaj neniu el ili restos, nek forsaviĝos de la malbono, kiun Mi venigos sur ilin.","Tiamaniere ĉiuj homoj, kiuj turnis sian vizaĝon, por iri en Egiptujon, por tie ekloĝi, mortos de glavo, de malsato, kaj de pesto, kaj neniu el ili restos, nek forsaviĝos de la malbono, kiun Mi venigos sur ilin."],[42,18,"Ĉar tiele diras la Eternulo Cebaot, Dio de Izrael: Kiel elverŝiĝis Mia kolero kaj indigno sur la loĝantojn de Jerusalem, tiel Mia kolero elverŝiĝos sur vin, kiam vi venos en Egiptujon, kaj vi fariĝos objekto de ĵuro, de teruro, de malbeno, kaj de honto, kaj vi ne plu vidos ĉi tiun lokon.","Ĉar tiele diras la Eternulo Cebaot, Dio de Izrael: Kiel elverŝiĝis Mia kolero kaj indigno sur la loĝantojn de Jerusalem, tiel Mia kolero elverŝiĝos sur vin, kiam vi venos en Egiptujon, kaj vi fariĝos objekto de ĵuro, de teruro, de malbeno, kaj de honto, kaj vi ne plu vidos ĉi tiun lokon."],[42,19,"Pri vi, ho restaĵo de Jehuda, la Eternulo parolis: Ne iru en Egiptujon; sciu, ke Mi avertis vin hodiaŭ.","Pri vi, ho restaĵo de Jehuda, la Eternulo parolis: Ne iru en Egiptujon; sciu, ke Mi avertis vin hodiaŭ."],[42,20,"Vi fariĝis kulpaj kontraŭ viaj propraj animoj; ĉar vi sendis min al la Eternulo, via Dio, dirante: Preĝu por ni al la Eternulo, nia Dio, kaj ĉion, kion diros la Eternulo, nia Dio, sciigu al ni, por ke ni tion faru.","Vi fariĝis kulpaj kontraŭ viaj propraj animoj; ĉar vi sendis min al la Eternulo, via Dio, dirante: Preĝu por ni al la Eternulo, nia Dio, kaj ĉion, kion diros la Eternulo, nia Dio, sciigu al ni, por ke ni tion faru."],[42,21,"Kaj mi sciigis al vi hodiaŭ, sed vi ne aŭskultis la voĉon de la Eternulo, via Dio, nek ĉion, kun kio Li sendis min al vi;","Kaj mi sciigis al vi hodiaŭ, sed vi ne aŭskultis la voĉon de la Eternulo, via Dio, nek ĉion, kun kio Li sendis min al vi;"],[42,22,"sciu do, ke vi mortos de glavo, de malsato, kaj de pesto, sur la loko, kien vi volas iri, por tie ekloĝi.","sciu do, ke vi mortos de glavo, de malsato, kaj de pesto, sur la loko, kien vi volas iri, por tie ekloĝi."],[43,1,"Kiam Jeremia finis antaŭ la tuta popolo la raportadon pri ĉiuj vortoj de la Eternulo, ilia Dio, pri ĉiuj vortoj, kun kiuj la Eternulo, ilia Dio, sendis lin al ili,","Kiam Jeremia finis antaŭ la tuta popolo la raportadon pri ĉiuj vortoj de la Eternulo, ilia Dio, pri ĉiuj vortoj, kun kiuj la Eternulo, ilia Dio, sendis lin al ili,"],[43,2,"tiam Azarja, filo de Hoŝaja, kaj Joĥanan, filo de Kareaĥ, kaj ĉiuj malhumilaj homoj diris al Jeremia: Malveron vi parolas; la Eternulo, nia Dio, ne sendis vin, por diri: Ne iru en Egiptujon, por tie ekloĝi;","tiam Azarja, filo de Hoŝaja, kaj Joĥanan, filo de Kareaĥ, kaj ĉiuj malhumilaj homoj diris al Jeremia: Malveron vi parolas; la Eternulo, nia Dio, ne sendis vin, por diri: Ne iru en Egiptujon, por tie ekloĝi;"],[43,3,"sed nur Baruĥ, filo de Nerija, instigas vin kontraŭ ni, por transdoni nin en la manojn de la Ĥaldeoj, por ke ili mortigu nin aŭ transloĝigu nin en Babelon.","sed nur Baruĥ, filo de Nerija, instigas vin kontraŭ ni, por transdoni nin en la manojn de la Ĥaldeoj, por ke ili mortigu nin aŭ transloĝigu nin en Babelon."],[43,4,"Tiamaniere Joĥanan, filo de Kareaĥ, kaj ĉiuj militestroj, kaj la tuta popolo, ne obeis la voĉon de la Eternulo, por resti en la lando Juda.","Tiamaniere Joĥanan, filo de Kareaĥ, kaj ĉiuj militestroj, kaj la tuta popolo, ne obeis la voĉon de la Eternulo, por resti en la lando Juda."],[43,5,"Kaj Joĥanan, filo de Kareaĥ, kaj ĉiuj militestroj prenis la tutan restaĵon de la Judoj, kiuj revenis el ĉiuj nacioj, kien ili estis dispelitaj, por loĝi en la lando Juda:","Kaj Joĥanan, filo de Kareaĥ, kaj ĉiuj militestroj prenis la tutan restaĵon de la Judoj, kiuj revenis el ĉiuj nacioj, kien ili estis dispelitaj, por loĝi en la lando Juda:"],[43,6,"la virojn, la virinojn, la infanojn, la reĝidinojn, kaj ĉiujn, kiujn Nebuzaradan, estro de la korpogardistoj, restigis kun Gedalja, filo de Aĥikam, filo de Ŝafan, kaj la profeton Jeremia, kaj Baruĥon, filon de Nerija.","la virojn, la virinojn, la infanojn, la reĝidinojn, kaj ĉiujn, kiujn Nebuzaradan, estro de la korpogardistoj, restigis kun Gedalja, filo de Aĥikam, filo de Ŝafan, kaj la profeton Jeremia, kaj Baruĥon, filon de Nerija."],[43,7,"Kaj ili iris en la landon Egiptan, ne obeante la voĉon de la Eternulo, kaj venis ĝis Taĥpanĥes.","Kaj ili iris en la landon Egiptan, ne obeante la voĉon de la Eternulo, kaj venis ĝis Taĥpanĥes."],[43,8,"Kaj aperis vorto de la Eternulo al Jeremia en Taĥpanĥes, dirante:","Kaj aperis vorto de la Eternulo al Jeremia en Taĥpanĥes, dirante:"],[43,9,"Prenu en vian manon grandajn ŝtonojn, kaj antaŭ la okuloj de la Judaj viroj kaŝu ilin en la kalko en la brikfarejo, kiu troviĝas ĉe la enirejo de la domo de Faraono en Taĥpanĥes;","Prenu en vian manon grandajn ŝtonojn, kaj antaŭ la okuloj de la Judaj viroj kaŝu ilin en la kalko en la brikfarejo, kiu troviĝas ĉe la enirejo de la domo de Faraono en Taĥpanĥes;"],[43,10,"kaj diru al ili: Tiele diras la Eternulo Cebaot, Dio de Izrael: Jen Mi sendos, kaj venigos Nebukadnecaron, reĝon de Babel, Mian servanton, kaj Mi starigos lian tronon supre de ĉi tiuj ŝtonoj, kiujn Mi kaŝis, kaj li starigos sur ili sian tendon.","kaj diru al ili: Tiele diras la Eternulo Cebaot, Dio de Izrael: Jen Mi sendos, kaj venigos Nebukadnecaron, reĝon de Babel, Mian servanton, kaj Mi starigos lian tronon supre de ĉi tiuj ŝtonoj, kiujn Mi kaŝis, kaj li starigos sur ili sian tendon."],[43,11,"Kaj li venos, kaj frapos la landon Egiptan: kiu estas destinita al la morto, tiu ricevos la morton; kiu estas destinita al kaptiteco, tiu iros en kaptitecon; kaj kiu estas destinita al glavo, tiun trafos glavo.","Kaj li venos, kaj frapos la landon Egiptan: kiu estas destinita al la morto, tiu ricevos la morton; kiu estas destinita al kaptiteco, tiu iros en kaptitecon; kaj kiu estas destinita al glavo, tiun trafos glavo."],[43,12,"Kaj Mi ekbruligos fajron en la domoj de la dioj de Egiptujo, kaj ĝi bruligos ilin kaj forkaptos. Kaj li ĉirkaŭkovros sin per la havo de la lando Egipta, kiel paŝtisto kovras sin per sia vesto, kaj li eliros el tie bonstate.","Kaj Mi ekbruligos fajron en la domoj de la dioj de Egiptujo, kaj ĝi bruligos ilin kaj forkaptos. Kaj li ĉirkaŭkovros sin per la havo de la lando Egipta, kiel paŝtisto kovras sin per sia vesto, kaj li eliros el tie bonstate."],[43,13,"Kaj li rompos la statuojn de la templo de la suno en la lando Egipta, kaj la domojn de la dioj de Egiptujo li forbruligos per fajro.","Kaj li rompos la statuojn de la templo de la suno en la lando Egipta, kaj la domojn de la dioj de Egiptujo li forbruligos per fajro."],[44,1,"Jen estas la vorto, kiu aperis al Jeremia pri ĉiuj Judoj, kiuj loĝas en la lando Egipta, kiuj loĝas en Migdol, en Taĥpanĥes, en Nof, kaj en la lando Patros:","Jen estas la vorto, kiu aperis al Jeremia pri ĉiuj Judoj, kiuj loĝas en la lando Egipta, kiuj loĝas en Migdol, en Taĥpanĥes, en Nof, kaj en la lando Patros:"],[44,2,"Tiele diras la Eternulo Cebaot, Dio de Izrael: Vi vidis la tutan malbonon, kiun Mi venigis sur Jerusalemon kaj sur ĉiujn urbojn de Judujo; jen ili estas nun dezertaj, kaj neniu loĝas en ili,","Tiele diras la Eternulo Cebaot, Dio de Izrael: Vi vidis la tutan malbonon, kiun Mi venigis sur Jerusalemon kaj sur ĉiujn urbojn de Judujo; jen ili estas nun dezertaj, kaj neniu loĝas en ili,"],[44,3,"pro iliaj malbonagoj, kiujn ili faris, kolerigante Min, irante incensi kaj servi al aliaj dioj, kiujn ne konis ili, nek vi, nek viaj patroj.","pro iliaj malbonagoj, kiujn ili faris, kolerigante Min, irante incensi kaj servi al aliaj dioj, kiujn ne konis ili, nek vi, nek viaj patroj."],[44,4,"Mi sendis al vi ĉiujn Miajn servantojn, la profetojn, Mi konstante sendadis, dirante: Ne faru tiun abomenindan aferon, kiun Mi malamas.","Mi sendis al vi ĉiujn Miajn servantojn, la profetojn, Mi konstante sendadis, dirante: Ne faru tiun abomenindan aferon, kiun Mi malamas."],[44,5,"Sed ili ne obeis, kaj ne alklinis sian orelon, por deturni sin de siaj malbonagoj, por ne incensi al aliaj dioj.","Sed ili ne obeis, kaj ne alklinis sian orelon, por deturni sin de siaj malbonagoj, por ne incensi al aliaj dioj."],[44,6,"Pro tio elverŝiĝis Mia indigno kaj kolero, kaj ĝi ekbrulis en la urboj de Judujo kaj sur la stratoj de Jerusalem, kaj ili ruiniĝis kaj dezertiĝis, kiel oni nun vidas.","Pro tio elverŝiĝis Mia indigno kaj kolero, kaj ĝi ekbrulis en la urboj de Judujo kaj sur la stratoj de Jerusalem, kaj ili ruiniĝis kaj dezertiĝis, kiel oni nun vidas."],[44,7,"Kaj nun tiele diras la Eternulo, Dio Cebaot, Dio de Izrael: Kial vi faras grandan malbonon al viaj propraj animoj, por ke ekstermiĝu ĉe vi viroj kaj virinoj, infanoj kaj suĉinfanoj en Judujo, por ke nenio restu ĉe vi?","Kaj nun tiele diras la Eternulo, Dio Cebaot, Dio de Izrael: Kial vi faras grandan malbonon al viaj propraj animoj, por ke ekstermiĝu ĉe vi viroj kaj virinoj, infanoj kaj suĉinfanoj en Judujo, por ke nenio restu ĉe vi?"],[44,8,"Kial vi kolerigas Min per la faroj de viaj manoj, incensante al aliaj dioj en la lando Egipta, kien vi venis, por tie loĝi, por ke vi ekstermiĝu kaj por ke vi fariĝu objekto de malbeno kaj de honto inter ĉiuj nacioj de la tero?","Kial vi kolerigas Min per la faroj de viaj manoj, incensante al aliaj dioj en la lando Egipta, kien vi venis, por tie loĝi, por ke vi ekstermiĝu kaj por ke vi fariĝu objekto de malbeno kaj de honto inter ĉiuj nacioj de la tero?"],[44,9,"Ĉu vi forgesis la malbonaĵojn de viaj patroj kaj la malbonaĵojn de la reĝoj de Judujo, la malbonaĵojn de iliaj edzinoj, viajn malbonaĵojn, kaj la malbonaĵojn de viaj edzinoj, kiujn ili faris en la lando Juda kaj sur la stratoj de Jerusalem?","Ĉu vi forgesis la malbonaĵojn de viaj patroj kaj la malbonaĵojn de la reĝoj de Judujo, la malbonaĵojn de iliaj edzinoj, viajn malbonaĵojn, kaj la malbonaĵojn de viaj edzinoj, kiujn ili faris en la lando Juda kaj sur la stratoj de Jerusalem?"],[44,10,"Ili ne humiliĝis ĝis la nuna tago, ili ne timas kaj ne agas laŭ Mia instruo kaj laŭ Miaj leĝoj, kiujn Mi donis al vi kaj al viaj patroj.","Ili ne humiliĝis ĝis la nuna tago, ili ne timas kaj ne agas laŭ Mia instruo kaj laŭ Miaj leĝoj, kiujn Mi donis al vi kaj al viaj patroj."],[44,11,"Tial tiele diras la Eternulo Cebaot, Dio de Izrael: Jen Mi turnos Mian vizaĝon kontraŭ vin por malfeliĉo kaj por ekstermi la tutan Judujon.","Tial tiele diras la Eternulo Cebaot, Dio de Izrael: Jen Mi turnos Mian vizaĝon kontraŭ vin por malfeliĉo kaj por ekstermi la tutan Judujon."],[44,12,"Kaj Mi prenos la restaĵon de la Judoj, kiuj turnis sian vizaĝon, por iri en la landon Egiptan, por tie ekloĝi, kaj ili ĉiuj ekstermiĝos en la lando Egipta; ili falos de glavo, de malsato ili ekstermiĝos, de la malgrandaj ĝis la grandaj; de glavo kaj de malsato ili mortos, kaj ili fariĝos objekto de ĵuro, de teruro, de malbeno, kaj de honto.","Kaj Mi prenos la restaĵon de la Judoj, kiuj turnis sian vizaĝon, por iri en la landon Egiptan, por tie ekloĝi, kaj ili ĉiuj ekstermiĝos en la lando Egipta; ili falos de glavo, de malsato ili ekstermiĝos, de la malgrandaj ĝis la grandaj; de glavo kaj de malsato ili mortos, kaj ili fariĝos objekto de ĵuro, de teruro, de malbeno, kaj de honto."],[44,13,"Kaj Mi punos tiujn, kiuj loĝas en la lando Egipta, kiel Mi punis Jerusalemon, per glavo, per malsato, kaj per pesto.","Kaj Mi punos tiujn, kiuj loĝas en la lando Egipta, kiel Mi punis Jerusalemon, per glavo, per malsato, kaj per pesto."],[44,14,"Kaj neniu saviĝos nek restos el la restaĵo de la Judoj, kiuj venis en la landon Egiptan, por loĝi tie kelktempe kaj por poste reiri en la landon Judan, kien ili sopiras per sia animo reveni kaj tie loĝi; ili ne revenos, krom tiuj, kiuj forkuros.","Kaj neniu saviĝos nek restos el la restaĵo de la Judoj, kiuj venis en la landon Egiptan, por loĝi tie kelktempe kaj por poste reiri en la landon Judan, kien ili sopiras per sia animo reveni kaj tie loĝi; ili ne revenos, krom tiuj, kiuj forkuros."],[44,15,"Tiam respondis al Jeremia ĉiuj viroj, kiuj sciis, ke iliaj edzinoj incensas al aliaj dioj, kaj ĉiuj virinoj, kiuj staris en granda amaso, kaj la tuta popolo, kiu loĝis en la lando Egipta, en Patros; ili diris:","Tiam respondis al Jeremia ĉiuj viroj, kiuj sciis, ke iliaj edzinoj incensas al aliaj dioj, kaj ĉiuj virinoj, kiuj staris en granda amaso, kaj la tuta popolo, kiu loĝis en la lando Egipta, en Patros; ili diris:"],[44,16,"Tion, kion vi diris al ni en la nomo de la Eternulo, ni ne obeos al vi;","Tion, kion vi diris al ni en la nomo de la Eternulo, ni ne obeos al vi;"],[44,17,"sed ni faros ĉion laŭ la vortoj, kiuj eliras el nia buŝo, ni incensos al la reĝino de la ĉielo, ni verŝos al ŝi verŝoferojn, kiel faris ni kaj niaj patroj, niaj reĝoj kaj niaj eminentuloj, en la urboj de Judujo kaj sur la stratoj de Jerusalem; tiam ni havis abundan panon, kaj estis al ni bone, kaj malbonon ni ne vidis.","sed ni faros ĉion laŭ la vortoj, kiuj eliras el nia buŝo, ni incensos al la reĝino de la ĉielo, ni verŝos al ŝi verŝoferojn, kiel faris ni kaj niaj patroj, niaj reĝoj kaj niaj eminentuloj, en la urboj de Judujo kaj sur la stratoj de Jerusalem; tiam ni havis abundan panon, kaj estis al ni bone, kaj malbonon ni ne vidis."],[44,18,"Sed de tiu tempo, kiam ni ĉesis incensi al la reĝino de la ĉielo kaj verŝi al ŝi verŝoferojn, ĉio mankas al ni, kaj ni pereas de glavo kaj de malsato.","Sed de tiu tempo, kiam ni ĉesis incensi al la reĝino de la ĉielo kaj verŝi al ŝi verŝoferojn, ĉio mankas al ni, kaj ni pereas de glavo kaj de malsato."],[44,19,"Kaj kiam ni incensas al la reĝino de la ĉielo kaj verŝas al ŝi verŝoferojn, ĉu sen la scio de niaj edzoj ni faras al ŝi kukojn kun ŝia bildo kaj verŝas al ŝi verŝoferojn?","Kaj kiam ni incensas al la reĝino de la ĉielo kaj verŝas al ŝi verŝoferojn, ĉu sen la scio de niaj edzoj ni faras al ŝi kukojn kun ŝia bildo kaj verŝas al ŝi verŝoferojn?"],[44,20,"Tiam Jeremia diris al la tuta popolo, pri la viroj kaj virinoj, kaj pri ĉiuj el la popolo, kiuj respondis al li:","Tiam Jeremia diris al la tuta popolo, pri la viroj kaj virinoj, kaj pri ĉiuj el la popolo, kiuj respondis al li:"],[44,21,"Ĝuste tiun incensadon, kiun vi faradis en la urboj de Judujo kaj sur la stratoj de Jerusalem, vi kaj viaj patroj, viaj reĝoj kaj viaj eminentuloj kaj la popolo de la lando — ĝuste tion la Eternulo ja rememoris, kaj ĝi atingis Lian koron.","Ĝuste tiun incensadon, kiun vi faradis en la urboj de Judujo kaj sur la stratoj de Jerusalem, vi kaj viaj patroj, viaj reĝoj kaj viaj eminentuloj kaj la popolo de la lando — ĝuste tion la Eternulo ja rememoris, kaj ĝi atingis Lian koron."],[44,22,"Kaj la Eternulo ne plu povis toleri viajn malbonajn agojn, la abomenindaĵojn, kiujn vi faris; tial via lando fariĝis dezerto, objekto de teruro kaj de malbeno, kaj neniu loĝas en ĝi, kiel oni nun vidas.","Kaj la Eternulo ne plu povis toleri viajn malbonajn agojn, la abomenindaĵojn, kiujn vi faris; tial via lando fariĝis dezerto, objekto de teruro kaj de malbeno, kaj neniu loĝas en ĝi, kiel oni nun vidas."],[44,23,"Pro tio, ke vi incensadis kaj pekadis antaŭ la Eternulo kaj ne obeis la voĉon de la Eternulo kaj ne agadis laŭ Lia instruo, laŭ Liaj leĝoj kaj ordonoj — pro tio trafis vin tiu malbono, kiel vi nun vidas.","Pro tio, ke vi incensadis kaj pekadis antaŭ la Eternulo kaj ne obeis la voĉon de la Eternulo kaj ne agadis laŭ Lia instruo, laŭ Liaj leĝoj kaj ordonoj — pro tio trafis vin tiu malbono, kiel vi nun vidas."],[44,24,"Kaj Jeremia diris al la tuta popolo kaj al ĉiuj virinoj: Aŭskultu la vorton de la Eternulo, ĉiuj Judoj, kiuj estas en la lando Egipta!","Kaj Jeremia diris al la tuta popolo kaj al ĉiuj virinoj: Aŭskultu la vorton de la Eternulo, ĉiuj Judoj, kiuj estas en la lando Egipta!"],[44,25,"Tiele diras la Eternulo Cebaot, Dio de Izrael: Vi kaj viaj edzinoj parolis per via buŝo kaj plenumis per viaj manoj tion, kion vi diris: Ni plenumos nian solenan promeson, kiun ni faris, incensi al la reĝino de la ĉielo kaj verŝi al ŝi verŝoferojn; vi efektive plenumas viajn promesojn, kaj faras, kion vi promesis.","Tiele diras la Eternulo Cebaot, Dio de Izrael: Vi kaj viaj edzinoj parolis per via buŝo kaj plenumis per viaj manoj tion, kion vi diris: Ni plenumos nian solenan promeson, kiun ni faris, incensi al la reĝino de la ĉielo kaj verŝi al ŝi verŝoferojn; vi efektive plenumas viajn promesojn, kaj faras, kion vi promesis."],[44,26,"Tial aŭskultu la vorton de la Eternulo, ĉiuj Judoj, kiuj loĝas en la lando Egipta: Jen Mi ĵuris per Mia granda nomo, diras la Eternulo, ke la buŝo de neniu Judo en la tuta lando Egipta plu vokos Mian nomon, dirante: Kiel vivas la Sinjoro, la Eternulo.","Tial aŭskultu la vorton de la Eternulo, ĉiuj Judoj, kiuj loĝas en la lando Egipta: Jen Mi ĵuris per Mia granda nomo, diras la Eternulo, ke la buŝo de neniu Judo en la tuta lando Egipta plu vokos Mian nomon, dirante: Kiel vivas la Sinjoro, la Eternulo."],[44,27,"Jen Mi viglos super ili por malbono, ne por bono; kaj ĉiuj Judoj, kiuj estas en la lando Egipta, pereos de glavo kaj de malsato, ĝis ili tute ekstermiĝos.","Jen Mi viglos super ili por malbono, ne por bono; kaj ĉiuj Judoj, kiuj estas en la lando Egipta, pereos de glavo kaj de malsato, ĝis ili tute ekstermiĝos."],[44,28,"Nur malgranda nombro da homoj, kiuj saviĝos de glavo, revenos el la lando Egipta en la landon Judan; kaj la tuta restaĵo de la Judoj, kiuj venis en la landon Egiptan, por tie loĝi, ekscios, kies vorto plenumiĝas, Mia aŭ ilia.","Nur malgranda nombro da homoj, kiuj saviĝos de glavo, revenos el la lando Egipta en la landon Judan; kaj la tuta restaĵo de la Judoj, kiuj venis en la landon Egiptan, por tie loĝi, ekscios, kies vorto plenumiĝas, Mia aŭ ilia."],[44,29,"Kaj jen estas por vi la pruvosigno, diras la Eternulo, ke Mi punos vin sur ĉi tiu loko, por ke vi sciu, ke plenumiĝos Miaj vortoj sur vi por malbono:","Kaj jen estas por vi la pruvosigno, diras la Eternulo, ke Mi punos vin sur ĉi tiu loko, por ke vi sciu, ke plenumiĝos Miaj vortoj sur vi por malbono:"],[44,30,"tiele diras la Eternulo: Jen Mi transdonos Faraonon Ĥofran, reĝon de Egiptujo, en la manojn de liaj malamikoj, kaj en la manojn de tiuj, kiuj celas lian morton, kiel Mi transdonis Cidkijan, reĝon de Judujo, en la manon de Nebukadnecar, reĝo de Babel, lia malamiko kaj celanto de lia morto.","tiele diras la Eternulo: Jen Mi transdonos Faraonon Ĥofran, reĝon de Egiptujo, en la manojn de liaj malamikoj, kaj en la manojn de tiuj, kiuj celas lian morton, kiel Mi transdonis Cidkijan, reĝon de Judujo, en la manon de Nebukadnecar, reĝo de Babel, lia malamiko kaj celanto de lia morto."],[45,1,"Jen estas la vorto, kiun la profeto Jeremia diris al Baruĥ, filo de Nerija, kiam ĉi tiu skribis tiujn vortojn en libron sub diktado de Jeremia, en la kvara jaro de Jehojakim, filo de Joŝija, reĝo de Judujo:","Jen estas la vorto, kiun la profeto Jeremia diris al Baruĥ, filo de Nerija, kiam ĉi tiu skribis tiujn vortojn en libron sub diktado de Jeremia, en la kvara jaro de Jehojakim, filo de Joŝija, reĝo de Judujo:"],[45,2,"Tiele diras la Eternulo, Dio de Izrael, pri vi, ho Baruĥ:","Tiele diras la Eternulo, Dio de Izrael, pri vi, ho Baruĥ:"],[45,3,"Vi diris: Ve al mi! ĉar la Eternulo aldonis malĝojon al mia suferado; mi laciĝis de mia ĝemado, kaj mi ne trovas ripozon.","Vi diris: Ve al mi! ĉar la Eternulo aldonis malĝojon al mia suferado; mi laciĝis de mia ĝemado, kaj mi ne trovas ripozon."],[45,4,"Tiele diru al li: Tiele diras la Eternulo: Jen tion, kion Mi konstruis, Mi detruas, kaj kion Mi plantis, tion Mi elradikigas, ĉi tiun tutan Mian landon;","Tiele diru al li: Tiele diras la Eternulo: Jen tion, kion Mi konstruis, Mi detruas, kaj kion Mi plantis, tion Mi elradikigas, ĉi tiun tutan Mian landon;"],[45,5,"kaj vi postulas por vi grandaĵon! Ne postulu; ĉar jen Mi venigos malbonon sur ĉiun karnon, diras la Eternulo, sed al vi Mi donos vian animon kiel akiron sur ĉiuj lokoj, kien vi iros.","kaj vi postulas por vi grandaĵon! Ne postulu; ĉar jen Mi venigos malbonon sur ĉiun karnon, diras la Eternulo, sed al vi Mi donos vian animon kiel akiron sur ĉiuj lokoj, kien vi iros."],[46,1,"Jen estas la vorto de la Eternulo, kiu aperis al la profeto Jeremia pri la nacioj:","Jen estas la vorto de la Eternulo, kiu aperis al la profeto Jeremia pri la nacioj:"],[46,2,"Pri Egiptujo, pri la militistaro de Faraono Neĥo, reĝo de Egiptujo, kiu estis ĉe la rivero Eŭfrato en Karkemiŝ, kaj kiun venkobatis Nebukadnecar, reĝo de Babel, en la kvara jaro de Jehojakim, filo de Joŝija, reĝo de Judujo:","Pri Egiptujo, pri la militistaro de Faraono Neĥo, reĝo de Egiptujo, kiu estis ĉe la rivero Eŭfrato en Karkemiŝ, kaj kiun venkobatis Nebukadnecar, reĝo de Babel, en la kvara jaro de Jehojakim, filo de Joŝija, reĝo de Judujo:"],[46,3,"Pretigu ŝildon kaj kirason, kaj iru en batalon.","Pretigu ŝildon kaj kirason, kaj iru en batalon."],[46,4,"Jungu la ĉevalojn kaj surĉevaligu la rajdistojn, stariĝu en kaskoj, akrigu la lancojn, surmetu sur vin armaĵojn.","Jungu la ĉevalojn kaj surĉevaligu la rajdistojn, stariĝu en kaskoj, akrigu la lancojn, surmetu sur vin armaĵojn."],[46,5,"Kial Mi vidas, ke ili ektimis kaj kuras malantaŭen? iliaj herooj estas frapitaj, kaj forkuras rapide, ne deturnante sin; teruro estas ĉirkaŭe, diras la Eternulo.","Kial Mi vidas, ke ili ektimis kaj kuras malantaŭen? iliaj herooj estas frapitaj, kaj forkuras rapide, ne deturnante sin; teruro estas ĉirkaŭe, diras la Eternulo."],[46,6,"Ne forkuros la rapidpiedulo, ne forsaviĝos la heroo; norde, ĉe la rivero Eŭfrato, ili falpuŝiĝos kaj falos.","Ne forkuros la rapidpiedulo, ne forsaviĝos la heroo; norde, ĉe la rivero Eŭfrato, ili falpuŝiĝos kaj falos."],[46,7,"Kiu estas tiu, kiu leviĝas kiel Nilo kaj kies akvo ondiĝas kiel torentoj?","Kiu estas tiu, kiu leviĝas kiel Nilo kaj kies akvo ondiĝas kiel torentoj?"],[46,8,"Egiptujo leviĝas kiel Nilo, kaj kiel torentoj, en kiuj ondiĝas la akvo; kaj ĝi diras: Leviĝante, mi kovros la teron, mi pereigos urbon kun ĝiaj loĝantoj.","Egiptujo leviĝas kiel Nilo, kaj kiel torentoj, en kiuj ondiĝas la akvo; kaj ĝi diras: Leviĝante, mi kovros la teron, mi pereigos urbon kun ĝiaj loĝantoj."],[46,9,"Leviĝu sur la ĉevalojn, kaj kuru rapide sur la ĉaroj; eliru la herooj, la Etiopoj kaj la Putidoj, tenantaj ŝildon, kaj la Ludidoj, tenantaj kaj streĉantaj pafarkon.","Leviĝu sur la ĉevalojn, kaj kuru rapide sur la ĉaroj; eliru la herooj, la Etiopoj kaj la Putidoj, tenantaj ŝildon, kaj la Ludidoj, tenantaj kaj streĉantaj pafarkon."],[46,10,"Kaj tiu tago estos ĉe la Sinjoro, la Eternulo Cebaot, tago de venĝo, por venĝi al Liaj malamikoj; kaj la glavo manĝegos kaj satiĝos kaj ebriiĝos de ilia sango; ĉar buĉofero estos al la Sinjoro, la Eternulo Cebaot, en la lando norda, ĉe la rivero Eŭfrato.","Kaj tiu tago estos ĉe la Sinjoro, la Eternulo Cebaot, tago de venĝo, por venĝi al Liaj malamikoj; kaj la glavo manĝegos kaj satiĝos kaj ebriiĝos de ilia sango; ĉar buĉofero estos al la Sinjoro, la Eternulo Cebaot, en la lando norda, ĉe la rivero Eŭfrato."],[46,11,"Iru en Gileadon kaj prenu balzamon, ho virga filino de Egiptujo; vane vi multigas la kuracilojn; ne ekzistas por vi resaniĝo.","Iru en Gileadon kaj prenu balzamon, ho virga filino de Egiptujo; vane vi multigas la kuracilojn; ne ekzistas por vi resaniĝo."],[46,12,"La nacioj aŭdis vian malhonoron, kaj via plorado plenigis la teron; ĉar fortulo falpuŝiĝis kontraŭ fortulo, kaj ambaŭ kune falis.","La nacioj aŭdis vian malhonoron, kaj via plorado plenigis la teron; ĉar fortulo falpuŝiĝis kontraŭ fortulo, kaj ambaŭ kune falis."],[46,13,"Jen estas la vorto, kiun la Eternulo diris al la profeto Jeremia pri la veno de Nebukadnecar, reĝo de Babel, por frapi la landon Egiptan:","Jen estas la vorto, kiun la Eternulo diris al la profeto Jeremia pri la veno de Nebukadnecar, reĝo de Babel, por frapi la landon Egiptan:"],[46,14,"Sciigu en Egiptujo, proklamu en Migdol, proklamu en Nof kaj en Taĥpanĥes, diru: Stariĝu kaj pretiĝu, ĉar la glavo ekstermas vian ĉirkaŭaĵon.","Sciigu en Egiptujo, proklamu en Migdol, proklamu en Nof kaj en Taĥpanĥes, diru: Stariĝu kaj pretiĝu, ĉar la glavo ekstermas vian ĉirkaŭaĵon."],[46,15,"Kial estas forpuŝita via fortulo, ne povis stari? ĉar la Eternulo lin renversis.","Kial estas forpuŝita via fortulo, ne povis stari? ĉar la Eternulo lin renversis."],[46,16,"Li multigis la falpuŝiĝantojn; falis unu sur la alian; kaj ili diras: Leviĝu, ni reiru al nia popolo kaj al la lando de nia naskiĝo, for de la glavo de la tirano.","Li multigis la falpuŝiĝantojn; falis unu sur la alian; kaj ili diras: Leviĝu, ni reiru al nia popolo kaj al la lando de nia naskiĝo, for de la glavo de la tirano."],[46,17,"Oni kriis tie: Faraono, reĝo de Egiptujo, estas nur bruo; li preterlasis la difinitan tempon.","Oni kriis tie: Faraono, reĝo de Egiptujo, estas nur bruo; li preterlasis la difinitan tempon."],[46,18,"Kiel Mi vivas, diras la Reĝo, kies nomo estas Eternulo Cebaot, li venos kiel Tabor inter la montoj kaj kiel Karmel ĉe la maro.","Kiel Mi vivas, diras la Reĝo, kies nomo estas Eternulo Cebaot, li venos kiel Tabor inter la montoj kaj kiel Karmel ĉe la maro."],[46,19,"Pretigu al vi ĉion, kio estas necesa por elmigro, ho loĝantino, filino de Egiptujo; ĉar Nof estos ruinigita kaj dezertigita, ke neniu en ĝi loĝos.","Pretigu al vi ĉion, kio estas necesa por elmigro, ho loĝantino, filino de Egiptujo; ĉar Nof estos ruinigita kaj dezertigita, ke neniu en ĝi loĝos."],[46,20,"Tre bela bovidino estas Egiptujo; sed de nordo venas jam la buĉonto.","Tre bela bovidino estas Egiptujo; sed de nordo venas jam la buĉonto."],[46,21,"Ankaŭ ĝiaj dungitoj interne de ĝi estas kiel bone nutritaj bovidoj; sed ili ankaŭ turnis sin malantaŭen, kune forkuris, ne povis kontraŭstari; ĉar la tago de ilia malfeliĉo venis sur ilin, la tempo de ilia puno.","Ankaŭ ĝiaj dungitoj interne de ĝi estas kiel bone nutritaj bovidoj; sed ili ankaŭ turnis sin malantaŭen, kune forkuris, ne povis kontraŭstari; ĉar la tago de ilia malfeliĉo venis sur ilin, la tempo de ilia puno."],[46,22,"Ĝia voĉo sonos kiel voĉo de serpento; ĉar ili iros kun militistaro, kaj kun hakiloj ili venos al ĝi, kiel lignohakistoj.","Ĝia voĉo sonos kiel voĉo de serpento; ĉar ili iros kun militistaro, kaj kun hakiloj ili venos al ĝi, kiel lignohakistoj."],[46,23,"Ili elhakos ĝian arbaron, diras la Eternulo, kvankam ĝi estas nekalkulebla; ĉar ili estas pli multenombraj ol akridoj, kaj oni ne povas ilin kalkuli.","Ili elhakos ĝian arbaron, diras la Eternulo, kvankam ĝi estas nekalkulebla; ĉar ili estas pli multenombraj ol akridoj, kaj oni ne povas ilin kalkuli."],[46,24,"Hontigita estas la filino de Egiptujo, transdonita en la manojn de norda popolo.","Hontigita estas la filino de Egiptujo, transdonita en la manojn de norda popolo."],[46,25,"La Eternulo Cebaot, Dio de Izrael, diras: Jen Mi punvizitos Amonon en No, kaj Faraonon, kaj Egiptujon kaj ĝiajn diojn kaj ĝiajn reĝojn, Faraonon mem, kaj tiujn, kiuj fidas lin.","La Eternulo Cebaot, Dio de Izrael, diras: Jen Mi punvizitos Amonon en No, kaj Faraonon, kaj Egiptujon kaj ĝiajn diojn kaj ĝiajn reĝojn, Faraonon mem, kaj tiujn, kiuj fidas lin."],[46,26,"Kaj Mi transdonos ilin en la manojn de tiuj, kiuj celas ilian morton, kaj en la manojn de Nebukadnecar, reĝo de Babel, kaj en la manojn de liaj servantoj; sed poste ĝi estos loĝata, kiel en la tempo antaŭa, diras la Eternulo.","Kaj Mi transdonos ilin en la manojn de tiuj, kiuj celas ilian morton, kaj en la manojn de Nebukadnecar, reĝo de Babel, kaj en la manojn de liaj servantoj; sed poste ĝi estos loĝata, kiel en la tempo antaŭa, diras la Eternulo."],[46,27,"Sed vi ne timu, ho Mia servanto Jakob, kaj ne tremu, ho Izrael; ĉar jen Mi savos vin el malproksime kaj vian idaron el la lando de ilia kaptiteco, kaj Jakob revenos kaj vivos trankvile kaj pace, kaj neniu lin timigos.","Sed vi ne timu, ho Mia servanto Jakob, kaj ne tremu, ho Izrael; ĉar jen Mi savos vin el malproksime kaj vian idaron el la lando de ilia kaptiteco, kaj Jakob revenos kaj vivos trankvile kaj pace, kaj neniu lin timigos."],[46,28,"Vi ne timu, ho Mia servanto Jakob, diras la Eternulo, ĉar Mi estas kun vi; ĉar Mi ekstermos ĉiujn popolojn, inter kiujn Mi dispelis vin, sed vin Mi ne ekstermos; Mi nur punos vin modere, por ke Mi ne lasu vin tute sen puno.","Vi ne timu, ho Mia servanto Jakob, diras la Eternulo, ĉar Mi estas kun vi; ĉar Mi ekstermos ĉiujn popolojn, inter kiujn Mi dispelis vin, sed vin Mi ne ekstermos; Mi nur punos vin modere, por ke Mi ne lasu vin tute sen puno."],[47,1,"Jen estas la vorto de la Eternulo, kiu aperis al la profeto Jeremia pri la Filiŝtoj, antaŭ ol Faraono venkobatis Gazan:","Jen estas la vorto de la Eternulo, kiu aperis al la profeto Jeremia pri la Filiŝtoj, antaŭ ol Faraono venkobatis Gazan:"],[47,2,"Tiele diras la Eternulo: Jen venos akvo de norde, kaj ĝi fariĝos inundanta torento, kaj ĝi inundos la landon, kaj ĉion, kio estas en ĝi, la urbon kaj ĝiajn loĝantojn; ekkrios la homoj, kaj ekploregos ĉiuj loĝantoj de la lando.","Tiele diras la Eternulo: Jen venos akvo de norde, kaj ĝi fariĝos inundanta torento, kaj ĝi inundos la landon, kaj ĉion, kio estas en ĝi, la urbon kaj ĝiajn loĝantojn; ekkrios la homoj, kaj ekploregos ĉiuj loĝantoj de la lando."],[47,3,"Pro la sonado de la hufoj de la fortaj ĉevaloj, pro la bruo de la ĉaroj, pro la bruego de la radoj la patroj ne atentos siajn infanojn, senforte malleviĝos iliaj manoj;","Pro la sonado de la hufoj de la fortaj ĉevaloj, pro la bruo de la ĉaroj, pro la bruego de la radoj la patroj ne atentos siajn infanojn, senforte malleviĝos iliaj manoj;"],[47,4,"pro la tago, kiu venos, kiam oni prirabos ĉiujn Filiŝtojn, ekstermos ĉe Tiro kaj Cidon ĉiujn restintajn helpantojn; ĉar la Eternulo ruinigos la Filiŝtojn, la restaĵon de la insulo Kaftor.","pro la tago, kiu venos, kiam oni prirabos ĉiujn Filiŝtojn, ekstermos ĉe Tiro kaj Cidon ĉiujn restintajn helpantojn; ĉar la Eternulo ruinigos la Filiŝtojn, la restaĵon de la insulo Kaftor."],[47,5,"Kalveco trafos Gazan, pereos Aŝkelon kaj la restaĵo de ilia valo. Kiel longe ankoraŭ vi faros al vi tranĉojn?","Kalveco trafos Gazan, pereos Aŝkelon kaj la restaĵo de ilia valo. Kiel longe ankoraŭ vi faros al vi tranĉojn?"],[47,6,"Ho glavo de la Eternulo, kiel longe vi ne kvietiĝos? eniru en vian ingon, haltu kaj silentu.","Ho glavo de la Eternulo, kiel longe vi ne kvietiĝos? eniru en vian ingon, haltu kaj silentu."],[47,7,"Sed kiel vi povas kvietiĝi? la Eternulo donis al ĝi ordonon kontraŭ Aŝkelon kaj kontraŭ la bordo de la maro; tien Li destinis ĝin.","Sed kiel vi povas kvietiĝi? la Eternulo donis al ĝi ordonon kontraŭ Aŝkelon kaj kontraŭ la bordo de la maro; tien Li destinis ĝin."],[48,1,"Pri Moab: Tiele diras la Eternulo Cebaot, Dio de Izrael: Ve al Nebo! ĉar ĝi estas ruinigita; hontigita kaj venkoprenita estas Kirjataim; hontigita kaj tremigita estas la fortikaĵo.","Pri Moab: Tiele diras la Eternulo Cebaot, Dio de Izrael: Ve al Nebo! ĉar ĝi estas ruinigita; hontigita kaj venkoprenita estas Kirjataim; hontigita kaj tremigita estas la fortikaĵo."],[48,2,"Jam ne ekzistas la gloro de Moab; en Ĥeŝbon oni intencas kontraŭ ĝi malbonon, dirante: Ni iru, kaj ni ekstermu ĝin, ke ĝi ne plu estu popolo. Ankaŭ vi, ho Madmen, eksilentu; vin persekutos glavo.","Jam ne ekzistas la gloro de Moab; en Ĥeŝbon oni intencas kontraŭ ĝi malbonon, dirante: Ni iru, kaj ni ekstermu ĝin, ke ĝi ne plu estu popolo. Ankaŭ vi, ho Madmen, eksilentu; vin persekutos glavo."],[48,3,"Kriadon oni aŭdas de Ĥoronaim, tie estas ruinigado kaj granda malfeliĉo.","Kriadon oni aŭdas de Ĥoronaim, tie estas ruinigado kaj granda malfeliĉo."],[48,4,"Disbatita estas Moab; ĝiaj infanoj laŭte krias.","Disbatita estas Moab; ĝiaj infanoj laŭte krias."],[48,5,"Kiuj supreniras al Luĥit, tiuj iras kun plorado; ĉe la malsuprenirado de Ĥoronaim la malamikoj aŭdas kriadon de malfeliĉo.","Kiuj supreniras al Luĥit, tiuj iras kun plorado; ĉe la malsuprenirado de Ĥoronaim la malamikoj aŭdas kriadon de malfeliĉo."],[48,6,"Forkuru, savu vian vivon, kaj estu kiel seknudiĝinta arbo en la dezerto.","Forkuru, savu vian vivon, kaj estu kiel seknudiĝinta arbo en la dezerto."],[48,7,"Ĉar vi fidis viajn faritaĵojn kaj viajn trezorojn, vi ankaŭ estos venkoprenita; kaj Kemoŝ iros en kaptitecon kune kun siaj pastroj kaj eminentuloj.","Ĉar vi fidis viajn faritaĵojn kaj viajn trezorojn, vi ankaŭ estos venkoprenita; kaj Kemoŝ iros en kaptitecon kune kun siaj pastroj kaj eminentuloj."],[48,8,"Venos ruiniganto en ĉiun urbon, neniu urbo saviĝos; pereos la valo kaj dezertiĝos la ebenaĵo, kiel diris la Eternulo.","Venos ruiniganto en ĉiun urbon, neniu urbo saviĝos; pereos la valo kaj dezertiĝos la ebenaĵo, kiel diris la Eternulo."],[48,9,"Donu flugilojn al Moab, ĉar li devas forflugi; liaj urboj dezertiĝos tiel, ke neniu en ili loĝos.","Donu flugilojn al Moab, ĉar li devas forflugi; liaj urboj dezertiĝos tiel, ke neniu en ili loĝos."],[48,10,"Malbenita estu tiu, kiu plenumas malĝuste la faron de la Eternulo, kaj malbenita estu tiu, kiu detenas sian glavon de sango.","Malbenita estu tiu, kiu plenumas malĝuste la faron de la Eternulo, kaj malbenita estu tiu, kiu detenas sian glavon de sango."],[48,11,"De sia juneco Moab havis trankvilecon kaj ripozadis sur sia feĉo, li ne estis transverŝata el unu vazo en alian, kaj en kaptitecon li ne iris; tial lia gusto restis en li kaj lia odoro ne ŝanĝiĝis.","De sia juneco Moab havis trankvilecon kaj ripozadis sur sia feĉo, li ne estis transverŝata el unu vazo en alian, kaj en kaptitecon li ne iris; tial lia gusto restis en li kaj lia odoro ne ŝanĝiĝis."],[48,12,"Tial jen venos tempo, diras la Eternulo, kiam Mi sendos al li verŝistojn, kaj ili verŝos lin, malplenigos liajn vazojn, kaj disrompos liajn kruĉojn.","Tial jen venos tempo, diras la Eternulo, kiam Mi sendos al li verŝistojn, kaj ili verŝos lin, malplenigos liajn vazojn, kaj disrompos liajn kruĉojn."],[48,13,"Kaj Moab estos hontigita pro Kemoŝ, kiel la domo de Izrael estis hontigita pro Bet-El, kiun ili fidis.","Kaj Moab estos hontigita pro Kemoŝ, kiel la domo de Izrael estis hontigita pro Bet-El, kiun ili fidis."],[48,14,"Kiel vi povas diri: Ni estas herooj kaj kapabluloj por la milito?","Kiel vi povas diri: Ni estas herooj kaj kapabluloj por la milito?"],[48,15,"Ruinigita estas Moab, liaj urboj falis, kaj liaj plej bravaj junuloj iris al buĉo, diras al Reĝo, kies nomo estas Eternulo Cebaot.","Ruinigita estas Moab, liaj urboj falis, kaj liaj plej bravaj junuloj iris al buĉo, diras al Reĝo, kies nomo estas Eternulo Cebaot."],[48,16,"Baldaŭ venos pereo al Moab, kaj lia malfeliĉo tre rapidas.","Baldaŭ venos pereo al Moab, kaj lia malfeliĉo tre rapidas."],[48,17,"Bedaŭru lin ĉiuj liaj ĉirkaŭantoj, kaj ĉiuj, kiuj konas lian nomon, diru: Kiele disrompiĝis la forta vergo, la belega bastono!","Bedaŭru lin ĉiuj liaj ĉirkaŭantoj, kaj ĉiuj, kiuj konas lian nomon, diru: Kiele disrompiĝis la forta vergo, la belega bastono!"],[48,18,"Iru malsupren de via majesto, sidu en senakva loko, ho loĝantino, filino de Dibon; ĉar la ruiniganto de Moab elpaŝis kontraŭ vin kaj detruis viajn fortikaĵojn.","Iru malsupren de via majesto, sidu en senakva loko, ho loĝantino, filino de Dibon; ĉar la ruiniganto de Moab elpaŝis kontraŭ vin kaj detruis viajn fortikaĵojn."],[48,19,"Staru ĉe la vojo kaj rigardu, ho loĝantino de Aroer; demandu la forkuranton kaj la forsaviĝanton, kaj diru: Kio fariĝis?","Staru ĉe la vojo kaj rigardu, ho loĝantino de Aroer; demandu la forkuranton kaj la forsaviĝanton, kaj diru: Kio fariĝis?"],[48,20,"Hontigita estas Moab, ĉar li estas frapita; ploru kaj kriu, sciigu en Arnon, ke Moab estas ruinigita.","Hontigita estas Moab, ĉar li estas frapita; ploru kaj kriu, sciigu en Arnon, ke Moab estas ruinigita."],[48,21,"Juĝo venis kontraŭ la lando de la ebenaĵo, kontraŭ Ĥolon, Jahac, kaj Mefaat,","Juĝo venis kontraŭ la lando de la ebenaĵo, kontraŭ Ĥolon, Jahac, kaj Mefaat,"],[48,22,"kontraŭ Dibon, Nebo, kaj Bet-Diblataim,","kontraŭ Dibon, Nebo, kaj Bet-Diblataim,"],[48,23,"kontraŭ Kirjataim, Bet-Gamul, kaj Bet-Meon,","kontraŭ Kirjataim, Bet-Gamul, kaj Bet-Meon,"],[48,24,"kontraŭ Keriot kaj Bocra, kaj kontraŭ ĉiuj urboj de la lando de Moab, la malproksimaj kaj la proksimaj.","kontraŭ Keriot kaj Bocra, kaj kontraŭ ĉiuj urboj de la lando de Moab, la malproksimaj kaj la proksimaj."],[48,25,"Dehakita estas la korno de Moab, kaj lia brako estas rompita, diras la Eternulo.","Dehakita estas la korno de Moab, kaj lia brako estas rompita, diras la Eternulo."],[48,26,"Ebriigu lin, ĉar li leviĝis kontraŭ la Eternulo; Moab plaŭdos en sia vomaĵo, kaj li mem estos objekto de mokado.","Ebriigu lin, ĉar li leviĝis kontraŭ la Eternulo; Moab plaŭdos en sia vomaĵo, kaj li mem estos objekto de mokado."],[48,27,"Ĉu vi ne mokis Izraelon? ĉu oni trovis lin inter ŝtelistoj, ke ĉiufoje, kiam vi parolas pri li, vi balancas la kapon?","Ĉu vi ne mokis Izraelon? ĉu oni trovis lin inter ŝtelistoj, ke ĉiufoje, kiam vi parolas pri li, vi balancas la kapon?"],[48,28,"Forlasu la urbojn kaj ekloĝu sur roko, ho loĝantoj de Moab, kaj fariĝu kiel kolomboj, kiuj nestas en truoj de kavernoj.","Forlasu la urbojn kaj ekloĝu sur roko, ho loĝantoj de Moab, kaj fariĝu kiel kolomboj, kiuj nestas en truoj de kavernoj."],[48,29,"Ni aŭdis pri la fiereco de Moab, granda fiereco, pri lia malmodesteco, fiereco, aroganteco, kaj pri la malhumileco de lia koro.","Ni aŭdis pri la fiereco de Moab, granda fiereco, pri lia malmodesteco, fiereco, aroganteco, kaj pri la malhumileco de lia koro."],[48,30,"Mi konas, diras la Eternulo, lian koleremecon, la nesincerecon de liaj vortoj kaj la nesincerecon de liaj agoj.","Mi konas, diras la Eternulo, lian koleremecon, la nesincerecon de liaj vortoj kaj la nesincerecon de liaj agoj."],[48,31,"Tial Mi devas plori pri Moab, ĝemi pri ĉiuj Moabidoj, priplori la loĝantojn de Kir-Ĥeres.","Tial Mi devas plori pri Moab, ĝemi pri ĉiuj Moabidoj, priplori la loĝantojn de Kir-Ĥeres."],[48,32,"Per pli ol la plorado de Jazer Mi ploros pri vi, ho vinberĝardeno de Sibma; viaj branĉoj etendiĝis trans la maron, atingis la maron de Jazer; rabisto atakis viajn somerajn fruktojn kaj vian rikolton.","Per pli ol la plorado de Jazer Mi ploros pri vi, ho vinberĝardeno de Sibma; viaj branĉoj etendiĝis trans la maron, atingis la maron de Jazer; rabisto atakis viajn somerajn fruktojn kaj vian rikolton."],[48,33,"Foriĝis ĝojo kaj gajeco de la fruktodona kampo kaj de la lando de Moab; Mi malaperigis vinon en la vinpremejoj, oni ne premos tie kun ĝojo vinon, triumfaj kantoj ne plu sonos.","Foriĝis ĝojo kaj gajeco de la fruktodona kampo kaj de la lando de Moab; Mi malaperigis vinon en la vinpremejoj, oni ne premos tie kun ĝojo vinon, triumfaj kantoj ne plu sonos."],[48,34,"Pro la kriado, kiu aŭdiĝas de Ĥeŝbon ĝis Eleale kaj ĝis Jahac, ili laŭte ekploris de Coar ĝis Ĥoronaim kaj ĝis la tria Eglat; ĉar ankaŭ la akvo de Nimrim sekmalaperis.","Pro la kriado, kiu aŭdiĝas de Ĥeŝbon ĝis Eleale kaj ĝis Jahac, ili laŭte ekploris de Coar ĝis Ĥoronaim kaj ĝis la tria Eglat; ĉar ankaŭ la akvo de Nimrim sekmalaperis."],[48,35,"Mi ekstermos ĉe Moab, diras la Eternulo, ĉiun, kiu supreniras sur altaĵon kaj incensas al siaj dioj.","Mi ekstermos ĉe Moab, diras la Eternulo, ĉiun, kiu supreniras sur altaĵon kaj incensas al siaj dioj."],[48,36,"Tial Mia koro ĝemas pri Moab kiel fluto, kaj pri la loĝantoj de Kir-Ĥeres Mia koro ĝemas kiel fluto; ĉar la abundaĵo, kiun ili akiris, pereis.","Tial Mia koro ĝemas pri Moab kiel fluto, kaj pri la loĝantoj de Kir-Ĥeres Mia koro ĝemas kiel fluto; ĉar la abundaĵo, kiun ili akiris, pereis."],[48,37,"Ĉar ĉiu kapo kalviĝis, kaj ĉiu barbo estas fortondita, sur ĉiuj manoj estas tranĉoj, kaj sur la lumboj estas sakaĵo.","Ĉar ĉiu kapo kalviĝis, kaj ĉiu barbo estas fortondita, sur ĉiuj manoj estas tranĉoj, kaj sur la lumboj estas sakaĵo."],[48,38,"Sur ĉiuj tegmentoj de Moab kaj sur liaj stratoj ĉie estas plorado; ĉar Mi disrompis Moabon kiel senvaloran vazon, diras la Eternulo.","Sur ĉiuj tegmentoj de Moab kaj sur liaj stratoj ĉie estas plorado; ĉar Mi disrompis Moabon kiel senvaloran vazon, diras la Eternulo."],[48,39,"Kiele disbatita li estas, kiele ili ploregas! kiele Moab turnis sian nukon, estas hontigita, kaj Moab fariĝis objekto de mokado kaj de teruro por ĉiuj siaj ĉirkaŭantoj!","Kiele disbatita li estas, kiele ili ploregas! kiele Moab turnis sian nukon, estas hontigita, kaj Moab fariĝis objekto de mokado kaj de teruro por ĉiuj siaj ĉirkaŭantoj!"],[48,40,"Ĉar tiele diras la Eternulo: Jen li alflugos kiel aglo kaj etendos siajn flugilojn super Moab.","Ĉar tiele diras la Eternulo: Jen li alflugos kiel aglo kaj etendos siajn flugilojn super Moab."],[48,41,"Prenita estas Keriot, kaj la fortikigitaj urboj estas kaptitaj; kaj la koro de la herooj de Moab en tiu tago estos kiel la koro de virino dum la doloroj de naskado.","Prenita estas Keriot, kaj la fortikigitaj urboj estas kaptitaj; kaj la koro de la herooj de Moab en tiu tago estos kiel la koro de virino dum la doloroj de naskado."],[48,42,"Kaj Moab estos ekstermita, ke li ne plu estos popolo, ĉar li leviĝis kontraŭ la Eternulo.","Kaj Moab estos ekstermita, ke li ne plu estos popolo, ĉar li leviĝis kontraŭ la Eternulo."],[48,43,"Teruro, kavo, kaj kaptilo trafos vin, ho loĝanto de Moab, diras la Eternulo.","Teruro, kavo, kaj kaptilo trafos vin, ho loĝanto de Moab, diras la Eternulo."],[48,44,"Kiu forkuros de la teruro, tiu falos en la kavon; kaj kiu eliros el la kavo, tiu trafos en kaptilon; ĉar Mi venigos sur lin, sur Moabon, la jaron de lia puno, diras la Eternulo.","Kiu forkuros de la teruro, tiu falos en la kavon; kaj kiu eliros el la kavo, tiu trafos en kaptilon; ĉar Mi venigos sur lin, sur Moabon, la jaron de lia puno, diras la Eternulo."],[48,45,"Sub la ombro de Ĥeŝbon stariĝos tiuj, kiuj forkuros de la forto; sed fajro eliros el Ĥeŝbon kaj flamo el la mezo de Siĥon, kaj ĝi manĝegos la flankon de Moab kaj la verton de la filoj malkvietaj.","Sub la ombro de Ĥeŝbon stariĝos tiuj, kiuj forkuros de la forto; sed fajro eliros el Ĥeŝbon kaj flamo el la mezo de Siĥon, kaj ĝi manĝegos la flankon de Moab kaj la verton de la filoj malkvietaj."],[48,46,"Ve al vi, ho Moab! pereis la popolo de Kemoŝ; ĉar viaj filoj estas prenitaj en kaptitecon kaj viaj filinoj estas forkondukitaj.","Ve al vi, ho Moab! pereis la popolo de Kemoŝ; ĉar viaj filoj estas prenitaj en kaptitecon kaj viaj filinoj estas forkondukitaj."],[48,47,"Sed en la tempo estonta Mi revenigos la kaptitojn de Moab, diras la Eternulo. Ĝis ĉi tie estas la verdikto pri Moab.","Sed en la tempo estonta Mi revenigos la kaptitojn de Moab, diras la Eternulo. Ĝis ĉi tie estas la verdikto pri Moab."],[49,1,"Pri la Amonidoj: Tiele diras la Eternulo: Ĉu Izrael ne havas filojn? ĉu li ne havas heredanton? kial do Malkam heredis Gadon kaj lia popolo loĝas en la urboj de ĉi tiu?","Pri la Amonidoj: Tiele diras la Eternulo: Ĉu Izrael ne havas filojn? ĉu li ne havas heredanton? kial do Malkam heredis Gadon kaj lia popolo loĝas en la urboj de ĉi tiu?"],[49,2,"Tial jen venos tempo, diras la Eternulo, kaj Mi eksonigos militan trumpetadon super Raba de la Amonidoj; kaj ĝi fariĝos amaso da ruinoj, kaj ĝiaj filinoj forbrulos en fajro, kaj Izrael ekposedos siajn posedintojn, diras la Eternulo.","Tial jen venos tempo, diras la Eternulo, kaj Mi eksonigos militan trumpetadon super Raba de la Amonidoj; kaj ĝi fariĝos amaso da ruinoj, kaj ĝiaj filinoj forbrulos en fajro, kaj Izrael ekposedos siajn posedintojn, diras la Eternulo."],[49,3,"Ploregu, ho Ĥeŝbon, ĉar Aj estas ruinigita. Kriu, ho filinoj de Raba, zonu vin per sakaĵo, ploru kaj vagadu inter la bariloj; ĉar Malkam iras en kaptitecon kune kun siaj pastroj kaj eminentuloj.","Ploregu, ho Ĥeŝbon, ĉar Aj estas ruinigita. Kriu, ho filinoj de Raba, zonu vin per sakaĵo, ploru kaj vagadu inter la bariloj; ĉar Malkam iras en kaptitecon kune kun siaj pastroj kaj eminentuloj."],[49,4,"Kial vi fanfaronas pri viaj valoj? sangon fluigas via valo, ho filino malobeema, kiu fidas siajn trezorojn, kaj diras: Kiu povas veni al mi?","Kial vi fanfaronas pri viaj valoj? sangon fluigas via valo, ho filino malobeema, kiu fidas siajn trezorojn, kaj diras: Kiu povas veni al mi?"],[49,5,"Jen Mi venigos sur vin timon, diras la Sinjoro, la Eternulo Cebaot, de ĉiuj viaj ĉirkaŭaĵoj; kaj vi estos dispelitaj ĉiu aparte, kaj neniu kolektos la vagantojn.","Jen Mi venigos sur vin timon, diras la Sinjoro, la Eternulo Cebaot, de ĉiuj viaj ĉirkaŭaĵoj; kaj vi estos dispelitaj ĉiu aparte, kaj neniu kolektos la vagantojn."],[49,6,"Tamen poste Mi revenigos la forkaptitajn Amonidojn, diras la Eternulo.","Tamen poste Mi revenigos la forkaptitajn Amonidojn, diras la Eternulo."],[49,7,"Pri Edom: Tiele diras la Eternulo Cebaot: Ĉu jam ne ekzistas saĝo en Teman? ĉu la filoj jam ne havas konsilon? ĉu ilia saĝeco malaperis?","Pri Edom: Tiele diras la Eternulo Cebaot: Ĉu jam ne ekzistas saĝo en Teman? ĉu la filoj jam ne havas konsilon? ĉu ilia saĝeco malaperis?"],[49,8,"Forkuras, turnis sian dorson, kaj profunde sin kaŝas la loĝantoj de Dedan; ĉar malfeliĉon de Esav Mi venigis sur lin, la tempon de lia puno.","Forkuras, turnis sian dorson, kaj profunde sin kaŝas la loĝantoj de Dedan; ĉar malfeliĉon de Esav Mi venigis sur lin, la tempon de lia puno."],[49,9,"Kiam venos al vi vinberkolektantoj, ili ne restigos forgesitajn berojn; se venos ŝtelistoj en la nokto, ili rabos plenan kvanton.","Kiam venos al vi vinberkolektantoj, ili ne restigos forgesitajn berojn; se venos ŝtelistoj en la nokto, ili rabos plenan kvanton."],[49,10,"Ĉar Mi nudigis Esavon, Mi malkaŝis liajn sekretajn rifuĝejojn, por ke li ne povu sin kaŝi; ekstermitaj estas lia idaro, liaj fratoj, kaj liaj najbaroj, kaj li jam ne ekzistas.","Ĉar Mi nudigis Esavon, Mi malkaŝis liajn sekretajn rifuĝejojn, por ke li ne povu sin kaŝi; ekstermitaj estas lia idaro, liaj fratoj, kaj liaj najbaroj, kaj li jam ne ekzistas."],[49,11,"Restigu viajn orfojn, Mi konservos ilian vivon; kaj viaj vidvinoj fidu Min.","Restigu viajn orfojn, Mi konservos ilian vivon; kaj viaj vidvinoj fidu Min."],[49,12,"Ĉar tiele diras la Eternulo: Jen tiuj, kiuj ne meritis trinki la pokalon, tamen ĝin trinkos; ĉu vi do povas resti nepunita? vi ne restos nepunita, sed vi nepre trinkos.","Ĉar tiele diras la Eternulo: Jen tiuj, kiuj ne meritis trinki la pokalon, tamen ĝin trinkos; ĉu vi do povas resti nepunita? vi ne restos nepunita, sed vi nepre trinkos."],[49,13,"Ĉar Mi ĵuris per Mi, diras la Eternulo, ke Bocra fariĝos objekto de teruro, honto, ruinigo, kaj malbeno; kaj ĉiuj ĝiaj urboj fariĝos ruinoj por eterne.","Ĉar Mi ĵuris per Mi, diras la Eternulo, ke Bocra fariĝos objekto de teruro, honto, ruinigo, kaj malbeno; kaj ĉiuj ĝiaj urboj fariĝos ruinoj por eterne."],[49,14,"Diron mi aŭdis de la Eternulo, kaj kuriero estas sendita al la nacioj: Kolektiĝu kaj iru kontraŭ ĝin, kaj leviĝu por batalo.","Diron mi aŭdis de la Eternulo, kaj kuriero estas sendita al la nacioj: Kolektiĝu kaj iru kontraŭ ĝin, kaj leviĝu por batalo."],[49,15,"Ĉar jen Mi faris vin malgranda inter la nacioj, malestimata inter la homoj.","Ĉar jen Mi faris vin malgranda inter la nacioj, malestimata inter la homoj."],[49,16,"Via malhumileco kaj la fiereco de via koro trompis vin, kiu loĝas en la fendegoj de la rokoj kaj okupas suprojn de montoj; sed se vi eĉ aranĝus vian neston tiel alte, kiel aglo, eĉ de tie Mi ĵetos vin malsupren, diras la Eternulo.","Via malhumileco kaj la fiereco de via koro trompis vin, kiu loĝas en la fendegoj de la rokoj kaj okupas suprojn de montoj; sed se vi eĉ aranĝus vian neston tiel alte, kiel aglo, eĉ de tie Mi ĵetos vin malsupren, diras la Eternulo."],[49,17,"Edom fariĝos objekto de teruro; ĉiu, kiu pasos preter li, miros kaj fajfos pri ĉiuj liaj vundoj.","Edom fariĝos objekto de teruro; ĉiu, kiu pasos preter li, miros kaj fajfos pri ĉiuj liaj vundoj."],[49,18,"Kiel renversitaj estas Sodom kaj Gomora kaj iliaj najbarlokoj, diras la Eternulo, tiel ankaŭ tie neniu restos, neniu homido tie loĝos.","Kiel renversitaj estas Sodom kaj Gomora kaj iliaj najbarlokoj, diras la Eternulo, tiel ankaŭ tie neniu restos, neniu homido tie loĝos."],[49,19,"Jen kiel leono li supreniras de la majesta Jordan kontraŭ la fortikan loĝejon; ĉar Mi rapide forpelos ilin de tie, kaj Mi estrigos tie tiun, kiu estas elektita. Ĉar kiu estas simila al Mi? kiu donos al Mi decidojn? kiu estas la paŝtisto, kiu povas kontraŭstari al Mi?","Jen kiel leono li supreniras de la majesta Jordan kontraŭ la fortikan loĝejon; ĉar Mi rapide forpelos ilin de tie, kaj Mi estrigos tie tiun, kiu estas elektita. Ĉar kiu estas simila al Mi? kiu donos al Mi decidojn? kiu estas la paŝtisto, kiu povas kontraŭstari al Mi?"],[49,20,"Tial aŭskultu la decidon de la Eternulo, kiun Li decidis pri Edom, kaj Liajn intencojn, kiujn Li havas pri la loĝantoj de Teman: la knaboj-paŝtistoj ilin fortrenos kaj detruos super ili ilian loĝejon.","Tial aŭskultu la decidon de la Eternulo, kiun Li decidis pri Edom, kaj Liajn intencojn, kiujn Li havas pri la loĝantoj de Teman: la knaboj-paŝtistoj ilin fortrenos kaj detruos super ili ilian loĝejon."],[49,21,"De la bruo de ilia falo ektremos la tero, ilian kriadon oni aŭdos ĉe la Ruĝa Maro.","De la bruo de ilia falo ektremos la tero, ilian kriadon oni aŭdos ĉe la Ruĝa Maro."],[49,22,"Jen li leviĝos kiel aglo, ekflugos kaj etendos siajn flugilojn super Bocra; kaj la koro de la herooj de Edom en tiu tago estos kiel la koro de virino ĉe la naskodoloroj.","Jen li leviĝos kiel aglo, ekflugos kaj etendos siajn flugilojn super Bocra; kaj la koro de la herooj de Edom en tiu tago estos kiel la koro de virino ĉe la naskodoloroj."],[49,23,"Pri Damasko: Hontigitaj estas Ĥamat kaj Arpad, ĉar, aŭdinte malbonan sciigon, ili senkuraĝiĝis; ĉe la maro ili tiel ektremis, ke ili ne povas trankviliĝi.","Pri Damasko: Hontigitaj estas Ĥamat kaj Arpad, ĉar, aŭdinte malbonan sciigon, ili senkuraĝiĝis; ĉe la maro ili tiel ektremis, ke ili ne povas trankviliĝi."],[49,24,"Damasko senkuraĝiĝis, turnis sin, por forkuri; tremo atakis ĝin, doloro kaj turmentoj ĝin kaptis, kiel naskantinon.","Damasko senkuraĝiĝis, turnis sin, por forkuri; tremo atakis ĝin, doloro kaj turmentoj ĝin kaptis, kiel naskantinon."],[49,25,"Kial ne estas riparita la glora urbo, la gaja urbo?","Kial ne estas riparita la glora urbo, la gaja urbo?"],[49,26,"Tial ĝiaj junuloj falos sur ĝiaj stratoj, kaj ĉiuj militistoj pereos en tiu tago, diras la Eternulo Cebaot.","Tial ĝiaj junuloj falos sur ĝiaj stratoj, kaj ĉiuj militistoj pereos en tiu tago, diras la Eternulo Cebaot."],[49,27,"Kaj Mi ekbruligos fajron sur la murego de Damasko, kaj ĝi ekstermos la palacojn de Ben-Hadad.","Kaj Mi ekbruligos fajron sur la murego de Damasko, kaj ĝi ekstermos la palacojn de Ben-Hadad."],[49,28,"Pri Kedar, kaj pri la regnoj de Ĥacor, kiujn venkobatis Nebukadnecar, reĝo de Babel: Tiele diras la Eternulo: Leviĝu, iru kontraŭ Kedaron, kaj ruinigu la filojn de la oriento.","Pri Kedar, kaj pri la regnoj de Ĥacor, kiujn venkobatis Nebukadnecar, reĝo de Babel: Tiele diras la Eternulo: Leviĝu, iru kontraŭ Kedaron, kaj ruinigu la filojn de la oriento."],[49,29,"Iliaj tendoj kaj ŝafaroj estos prenitaj; iliajn tapiŝojn kaj ĉiujn iliajn vazojn kaj iliajn kamelojn oni forprenos, kaj oni kriados al ili: Teruro ĉirkaŭe.","Iliaj tendoj kaj ŝafaroj estos prenitaj; iliajn tapiŝojn kaj ĉiujn iliajn vazojn kaj iliajn kamelojn oni forprenos, kaj oni kriados al ili: Teruro ĉirkaŭe."],[49,30,"Forkuru, foriĝu rapide, kaŝu vin profunde, ho loĝantoj de Ĥacor, diras la Eternulo; ĉar Nebukadnecar, reĝo de Babel, faras pri vi decidon kaj havas intencon kontraŭ vi.","Forkuru, foriĝu rapide, kaŝu vin profunde, ho loĝantoj de Ĥacor, diras la Eternulo; ĉar Nebukadnecar, reĝo de Babel, faras pri vi decidon kaj havas intencon kontraŭ vi."],[49,31,"Leviĝu, iru kontraŭ popolon trankvilan, kiu sidas en sendanĝereco, diras la Eternulo; ĝi ne havas pordojn nek riglilojn, ili vivas izolite.","Leviĝu, iru kontraŭ popolon trankvilan, kiu sidas en sendanĝereco, diras la Eternulo; ĝi ne havas pordojn nek riglilojn, ili vivas izolite."],[49,32,"Kaj iliaj kameloj estos forrabitaj, kaj la multo de iliaj brutoj fariĝos rabakiro; kaj Mi dispelos ilin al ĉiuj ventoj, ilin, kiuj tondas la harojn sur la tempioj, kaj de ĉiuj flankoj Mi venigos ilian malfeliĉon, diras la Eternulo.","Kaj iliaj kameloj estos forrabitaj, kaj la multo de iliaj brutoj fariĝos rabakiro; kaj Mi dispelos ilin al ĉiuj ventoj, ilin, kiuj tondas la harojn sur la tempioj, kaj de ĉiuj flankoj Mi venigos ilian malfeliĉon, diras la Eternulo."],[49,33,"Kaj Ĥacor fariĝos loĝejo de ŝakaloj, eterna dezerto; neniu tie restos, kaj neniu homido tie loĝos.","Kaj Ĥacor fariĝos loĝejo de ŝakaloj, eterna dezerto; neniu tie restos, kaj neniu homido tie loĝos."],[49,34,"Jen estas la vorto de la Eternulo, kiu aperis al la profeto Jeremia pri Elam, en la komenco de la reĝado de Cidkija, reĝo de Judujo:","Jen estas la vorto de la Eternulo, kiu aperis al la profeto Jeremia pri Elam, en la komenco de la reĝado de Cidkija, reĝo de Judujo:"],[49,35,"Tiele diras la Eternulo Cebaot: Jen Mi rompos la pafarkon de Elam, ilian ĉefan forton.","Tiele diras la Eternulo Cebaot: Jen Mi rompos la pafarkon de Elam, ilian ĉefan forton."],[49,36,"Kaj Mi venigos sur Elamon kvar ventojn de la kvar finoj de la ĉielo, kaj Mi dispelos ilin al ĉiuj tiuj ventoj; kaj ne ekzistos popolo, al kiu ne venus la dispelitoj el Elam.","Kaj Mi venigos sur Elamon kvar ventojn de la kvar finoj de la ĉielo, kaj Mi dispelos ilin al ĉiuj tiuj ventoj; kaj ne ekzistos popolo, al kiu ne venus la dispelitoj el Elam."],[49,37,"Kaj Mi senkuraĝigos Elamon antaŭ iliaj malamikoj, kaj antaŭ tiuj, kiuj celas ilian morton; kaj Mi venigos sur ilin malbonon, la flamon de Mia kolero, diras la Eternulo, kaj Mi persekutos ilin per la glavo, ĝis Mi ekstermos ilin.","Kaj Mi senkuraĝigos Elamon antaŭ iliaj malamikoj, kaj antaŭ tiuj, kiuj celas ilian morton; kaj Mi venigos sur ilin malbonon, la flamon de Mia kolero, diras la Eternulo, kaj Mi persekutos ilin per la glavo, ĝis Mi ekstermos ilin."],[49,38,"Kaj Mi starigos Mian tronon en Elam, kaj Mi pereigos tie la reĝon kaj la eminentulojn, diras la Eternulo.","Kaj Mi starigos Mian tronon en Elam, kaj Mi pereigos tie la reĝon kaj la eminentulojn, diras la Eternulo."],[49,39,"Tamen en la tempo estonta Mi revenigos la forkaptitojn de Elam, diras la Eternulo.","Tamen en la tempo estonta Mi revenigos la forkaptitojn de Elam, diras la Eternulo."],[50,1,"Jen estas la vorto, kiun la Eternulo diris per la profeto Jeremia pri Babel kaj pri la lando de la Ĥaldeoj:","Jen estas la vorto, kiun la Eternulo diris per la profeto Jeremia pri Babel kaj pri la lando de la Ĥaldeoj:"],[50,2,"Sciigu al la nacioj kaj proklamu, levu standardon, proklamu, ne kaŝu, diru: Prenita estas Babel, hontigita estas Bel, frakasita estas Merodaĥ, hontigitaj estas ĝiaj idoloj, frakasitaj estas ĝiaj statuoj.","Sciigu al la nacioj kaj proklamu, levu standardon, proklamu, ne kaŝu, diru: Prenita estas Babel, hontigita estas Bel, frakasita estas Merodaĥ, hontigitaj estas ĝiaj idoloj, frakasitaj estas ĝiaj statuoj."],[50,3,"Ĉar eliris kontraŭ ĝin popolo el la nordo, kiu faros ĝian landon dezerto, kaj ne plu estos loĝanto en ĝi: de homo ĝis bruto ĉio foriĝos kaj foriros.","Ĉar eliris kontraŭ ĝin popolo el la nordo, kiu faros ĝian landon dezerto, kaj ne plu estos loĝanto en ĝi: de homo ĝis bruto ĉio foriĝos kaj foriros."],[50,4,"En tiuj tagoj kaj en tiu tempo, diras la Eternulo, venos la idoj de Izrael kune kun la idoj de Jehuda; ili iros kaj ploros, kaj serĉos la Eternulon, sian Dion.","En tiuj tagoj kaj en tiu tempo, diras la Eternulo, venos la idoj de Izrael kune kun la idoj de Jehuda; ili iros kaj ploros, kaj serĉos la Eternulon, sian Dion."],[50,5,"Pri la vojo al Cion ili demandos, tien estos turnita ilia vizaĝo: Venu, ni aliĝos al la Eternulo per interligo eterna, neforgesebla.","Pri la vojo al Cion ili demandos, tien estos turnita ilia vizaĝo: Venu, ni aliĝos al la Eternulo per interligo eterna, neforgesebla."],[50,6,"Mia popolo estis kiel erarvagantaj ŝafoj: ili paŝtistoj delogis ilin, erarvagigis ilin sur la montoj; de monto sur monteton ili vagis, ili forgesis sian ŝafejon.","Mia popolo estis kiel erarvagantaj ŝafoj: ili paŝtistoj delogis ilin, erarvagigis ilin sur la montoj; de monto sur monteton ili vagis, ili forgesis sian ŝafejon."],[50,7,"Ĉiuj, kiuj renkontis ilin, manĝis ilin; kaj iliaj malamikoj diris: Ni ne estas kulpaj, ĉar ili pekis antaŭ la Eternulo, la loĝejo de la vero, antaŭ la espero de iliaj patroj, la Eternulo.","Ĉiuj, kiuj renkontis ilin, manĝis ilin; kaj iliaj malamikoj diris: Ni ne estas kulpaj, ĉar ili pekis antaŭ la Eternulo, la loĝejo de la vero, antaŭ la espero de iliaj patroj, la Eternulo."],[50,8,"Kuru el Babel kaj eliru el la lando de la Ĥaldeoj, kaj estu kiel virkaproj antaŭ la ŝafoj.","Kuru el Babel kaj eliru el la lando de la Ĥaldeoj, kaj estu kiel virkaproj antaŭ la ŝafoj."],[50,9,"Ĉar jen Mi vekos kaj venigos sur Babelon amason da grandaj popoloj el lando norda, kaj ili aranĝos sin kontraŭ ĝi, kaj ĝi estos venkoprenita; iliaj sagoj, kiel lerta heroo, ne revenas vane.","Ĉar jen Mi vekos kaj venigos sur Babelon amason da grandaj popoloj el lando norda, kaj ili aranĝos sin kontraŭ ĝi, kaj ĝi estos venkoprenita; iliaj sagoj, kiel lerta heroo, ne revenas vane."],[50,10,"Kaj Ĥaldeujo fariĝos militakiro; ĉiuj ĝiaj prirabantoj satiĝos, diras la Eternulo.","Kaj Ĥaldeujo fariĝos militakiro; ĉiuj ĝiaj prirabantoj satiĝos, diras la Eternulo."],[50,11,"Ĉar vi ĝojis, ĉar vi triumfis, ho rabintoj de Mia heredaĵo, ĉar vi saltis, kiel bovidino sur herbo, kaj blekis, kiel fortaj ĉevaloj,","Ĉar vi ĝojis, ĉar vi triumfis, ho rabintoj de Mia heredaĵo, ĉar vi saltis, kiel bovidino sur herbo, kaj blekis, kiel fortaj ĉevaloj,"],[50,12,"tre hontigita estas via patrino, mokata estas via naskintino; jen estas la estonteco de la nacioj: dezerto, neloĝata tero, kaj stepo.","tre hontigita estas via patrino, mokata estas via naskintino; jen estas la estonteco de la nacioj: dezerto, neloĝata tero, kaj stepo."],[50,13,"De la kolero de la Eternulo ĝi fariĝos neloĝata, kaj ĝi tuta fariĝos dezerta; ĉiu, kiu iros preter Babel, miros kaj fajfos pri ĉiuj ĝiaj vundoj.","De la kolero de la Eternulo ĝi fariĝos neloĝata, kaj ĝi tuta fariĝos dezerta; ĉiu, kiu iros preter Babel, miros kaj fajfos pri ĉiuj ĝiaj vundoj."],[50,14,"Pretigu vin kontraŭ Babel ĉirkaŭe, ĉiuj streĉantoj de pafarkoj, pafu sur ĝin, ne domaĝu sagojn; ĉar ĝi pekis antaŭ la Eternulo.","Pretigu vin kontraŭ Babel ĉirkaŭe, ĉiuj streĉantoj de pafarkoj, pafu sur ĝin, ne domaĝu sagojn; ĉar ĝi pekis antaŭ la Eternulo."],[50,15,"Triumfe kriu kontraŭ ĝi ĉirkaŭe; malleviĝis ĝia mano, falis ĝia fundamento, detruiĝis ĝiaj muregoj; ĉar tio estas venĝo de la Eternulo; venĝu al ĝi; kiel ĝi agis, tiel agu kontraŭ ĝi.","Triumfe kriu kontraŭ ĝi ĉirkaŭe; malleviĝis ĝia mano, falis ĝia fundamento, detruiĝis ĝiaj muregoj; ĉar tio estas venĝo de la Eternulo; venĝu al ĝi; kiel ĝi agis, tiel agu kontraŭ ĝi."],[50,16,"Ekstermu el Babel semanton kaj rikoltanton en la tempo de rikoltado; de la glavo de la tirano ĉiu sin turnu al sia popolo, kaj ĉiu forkuru en sian landon.","Ekstermu el Babel semanton kaj rikoltanton en la tempo de rikoltado; de la glavo de la tirano ĉiu sin turnu al sia popolo, kaj ĉiu forkuru en sian landon."],[50,17,"Izrael estas kiel disĵetita ŝafaro; leonoj lin dispelis: la unua manĝis lin la reĝo de Asirio, kaj ĉi tiu lasta, Nebukadnecar, reĝo de Babel, rompis al li la ostojn.","Izrael estas kiel disĵetita ŝafaro; leonoj lin dispelis: la unua manĝis lin la reĝo de Asirio, kaj ĉi tiu lasta, Nebukadnecar, reĝo de Babel, rompis al li la ostojn."],[50,18,"Tial tiele diras la Eternulo Cebaot, Dio de Izrael: Jen Mi punos la reĝon de Babel kaj lian landon, kiel Mi punis la reĝon de Asirio.","Tial tiele diras la Eternulo Cebaot, Dio de Izrael: Jen Mi punos la reĝon de Babel kaj lian landon, kiel Mi punis la reĝon de Asirio."],[50,19,"Kaj Mi revenigos Izraelon en lian loĝejon, kaj li paŝtiĝos sur Karmel kaj Baŝan, kaj sur la monto de Efraim kaj en Gilead lia animo satiĝos.","Kaj Mi revenigos Izraelon en lian loĝejon, kaj li paŝtiĝos sur Karmel kaj Baŝan, kaj sur la monto de Efraim kaj en Gilead lia animo satiĝos."],[50,20,"En tiuj tagoj kaj en tiu tempo, diras la Eternulo, oni serĉos malbonagon de Izrael, sed ĝi ne estos, kaj pekon de Jehuda, sed ĝi ne troviĝos; ĉar Mi pardonos al tiuj, kiujn Mi restigos.","En tiuj tagoj kaj en tiu tempo, diras la Eternulo, oni serĉos malbonagon de Izrael, sed ĝi ne estos, kaj pekon de Jehuda, sed ĝi ne troviĝos; ĉar Mi pardonos al tiuj, kiujn Mi restigos."],[50,21,"Iru kontraŭ la landon de la maldolĉigantoj, kontraŭ ĝin kaj kontraŭ la loĝantojn de la punejo; ruinigu kaj ekstermu ĉion post ili, diras la Eternulo, kaj faru ĉion tiel, kiel Mi ordonis al vi.","Iru kontraŭ la landon de la maldolĉigantoj, kontraŭ ĝin kaj kontraŭ la loĝantojn de la punejo; ruinigu kaj ekstermu ĉion post ili, diras la Eternulo, kaj faru ĉion tiel, kiel Mi ordonis al vi."],[50,22,"Bruo de batalo estas en la lando, kaj granda frakasado.","Bruo de batalo estas en la lando, kaj granda frakasado."],[50,23,"Kiele rompita kaj frakasita estas la martelo de la tuta tero! kiele dezertiĝis Babel inter la nacioj!","Kiele rompita kaj frakasita estas la martelo de la tuta tero! kiele dezertiĝis Babel inter la nacioj!"],[50,24,"Mi starigis reton por vi, kaj vi estas kaptita, ho Babel, antaŭ ol vi tion rimarkis; vi estas trovita kaj kaptita, ĉar vi leviĝis kontraŭ la Eternulon.","Mi starigis reton por vi, kaj vi estas kaptita, ho Babel, antaŭ ol vi tion rimarkis; vi estas trovita kaj kaptita, ĉar vi leviĝis kontraŭ la Eternulon."],[50,25,"La Eternulo malfermis Sian trezorejon, kaj elprenis el tie la ilojn de Sia kolero; ĉar ion por fari havas la Sinjoro, la Eternulo Cebaot, en la lando de la Ĥaldeoj.","La Eternulo malfermis Sian trezorejon, kaj elprenis el tie la ilojn de Sia kolero; ĉar ion por fari havas la Sinjoro, la Eternulo Cebaot, en la lando de la Ĥaldeoj."],[50,26,"Iru kontraŭ ĝin de plej malproksime, malfermu ĝiajn grenejojn, piedpremu ĝin kiel amasaĵon, ekstermu ĝin, ke nenio de ĝi restu.","Iru kontraŭ ĝin de plej malproksime, malfermu ĝiajn grenejojn, piedpremu ĝin kiel amasaĵon, ekstermu ĝin, ke nenio de ĝi restu."],[50,27,"Dishaku per glavo ĉiujn ĝiajn bovojn; ili estu buĉataj. Ve al ili! ĉar venis ilia tago, la tempo de ilia puno.","Dishaku per glavo ĉiujn ĝiajn bovojn; ili estu buĉataj. Ve al ili! ĉar venis ilia tago, la tempo de ilia puno."],[50,28,"Aŭdiĝas voĉo de forkurantoj kaj forsaviĝantoj el la lando Babela, por sciigi en Cion pri la venĝo de la Eternulo, nia Dio, pri la venĝo pro Lia templo.","Aŭdiĝas voĉo de forkurantoj kaj forsaviĝantoj el la lando Babela, por sciigi en Cion pri la venĝo de la Eternulo, nia Dio, pri la venĝo pro Lia templo."],[50,29,"Alvoku multajn kontraŭ Babelon, ĉiujn, kiuj streĉas pafarkon; stariĝu tendare ĉirkaŭ ĝi, ke neniu povu forsaviĝi el ĝi; repagu al ĝi laŭ ĝiaj agoj: ĉion, kion ĝi faris, faru al ĝi; ĉar ĝi estis malhumila kontraŭ la Eternulo, kontraŭ la Sanktulo de Izrael.","Alvoku multajn kontraŭ Babelon, ĉiujn, kiuj streĉas pafarkon; stariĝu tendare ĉirkaŭ ĝi, ke neniu povu forsaviĝi el ĝi; repagu al ĝi laŭ ĝiaj agoj: ĉion, kion ĝi faris, faru al ĝi; ĉar ĝi estis malhumila kontraŭ la Eternulo, kontraŭ la Sanktulo de Izrael."],[50,30,"Pro tio ĝiaj junuloj falos sur ĝiaj stratoj, kaj ĉiuj ĝiaj militistoj pereos en tiu tago, diras la Eternulo.","Pro tio ĝiaj junuloj falos sur ĝiaj stratoj, kaj ĉiuj ĝiaj militistoj pereos en tiu tago, diras la Eternulo."],[50,31,"Jen Mi estas kontraŭ vi, ho malhumilulo, diras la Sinjoro, la Eternulo Cebaot; ĉar venis via tago, la tempo de via puno.","Jen Mi estas kontraŭ vi, ho malhumilulo, diras la Sinjoro, la Eternulo Cebaot; ĉar venis via tago, la tempo de via puno."],[50,32,"Kaj la malhumilulo falpuŝiĝos kaj falos, kaj neniu lin levos; kaj Mi ekbruligos fajron en liaj urboj, kaj ĝi ekstermos ĉiujn liajn ĉirkaŭaĵojn.","Kaj la malhumilulo falpuŝiĝos kaj falos, kaj neniu lin levos; kaj Mi ekbruligos fajron en liaj urboj, kaj ĝi ekstermos ĉiujn liajn ĉirkaŭaĵojn."],[50,33,"Tiele diras la Eternulo Cebaot: Turmentataj estas la idoj de Izrael kune kun la idoj de Jehuda; kaj ĉiuj iliaj kaptintoj forte ilin tenas, ne volas forliberigi ilin.","Tiele diras la Eternulo Cebaot: Turmentataj estas la idoj de Izrael kune kun la idoj de Jehuda; kaj ĉiuj iliaj kaptintoj forte ilin tenas, ne volas forliberigi ilin."],[50,34,"Sed ilia Liberiganto estas forta, Eternulo Cebaot estas Lia nomo; Li defendos ilian aferon tiel, ke la tero skuiĝos kaj la loĝantoj de Babel ektremos.","Sed ilia Liberiganto estas forta, Eternulo Cebaot estas Lia nomo; Li defendos ilian aferon tiel, ke la tero skuiĝos kaj la loĝantoj de Babel ektremos."],[50,35,"Glavo falu sur la Ĥaldeojn, diras la Eternulo, sur la loĝantojn de Babel, sur ĝiajn eminentulojn kaj saĝulojn;","Glavo falu sur la Ĥaldeojn, diras la Eternulo, sur la loĝantojn de Babel, sur ĝiajn eminentulojn kaj saĝulojn;"],[50,36,"glavo sur la antaŭdiristojn, ke ili malsaĝiĝu; glavo sur ĝiajn heroojn, ke ili senkuraĝiĝu;","glavo sur la antaŭdiristojn, ke ili malsaĝiĝu; glavo sur ĝiajn heroojn, ke ili senkuraĝiĝu;"],[50,37,"glavo sur ĝiajn ĉevalojn kaj sur ĝiajn ĉarojn, kaj sur ĉiujn diversgentajn loĝantojn, kiuj estas en ĝi, ke ili fariĝu kiel virinoj; glavo sur ĝiajn trezorojn, ke ili estu disrabitaj.","glavo sur ĝiajn ĉevalojn kaj sur ĝiajn ĉarojn, kaj sur ĉiujn diversgentajn loĝantojn, kiuj estas en ĝi, ke ili fariĝu kiel virinoj; glavo sur ĝiajn trezorojn, ke ili estu disrabitaj."],[50,38,"Sekeco trafu ĝiajn akvojn, ke ili malaperu; ĉar tio estas lando de idoloj, kaj pri siaj monstroj ili fanfaronas.","Sekeco trafu ĝiajn akvojn, ke ili malaperu; ĉar tio estas lando de idoloj, kaj pri siaj monstroj ili fanfaronas."],[50,39,"Tial tie ekloĝos stepaj bestoj kaj ŝakaloj, kaj strutoj en ĝi loĝos; ĝi neniam plu estos loĝata, kaj neniu tie havos domon en ĉiuj venontaj generacioj.","Tial tie ekloĝos stepaj bestoj kaj ŝakaloj, kaj strutoj en ĝi loĝos; ĝi neniam plu estos loĝata, kaj neniu tie havos domon en ĉiuj venontaj generacioj."],[50,40,"Kiel Dio renversis Sodomon kaj Gomoran kaj iliajn najbarlokojn, diras la Eternulo, tiel ankaŭ tie restos neniu kaj loĝos neniu homido.","Kiel Dio renversis Sodomon kaj Gomoran kaj iliajn najbarlokojn, diras la Eternulo, tiel ankaŭ tie restos neniu kaj loĝos neniu homido."],[50,41,"Jen venas popolo el nordo, granda nacio kaj multe da reĝoj leviĝas de la randoj de la tero.","Jen venas popolo el nordo, granda nacio kaj multe da reĝoj leviĝas de la randoj de la tero."],[50,42,"Pafarkon kaj lancon ili tenas forte; kruelaj ili estas kaj senkompataj; ilia voĉo bruas kiel maro; sur ĉevaloj ili rajdas, armite por la batalo kiel unu homo, kontraŭ vin, ho filino de Babel.","Pafarkon kaj lancon ili tenas forte; kruelaj ili estas kaj senkompataj; ilia voĉo bruas kiel maro; sur ĉevaloj ili rajdas, armite por la batalo kiel unu homo, kontraŭ vin, ho filino de Babel."],[50,43,"Aŭdis la reĝo de Babel la sciigon pri ili, kaj senfortiĝis liaj manoj; suferego atakis lin, doloro kiel ĉe naskantino.","Aŭdis la reĝo de Babel la sciigon pri ili, kaj senfortiĝis liaj manoj; suferego atakis lin, doloro kiel ĉe naskantino."],[50,44,"Jen kiel leono li supreniras de la majesta Jordan kontraŭ la fortikan loĝejon; ĉar Mi rapide forpelos ilin de tie, kaj Mi estrigos tie tiun, kiu estas elektita. Ĉar kiu estas simila al Mi? kiu donos al Mi decidojn? kaj kiu estas la paŝtisto, kiu povas kontraŭstari al Mi?","Jen kiel leono li supreniras de la majesta Jordan kontraŭ la fortikan loĝejon; ĉar Mi rapide forpelos ilin de tie, kaj Mi estrigos tie tiun, kiu estas elektita. Ĉar kiu estas simila al Mi? kiu donos al Mi decidojn? kaj kiu estas la paŝtisto, kiu povas kontraŭstari al Mi?"],[50,45,"Tial aŭskultu la decidon de la Eternulo, kiun Li decidis pri Babel, kaj Liajn intencojn, kiujn Li havas pri la lando de la Ĥaldeoj: la knaboj-paŝtistoj ilin fortrenos, kaj detruos super ili ilian loĝejon.","Tial aŭskultu la decidon de la Eternulo, kiun Li decidis pri Babel, kaj Liajn intencojn, kiujn Li havas pri la lando de la Ĥaldeoj: la knaboj-paŝtistoj ilin fortrenos, kaj detruos super ili ilian loĝejon."],[50,46,"De la famo pri la preno de Babel ektremos la tero, kaj krio estos aŭdata ĉe la nacioj.","De la famo pri la preno de Babel ektremos la tero, kaj krio estos aŭdata ĉe la nacioj."],[51,1,"Tiele diras la Eternulo: Jen Mi vekos pereigan venton kontraŭ Babelon, kaj kontraŭ ĝiajn loĝantojn, kiuj leviĝis kontraŭ Min.","Tiele diras la Eternulo: Jen Mi vekos pereigan venton kontraŭ Babelon, kaj kontraŭ ĝiajn loĝantojn, kiuj leviĝis kontraŭ Min."],[51,2,"Kaj Mi sendos ventumistojn kontraŭ Babelon, kaj ili ĝin disventumos, kaj dezertigos ĝian landon; ĉar en la tago de la malfeliĉo ili estos ĉirkaŭ ĝi ĉiuflanke.","Kaj Mi sendos ventumistojn kontraŭ Babelon, kaj ili ĝin disventumos, kaj dezertigos ĝian landon; ĉar en la tago de la malfeliĉo ili estos ĉirkaŭ ĝi ĉiuflanke."],[51,3,"La pafarkisto streĉu sian pafarkon, kaj sin levu en sia kiraso; ne kompatu ĝiajn junulojn, ekstermu ĝian tutan militistaron.","La pafarkisto streĉu sian pafarkon, kaj sin levu en sia kiraso; ne kompatu ĝiajn junulojn, ekstermu ĝian tutan militistaron."],[51,4,"Kaj falu mortigitoj en la lando de la Ĥaldeoj, kaj trapikitoj sur iliaj stratoj.","Kaj falu mortigitoj en la lando de la Ĥaldeoj, kaj trapikitoj sur iliaj stratoj."],[51,5,"Ĉar Izrael kaj Jehuda ne estas vidvigitaj de sia Dio, de la Eternulo Cebaot; ĉar ilia lando estas plena de kulpoj kontraŭ la Sanktulo de Izrael.","Ĉar Izrael kaj Jehuda ne estas vidvigitaj de sia Dio, de la Eternulo Cebaot; ĉar ilia lando estas plena de kulpoj kontraŭ la Sanktulo de Izrael."],[51,6,"Forkuru el interne de Babel, kaj savu ĉiu sian animon, ke vi ne pereu pro ĝiaj malbonagoj; ĉar tio estas tempo de venĝo por la Eternulo, Li donas al ĝi repagon.","Forkuru el interne de Babel, kaj savu ĉiu sian animon, ke vi ne pereu pro ĝiaj malbonagoj; ĉar tio estas tempo de venĝo por la Eternulo, Li donas al ĝi repagon."],[51,7,"En la mano de la Eternulo Babel estis ora kaliko, ebriiganta la tutan teron: el ĝi trinkis vinon la nacioj, kaj tial ili freneziĝis.","En la mano de la Eternulo Babel estis ora kaliko, ebriiganta la tutan teron: el ĝi trinkis vinon la nacioj, kaj tial ili freneziĝis."],[51,8,"Subite falis Babel kaj frakasiĝis; ploru pri ĝi, prenu balzamon por ĝia vundo; eble ĝi saniĝos.","Subite falis Babel kaj frakasiĝis; ploru pri ĝi, prenu balzamon por ĝia vundo; eble ĝi saniĝos."],[51,9,"Ni kuracis Babelon, sed ĝi ne saniĝis; lasu ĝin, kaj ni iru ĉiu en sian landon; ĉar la juĝo kontraŭ ĝi atingis la ĉielon kaj leviĝis ĝis la nuboj.","Ni kuracis Babelon, sed ĝi ne saniĝis; lasu ĝin, kaj ni iru ĉiu en sian landon; ĉar la juĝo kontraŭ ĝi atingis la ĉielon kaj leviĝis ĝis la nuboj."],[51,10,"La Eternulo elaperigis nian pravecon; venu, kaj ni rakontu en Cion la faron de la Eternulo, nia Dio.","La Eternulo elaperigis nian pravecon; venu, kaj ni rakontu en Cion la faron de la Eternulo, nia Dio."],[51,11,"Akrigu la sagojn, pretigu la ŝildojn! la Eternulo vekis la spiriton de la reĝoj de Medujo, ĉar Lia intenco estas kontraŭ Babel, por pereigi ĝin; ĉar tio estas venĝo de la Eternulo, venĝo pro Lia templo.","Akrigu la sagojn, pretigu la ŝildojn! la Eternulo vekis la spiriton de la reĝoj de Medujo, ĉar Lia intenco estas kontraŭ Babel, por pereigi ĝin; ĉar tio estas venĝo de la Eternulo, venĝo pro Lia templo."],[51,12,"Kontraŭ la muregojn de Babel levu standardon, plifortigu la gardistaron, starigu observistojn, pretigu embuskon; ĉar kiel la Eternulo intencis, tiel Li faris tion, kion Li diris pri la loĝantoj de Babel.","Kontraŭ la muregojn de Babel levu standardon, plifortigu la gardistaron, starigu observistojn, pretigu embuskon; ĉar kiel la Eternulo intencis, tiel Li faris tion, kion Li diris pri la loĝantoj de Babel."],[51,13,"Ho vi, kiu loĝas ĉe granda akvo kaj havas grandajn trezorojn! venis via fino, finiĝis via avideco.","Ho vi, kiu loĝas ĉe granda akvo kaj havas grandajn trezorojn! venis via fino, finiĝis via avideco."],[51,14,"La Eternulo Cebaot ĵuris per Sia animo: Mi plenigos vin de homoj kiel de skaraboj, kaj ili eksonigos kontraŭ vi triumfan kanton.","La Eternulo Cebaot ĵuris per Sia animo: Mi plenigos vin de homoj kiel de skaraboj, kaj ili eksonigos kontraŭ vi triumfan kanton."],[51,15,"Li kreis la teron per Sia forto, aranĝis la mondon per Sia saĝo, kaj per Sia prudento etendis la ĉielon.","Li kreis la teron per Sia forto, aranĝis la mondon per Sia saĝo, kaj per Sia prudento etendis la ĉielon."],[51,16,"Kiam Li eksonigas Sian voĉon, kolektiĝas multego da akvo en la ĉielo; Li levas la nubojn de la randoj de la tero, Li aperigas fulmojn inter la pluvo, kaj elirigas la venton el Siaj trezorejoj.","Kiam Li eksonigas Sian voĉon, kolektiĝas multego da akvo en la ĉielo; Li levas la nubojn de la randoj de la tero, Li aperigas fulmojn inter la pluvo, kaj elirigas la venton el Siaj trezorejoj."],[51,17,"Malsaĝiĝis ĉiu homo kun sia sciado, per honto kovriĝis ĉiu fandisto kun sia statuo; ĉar lia fanditaĵo estas malveraĵo, ĝi ne havas en si spiriton.","Malsaĝiĝis ĉiu homo kun sia sciado, per honto kovriĝis ĉiu fandisto kun sia statuo; ĉar lia fanditaĵo estas malveraĵo, ĝi ne havas en si spiriton."],[51,18,"Tio estas vantaĵo, faro de eraro; kiam ili estos vizititaj, ili pereos.","Tio estas vantaĵo, faro de eraro; kiam ili estos vizititaj, ili pereos."],[51,19,"Ne simila al ili estas Tiu, kiun havas Jakob; ĉar Li estas la kreinto de ĉio, kaj Izrael estas la gento de Lia heredo; Eternulo Cebaot estas Lia nomo.","Ne simila al ili estas Tiu, kiun havas Jakob; ĉar Li estas la kreinto de ĉio, kaj Izrael estas la gento de Lia heredo; Eternulo Cebaot estas Lia nomo."],[51,20,"Vi estis por Mi martelo, ilo de batalo, kaj per vi Mi frakasis naciojn, kaj per vi Mi ekstermis regnojn;","Vi estis por Mi martelo, ilo de batalo, kaj per vi Mi frakasis naciojn, kaj per vi Mi ekstermis regnojn;"],[51,21,"Mi frakasis per vi ĉevalon kaj ĝian rajdanton, Mi frakasis per vi ĉaron kaj ĝian veturanton;","Mi frakasis per vi ĉevalon kaj ĝian rajdanton, Mi frakasis per vi ĉaron kaj ĝian veturanton;"],[51,22,"Mi frakasis per vi viron kaj virinon, Mi frakasis per vi maljunulon kaj junulon, Mi frakasis per vi junulon kaj junulinon;","Mi frakasis per vi viron kaj virinon, Mi frakasis per vi maljunulon kaj junulon, Mi frakasis per vi junulon kaj junulinon;"],[51,23,"Mi frakasis per vi paŝtiston kaj lian ŝafaron, Mi frakasis per vi terlaboriston kaj lian jungaĵon, Mi frakasis per vi komandantojn kaj estrojn.","Mi frakasis per vi paŝtiston kaj lian ŝafaron, Mi frakasis per vi terlaboriston kaj lian jungaĵon, Mi frakasis per vi komandantojn kaj estrojn."],[51,24,"Kaj Mi repagos al Babel kaj al ĉiuj loĝantoj de Ĥaldeujo pro ilia tuta malbono, kiun ili faris en Cion antaŭ viaj okuloj, diras la Eternulo.","Kaj Mi repagos al Babel kaj al ĉiuj loĝantoj de Ĥaldeujo pro ilia tuta malbono, kiun ili faris en Cion antaŭ viaj okuloj, diras la Eternulo."],[51,25,"Jen Mi iras kontraŭ vin, ho pereiga monto, pereiganto de la tuta tero, diras la Eternulo; Mi etendos Mian manon kontraŭ vin, Mi rulĵetos vin de la rokoj kaj faros vin monto de brulo.","Jen Mi iras kontraŭ vin, ho pereiga monto, pereiganto de la tuta tero, diras la Eternulo; Mi etendos Mian manon kontraŭ vin, Mi rulĵetos vin de la rokoj kaj faros vin monto de brulo."],[51,26,"Oni ne prenos el vi angulŝtonon, nek ŝtonon por fundamento, sed vi estos eterna ruino, diras la Eternulo.","Oni ne prenos el vi angulŝtonon, nek ŝtonon por fundamento, sed vi estos eterna ruino, diras la Eternulo."],[51,27,"Levu standardon en la lando, blovu per trumpeto inter la nacioj, armu kontraŭ ĝin popolojn, kunvoku kontraŭ ĝin la regnojn de Ararat, Mini, kaj Aŝkenaz; starigu kontraŭ ĝin militestron, alkonduku ĉevalojn kiel pikantajn skarabojn.","Levu standardon en la lando, blovu per trumpeto inter la nacioj, armu kontraŭ ĝin popolojn, kunvoku kontraŭ ĝin la regnojn de Ararat, Mini, kaj Aŝkenaz; starigu kontraŭ ĝin militestron, alkonduku ĉevalojn kiel pikantajn skarabojn."],[51,28,"Armu kontraŭ ĝin popolojn, la reĝojn de Medujo, ĝiajn komandantojn kaj ĉiujn ĝiajn estrojn, kaj la tutan landaron, super kiu ĝi regas.","Armu kontraŭ ĝin popolojn, la reĝojn de Medujo, ĝiajn komandantojn kaj ĉiujn ĝiajn estrojn, kaj la tutan landaron, super kiu ĝi regas."],[51,29,"Kaj la tero skuiĝas kaj tremas, ĉar plenumiĝas super Babel la intencoj de la Eternulo, por fari la landon de Babel dezerto, en kiu neniu loĝas.","Kaj la tero skuiĝas kaj tremas, ĉar plenumiĝas super Babel la intencoj de la Eternulo, por fari la landon de Babel dezerto, en kiu neniu loĝas."],[51,30,"La herooj de Babel ĉesis batali, ili restis en la fortikaĵoj; malaperis ilia forto, ili fariĝis kiel virinoj; ĝiaj loĝejoj ekbrulis, ĝiaj rigliloj estas rompitaj.","La herooj de Babel ĉesis batali, ili restis en la fortikaĵoj; malaperis ilia forto, ili fariĝis kiel virinoj; ĝiaj loĝejoj ekbrulis, ĝiaj rigliloj estas rompitaj."],[51,31,"Kuranto kuras renkonte al kuranto, sciiganto renkonte al sciiganto, por raporti al la reĝo de Babel, ke lia urbo estas venkoprenita ĉe ĉiuj flankoj,","Kuranto kuras renkonte al kuranto, sciiganto renkonte al sciiganto, por raporti al la reĝo de Babel, ke lia urbo estas venkoprenita ĉe ĉiuj flankoj,"],[51,32,"ke la transirejoj estas okupitaj, la fortikaĵoj brulas per fajro, kaj la militistojn atakis teruro.","ke la transirejoj estas okupitaj, la fortikaĵoj brulas per fajro, kaj la militistojn atakis teruro."],[51,33,"Ĉar tiele diras la Eternulo Cebaot, Dio de Izrael: La filino de Babel estas kiel draŝejo dum la draŝado; tre baldaŭ venos la tempo de ĝia rikolto.","Ĉar tiele diras la Eternulo Cebaot, Dio de Izrael: La filino de Babel estas kiel draŝejo dum la draŝado; tre baldaŭ venos la tempo de ĝia rikolto."],[51,34,"Manĝis min, frakasis min Nebukadnecar, reĝo de Babel, li faris min malplena vazo, glutis min kiel drako, plenigis sian ventron per miaj dolĉaĵoj, kaj forpelis min.","Manĝis min, frakasis min Nebukadnecar, reĝo de Babel, li faris min malplena vazo, glutis min kiel drako, plenigis sian ventron per miaj dolĉaĵoj, kaj forpelis min."],[51,35,"La maljusteco kontraŭ mi kaj mia karno estu nun sur Babel, diras la loĝantino de Cion; kaj mia sango sur la loĝantoj de Ĥaldeujo, diras Jerusalem.","La maljusteco kontraŭ mi kaj mia karno estu nun sur Babel, diras la loĝantino de Cion; kaj mia sango sur la loĝantoj de Ĥaldeujo, diras Jerusalem."],[51,36,"Tial tiele diras la Eternulo: Jen Mi juĝos vian aferon kaj Mi faros venĝon pro vi, Mi sekigos ĝian maron kaj Mi senakvigos ĝian fonton.","Tial tiele diras la Eternulo: Jen Mi juĝos vian aferon kaj Mi faros venĝon pro vi, Mi sekigos ĝian maron kaj Mi senakvigos ĝian fonton."],[51,37,"Kaj Babel fariĝos amaso da ŝtonoj, loĝejo de ŝakaloj, objekto de teruro kaj mokado, kaj neniu en ĝi loĝos.","Kaj Babel fariĝos amaso da ŝtonoj, loĝejo de ŝakaloj, objekto de teruro kaj mokado, kaj neniu en ĝi loĝos."],[51,38,"Ili ĉiuj blekegos kiel junaj leonoj, krios kiel leonidoj.","Ili ĉiuj blekegos kiel junaj leonoj, krios kiel leonidoj."],[51,39,"Dum ilia varmegiĝo Mi faros al ili festenon, kaj Mi ebriigos ilin, por ke ili fariĝu gajaj kaj ekdormu per eterna dormo kaj ne vekiĝu, diras la Eternulo.","Dum ilia varmegiĝo Mi faros al ili festenon, kaj Mi ebriigos ilin, por ke ili fariĝu gajaj kaj ekdormu per eterna dormo kaj ne vekiĝu, diras la Eternulo."],[51,40,"Mi kondukos ilin malsupren, kiel ŝafidojn al la buĉo, kiel ŝafojn kun kaproj.","Mi kondukos ilin malsupren, kiel ŝafidojn al la buĉo, kiel ŝafojn kun kaproj."],[51,41,"Kiele prenita estas Ŝeŝaĥ! kaj kaptita la gloro de la tuta mondo! kiele Babel fariĝis objekto de teruro inter la popoloj!","Kiele prenita estas Ŝeŝaĥ! kaj kaptita la gloro de la tuta mondo! kiele Babel fariĝis objekto de teruro inter la popoloj!"],[51,42,"Leviĝis kontraŭ Babelon la maro kaj kovris ĝin per la multego de siaj ondoj.","Leviĝis kontraŭ Babelon la maro kaj kovris ĝin per la multego de siaj ondoj."],[51,43,"Ĝiaj urboj fariĝis dezerto, tero seka kaj senviva, tero, sur kiu neniu loĝas kaj tra kiu neniu homido trairas.","Ĝiaj urboj fariĝis dezerto, tero seka kaj senviva, tero, sur kiu neniu loĝas kaj tra kiu neniu homido trairas."],[51,44,"Kaj Mi punos Belon en Babel, Mi eltiros el lia buŝo tion, kion li englutis, kaj ne plu kolektiĝos al li popoloj; ankaŭ la muregoj de Babel falos.","Kaj Mi punos Belon en Babel, Mi eltiros el lia buŝo tion, kion li englutis, kaj ne plu kolektiĝos al li popoloj; ankaŭ la muregoj de Babel falos."],[51,45,"Eliru el ĝia interno, Mia popolo, kaj ĉiu savu sian animon antaŭ la flama kolero de la Eternulo,","Eliru el ĝia interno, Mia popolo, kaj ĉiu savu sian animon antaŭ la flama kolero de la Eternulo,"],[51,46,"por ke via koro ne senkuraĝiĝu kaj vi ne ektimu, kiam oni aŭdos la famon en la lando; ĉar venos famo en unu jaro, kaj post ĝi venos famo en la sekvanta jaro, kaj sur la tero estos perforteco, unu reganto kontraŭ alia reganto.","por ke via koro ne senkuraĝiĝu kaj vi ne ektimu, kiam oni aŭdos la famon en la lando; ĉar venos famo en unu jaro, kaj post ĝi venos famo en la sekvanta jaro, kaj sur la tero estos perforteco, unu reganto kontraŭ alia reganto."],[51,47,"Tial jen venos tempo, kaj Mi vizitos la idolojn en Babel, kaj ĝia tuta lando estos hontigita, kaj ĉiuj ĝiaj mortigitoj falos meze de ĝi.","Tial jen venos tempo, kaj Mi vizitos la idolojn en Babel, kaj ĝia tuta lando estos hontigita, kaj ĉiuj ĝiaj mortigitoj falos meze de ĝi."],[51,48,"Kaj ĝojkantos pri Babel la ĉielo kaj la tero, kaj ĉio, kio estas sur ili; ĉar el la nordo venos al ĝi ruinigantoj, diras la Eternulo.","Kaj ĝojkantos pri Babel la ĉielo kaj la tero, kaj ĉio, kio estas sur ili; ĉar el la nordo venos al ĝi ruinigantoj, diras la Eternulo."],[51,49,"Kiel Babel faligis la mortigitojn de Izrael, tiel ankaŭ en Babel falos mortigitoj el la tuta lando.","Kiel Babel faligis la mortigitojn de Izrael, tiel ankaŭ en Babel falos mortigitoj el la tuta lando."],[51,50,"Vi, kiuj forsaviĝis de glavo, iru, ne haltu; en malproksimeco rememoru la Eternulon, kaj Jerusalem sin levu en via koro.","Vi, kiuj forsaviĝis de glavo, iru, ne haltu; en malproksimeco rememoru la Eternulon, kaj Jerusalem sin levu en via koro."],[51,51,"Ni hontis, kiam ni aŭdis la insulton; honto kovris nian vizaĝon, kiam fremduloj eniris en la sanktejon de la domo de la Eternulo.","Ni hontis, kiam ni aŭdis la insulton; honto kovris nian vizaĝon, kiam fremduloj eniris en la sanktejon de la domo de la Eternulo."],[51,52,"Tial jen venos tempo, diras la Eternulo, kiam Mi vizitos ĝiajn idolojn, kaj en la tuta lando ĝemos morte-vunditoj.","Tial jen venos tempo, diras la Eternulo, kiam Mi vizitos ĝiajn idolojn, kaj en la tuta lando ĝemos morte-vunditoj."],[51,53,"Eĉ se Babel leviĝus al la ĉielo kaj se ĝi fortikigus alte sian forton, tamen al ĝi venus de Mi ruinigantoj, diras la Eternulo.","Eĉ se Babel leviĝus al la ĉielo kaj se ĝi fortikigus alte sian forton, tamen al ĝi venus de Mi ruinigantoj, diras la Eternulo."],[51,54,"Kriado estas aŭdata el Babel, kaj granda lamentado el la lando de la Ĥaldeoj;","Kriado estas aŭdata el Babel, kaj granda lamentado el la lando de la Ĥaldeoj;"],[51,55,"ĉar la Eternulo ruinigas Babelon kaj pereigas ĝin kun ĝia granda bruo; iliaj ondoj bruas kiel granda akvo, aŭdiĝas ilia malkvieta voĉo.","ĉar la Eternulo ruinigas Babelon kaj pereigas ĝin kun ĝia granda bruo; iliaj ondoj bruas kiel granda akvo, aŭdiĝas ilia malkvieta voĉo."],[51,56,"Ĉar venos sur ĝin, sur Babelon, ruiniganto, kaj kaptitaj estos ĝiaj herooj, rompitaj estos iliaj pafarkoj; ĉar la Eternulo, Dio de repagado, nepre repagos.","Ĉar venos sur ĝin, sur Babelon, ruiniganto, kaj kaptitaj estos ĝiaj herooj, rompitaj estos iliaj pafarkoj; ĉar la Eternulo, Dio de repagado, nepre repagos."],[51,57,"Mi ebriigos ĝiajn eminentulojn, saĝulojn, komandantojn, estrojn, kaj heroojn, kaj ili ekdormos per eterna dormo kaj ne vekiĝos, diras la Reĝo, kies nomo estas Eternulo Cebaot.","Mi ebriigos ĝiajn eminentulojn, saĝulojn, komandantojn, estrojn, kaj heroojn, kaj ili ekdormos per eterna dormo kaj ne vekiĝos, diras la Reĝo, kies nomo estas Eternulo Cebaot."],[51,58,"Tiele diras la Eternulo Cebaot: La larĝaj muregoj de Babel estos subfositaj, kaj ĝiaj altaj pordegoj estos forbruligitaj per fajro; kaj vana fariĝos la penado de la popoloj, kaj gentoj estos lacigintaj sin por fajro.","Tiele diras la Eternulo Cebaot: La larĝaj muregoj de Babel estos subfositaj, kaj ĝiaj altaj pordegoj estos forbruligitaj per fajro; kaj vana fariĝos la penado de la popoloj, kaj gentoj estos lacigintaj sin por fajro."],[51,59,"Jen estas la vorto, kiun ordonis la profeto Jeremia al Seraja, filo de Nerija, filo de Maĥseja, kiam tiu iris kun Cidkija, reĝo de Judujo, en Babelon, en la kvara jaro de lia reĝado; Seraja estis la ripozejestro.","Jen estas la vorto, kiun ordonis la profeto Jeremia al Seraja, filo de Nerija, filo de Maĥseja, kiam tiu iris kun Cidkija, reĝo de Judujo, en Babelon, en la kvara jaro de lia reĝado; Seraja estis la ripozejestro."],[51,60,"Kaj Jeremia enskribis en unu libron la tutan malbonon, kiu venos sur Babelon, ĉiujn tiujn vortojn, skribitajn pri Babel.","Kaj Jeremia enskribis en unu libron la tutan malbonon, kiu venos sur Babelon, ĉiujn tiujn vortojn, skribitajn pri Babel."],[51,61,"Kaj Jeremia diris al Seraja: Kiam vi venos en Babelon, tiam rigardu kaj tralegu ĉiujn tiujn vortojn,","Kaj Jeremia diris al Seraja: Kiam vi venos en Babelon, tiam rigardu kaj tralegu ĉiujn tiujn vortojn,"],[51,62,"kaj diru: Ho Eternulo! Vi diris pri ĉi tiu loko, ke Vi ekstermos ĝin tiel, ke estos en ĝi neniu loĝanto, nek homo, nek bruto, sed ĝi estos eterna dezerto.","kaj diru: Ho Eternulo! Vi diris pri ĉi tiu loko, ke Vi ekstermos ĝin tiel, ke estos en ĝi neniu loĝanto, nek homo, nek bruto, sed ĝi estos eterna dezerto."],[51,63,"Kaj kiam vi finos la legadon de ĉi tiu libro, alligu al ĝi ŝtonon, kaj ĵetu ĝin en la mezon de Eŭfrato;","Kaj kiam vi finos la legadon de ĉi tiu libro, alligu al ĝi ŝtonon, kaj ĵetu ĝin en la mezon de Eŭfrato;"],[51,64,"kaj diru: Tiele dronos Babel, kaj ĝi ne releviĝos de la malfeliĉo, kiun Mi venigos sur ĝin, kaj ili pereos. Ĝis ĉi tie estas la vortoj de Jeremia.","kaj diru: Tiele dronos Babel, kaj ĝi ne releviĝos de la malfeliĉo, kiun Mi venigos sur ĝin, kaj ili pereos. Ĝis ĉi tie estas la vortoj de Jeremia."],[52,1,"La aĝon de dudek unu jaroj havis Cidkija, kiam li fariĝis reĝo, kaj dek unu jarojn li reĝis en Jerusalem. La nomo de lia patrino estis Ĥamutal, filino de Jeremia, el Libna.","La aĝon de dudek unu jaroj havis Cidkija, kiam li fariĝis reĝo, kaj dek unu jarojn li reĝis en Jerusalem. La nomo de lia patrino estis Ĥamutal, filino de Jeremia, el Libna."],[52,2,"Li agadis malbone antaŭ la Eternulo, kiel ĉio, kion faris Jehojakim.","Li agadis malbone antaŭ la Eternulo, kiel ĉio, kion faris Jehojakim."],[52,3,"Ĉar la kolero de la Eternulo estis kontraŭ Jerusalem kaj kontraŭ Judujo, ĝis Li forĵetis ilin de antaŭ Sia vizaĝo. Kaj Cidkija defalis de la reĝo de Babel.","Ĉar la kolero de la Eternulo estis kontraŭ Jerusalem kaj kontraŭ Judujo, ĝis Li forĵetis ilin de antaŭ Sia vizaĝo. Kaj Cidkija defalis de la reĝo de Babel."],[52,4,"En la naŭa jaro de lia reĝado, en la deka monato, en la deka tago de la monato, venis Nebukadnecar, reĝo de Babel, li kaj lia tuta militistaro, kontraŭ Jerusalemon, kaj eksieĝis ĝin, kaj oni konstruis ĉirkaŭ ĝi bastionojn.","En la naŭa jaro de lia reĝado, en la deka monato, en la deka tago de la monato, venis Nebukadnecar, reĝo de Babel, li kaj lia tuta militistaro, kontraŭ Jerusalemon, kaj eksieĝis ĝin, kaj oni konstruis ĉirkaŭ ĝi bastionojn."],[52,5,"Kaj la urbo restis sieĝata ĝis la dek-unua jaro de la reĝo Cidkija.","Kaj la urbo restis sieĝata ĝis la dek-unua jaro de la reĝo Cidkija."],[52,6,"En la kvara monato, en la naŭa tago de la monato, kiam la malsato tiel fortiĝis en la urbo, ke la popolo de la lando ne havis panon,","En la kvara monato, en la naŭa tago de la monato, kiam la malsato tiel fortiĝis en la urbo, ke la popolo de la lando ne havis panon,"],[52,7,"tiam oni faris enrompon en la urbon; kaj ĉiuj militistoj forkuris, kaj eliris el la urbo nokte, laŭ la vojo de la pordego inter la du muregoj apud la ĝardeno de la reĝo, kaj foriris laŭ la vojo al la stepo. Kaj la Ĥaldeoj staris ĉirkaŭ la urbo.","tiam oni faris enrompon en la urbon; kaj ĉiuj militistoj forkuris, kaj eliris el la urbo nokte, laŭ la vojo de la pordego inter la du muregoj apud la ĝardeno de la reĝo, kaj foriris laŭ la vojo al la stepo. Kaj la Ĥaldeoj staris ĉirkaŭ la urbo."],[52,8,"Kaj la militistaro de la Ĥaldeoj postkuris la reĝon kaj kuratingis Cidkijan sur la stepo de Jeriĥo, kaj lia tuta militistaro diskuris for de li.","Kaj la militistaro de la Ĥaldeoj postkuris la reĝon kaj kuratingis Cidkijan sur la stepo de Jeriĥo, kaj lia tuta militistaro diskuris for de li."],[52,9,"Kaj ili kaptis la reĝon kaj forkondukis lin al la reĝo de Babel, en Riblan, en la lando Ĥamat, kaj oni faris pri li juĝon.","Kaj ili kaptis la reĝon kaj forkondukis lin al la reĝo de Babel, en Riblan, en la lando Ĥamat, kaj oni faris pri li juĝon."],[52,10,"Kaj la reĝo de Babel buĉis la filojn de Cidkija antaŭ liaj okuloj, kaj ankaŭ ĉiujn eminentulojn de Judujo li buĉis en Ribla.","Kaj la reĝo de Babel buĉis la filojn de Cidkija antaŭ liaj okuloj, kaj ankaŭ ĉiujn eminentulojn de Judujo li buĉis en Ribla."],[52,11,"Kaj al Cidkija li blindigis la okulojn, kaj ligis lin per kupraj katenoj; kaj la reĝo de Babel venigis lin en Babelon, kaj metis lin en malliberejon ĝis la tago de lia morto.","Kaj al Cidkija li blindigis la okulojn, kaj ligis lin per kupraj katenoj; kaj la reĝo de Babel venigis lin en Babelon, kaj metis lin en malliberejon ĝis la tago de lia morto."],[52,12,"En la kvina monato, en la deka tago de la monato, tio estas en la dek-naŭa jaro de la reĝo Nebukadnecar, reĝo de Babel, venis Nebuzaradan, estro de la korpogardistoj, kiu ĉiam estis apud la reĝo de Babel, en Jerusalemon.","En la kvina monato, en la deka tago de la monato, tio estas en la dek-naŭa jaro de la reĝo Nebukadnecar, reĝo de Babel, venis Nebuzaradan, estro de la korpogardistoj, kiu ĉiam estis apud la reĝo de Babel, en Jerusalemon."],[52,13,"Kaj li forbruligis la domon de la Eternulo kaj la domon de la reĝo kaj ĉiujn domojn de Jerusalem; ĉiujn grandajn domojn li forbruligis per fajro.","Kaj li forbruligis la domon de la Eternulo kaj la domon de la reĝo kaj ĉiujn domojn de Jerusalem; ĉiujn grandajn domojn li forbruligis per fajro."],[52,14,"Kaj ĉiujn muregojn de Jerusalem ĉirkaŭe detruis la tuta militistaro de la Ĥaldeoj, kiu estis kun la estro de la korpogardistoj.","Kaj ĉiujn muregojn de Jerusalem ĉirkaŭe detruis la tuta militistaro de la Ĥaldeoj, kiu estis kun la estro de la korpogardistoj."],[52,15,"La malriĉulojn el la urbo, kaj la ceteran popolon, kiu restis en la urbo, kaj la transkurintojn, kiuj transkuris al la reĝo de Babel, kaj la ceteran popolamason forkondukis Nebuzaradan, la estro de la korpogardistoj.","La malriĉulojn el la urbo, kaj la ceteran popolon, kiu restis en la urbo, kaj la transkurintojn, kiuj transkuris al la reĝo de Babel, kaj la ceteran popolamason forkondukis Nebuzaradan, la estro de la korpogardistoj."],[52,16,"Sed iom el la malriĉuloj de la lando Nebuzaradan, la estro de la korpogardistoj, restigis, ke ili estu vinberistoj kaj terkultivistoj.","Sed iom el la malriĉuloj de la lando Nebuzaradan, la estro de la korpogardistoj, restigis, ke ili estu vinberistoj kaj terkultivistoj."],[52,17,"La kuprajn kolonojn, kiuj estis en la domo de la Eternulo, kaj la bazaĵojn kaj la kupran maron, kiuj estis en la domo de la Eternulo, la Ĥaldeoj disrompis kaj forportis ilian tutan kupron en Babelon.","La kuprajn kolonojn, kiuj estis en la domo de la Eternulo, kaj la bazaĵojn kaj la kupran maron, kiuj estis en la domo de la Eternulo, la Ĥaldeoj disrompis kaj forportis ilian tutan kupron en Babelon."],[52,18,"Kaj la potojn kaj la ŝovelilojn kaj la tranĉilojn kaj la aspergajn kalikojn kaj la kulerojn kaj ĉiujn kuprajn vazojn, kiuj estis uzataj ĉe la servado, ili forprenis.","Kaj la potojn kaj la ŝovelilojn kaj la tranĉilojn kaj la aspergajn kalikojn kaj la kulerojn kaj ĉiujn kuprajn vazojn, kiuj estis uzataj ĉe la servado, ili forprenis."],[52,19,"Kaj la tasojn kaj la karbujojn kaj la aspergajn kalikojn kaj la potojn kaj la lucernojn kaj la kulerojn kaj la verŝilojn, kiuj estis aŭ el oro aŭ el arĝento, prenis la estro de la korpogardistoj.","Kaj la tasojn kaj la karbujojn kaj la aspergajn kalikojn kaj la potojn kaj la lucernojn kaj la kulerojn kaj la verŝilojn, kiuj estis aŭ el oro aŭ el arĝento, prenis la estro de la korpogardistoj."],[52,20,"Koncerne la du kolonojn, la unu maron, la dek du kuprajn bovojn, kiuj servis kiel subtenilo, kiujn faris la reĝo Salomono por la domo de la Eternulo: la kvanto da kupro en ĉiuj tiuj iloj estis nemezurebla.","Koncerne la du kolonojn, la unu maron, la dek du kuprajn bovojn, kiuj servis kiel subtenilo, kiujn faris la reĝo Salomono por la domo de la Eternulo: la kvanto da kupro en ĉiuj tiuj iloj estis nemezurebla."],[52,21,"La kolonoj havis ĉiu la alton de dek ok ulnoj, kaj ĝin ĉirkaŭis ŝnuro, havanta la longon de dek du ulnoj; ĝia diko estis kvar fingroj, kaj interne ĝi estis malplena.","La kolonoj havis ĉiu la alton de dek ok ulnoj, kaj ĝin ĉirkaŭis ŝnuro, havanta la longon de dek du ulnoj; ĝia diko estis kvar fingroj, kaj interne ĝi estis malplena."],[52,22,"Ĝi havis sur si kupran kronon, kaj la alto de unu krono estis kvin ulnoj; kaj ĉirkaŭ la krono estis kradaĵo kaj granatoj, ĉio el kupro; tiel same estis ĉe la dua kolono, ankaŭ kun granatoj.","Ĝi havis sur si kupran kronon, kaj la alto de unu krono estis kvin ulnoj; kaj ĉirkaŭ la krono estis kradaĵo kaj granatoj, ĉio el kupro; tiel same estis ĉe la dua kolono, ankaŭ kun granatoj."],[52,23,"Da granatoj estis sur ĉiu flanko naŭdek ses; la nombro de la granatoj ĉirkaŭ la krono estis cent.","Da granatoj estis sur ĉiu flanko naŭdek ses; la nombro de la granatoj ĉirkaŭ la krono estis cent."],[52,24,"Kaj la korpogardistestro prenis la ĉefpastron Seraja kaj la duan pastron Cefanja kaj la tri pordogardistojn.","Kaj la korpogardistestro prenis la ĉefpastron Seraja kaj la duan pastron Cefanja kaj la tri pordogardistojn."],[52,25,"Kaj el la urbo li prenis unu korteganon, kiu estis super la militistoj, kaj sep virojn el la adjutantoj de la reĝo, kiuj troviĝis en la urbo, kaj la skribiston de la militestro, kiu enregistradis militistojn el la popolo de la lando, kaj sesdek homojn el la popolo de la lando, kiuj troviĝis en la urbo.","Kaj el la urbo li prenis unu korteganon, kiu estis super la militistoj, kaj sep virojn el la adjutantoj de la reĝo, kiuj troviĝis en la urbo, kaj la skribiston de la militestro, kiu enregistradis militistojn el la popolo de la lando, kaj sesdek homojn el la popolo de la lando, kiuj troviĝis en la urbo."],[52,26,"Ilin prenis Nebuzaradan, la estro de la korpogardistoj, kaj forkondukis al la reĝo de Babel en Riblan.","Ilin prenis Nebuzaradan, la estro de la korpogardistoj, kaj forkondukis al la reĝo de Babel en Riblan."],[52,27,"Kaj la reĝo de Babel frapis ilin kaj mortigis ilin en Ribla, en la lando Ĥamat. Tiamaniere Jehuda estis elhejmigita el sia lando.","Kaj la reĝo de Babel frapis ilin kaj mortigis ilin en Ribla, en la lando Ĥamat. Tiamaniere Jehuda estis elhejmigita el sia lando."],[52,28,"Jen estas la kvanto de la popolo, kiun Nebukadnecar elhejmigis: en la sepa jaro tri mil dudek tri Judojn;","Jen estas la kvanto de la popolo, kiun Nebukadnecar elhejmigis: en la sepa jaro tri mil dudek tri Judojn;"],[52,29,"en la dek-oka jaro de Nebukadnecar okcent tridek du homojn el Jerusalem;","en la dek-oka jaro de Nebukadnecar okcent tridek du homojn el Jerusalem;"],[52,30,"en la dudek-tria jaro de Nebukadnecar la korpogardistestro Nebuzaradan elhejmigis sepcent kvardek kvin homojn el la Judoj: la kvanto de ĉiuj estis kvar mil sescent homoj.","en la dudek-tria jaro de Nebukadnecar la korpogardistestro Nebuzaradan elhejmigis sepcent kvardek kvin homojn el la Judoj: la kvanto de ĉiuj estis kvar mil sescent homoj."],[52,31,"En la tridek-sepa jaro post la elpatrujigo de Jehojaĥin, reĝo de Judujo, en la dek-dua monato, en la dudek-kvina tago de la monato, Evil-Merodaĥ, reĝo de Babel, en la unua jaro de sia reĝado, levis la kapon de Jehojaĥin, reĝo de Judujo, kaj elirigis lin el la malliberejo;","En la tridek-sepa jaro post la elpatrujigo de Jehojaĥin, reĝo de Judujo, en la dek-dua monato, en la dudek-kvina tago de la monato, Evil-Merodaĥ, reĝo de Babel, en la unua jaro de sia reĝado, levis la kapon de Jehojaĥin, reĝo de Judujo, kaj elirigis lin el la malliberejo;"],[52,32,"kaj li parolis kun li afable, kaj starigis lian tronon pli alte ol la tronoj de la aliaj reĝoj, kiuj estis ĉe li en Babel;","kaj li parolis kun li afable, kaj starigis lian tronon pli alte ol la tronoj de la aliaj reĝoj, kiuj estis ĉe li en Babel;"],[52,33,"kaj li ŝanĝis liajn vestojn de malliberejo; kaj li manĝadis ĉiam ĉe li dum sia tuta vivo.","kaj li ŝanĝis liajn vestojn de malliberejo; kaj li manĝadis ĉiam ĉe li dum sia tuta vivo."],[52,34,"Kaj liaj vivrimedoj, vivrimedoj konstantaj, estis donataj al li de la reĝo de Babel ĉiutage dum lia tuta vivo, ĝis la tago de lia morto.","Kaj liaj vivrimedoj, vivrimedoj konstantaj, estis donataj al li de la reĝo de Babel ĉiutage dum lia tuta vivo, ĝis la tago de lia morto."]]}};